/* Executed-assertion / executed-case counters, reported at the end. */
let ASSERT_COUNT = 0;
let CASE_COUNT = 0;
function eq(actual, expected, message) {
  ASSERT_COUNT += 1;
  assert.strictEqual(actual, expected, message);
}
function countCase() {
  CASE_COUNT += 1;
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const header = join(root, "native", "decomp", "sfx_pure_helpers.h");
const source = join(root, "native", "decomp", "sfx_pure_helpers.cpp");
const outDir = join(root, "output", "decomp", "sfx-pure");
const wasmPath = join(outDir, "sfx-pure-helpers.wasm");

function firstExisting(paths, label) {
  const found = paths.find((path) => path && existsSync(path));
  assert.ok(found, `${label} not found:\n${paths.filter(Boolean).join("\n")}`);
  return found;
}

