function buildWasm() {
  mkdirSync(outDir, { recursive: true });
  const emsdk = process.env.EMSDK || join(homedir(), "emsdk");
  const clang = firstExisting([
    process.env.CLANGXX,
    join(emsdk, "upstream", "bin", "clang++.exe"),
    join(emsdk, "upstream", "bin", "clang++"),
  ], "Host clang++");
  const emxx = firstExisting([
    process.env.EMXX,
    join(emsdk, "upstream", "emscripten", "em++.exe"),
    join(emsdk, "upstream", "emscripten", "em++"),
  ], "Emscripten em++");
  const syntax = spawnSync(clang, [
    source,
    "-std=c++20",
    "-I", join(root, "native", "decomp"),
    "-fsyntax-only",
    "-Wall",
    "-Wextra",
    "-Werror",
  ], { cwd: root, encoding: "utf8" });
  eq(syntax.status, 0, syntax.stderr || syntax.stdout);
  const exportArgs = EXPORTS.flatMap((name) => [`-Wl,--export=${name}`]);
  /* Windows CreateProcess caps the command line at 32K chars; the
     export surface crossed it at v40 (33.5K chars for 775 exports).
     The export flags move to a clang response file — the link line
     is otherwise unchanged. */
  const rspPath = join(outDir, "exports.rsp")
    .replaceAll("\\", "/");
  writeFileSync(rspPath, exportArgs.join("\n"), "utf8");
  const built = spawnSync(emxx, [
    source,
    "-std=c++20",
    "-O2",
    "-I", join(root, "native", "decomp"),
    "--no-entry",
    "-sSTANDALONE_WASM=1",
    "-sERROR_ON_UNDEFINED_SYMBOLS=1",
    `@${rspPath}`,
    "-o", wasmPath,
  ], { cwd: root, encoding: "utf8" });
  eq(built.status, 0, built.stderr || built.stdout);
}

function loadExports() {
  buildWasm();
  const module = new WebAssembly.Module(readFileSync(wasmPath));
  eq(
    WebAssembly.Module.imports(module).length,
    0,
    "SFX pure helpers must be zero-import",
  );
  const instance = new WebAssembly.Instance(module, {});
  const wasm = instance.exports;
  const exp = (name) => {
    const fn = wasm[name] ?? wasm[`_${name}`];
    eq(typeof fn, "function", `missing export ${name}`);
    return fn;
  };
  const out = { memory: wasm.memory };
  for (const name of EXPORTS) {
    out[name] = exp(name);
  }
  return out;
}

/* Wasm scratch MUST live at 0x100000 (1 MiB) or above. A pure-helper module
   keeps its switch/jump tables and constant data in low linear memory, and
   emscripten places a 64 KiB shadow stack immediately after the static data â€”
   so the tens-of-kilobytes bases this file used before v3 sat *inside* the
   shadow stack and could silently corrupt helper locals. Both failure modes
   are silent: arithmetic-only helpers keep passing while table-driven ones
   quietly return garbage. Every base below is SCRATCH + a small offset. */
const SCRATCH = 0x100000;

/* The deterministic LCG these corpora share is
   `seed = seed*1664525 + 1013904223 (mod 2^32)`, whose bit k has period
   2^(k+1). Its LOW bits are therefore useless: bit 0 simply ALTERNATES
   (0,1,0,1,â€¦), so a low-bit `& 1` drawn three times in a row can only produce
   (b, !b, b) â€” two of eight combinations â€” and a low-bit `% 4` walks a fixed
   4-cycle in lockstep with the iteration index. Before v3 this file used
   `% n` and `& 1` everywhere, so its reported case counts overstated real
   coverage. Every selection now comes from the HIGH bits, and
   "randomized corpus reaches every seeded value" below proves it. */
function pick(rnd, n) {
  return Math.floor((rnd() / 4294967296) * n);
}
function bit(rnd) {
  return pick(rnd, 2);
}

/* Which distinct values each randomized draw actually produced. */
const COVERAGE = new Map();
function seen(bucket, value) {
  let set = COVERAGE.get(bucket);
  if (set === undefined) {
    set = new Set();
    COVERAGE.set(bucket, set);
  }
  set.add(value);
}
function coverage(bucket) {
  return COVERAGE.get(bucket) ?? new Set();
}

/* `cmp byte [entry+0x198], 0` reads a BYTE of a 4-byte slot, so the values
   that matter are 0, 0x100 (low byte clear, word set â€” the full-word-test
   mutant) and anything with a non-zero low byte. A uniform draw over 0x200
   reaches the disabled branch about twice in 512 and left the DISABLED gate
   kind uncovered; bias to the boundary instead. */
function makeEnabledDraw(rnd) {
  return () => {
    const branch = pick(rnd, 6);
    seen("enabledDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 0x100; // low byte clear, dword non-zero
      case 2: return 1;
      case 3: return 0x101;
      case 4: return 0xff;
      default: return pick(rnd, 0x200);
    }
  };
}

const f32 = (v) => Math.fround(v);

function f32Bits(bits) {
  const buf = new ArrayBuffer(4);
  new DataView(buf).setUint32(0, bits >>> 0, true);
  return new DataView(buf).getFloat32(0, true);
}

function writeI32(view, offset, value) {
  view.setInt32(offset, value | 0, true);
}
function writeU32(view, offset, value) {
  view.setUint32(offset, value >>> 0, true);
}
function writeF32(view, offset, value) {
  view.setFloat32(offset, value, true);
}
function readI32(view, offset) {
  return view.getInt32(offset, true);
}
function readU32(view, offset) {
  return view.getUint32(offset, true);
}
function readF32(view, offset) {
  return view.getFloat32(offset, true);
}

