test("PE truth (native): Load cannot touch the fields Play re-reads", () => {
  /* This is the whole v3 result and it must be asserted against the module,
     not against the oracle. SoundEffect::Load stores exactly two things: the
     enabled byte at 0x198 and one byte at entry+(i+1)*0x38 per visited voice.
     No voice index makes the second alias entry[0x000], entry[0x004] or
     entry[0x190], so Play's post-Load re-reads fold onto its first reads. */
  for (const voices of [0, 1, 2, 6, 7, 8, 9, 64, 0x7fffffff, 0xffffffff]) {
    eq(
      wasm.isaac_sfx_load_writes_entry_field(SFX_ENTRY_OFF_FRAME_START, voices),
      0,
      `entry[0] must stay untouched for voices=${voices}`,
    );
    eq(
      wasm.isaac_sfx_load_writes_entry_field(SFX_ENTRY_OFF_FRAME_END, voices),
      0,
      `entry[4] must stay untouched for voices=${voices}`,
    );
    eq(
      wasm.isaac_sfx_load_writes_entry_field(
        SFX_ENTRY_OFF_VOICE_COUNT_190,
        voices,
      ),
      0,
      `entry[0x190] must stay untouched for voices=${voices}`,
    );
    // The enabled byte IS written, unconditionally, on both paths.
    eq(
      wasm.isaac_sfx_load_writes_entry_field(SFX_ENTRY_OFF_ENABLED_198, voices),
      1,
      `entry[0x198] is always written, voices=${voices}`,
    );
    // ... and the base volume next to it is not, which is what makes the
    // enabled answer a field answer rather than a "somewhere near" answer.
    eq(
      wasm.isaac_sfx_load_writes_entry_field(
        SFX_ENTRY_OFF_BASE_VOLUME_194,
        voices,
      ),
      0,
      `entry[0x194] must stay untouched for voices=${voices}`,
    );
    countCase();
  }
  // The stream bytes that ARE written, exactly where the cursor puts them.
  for (let i = 0; i < 10; ++i) {
    const at = (i + 1) * SFX_VOICE_STRIDE;
    eq(wasm.isaac_sfx_load_stream_byte_offset(i), at, `stream byte ${i}`);
    eq(wasm.isaac_sfx_load_writes_entry_field(at, i), 0, `slot ${i} unvisited`);
    eq(wasm.isaac_sfx_load_writes_entry_field(at, i + 1), 1, `slot ${i} visited`);
  }
  // Voice 7's stream byte lands past the 0x1b8 stride: entry+0x1c0 is the
  // NEXT entry's first name-string byte. Reproduced, not corrected.
  eq(wasm.isaac_sfx_load_stream_byte_offset(7), 0x1c0);
  assert.ok(0x1c0 > SFX_ENTRY_STRIDE, "voice 7 overruns the entry stride");
  ASSERT_COUNT += 1;
  // The recapture answer Play consumes.
  for (const voices of [0, 1, 4, 8, 0xffffffff]) {
    eq(
      wasm.isaac_sfx_play_recapture_mask(SFX_PLAY_GATE_PRELOAD, voices) &
        (SFX_PLAY_RECAPTURE_ENTRY_END_4 | SFX_PLAY_RECAPTURE_VOICES_190),
      0,
      `no entry recapture on PRELOAD, voices=${voices}`,
    );
    eq(
      wasm.isaac_sfx_play_recapture_mask(SFX_PLAY_GATE_PRELOAD, voices),
      SFX_PLAY_RECAPTURE_STREAM_FLAG,
      `only the stream byte is recaptured, voices=${voices}`,
    );
    eq(
      wasm.isaac_sfx_play_recapture_mask(SFX_PLAY_GATE_LIVE, voices),
      SFX_PLAY_RECAPTURE_STREAM_FLAG,
    );
    eq(
      wasm.isaac_sfx_play_recapture_mask(SFX_PLAY_GATE_MISS, voices),
      SFX_PLAY_RECAPTURE_NONE,
    );
    eq(
      wasm.isaac_sfx_play_recapture_mask(SFX_PLAY_GATE_NO_SAMPLES, voices),
      SFX_PLAY_RECAPTURE_NONE,
    );
    countCase();
  }
});

test("PE truth (native): Load's entry-level bookkeeping", () => {
  const view = new DataView(wasm.memory.buffer);
  const planBase = SCRATCH + 20000;
  // A sample-less entry takes the `jbe` straight to the enabled store: the
  // loop never runs, yet the entry still comes back marked enabled. Modelling
  // that store as part of the loop body would silently drop it.
  wasm.isaac_sfx_load_plan(0, 11, 22, planBase);
  const empty = readLoadPlan(view, planBase);
  eq(empty.voiceLoopEnter, false);
  eq(empty.voicesVisited, 0);
  eq(empty.enabledAfter, 1, "0x0092d10f runs on the zero-voice path too");
  eq(empty.streamByteStores, 0);
  eq(empty.entryHeaderStores, 1);
  eq(empty.pureComplete, true);
  eq(empty.frameStartAfter, 11);
  eq(empty.frameEndAfter, 22);
  eq(empty.voicesAfter, 0);
  eq(empty.headerAliasIndex, -1);
  // A normal entry: the loop bound is the same field the loop never writes,
  // so the visit count equals the count and both survive the call.
  wasm.isaac_sfx_load_plan(4, -1, 0x7fffffff, planBase);
  const four = readLoadPlan(view, planBase);
  eq(four.voiceLoopEnter, true);
  eq(four.voicesVisited, 4);
  eq(four.voicesAfter, 4);
  eq(four.streamByteStores, 4);
  eq(four.enabledAfter, 1);
  eq(four.pureComplete, false);
  eq(four.frameStartAfter, -1);
  eq(four.frameEndAfter, 0x7fffffff);
  eq(four.headerAliasIndex, -1);
  // The seventh slot is the last one that fits; the eighth IS the header.
  for (let i = 0; i <= 8; ++i) {
    eq(
      wasm.isaac_sfx_load_voice_slot_in_bounds(i),
      i <= 6 ? 1 : 0,
      `slot ${i} in bounds`,
    );
    eq(
      wasm.isaac_sfx_load_voice_aliases_entry_header(i),
      i === 7 ? 1 : 0,
      `slot ${i} alias`,
    );
  }
  // Voice 6 ends exactly at the header, which is what fixes the capacity.
  eq(
    wasm.isaac_sfx_load_voice_name_offset(6) + SFX_VOICE_STRIDE,
    SFX_ENTRY_OFF_VOICE_COUNT_190,
  );
  eq(wasm.isaac_sfx_load_voice_name_offset(7), SFX_ENTRY_OFF_VOICE_COUNT_190);
  wasm.isaac_sfx_load_plan(8, 0, 0, planBase);
  eq(readLoadPlan(view, planBase).headerAliasIndex, 7);
  wasm.isaac_sfx_load_plan(7, 0, 0, planBase);
  eq(readLoadPlan(view, planBase).headerAliasIndex, -1);
  countCase();
});

test("PE truth (native): Load's per-voice suffix / SSO decisions", () => {
  // `lea ecx,[size-4] ; cmp size,ecx ; jb` borrows only below four, so a
  // length of exactly four is fine. `<=` here would be a real misread.
  eq(wasm.isaac_sfx_load_path_len_fatal(0), 1);
  eq(wasm.isaac_sfx_load_path_len_fatal(3), 1);
  eq(wasm.isaac_sfx_load_path_len_fatal(4), 0, "size == 4 is NOT fatal");
  eq(wasm.isaac_sfx_load_path_len_fatal(5), 0);
  eq(wasm.isaac_sfx_load_path_len_fatal(0xffffffff), 0, "unsigned compare");
  // The clamp the compiler emitted alongside it is unreachable: the
  // difference is exactly four whenever the guard let us through.
  eq(wasm.isaac_sfx_load_compare_length(4), 4);
  eq(wasm.isaac_sfx_load_compare_length(0x10000), 4);
  eq(wasm.isaac_sfx_load_compare_length(3), 0);
  // `cmp capacity,0x10 ; cmovae` â€” the boundary value picks the heap.
  eq(wasm.isaac_sfx_load_uses_heap_buffer(0), 0);
  eq(wasm.isaac_sfx_load_uses_heap_buffer(0x0f), 0);
  eq(wasm.isaac_sfx_load_uses_heap_buffer(0x10), 1, "0x10 uses the heap");
  eq(wasm.isaac_sfx_load_uses_heap_buffer(0xffffffff), 1);
  // The compare returns zero on a match, and a match means "stream".
  eq(wasm.isaac_sfx_load_stream_byte(0), 1);
  eq(wasm.isaac_sfx_load_stream_byte(1), 0);
  eq(wasm.isaac_sfx_load_stream_byte(-1), 0);
  countCase();
});

test("Wasm matches JS: v3 Load / copy-assign / start differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const loadBase = SCRATCH + 21000;
  const voiceBase = SCRATCH + 21200;
  const swapBase = SCRATCH + 21400;
  const copyBase = SCRATCH + 21600;
  const startBase = SCRATCH + 21800;

  for (const voices of [0, 1, 6, 7, 8, 0xffffffff]) {
    for (const [fs, fe] of [[0, 0], [-1, -1], [5, 7], [0x7fffffff, -0x80000000]]) {
      wasm.isaac_sfx_load_plan(voices, fs, fe, loadBase);
      assertPlanEqual(
        readLoadPlan(view, loadBase),
        sfxLoadPlan(voices, fs, fe),
        `load plan v=${voices}`,
      );
      countCase();
    }
  }
  for (const index of [0, 1, 6, 7, 8, 0x10000, -1]) {
    eq(
      wasm.isaac_sfx_load_voice_name_offset(index),
      sfxLoadVoiceNameOffset(index),
      `name off ${index}`,
    );
    eq(
      wasm.isaac_sfx_load_voice_wrapper_offset(index),
      sfxLoadVoiceWrapperOffset(index),
      `wrapper off ${index}`,
    );
    eq(
      wasm.isaac_sfx_load_stream_byte_offset(index),
      sfxLoadStreamByteOffset(index),
      `stream off ${index}`,
    );
    eq(
      wasm.isaac_sfx_load_voice_slot_in_bounds(index),
      sfxLoadVoiceSlotInBounds(index) ? 1 : 0,
      `in bounds ${index}`,
    );
    eq(
      wasm.isaac_sfx_load_voice_aliases_entry_header(index),
      sfxLoadVoiceAliasesEntryHeader(index) ? 1 : 0,
      `alias ${index}`,
    );
    for (const size of [0, 3, 4, 5, 0x10, 0xffffffff]) {
      for (const cap of [0, 0x0f, 0x10, 0xffffffff]) {
        for (const cmp of [0, 1, -1]) {
          wasm.isaac_sfx_load_voice_plan(index, size, cap, cmp, voiceBase);
          assertPlanEqual(
            readLoadVoicePlan(view, voiceBase),
            sfxLoadVoicePlan(index, size, cap, cmp),
            `load voice ${index}/${size}/${cap}/${cmp}`,
          );
          countCase();
        }
      }
    }
  }
  for (const offset of [-4, -1, 0, 4, 8, 0x38, 0x39, 0x36, 0x70, 0x190, 0x194,
                        0x198, 0x1b8, 0x1c0]) {
    for (const voices of [0, 1, 7, 8, 0xffffffff]) {
      eq(
        wasm.isaac_sfx_load_writes_entry_field(offset, voices),
        sfxLoadWritesEntryField(offset, voices) ? 1 : 0,
        `writes ${offset}/${voices}`,
      );
      countCase();
    }
  }
  for (const kind of [SFX_PLAY_GATE_MISS, SFX_PLAY_GATE_NO_SAMPLES,
                      SFX_PLAY_GATE_PRELOAD, SFX_PLAY_GATE_LIVE]) {
    for (const voices of [0, 1, 8, 0xffffffff]) {
      eq(
        wasm.isaac_sfx_play_recapture_mask(kind, voices),
        sfxPlayRecaptureMask(kind, voices),
        `recapture ${kind}/${voices}`,
      );
      countCase();
    }
  }
  for (const quad of [
    [0, 0, 0, 0],
    [1, 2, 3, 4],
    [-1, 0x7fffffff, -0x80000000, 1],
    [5, 5, 5, 5],
  ]) {
    wasm.isaac_sfx_channel_pointer_swap(quad[0], quad[1], quad[2], quad[3],
                                        swapBase);
    assertPlanEqual(
      readSwap(view, swapBase),
      sfxChannelPointerSwap(quad[0], quad[1], quad[2], quad[3]),
      `swap ${quad}`,
    );
    countCase();
  }
  const floats = [f32(0), f32(-0), f32(1), f32(-1), f32(0.25), Number.NaN,
                  Infinity, -Infinity];
  for (const loop of [0, 1, 0xff, 0x100, 0x101]) {
    for (const pending of [0, 1, 0x100]) {
      for (const v of floats) {
        wasm.isaac_sfx_channel_copy_assign_plan(loop, pending, v, f32(-0),
                                                Number.NaN, copyBase);
        const w = readCopyAssign(view, copyBase);
        const js = sfxChannelCopyAssignPlan(loop, pending, v, f32(-0),
                                            Number.NaN);
        for (const key of Object.keys(js)) {
          if (typeof js[key] === "number" && !Number.isInteger(js[key])) {
            eq(bitsOf(w[key]), bitsOf(js[key]), `copy assign ${key} ${v}`);
          } else if (Number.isNaN(js[key])) {
            eq(bitsOf(w[key]), bitsOf(js[key]), `copy assign ${key} ${v}`);
          } else {
            eq(w[key], js[key], `copy assign ${key} ${v}`);
          }
        }
        countCase();
      }
    }
  }
  for (const chNull of [0, 1]) {
    for (const pending of [0, 1, 7, 0x100, 0x1ff]) {
      for (const flag of [0, 1, 0x100]) {
        wasm.isaac_sfx_channel_start_plan(chNull, pending, flag, startBase);
        assertPlanEqual(
          readStartPlan(view, startBase),
          sfxChannelStartPlan(chNull, pending, flag),
          `start ${chNull}/${pending}/${flag}`,
        );
        countCase();
      }
    }
  }
});

test("PE truth (native): copy-assign clobbers +0x0a and survives self-assign", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = SCRATCH + 22000;
  // The pack clears the spare flag byte and the restore never puts it back,
  // so a source with the flag set still yields a cleared destination. Copying
  // it back would be the natural "fix" and would be wrong.
  wasm.isaac_sfx_channel_copy_assign_plan(1, 1, f32(0.5), f32(-0.25), f32(2),
                                          base);
  const p = readCopyAssign(view, base);
  eq(p.finalFlag0a, 0, "+0x0a is never restored");
  eq(p.transientFlag0a, 0);
  eq(p.finalLoop08, 1, "loop comes back from bl");
  eq(p.finalPending09, 1, "pending comes back from bh");
  eq(p.finalVolume0c, f32(0.5));
  eq(p.finalPan10, f32(-0.25));
  eq(p.finalPitch14, f32(2));
  // The transient window the two hook probes observe is the shared pack.
  eq(p.transientVolume0c, f32(1));
  eq(p.transientPan10, f32(0));
  eq(p.transientPitch14, f32(1));
  eq(p.transientLoop08, 0);
  eq(p.transientPending09, 0);
  eq(p.releaseNeeded, true);
  eq(p.adoptCalls, 2);
  eq(p.hookProbeSites, 2);
  eq(p.snapshotBeforeRelease, true);
  eq(p.selfAssignSafe, true);
  // The two byte fields come back through separate byte stores (bl / bh), so
  // neither can bleed into the other the way the reset's word store does.
  wasm.isaac_sfx_channel_copy_assign_plan(0x100, 0, f32(1), f32(1), f32(1),
                                          base);
  eq(readCopyAssign(view, base).finalLoop08, 0, "loop is a byte read");
  wasm.isaac_sfx_channel_copy_assign_plan(0, 0x100, f32(1), f32(1), f32(1),
                                          base);
  eq(readCopyAssign(view, base).finalPending09, 0, "pending is a byte read");
  // The pointer exchange is a swap, so the temporary walks away with the
  // wrapper's old pair â€” which is exactly what the next probe inspects.
  const swapBase = SCRATCH + 22200;
  wasm.isaac_sfx_channel_pointer_swap(0x11, 0x22, 0x33, 0x44, swapBase);
  const s = readSwap(view, swapBase);
  eq(s.dst00, 0x33);
  eq(s.dst04, 0x44);
  eq(s.tmp00, 0x11);
  eq(s.tmp04, 0x22);
  countCase();
});

test("PE truth (native): channel start equals Play's inlined tail", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = SCRATCH + 22400;
  /* 0x00a2ac00 and Play's 0x0092de6a..0x0092de7e are the same code. Both end
     in a 16-bit store: `mov word [wrapper+9], 1`. A byte-only model would set
     pending and leave +0x0a alone, losing one field. */
  wasm.isaac_sfx_channel_start_plan(0, 0, 0xff, base);
  const started = readStartPlan(view, base);
  eq(started.deviceStartNeeded, true);
  eq(started.startArg, 1);
  eq(started.pending09After, 1, "low byte of the word store");
  eq(started.flag0aAfter, 0, "high byte of the SAME word store");
  eq(started.pending09After, wasm.isaac_sfx_word_store_lo(SFX_PLAY_STARTED_WORD));
  eq(started.flag0aAfter, wasm.isaac_sfx_word_store_hi(SFX_PLAY_STARTED_WORD));
  // With no channel object nothing is written at all.
  wasm.isaac_sfx_channel_start_plan(1, 0x42, 0x99, base);
  const idle = readStartPlan(view, base);
  eq(idle.deviceStartNeeded, false);
  eq(idle.wordStoreNeeded, false);
  eq(idle.pending09After, 0x42);
  eq(idle.flag0aAfter, 0x99);
  countCase();
});

test("deterministic randomized differential corpus: v3 Load / copy-assign", () => {
  let seed = (0x92cfb0 ^ 0xa2ac90) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const scratch = new DataView(new ArrayBuffer(4));
  const bitsFloat = (bits) => {
    scratch.setUint32(0, bits >>> 0, true);
    return scratch.getFloat32(0, true);
  };
  /* Bias to the boundaries the Load arithmetic actually has: the length-4
     borrow edge, the 0x10 SSO edge, and the seven-slot capacity edge. */
  const sizeDraw = () => {
    const branch = pick(rnd, 6);
    seen("loadSizeDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 3; // last fatal value
      case 2: return 4; // first non-fatal value
      case 3: return 5;
      case 4: return 0xffffffff;
      default: return pick(rnd, 0x10000);
    }
  };
  const capDraw = () => {
    const branch = pick(rnd, 5);
    seen("loadCapDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 0x0f; // last inline value
      case 2: return 0x10; // first heap value
      case 3: return 0xffffffff;
      default: return pick(rnd, 0x100);
    }
  };
  const indexDraw = () => {
    const branch = pick(rnd, 6);
    seen("loadIndexDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 6; // last in-bounds slot
      case 2: return 7; // the slot that IS the entry header
      case 3: return 8;
      case 4: return -1;
      default: return (rnd() | 0) >> pick(rnd, 26);
    }
  };
  const voicesDraw = () => {
    const branch = pick(rnd, 6);
    seen("loadVoicesDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 1;
      case 2: return 7;
      case 3: return 8;
      case 4: return 0xffffffff;
      default: return pick(rnd, 0x40);
    }
  };
  const floatDraw = () => {
    const branch = pick(rnd, 6);
    seen("copyFloatDraw", branch);
    switch (branch) {
      case 0: return f32(0);
      case 1: return f32(-0);
      case 2: return Number.NaN;
      case 3: return f32(1);
      case 4: return bitsFloat(rnd());
      default: return f32((pick(rnd, 2001) - 1000) / 128);
    }
  };

  const view = new DataView(wasm.memory.buffer);
  const loadBase = SCRATCH + 24000;
  const voicePlanBase = SCRATCH + 24200;
  const swapBase = SCRATCH + 24400;
  const copyBase = SCRATCH + 24600;
  const startBase = SCRATCH + 24800;

  for (let t = 0; t < 400; ++t) {
    const voices = voicesDraw();
    const fs = (rnd() | 0) >> pick(rnd, 12);
    const fe = (rnd() | 0) >> pick(rnd, 12);
    wasm.isaac_sfx_load_plan(voices, fs, fe, loadBase);
    const jsLoad = sfxLoadPlan(voices, fs, fe);
    seen("loadEnter", jsLoad.voiceLoopEnter);
    seen("loadAlias", jsLoad.headerAliasIndex);
    assertPlanEqual(readLoadPlan(view, loadBase), jsLoad, `t${t} load plan`);

    const index = indexDraw();
    const size = sizeDraw();
    const cap = capDraw();
    const cmp = pick(rnd, 3) - 1; // -1, 0, 1 â€” only zero means "match"
    seen("loadCmp", cmp);
    wasm.isaac_sfx_load_voice_plan(index, size, cap, cmp, voicePlanBase);
    const jsVoice = sfxLoadVoicePlan(index, size, cap, cmp);
    seen("loadFatal", jsVoice.pathLenFatal);
    seen("loadStreamByte", jsVoice.streamByteValue);
    seen("loadCreate", jsVoice.deviceCreateNeeded);
    seen("loadHeap", jsVoice.usesHeapBuffer);
    assertPlanEqual(
      readLoadVoicePlan(view, voicePlanBase),
      jsVoice,
      `t${t} load voice ${index}/${size}/${cap}/${cmp}`,
    );

    const fieldOffset = pick(rnd, 3) === 0
      ? [0, 4, 0x190, 0x194, 0x198][pick(rnd, 5)]
      : (rnd() | 0) >> pick(rnd, 22);
    eq(
      wasm.isaac_sfx_load_writes_entry_field(fieldOffset, voices),
      sfxLoadWritesEntryField(fieldOffset, voices) ? 1 : 0,
      `t${t} writes ${fieldOffset}/${voices}`,
    );
    const kind = pick(rnd, 4);
    seen("recaptureKind", kind);
    eq(
      wasm.isaac_sfx_play_recapture_mask(kind, voices),
      sfxPlayRecaptureMask(kind, voices),
      `t${t} recapture ${kind}`,
    );

    const q = [rnd() | 0, rnd() | 0, rnd() | 0, rnd() | 0];
    wasm.isaac_sfx_channel_pointer_swap(q[0], q[1], q[2], q[3], swapBase);
    assertPlanEqual(
      readSwap(view, swapBase),
      sfxChannelPointerSwap(q[0], q[1], q[2], q[3]),
      `t${t} swap`,
    );

    const loop = pick(rnd, 0x200);
    const pending = pick(rnd, 0x200);
    const vol = floatDraw();
    const pan = floatDraw();
    const pitch = floatDraw();
    wasm.isaac_sfx_channel_copy_assign_plan(loop, pending, vol, pan, pitch,
                                            copyBase);
    const w = readCopyAssign(view, copyBase);
    const js = sfxChannelCopyAssignPlan(loop, pending, vol, pan, pitch);
    for (const key of Object.keys(js)) {
      if (key.endsWith("0c") || key.endsWith("10") || key.endsWith("14")) {
        eq(bitsOf(w[key]), bitsOf(js[key]), `t${t} copy ${key}`);
      } else {
        eq(w[key], js[key], `t${t} copy ${key}`);
      }
    }

    const chNull = bit(rnd);
    const flag = pick(rnd, 0x200);
    wasm.isaac_sfx_channel_start_plan(chNull, pending, flag, startBase);
    assertPlanEqual(
      readStartPlan(view, startBase),
      sfxChannelStartPlan(chNull, pending, flag),
      `t${t} start`,
    );
    countCase();
  }
});

/* ------------------------------------------------------------------ *
 * v4: 0x0092d140 sample-table (re)builder â€” clear walk + fixed resize. *
 * ------------------------------------------------------------------ */

test("v4 header records the table-rebuilder evidence", () => {
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x0092d140/);
  assert.match(h, /0x0092d2f2/);
  assert.match(h, /0x0092cf10/);
  assert.match(h, /0x0092ea80/);
  assert.match(h, /0x0092edc0/);
  assert.match(h, /0x0092ee40/);
  assert.match(h, /__ehvec_dtor/);
  assert.match(h, /UNSIGNED/);
  assert.match(h, /rounded\s*\n?\s*DOWN|rounded DOWN/);
  assert.match(h, /STATICALLY DEAD/);
  // The register-allocation caveat on the shared count model must be stated,
  // not glossed as "byte-identical".
  assert.match(h, /c1fa04 8bf2 c1ee1f 03f2/);
  assert.match(h, /Register allocation only/);
  const h2 = readFileSync(header, "utf8");
  const pairs = [
    ["ISAAC_SFX_TABLE_TARGET_COUNT", SFX_TABLE_TARGET_COUNT, 0x443],
    ["ISAAC_SFX_TABLE_TARGET_BYTES", SFX_TABLE_TARGET_BYTES, 0x75328],
    ["ISAAC_SFX_ENTRY_VOICE_DTOR_BASE_OFF", SFX_ENTRY_VOICE_DTOR_BASE_OFF, 0x08],
    ["ISAAC_SFX_ENTRY_VOICE_DTOR_STRIDE", SFX_ENTRY_VOICE_DTOR_STRIDE, 0x38],
    ["ISAAC_SFX_ENTRY_VOICE_DTOR_COUNT", SFX_ENTRY_VOICE_DTOR_COUNT, 7],
    ["ISAAC_SFX_VOICE_SLOT_OFF_NAME", SFX_VOICE_SLOT_OFF_NAME, 0x00],
    ["ISAAC_SFX_VOICE_SLOT_OFF_WRAPPER", SFX_VOICE_SLOT_OFF_WRAPPER, 0x18],
    ["ISAAC_SFX_ENTRY_OFF_NAME_STRING_1A0", SFX_ENTRY_OFF_NAME_STRING_1A0,
     0x1a0],
    ["ISAAC_SFX_STRING_SSO_LIMIT", SFX_STRING_SSO_LIMIT, 0x10],
    ["ISAAC_SFX_STRING_BIG_ALLOC_LIMIT", SFX_STRING_BIG_ALLOC_LIMIT, 0x1000],
    ["ISAAC_SFX_STRING_BIG_ALLOC_BIAS", SFX_STRING_BIG_ALLOC_BIAS, 0x23],
    ["ISAAC_SFX_STRING_ALIGN_SLACK_MAX", SFX_STRING_ALIGN_SLACK_MAX, 0x1f],
    ["ISAAC_SFX_STRING_RESET_CAPACITY", SFX_STRING_RESET_CAPACITY, 0x0f],
    ["ISAAC_SFX_HOST_VA_TABLE_LOAD", SFX_HOST_VA_TABLE_LOAD, 0x0092d140],
    ["ISAAC_SFX_HOST_VA_TABLE_DESTROY_RANGE", SFX_HOST_VA_TABLE_DESTROY_RANGE,
     0x0092ea80],
    ["ISAAC_SFX_HOST_VA_TABLE_APPEND_N", SFX_HOST_VA_TABLE_APPEND_N,
     0x0092edc0],
    ["ISAAC_SFX_HOST_VA_TABLE_GROW", SFX_HOST_VA_TABLE_GROW, 0x0092ee40],
    ["ISAAC_SFX_HOST_VA_VOICE_SLOT_DTOR", SFX_HOST_VA_VOICE_SLOT_DTOR,
     0x0092cf10],
    ["ISAAC_SFX_HOST_VA_VECTOR_DTOR_ITER", SFX_HOST_VA_VECTOR_DTOR_ITER,
     0x00aef638],
    ["ISAAC_SFX_TABLE_LOAD_CALLER_COUNT", SFX_TABLE_LOAD_CALLER_COUNT, 2],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h2, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }
  eq(DTOR_ARGS_SIZE, 28);
  eq(FREE_PLAN_SIZE, 28);
  eq(CLEAR_PLAN_SIZE, 36);
  eq(RESIZE_PLAN_SIZE, 36);
  eq(DEAD_BRANCH_SIZE, 16);
});

test("PE truth (native): the machine states the seven voice slots itself", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = SCRATCH + 26000;
  /* v3 derived the seven-slot capacity arithmetically (voice 6 ends exactly
     at 0x190). The destructor call at 0x0092d24a pushes the count as a
     LITERAL, so this is the same fact from an unrelated code path. */
  wasm.isaac_sfx_entry_voice_dtor_args(base);
  const a = readDtorArgs(view, base);
  eq(a.baseOffset, 0x08, "base is elem+0x08");
  eq(a.stride, 0x38);
  eq(a.count, 7, "the literal pushed at 0x0092d24a");
  eq(a.dtorVa, 0x0092cf10);
  // 0x0092cf10 destroys slot+0x18 through 0x00a2ab40 and slot+0x00 as a
  // string, which is exactly the v3 wrapper/name split.
  eq(a.slotNameOffset, 0x00);
  eq(a.slotWrapperOffset, 0x18);
  // Cross-check against the v3 helpers: they must agree on both offsets.
  eq(
    a.baseOffset + a.slotNameOffset,
    wasm.isaac_sfx_load_voice_name_offset(0),
    "v3 name offset agrees with the destructor",
  );
  eq(
    a.baseOffset + a.slotWrapperOffset,
    wasm.isaac_sfx_load_voice_wrapper_offset(0),
    "v3 wrapper offset agrees with the destructor",
  );
  for (let i = 0; i < a.count; ++i) {
    eq(
      a.baseOffset + i * a.stride + a.slotNameOffset,
      wasm.isaac_sfx_load_voice_name_offset(i),
      `slot ${i} name`,
    );
    eq(
      a.baseOffset + i * a.stride + a.slotWrapperOffset,
      wasm.isaac_sfx_load_voice_wrapper_offset(i),
      `slot ${i} wrapper`,
    );
    eq(wasm.isaac_sfx_load_voice_slot_in_bounds(i), 1, `slot ${i} fits`);
  }
  // The array ends exactly where the entry header begins, and the slot after
  // it is the header â€” the v3 defect, now corroborated.
  eq(a.spanEnd, SFX_ENTRY_OFF_VOICE_COUNT_190, "seven slots end at 0x190");
  eq(wasm.isaac_sfx_load_voice_slot_in_bounds(a.count), 0);
  eq(wasm.isaac_sfx_load_voice_aliases_entry_header(a.count), 1);
  // The entry's own string sits above the header and fills the stride.
  eq(SFX_ENTRY_OFF_NAME_STRING_1A0 + 0x18, SFX_ENTRY_STRIDE);
  countCase();
});

test("PE truth (native): the resize cap is 0x443 and 0x443*0x1b8 == 0x75328", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = SCRATCH + 26200;
  // The shrink path writes `begin + 0x75328` as the new end. That literal is
  // only correct because it is the target count times the stride; assert the
  // identity rather than trusting two independent constants.
  eq(wasm.isaac_sfx_table_target_bytes(), 0x75328);
  eq(wasm.isaac_sfx_table_target_bytes(), SFX_TABLE_TARGET_COUNT * SFX_ENTRY_STRIDE);
  eq(SFX_TABLE_TARGET_BYTES, 0x75328);
  // Both compares are unsigned and the second reuses the first's flags, so
  // an exact hit does nothing at all â€” not "grow by zero".
  eq(wasm.isaac_sfx_table_resize_action(0x444, 0), SFX_TABLE_RESIZE_SHRINK);
  eq(wasm.isaac_sfx_table_resize_action(0x443, 0), SFX_TABLE_RESIZE_NONE);
  eq(
    wasm.isaac_sfx_table_resize_action(0x442, 0x443),
    SFX_TABLE_RESIZE_GROW_INPLACE,
  );
  eq(
    wasm.isaac_sfx_table_resize_action(0x442, 0x442),
    SFX_TABLE_RESIZE_GROW_REALLOC,
  );
  // Unsignedness: a count whose top bit is set is ABOVE the target, not below.
  eq(wasm.isaac_sfx_table_resize_action(0x80000000, 0), SFX_TABLE_RESIZE_SHRINK);
  eq(wasm.isaac_sfx_table_resize_action(0xffffffff, 0), SFX_TABLE_RESIZE_SHRINK);
  eq(
    wasm.isaac_sfx_table_resize_action(0, 0x80000000),
    SFX_TABLE_RESIZE_GROW_INPLACE,
  );
  // The exact-hit arm never reads the capacity at all (0x0092d32d is skipped).
  wasm.isaac_sfx_table_resize_plan(0x443, 0, base);
  const none = readResizePlan(view, base);
  eq(none.capacityRead, false, "0x0092d32d is not reached on an exact hit");
  eq(none.pureComplete, true);
  eq(none.appendCount, 0);
  eq(none.newEndOffset, 0);
  wasm.isaac_sfx_table_resize_plan(0x444, 0, base);
  const shrink = readResizePlan(view, base);
  eq(shrink.capacityRead, false, "the shrink arm does not read the capacity");
  eq(shrink.newEndOffset, 0x75328);
  eq(shrink.destroyRangeNeeded, true);
  wasm.isaac_sfx_table_resize_plan(0, 0x443, base);
  const inplace = readResizePlan(view, base);
  eq(inplace.appendCount, 0x443, "append the whole table");
  eq(inplace.appendNeeded, true);
  eq(inplace.growNeeded, false);
  countCase();
});

test("PE truth (native): the clear walk detaches first and rounds the free down", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = SCRATCH + 26400;
  // All three pointer slots are zeroed before the first destructor runs.
  wasm.isaac_sfx_table_clear_plan(0, 4 * SFX_ENTRY_STRIDE,
                                  8 * SFX_ENTRY_STRIDE, base);
  const p = readClearPlan(view, base);
  eq(p.detachStores, 3);
  eq(p.detachBeforeDestroy, true);
  eq(p.selfAssignGuardTaken, false, "0x0092d1c9 is statically dead");
  eq(p.destroyLoopEnter, true);
  eq(p.elementsDestroyed, 4);
  eq(p.freeNeeded, true);
  eq(p.freeBytes, 8 * SFX_ENTRY_STRIDE);
  eq(p.freeSpanRoundedDown, false);
  // A ragged capacity span is divided and multiplied back, so the block size
  // handed to the deallocator SHRINKS. Passing the raw span would be the
  // natural simplification and would be wrong.
  wasm.isaac_sfx_table_clear_plan(0, 0, 8 * SFX_ENTRY_STRIDE + 1, base);
  const ragged = readClearPlan(view, base);
  eq(ragged.destroyLoopEnter, false, "begin == end runs no destructors");
  eq(ragged.elementsDestroyed, 0);
  eq(ragged.freeNeeded, true, "... but the block is still freed");
  eq(ragged.freeBytes, 8 * SFX_ENTRY_STRIDE);
  eq(ragged.freeSpanRoundedDown, true);
  // A null begin does nothing beyond the three zero stores.
  wasm.isaac_sfx_table_clear_plan(1, 99, 99, base);
  const empty = readClearPlan(view, base);
  eq(empty.freeNeeded, false);
  eq(empty.destroyLoopEnter, false);
  eq(empty.pureComplete, true);
  eq(empty.detachStores, 3, "the detach happens even with a null begin");
  countCase();
});

test("PE truth (native): the shared count model is reused, not re-derived", () => {
  /* The v4 divides use the same 0x094f2095 / sar 4 sequence as the six v1/v2
     roots. Two of the three are the exact same bytes; 0x0092d2dd differs only
     in its destination register. Pin the SEMANTIC identity here so the two
     models can never drift apart. */
  const view = new DataView(wasm.memory.buffer);
  const base = SCRATCH + 26600;
  const spans = [
    0, 1, -1, SFX_ENTRY_STRIDE, SFX_ENTRY_STRIDE - 1, -SFX_ENTRY_STRIDE,
    -SFX_ENTRY_STRIDE + 1, 4 * SFX_ENTRY_STRIDE, 0x7fffffff, -0x80000000,
    0x443 * SFX_ENTRY_STRIDE, 0x75328,
  ];
  for (const span of spans) {
    const shared = wasm.isaac_sfx_entry_count(span);
    wasm.isaac_sfx_table_clear_plan(0, span, span, base);
    const p = readClearPlan(view, base);
    if (span !== 0) {
      eq(p.elementsDestroyed, shared, `clear walk count span=${span}`);
    }
    eq(
      p.freeBytes,
      Math.imul(shared, SFX_ENTRY_STRIDE) | 0,
      `free bytes span=${span}`,
    );
    countCase();
  }
  // The truncating divide really is toward zero, both signs.
  eq(wasm.isaac_sfx_entry_count(SFX_ENTRY_STRIDE - 1), 0);
  eq(wasm.isaac_sfx_entry_count(-(SFX_ENTRY_STRIDE - 1)), 0);
  eq(wasm.isaac_sfx_entry_count(-SFX_ENTRY_STRIDE), -1);
});

test("PE truth (native): proven-dead branches stay flagged, not deleted", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = SCRATCH + 26800;
  eq(wasm.isaac_sfx_dead_branch_count(), 2);
  eq(SFX_DEAD_BRANCH_COUNT, 2);
  wasm.isaac_sfx_dead_branch(SFX_DEAD_BRANCH_PLAY_VOICE_DIV_GUARD, base);
  const d0 = readDeadBranch(view, base);
  eq(d0.va, 0x0092dd7e, "Play's div-by-zero guard");
  eq(d0.taken, 0);
  eq(d0.arithmeticRetained, true, "the guard is modelled, not removed");
  wasm.isaac_sfx_dead_branch(SFX_DEAD_BRANCH_TABLE_SELF_ASSIGN, base);
  const d1 = readDeadBranch(view, base);
  eq(d1.va, 0x0092d1c9, "the table self-assignment guard");
  eq(d1.taken, 0);
  eq(d1.arithmeticRetained, true);
  wasm.isaac_sfx_dead_branch(2, base);
  eq(readDeadBranch(view, base).id, -1, "unknown ids are rejected");
  wasm.isaac_sfx_dead_branch(-1, base);
  eq(readDeadBranch(view, base).id, -1);
  /* "Retained" has to mean something: the guard's own arithmetic must still
     be reachable through the isolated helper, even though the plan can never
     reach it. */
  eq(wasm.isaac_sfx_voice_select(0xffffffff, 0) >>> 0, 0, "guard arithmetic");
  eq(wasm.isaac_sfx_voice_select(0xffffffff, 4) >>> 0, 3);
  // ... and the plan really cannot: a zero count is rejected by the gate.
  eq(
    wasm.isaac_sfx_play_gate(0, 4 * SFX_ENTRY_STRIDE, 0, 1),
    SFX_PLAY_GATE_NO_SAMPLES,
  );
  countCase();
});

test("Wasm matches JS: v4 clear walk / resize / free differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const dtorBase = SCRATCH + 27000;
  const freeBase = SCRATCH + 27100;
  const clearBase = SCRATCH + 27200;
  const resizeBase = SCRATCH + 27300;
  const deadBase = SCRATCH + 27400;

  wasm.isaac_sfx_entry_voice_dtor_args(dtorBase);
  assertPlanEqual(readDtorArgs(view, dtorBase), sfxEntryVoiceDtorArgs(),
                  "dtor args");
  eq(wasm.isaac_sfx_table_target_bytes(), sfxTableTargetBytes());

  const caps = [0, 1, 0x0f, 0x10, 0x11, 0xfff, 0x1000, 0x1001, 0xffffffff];
  const deltas = [0, 1, 3, 4, 5, 0x23, 0x24, 0x1f, 0x20, 0xffffffff];
  for (const cap of caps) {
    for (const delta of deltas) {
      wasm.isaac_sfx_string_free_plan(cap, delta, freeBase);
      assertPlanEqual(
        readFreePlan(view, freeBase),
        sfxStringFreePlan(cap, delta),
        `string free ${cap}/${delta}`,
      );
      wasm.isaac_sfx_block_free_plan(cap, delta, freeBase);
      assertPlanEqual(
        readFreePlan(view, freeBase),
        sfxBlockFreePlan(cap, delta),
        `block free ${cap}/${delta}`,
      );
      countCase();
    }
  }

  const spans = [0, 1, -1, SFX_ENTRY_STRIDE, SFX_ENTRY_STRIDE - 1,
                 -SFX_ENTRY_STRIDE, 7 * SFX_ENTRY_STRIDE,
                 7 * SFX_ENTRY_STRIDE + 5, 0x7fffffff, -0x80000000, 0x75328];
  for (const beginNull of [0, 1]) {
    for (const sizeSpan of spans) {
      for (const capSpan of spans) {
        wasm.isaac_sfx_table_clear_plan(beginNull, sizeSpan, capSpan,
                                        clearBase);
        assertPlanEqual(
          readClearPlan(view, clearBase),
          sfxTableClearPlan(beginNull, sizeSpan, capSpan),
          `clear ${beginNull}/${sizeSpan}/${capSpan}`,
        );
        countCase();
      }
    }
  }

  const counts = [0, 1, 0x442, 0x443, 0x444, 0x1000, 0x7fffffff, 0x80000000,
                  0xffffffff];
  for (const size of counts) {
    for (const cap of counts) {
      eq(
        wasm.isaac_sfx_table_resize_action(size, cap),
        sfxTableResizeAction(size, cap),
        `resize action ${size}/${cap}`,
      );
      wasm.isaac_sfx_table_resize_plan(size, cap, resizeBase);
      assertPlanEqual(
        readResizePlan(view, resizeBase),
        sfxTableResizePlan(size, cap),
        `resize plan ${size}/${cap}`,
      );
      countCase();
    }
  }

  eq(wasm.isaac_sfx_dead_branch_count(), sfxDeadBranchCount());
  for (const id of [-1, 0, 1, 2, 99]) {
    wasm.isaac_sfx_dead_branch(id, deadBase);
    assertPlanEqual(readDeadBranch(view, deadBase), sfxDeadBranch(id),
                    `dead branch ${id}`);
    countCase();
  }
});

test("deterministic randomized differential corpus: v4 table rebuilder", () => {
  let seed = (0x92d140 ^ 0x92ea80) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  /* Bias to the boundaries this arithmetic actually has: the 0x443 cap and
     its neighbours, the 0x10 / 0x1000 allocation edges, the 0x1f slack
     window, exact multiples of the stride, and one-off ragged spans. */
  const countDraw = () => {
    const branch = pick(rnd, 8);
    seen("tableCountDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 1;
      case 2: return 0x442;
      case 3: return 0x443;
      case 4: return 0x444;
      case 5: return 0x80000000;
      case 6: return 0xffffffff;
      default: return pick(rnd, 0x900);
    }
  };
  const spanDraw = () => {
    const branch = pick(rnd, 7);
    seen("tableSpanDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return SFX_ENTRY_STRIDE;
      case 2: return SFX_ENTRY_STRIDE - 1;
      case 3: return -SFX_ENTRY_STRIDE;
      case 4: return Math.imul(pick(rnd, 0x900), SFX_ENTRY_STRIDE) | 0;
      case 5: return (Math.imul(pick(rnd, 0x900), SFX_ENTRY_STRIDE) + 1) | 0;
      default: return (rnd() | 0) >> pick(rnd, 20);
    }
  };
  const sizeDraw = () => {
    const branch = pick(rnd, 7);
    seen("freeSizeDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 0x0f;
      case 2: return 0x10;
      case 3: return 0xfff;
      case 4: return 0x1000;
      case 5: return 0xffffffff;
      default: return pick(rnd, 0x4000);
    }
  };
  const deltaDraw = () => {
    const branch = pick(rnd, 6);
    seen("freeDeltaDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 4;      // slack 0 â€” the smallest legal value
      case 2: return 4 + 0x1f; // slack 0x1f â€” the last legal value
      case 3: return 4 + 0x20; // slack 0x20 â€” the first fatal value
      case 4: return 0xffffffff;
      default: return pick(rnd, 0x80);
    }
  };

  const view = new DataView(wasm.memory.buffer);
  const clearBase = SCRATCH + 28000;
  const resizeBase = SCRATCH + 28200;
  const freeBase = SCRATCH + 28400;

  for (let t = 0; t < 400; ++t) {
    const beginNull = bit(rnd);
    const sizeSpan = spanDraw();
    const capSpan = spanDraw();
    wasm.isaac_sfx_table_clear_plan(beginNull, sizeSpan, capSpan, clearBase);
    const jsClear = sfxTableClearPlan(beginNull, sizeSpan, capSpan);
    seen("clearEnter", jsClear.destroyLoopEnter);
    seen("clearRounded", jsClear.freeSpanRoundedDown);
    seen("clearFree", jsClear.freeNeeded);
    assertPlanEqual(readClearPlan(view, clearBase), jsClear,
                    `t${t} clear ${beginNull}/${sizeSpan}/${capSpan}`);
    /* Cross-helper differential: the clear walk must agree with the count
       model the five v1 roots already use, on the very same span. */
    if (!beginNull && sizeSpan !== 0) {
      eq(
        jsClear.elementsDestroyed,
        wasm.isaac_sfx_entry_count(sizeSpan),
        `t${t} count model shared`,
      );
    }

    const size = countDraw();
    const cap = countDraw();
    wasm.isaac_sfx_table_resize_plan(size, cap, resizeBase);
    const jsResize = sfxTableResizePlan(size, cap);
    seen("resizeAction", jsResize.action);
    assertPlanEqual(readResizePlan(view, resizeBase), jsResize,
                    `t${t} resize ${size}/${cap}`);
    eq(
      wasm.isaac_sfx_table_resize_action(size, cap),
      sfxTableResizeAction(size, cap),
      `t${t} resize action`,
    );

    const fs = sizeDraw();
    const delta = deltaDraw();
    wasm.isaac_sfx_string_free_plan(fs, delta, freeBase);
    const jsStr = sfxStringFreePlan(fs, delta);
    seen("freeNeeded", jsStr.freeNeeded);
    seen("freeBig", jsStr.usesBackPointer);
    seen("freeFatal", jsStr.corruptFatal);
    assertPlanEqual(readFreePlan(view, freeBase), jsStr,
                    `t${t} string free ${fs}/${delta}`);
    wasm.isaac_sfx_block_free_plan(fs, delta, freeBase);
    assertPlanEqual(readFreePlan(view, freeBase), sfxBlockFreePlan(fs, delta),
                    `t${t} block free ${fs}/${delta}`);
    countCase();
  }
});

/* ---------- v5 struct layouts ---------- */

/* IsaacSfxAttrSample: 6 Ã— 4 bytes â†’ 24 bytes */
const ATTR_SAMPLE_SIZE = 24;
const ATTR_SAMPLE_OFF = {
  nameNull: 0,
  namePtr: 4,
  nameLen: 8,
  valueNull: 12,
  nextFlag: 16,
  nextNull: 20,
};

/* IsaacSfxAttrWalkPlan: 11 Ã— 4 bytes â†’ 44 bytes */
const ATTR_WALK_SIZE = 44;
const ATTR_WALK_OFF = {
  attrsVisited: 0,
  numericCount: 4,
  stringCount: 8,
  inertCount: 12,
  valueFallbackCount: 16,
  numericMask: 20,
  stringMask: 24,
  fallbackMask: 28,
  hostParseNeeded: 32,
  hostAssignNeeded: 36,
  pureComplete: 40,
};

/* IsaacSfxTableFillPlan: 13 Ã— 4 bytes â†’ 52 bytes */
const FILL_PLAN_SIZE = 52;
const FILL_PLAN_OFF = {
  appendMode: 0,
  countRecomputed: 4,
  targetIndex: 8,
  targetOffset: 12,
  outOfBoundsWarn: 16,
  idRecheckNeeded: 20,
  fillSkipped: 24,
  fillNeeded: 28,
  slotCopies: 32,
  headerStores: 36,
  tailCopies: 40,
  entryStringAssign: 44,
  pureComplete: 48,
};

/* IsaacSfxSampleSlotPlan: 5 Ã— 4 bytes â†’ 20 bytes */
const SLOT_PLAN_SIZE = 20;
const SLOT_PLAN_OFF = {
  overflow: 0,
  slotOffset: 4,
  countAfter: 8,
  attrWalkNeeded: 12,
  pureComplete: 16,
};

function readAttrWalk(view, base) {
  return {
    attrsVisited: readI32(view, base + ATTR_WALK_OFF.attrsVisited),
    numericCount: readI32(view, base + ATTR_WALK_OFF.numericCount),
    stringCount: readI32(view, base + ATTR_WALK_OFF.stringCount),
    inertCount: readI32(view, base + ATTR_WALK_OFF.inertCount),
    valueFallbackCount:
      readI32(view, base + ATTR_WALK_OFF.valueFallbackCount),
    numericMask: readU32(view, base + ATTR_WALK_OFF.numericMask),
    stringMask: readU32(view, base + ATTR_WALK_OFF.stringMask),
    fallbackMask: readU32(view, base + ATTR_WALK_OFF.fallbackMask),
    hostParseNeeded: readI32(view, base + ATTR_WALK_OFF.hostParseNeeded) !== 0,
    hostAssignNeeded:
      readI32(view, base + ATTR_WALK_OFF.hostAssignNeeded) !== 0,
    pureComplete: readI32(view, base + ATTR_WALK_OFF.pureComplete) !== 0,
  };
}

function readFillPlan(view, base) {
  return {
    appendMode: readI32(view, base + FILL_PLAN_OFF.appendMode) !== 0,
    countRecomputed: readI32(view, base + FILL_PLAN_OFF.countRecomputed) !== 0,
    targetIndex: readI32(view, base + FILL_PLAN_OFF.targetIndex),
    targetOffset: readU32(view, base + FILL_PLAN_OFF.targetOffset),
    outOfBoundsWarn: readI32(view, base + FILL_PLAN_OFF.outOfBoundsWarn) !== 0,
    idRecheckNeeded: readI32(view, base + FILL_PLAN_OFF.idRecheckNeeded) !== 0,
    fillSkipped: readI32(view, base + FILL_PLAN_OFF.fillSkipped) !== 0,
    fillNeeded: readI32(view, base + FILL_PLAN_OFF.fillNeeded) !== 0,
    slotCopies: readI32(view, base + FILL_PLAN_OFF.slotCopies),
    headerStores: readI32(view, base + FILL_PLAN_OFF.headerStores),
    tailCopies: readI32(view, base + FILL_PLAN_OFF.tailCopies),
    entryStringAssign:
      readI32(view, base + FILL_PLAN_OFF.entryStringAssign) !== 0,
    pureComplete: readI32(view, base + FILL_PLAN_OFF.pureComplete) !== 0,
  };
}

function readSlotPlan(view, base) {
  return {
    overflow: readI32(view, base + SLOT_PLAN_OFF.overflow) !== 0,
    slotOffset: readU32(view, base + SLOT_PLAN_OFF.slotOffset),
    countAfter: readU32(view, base + SLOT_PLAN_OFF.countAfter),
    attrWalkNeeded: readI32(view, base + SLOT_PLAN_OFF.attrWalkNeeded) !== 0,
    pureComplete: readI32(view, base + SLOT_PLAN_OFF.pureComplete) !== 0,
  };
}

/* IsaacSfxWarnStack: 4 x 4 bytes -> 16 bytes */
const WARN_STACK_SIZE = 16;
const WARN_STACK_OFF = {
  argCount: 0,
  varargCount: 4,
  level: 8,
  formatStringVa: 12,
};

function readWarnStack(view, base) {
  return {
    argCount: readI32(view, base + WARN_STACK_OFF.argCount),
    varargCount: readI32(view, base + WARN_STACK_OFF.varargCount),
    level: readI32(view, base + WARN_STACK_OFF.level),
    formatStringVa: readU32(view, base + WARN_STACK_OFF.formatStringVa),
  };
}

/* IsaacSfxTailPlan: 21 x 4 bytes -> 84 bytes */
const TAIL_PLAN_SIZE = 84;
const TAIL_PLAN_OFF = {
  entryIndex: 0,
  entryOffset: 4,
  loadNeeded: 8,
  counterBefore: 12,
  counterAfter: 16,
  protoFreeNeeded: 20,
  protoUsesBackPointer: 24,
  protoFreeSize: 28,
  protoSlackChecked: 32,
  protoCorruptFatal: 36,
  protoResetStores: 40,
  dtorRuns: 44,
  dtorCount: 48,
  dtorStride: 52,
  dtorVa: 56,
  freeBeforeDtor: 60,
  resetBeforeDtor: 64,
  loadBeforeFree: 68,
  loopBack: 72,
  exitReached: 76,
  pureComplete: 80,
};

function readTailPlan(view, base) {
  return {
    entryIndex: readI32(view, base + TAIL_PLAN_OFF.entryIndex),
    entryOffset: readU32(view, base + TAIL_PLAN_OFF.entryOffset),
    loadNeeded: readI32(view, base + TAIL_PLAN_OFF.loadNeeded) !== 0,
    counterBefore: readU32(view, base + TAIL_PLAN_OFF.counterBefore),
    counterAfter: readU32(view, base + TAIL_PLAN_OFF.counterAfter),
    protoFreeNeeded:
      readI32(view, base + TAIL_PLAN_OFF.protoFreeNeeded) !== 0,
    protoUsesBackPointer:
      readI32(view, base + TAIL_PLAN_OFF.protoUsesBackPointer) !== 0,
    protoFreeSize: readU32(view, base + TAIL_PLAN_OFF.protoFreeSize),
    protoSlackChecked: readI32(view, base + TAIL_PLAN_OFF.protoSlackChecked) !== 0,
    protoCorruptFatal:
      readI32(view, base + TAIL_PLAN_OFF.protoCorruptFatal) !== 0,
    protoResetStores: readI32(view, base + TAIL_PLAN_OFF.protoResetStores),
    dtorRuns: readI32(view, base + TAIL_PLAN_OFF.dtorRuns) !== 0,
    dtorCount: readI32(view, base + TAIL_PLAN_OFF.dtorCount),
    dtorStride: readI32(view, base + TAIL_PLAN_OFF.dtorStride),
    dtorVa: readU32(view, base + TAIL_PLAN_OFF.dtorVa),
    freeBeforeDtor: readI32(view, base + TAIL_PLAN_OFF.freeBeforeDtor) !== 0,
    resetBeforeDtor:
      readI32(view, base + TAIL_PLAN_OFF.resetBeforeDtor) !== 0,
    loadBeforeFree: readI32(view, base + TAIL_PLAN_OFF.loadBeforeFree) !== 0,
    loopBack: readI32(view, base + TAIL_PLAN_OFF.loopBack) !== 0,
    exitReached: readI32(view, base + TAIL_PLAN_OFF.exitReached) !== 0,
    pureComplete: readI32(view, base + TAIL_PLAN_OFF.pureComplete) !== 0,
  };
}

/* IsaacSfxSoundChainPlan: 6 x 4 bytes -> 24 bytes */
const CHAIN_PLAN_SIZE = 24;
const CHAIN_PLAN_OFF = {
  headNonzero: 0,
  soundsVisited: 4,
  loopsBack: 8,
  stopsAtNull: 12,
  truncated: 16,
  pureComplete: 20,
};

function readChainPlan(view, base) {
  return {
    headNonzero: readI32(view, base + CHAIN_PLAN_OFF.headNonzero) !== 0,
    soundsVisited: readI32(view, base + CHAIN_PLAN_OFF.soundsVisited),
    loopsBack: readI32(view, base + CHAIN_PLAN_OFF.loopsBack),
    stopsAtNull: readI32(view, base + CHAIN_PLAN_OFF.stopsAtNull) !== 0,
    truncated: readI32(view, base + CHAIN_PLAN_OFF.truncated) !== 0,
    pureComplete: readI32(view, base + CHAIN_PLAN_OFF.pureComplete) !== 0,
  };
}

/* Chain next-link flags array: 32 x 4 bytes. */
const CHAIN_FLAGS_BASE = SCRATCH + 34500;
const TAIL_PLAN_BASE = SCRATCH + 34600;
const WARN_STACK_BASE = SCRATCH + 34700;

/* Writes a byte string (NULs allowed) into scratch and returns its address.
   `view` is a DataView over wasm memory; the write is through the
   Uint8Array so the Wasm side sees exactly the JS oracle's bytes. */
function writeName(view, base, s) {
  for (let k = 0; k < s.length; ++k) {
    view.setUint8(base + k, s.charCodeAt(k) & 0xff);
  }
  return base;
}

const ATTR_WALK_NAME_BASE = SCRATCH + 30000; /* name slots, 64 B each */
const ATTR_WALK_BASE = SCRATCH + 33000;    /* sample array (33 x 24 B) */
const ATTR_WALK_PLAN_BASE = SCRATCH + 34000;
const FILL_PLAN_BASE = SCRATCH + 31000;
const SLOT_PLAN_BASE = SCRATCH + 31100;

/* ------------------------------------------------------------------ *
 * v5: PE ground truth asserted directly against the native module.    *
 * A C++ mutation cannot reach the JS oracle, so agreement checks      *
 * alone leave mutants alive â€” these pin the machine facts as          *
 * literals first.                                                     *
 * ------------------------------------------------------------------ */

test("v5 PE truth (native): inline strcmp literals", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = ATTR_WALK_NAME_BASE;
  const s = (str) => {
    writeName(view, base, str);
    return base;
  };
  /* Exact matches against all five constants. */
  eq(wasm.isaac_sfx_attr_strcmp(0, s("id\0"), 3, 0), 0, "id");
  eq(wasm.isaac_sfx_attr_strcmp(0, s("name\0"), 5, 1), 0, "name");
  eq(wasm.isaac_sfx_attr_strcmp(0, s("path\0"), 5, 2), 0, "path");
  eq(wasm.isaac_sfx_attr_strcmp(0, s("weight\0"), 7, 3), 0, "weight");
  eq(wasm.isaac_sfx_attr_strcmp(0, s("sample\0"), 7, 4), 0, "sample");
  /* Prefix: the NUL byte is smaller than any letter -> -1. */
  eq(wasm.isaac_sfx_attr_strcmp(0, s("i\0"), 2, 0), -1, "prefix i vs id");
  eq(wasm.isaac_sfx_attr_strcmp(0, s("id\0"), 3, 1), -1, "id vs name");
  /* Longer: the constant's NUL is smaller than the extra byte -> +1. */
  eq(wasm.isaac_sfx_attr_strcmp(0, s("idx\0"), 4, 0), 1, "idx vs id");
  /* Case: 'I' (0x49) < 'i' (0x69), unsigned. */
  eq(wasm.isaac_sfx_attr_strcmp(0, s("ID\0"), 3, 0), -1, "ID vs id");
  /* 0xff > 'i' â€” UNSIGNED byte compare: a signed compare would say -1. */
  eq(wasm.isaac_sfx_attr_strcmp(0, s("\xff\x69\0"), 3, 1), 1,
    "0xff byte vs name");
  eq(wasm.isaac_sfx_attr_strcmp(0, s("\x00\x00"), 2, 0), -1, "empty vs id");
  /* name_null is a FULL-WORD test: 1 and 0x100 are both "null", the empty
     string never matches a non-empty constant, and 0x100 must NOT read
     memory (the PE substitutes the fallback on `test edi,edi`). */
  eq(wasm.isaac_sfx_attr_strcmp(1, 0, 0, 0), -1, "null vs id");
  eq(wasm.isaac_sfx_attr_strcmp(0x100, 0, 0, 0), -1, "0x100 null vs id");
  eq(wasm.isaac_sfx_attr_strcmp(0xffffffff, 0, 0, 2), -1,
    "0xffffffff null vs path");
  /* Out-of-range constant never matches. */
  eq(wasm.isaac_sfx_attr_strcmp(0, s("id\0"), 3, 5), 1, "bad index");
  eq(wasm.isaac_sfx_attr_strcmp(0, s("id\0"), 3, -1), 1, "negative index");
  countCase();
});

test("v5 PE truth (native): arm / action / strlen / walk tail literals", () => {
  /* The two-compare arm shape: the second compare only runs when the first
     missed, so a first-match wins regardless of the second result. */
  eq(wasm.isaac_sfx_attr_arm(0, 0), SFX_ATTR_ARM_FIRST, "first wins");
  eq(wasm.isaac_sfx_attr_arm(0, 1), SFX_ATTR_ARM_FIRST, "first wins (2nd hit)");
  eq(wasm.isaac_sfx_attr_arm(1, 0), SFX_ATTR_ARM_SECOND, "second");
  eq(wasm.isaac_sfx_attr_arm(-1, -1), SFX_ATTR_ARM_NONE, "none");
  eq(wasm.isaac_sfx_attr_arm(0x100, 0), SFX_ATTR_ARM_SECOND,
    "non-zero full word is a miss");
  /* Site A/B -> action mapping. */
  eq(wasm.isaac_sfx_attr_arm_action(SFX_ATTR_ARM_FIRST, SFX_ATTR_SITE_ENTRY),
    SFX_ATTR_ACTION_NUMERIC_PARSE, "entry first = parse");
  eq(wasm.isaac_sfx_attr_arm_action(SFX_ATTR_ARM_SECOND, SFX_ATTR_SITE_ENTRY),
    SFX_ATTR_ACTION_STRING_ASSIGN, "entry second = assign");
  eq(wasm.isaac_sfx_attr_arm_action(SFX_ATTR_ARM_FIRST, SFX_ATTR_SITE_SLOT),
    SFX_ATTR_ACTION_STRING_ASSIGN, "slot first = assign");
  eq(wasm.isaac_sfx_attr_arm_action(SFX_ATTR_ARM_SECOND, SFX_ATTR_SITE_SLOT),
    SFX_ATTR_ACTION_NUMERIC_PARSE, "slot second = parse");
  eq(wasm.isaac_sfx_attr_arm_action(SFX_ATTR_ARM_NONE, SFX_ATTR_SITE_ENTRY),
    SFX_ATTR_ACTION_NONE, "none");
  /* Non-zero site means SLOT (normalize_form convention). */
  eq(wasm.isaac_sfx_attr_arm_action(SFX_ATTR_ARM_FIRST, 7),
    SFX_ATTR_ACTION_STRING_ASSIGN, "nonzero site = slot");
  /* Inline strlen over the value, NUL INCLUDED in max_len. */
  const view = new DataView(wasm.memory.buffer);
  const base = ATTR_WALK_NAME_BASE;
  writeName(view, base, "sound.ogg\0");
  eq(wasm.isaac_sfx_attr_value_strlen(0, base, 10), 9, "strlen sound.ogg");
  eq(wasm.isaac_sfx_attr_value_strlen(0, base, 9), 9, "strlen no NUL read");
  eq(wasm.isaac_sfx_attr_value_strlen(0, base, 5), 5, "truncated max");
  eq(wasm.isaac_sfx_attr_value_strlen(1, 0, 10), 0, "null -> empty");
  eq(wasm.isaac_sfx_attr_value_strlen(0x100, 0, 10), 0,
    "0x100 null -> empty (full-word)");
  eq(wasm.isaac_sfx_attr_value_strlen(0, base, 0), 0, "max 0");
  /* The loop-bottom continue test: BOTH full-word conditions. */
  eq(wasm.isaac_sfx_attr_walk_continue(1, 0), 1, "flag set, next ok");
  eq(wasm.isaac_sfx_attr_walk_continue(1, 1), 0, "next null");
  eq(wasm.isaac_sfx_attr_walk_continue(0, 0), 0, "flag clear");
  eq(wasm.isaac_sfx_attr_walk_continue(0x100, 0), 1,
    "flag is full-word (0x100 != 0)");
  /* Constant table. */
  eq(wasm.isaac_sfx_attr_constant_len(0), 2, "id len");
  eq(wasm.isaac_sfx_attr_constant_len(1), 4, "name len");
  eq(wasm.isaac_sfx_attr_constant_len(2), 4, "path len");
  eq(wasm.isaac_sfx_attr_constant_len(3), 6, "weight len");
  eq(wasm.isaac_sfx_attr_constant_len(4), 6, "sample len");
  eq(wasm.isaac_sfx_attr_constant_len(5), 0, "bad index");
  eq(wasm.isaac_sfx_attr_constant_va(0), SFX_ATTR_NAME_ID_VA, "id va");
  eq(wasm.isaac_sfx_attr_constant_va(3), SFX_ATTR_NAME_WEIGHT_VA, "weight va");
  eq(wasm.isaac_sfx_attr_constant_va(4), SFX_XML_SAMPLE_ELEMENT_VA,
    "sample va");
  eq(wasm.isaac_sfx_attr_constant_va(-1), 0, "bad index va");
  /* The append flag is a LOW-BYTE test (cmp byte [arg+0xc],0). */
  eq(wasm.isaac_sfx_table_append_flag(0), 0, "flag 0");
  eq(wasm.isaac_sfx_table_append_flag(1), 1, "flag 1");
  eq(wasm.isaac_sfx_table_append_flag(0x100), 0, "flag 0x100 -> low byte 0");
  eq(wasm.isaac_sfx_table_append_flag(0x1ff), 1, "flag 0x1ff -> low byte 1");
  eq(wasm.isaac_sfx_table_append_flag(0xffffffff), 1, "flag all ones");
  countCase();
});

test("v5 PE truth (native): walk plans (entry and slot sites)", () => {
  const view = new DataView(wasm.memory.buffer);
  const samples = ATTR_WALK_BASE;
  const plan = ATTR_WALK_PLAN_BASE;
  const nameBase = ATTR_WALK_NAME_BASE;
  /* Each sample gets its own name slot so later writes cannot clobber an
     earlier sample's bytes (the Wasm walk reads names at call time). */
  const put = (i, s, extra = {}) => {
    const off = samples + i * ATTR_SAMPLE_SIZE;
    writeName(view, nameBase + i * 64, s);
    view.setInt32(off + ATTR_SAMPLE_OFF.nameNull, extra.nameNull ?? 0, true);
    view.setInt32(off + ATTR_SAMPLE_OFF.namePtr, nameBase + i * 64, true);
    view.setInt32(off + ATTR_SAMPLE_OFF.nameLen, s.length, true);
    view.setInt32(off + ATTR_SAMPLE_OFF.valueNull, extra.valueNull ?? 0, true);
    view.setInt32(off + ATTR_SAMPLE_OFF.nextFlag, extra.nextFlag ?? 0, true);
    view.setInt32(off + ATTR_SAMPLE_OFF.nextNull, extra.nextNull ?? 0, true);
  };
  /* Head null: no attrs at all, nothing to do. */
  wasm.isaac_sfx_attr_walk(1, samples, 8, SFX_ATTR_SITE_ENTRY, plan);
  eq(readAttrWalk(view, plan).attrsVisited, 0, "head null visited");
  eq(readAttrWalk(view, plan).pureComplete, true, "head null pure");
  /* One "id" attr with a null value: the parse arm runs with the empty
     string fallback. */
  put(0, "id\0", { valueNull: 1 });
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_ENTRY, plan);
  let w = readAttrWalk(view, plan);
  eq(w.attrsVisited, 1, "single attr visited");
  eq(w.numericCount, 1, "id arm is numeric");
  eq(w.stringCount, 0, "no string arm");
  eq(w.inertCount, 0, "no inert");
  eq(w.valueFallbackCount, 1, "null value fallback");
  eq(w.numericMask, 1, "mask bit 0");
  eq(w.fallbackMask, 1, "fallback bit 0");
  eq(w.hostParseNeeded, true, "parse needed");
  eq(w.hostAssignNeeded, false, "no assign");
  eq(w.pureComplete, false, "host parse");
  /* Second attr continues only when flag set AND next non-null. */
  put(0, "id\0", { nextFlag: 1, nextNull: 1 });
  put(1, "name\0");
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_ENTRY, plan);
  w = readAttrWalk(view, plan);
  eq(w.attrsVisited, 1, "next null stops the walk");
  eq(w.numericMask, 1, "only first attr seen");
  put(0, "id\0", { nextFlag: 1, nextNull: 0 });
  put(1, "name\0");
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_ENTRY, plan);
  w = readAttrWalk(view, plan);
  eq(w.attrsVisited, 2, "two attrs visited");
  eq(w.numericCount, 1, "id numeric");
  eq(w.stringCount, 1, "name string");
  eq(w.numericMask, 1, "attr 0 numeric");
  eq(w.stringMask, 2, "attr 1 string");
  eq(w.hostAssignNeeded, true, "assign needed");
  /* An unknown name is inert and keeps the walk pure. */
  put(0, "volume\0", { nextFlag: 1, nextNull: 0 });
  put(1, "loop\0", { nextFlag: 0 });
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_ENTRY, plan);
  w = readAttrWalk(view, plan);
  eq(w.attrsVisited, 2, "two inert attrs");
  eq(w.inertCount, 2, "both inert");
  eq(w.numericCount, 0, "no parse");
  eq(w.stringCount, 0, "no assign");
  eq(w.pureComplete, true, "pure walk");
  /* A null name is the empty string and matches nothing. */
  put(0, "", { nameNull: 1 });
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_ENTRY, plan);
  eq(readAttrWalk(view, plan).inertCount, 1, "null name inert");
  /* An INERT attr with a null value is not a fallback: the fallback only
     counts on an arm that actually runs a host action. */
  put(0, "volume\0", { valueNull: 1 });
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_ENTRY, plan);
  w = readAttrWalk(view, plan);
  eq(w.inertCount, 1, "inert with null value");
  eq(w.valueFallbackCount, 0, "no fallback for inert attrs");
  eq(w.fallbackMask, 0, "no fallback bit");
  /* Site SLOT: first = path (assign), second = weight (parse). */
  put(0, "path\0");
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_SLOT, plan);
  w = readAttrWalk(view, plan);
  eq(w.stringCount, 1, "slot path -> string");
  eq(w.numericCount, 0, "slot path not numeric");
  put(0, "weight\0");
  wasm.isaac_sfx_attr_walk(0, samples, 8, SFX_ATTR_SITE_SLOT, plan);
  w = readAttrWalk(view, plan);
  eq(w.numericCount, 1, "slot weight -> numeric");
  eq(w.stringCount, 0, "slot weight not string");
  /* Non-zero site means SLOT. */
  put(0, "path\0");
  wasm.isaac_sfx_attr_walk(0, samples, 8, 7, plan);
  eq(readAttrWalk(view, plan).stringCount, 1, "nonzero site = slot");
  /* Count bounds the array even if the walk would continue. */
  put(0, "id\0", { nextFlag: 1, nextNull: 0 });
  put(1, "name\0");
  wasm.isaac_sfx_attr_walk(0, samples, 1, SFX_ATTR_SITE_ENTRY, plan);
  eq(readAttrWalk(view, plan).attrsVisited, 1, "count bounds the walk");
  /* 33 attrs: the arm MASKS are capped at 32 bits (a modeling bound â€” the
     PE itself has none), while the COUNTS keep going. A mutant that drops
     the cap would set bit 32 via the shifted-1 wrap and be caught here. */
  for (let i = 0; i < 32; ++i) {
    put(i, "id\0", { nextFlag: 1, nextNull: 0 });
  }
  put(32, "name\0");
  wasm.isaac_sfx_attr_walk(0, samples, 33, SFX_ATTR_SITE_ENTRY, plan);
  w = readAttrWalk(view, plan);
  eq(w.attrsVisited, 33, "33 attrs visited");
  eq(w.numericCount, 32, "32 numeric arms");
  eq(w.stringCount, 1, "1 string arm");
  eq(w.numericMask, 0xffffffff, "mask capped at 32 bits");
  eq(w.stringMask, 0, "bit 32 does not wrap into the mask");
  countCase();
});

test("v5 PE truth (native): fill plan and sample-slot plan literals", () => {
  const view = new DataView(wasm.memory.buffer);
  const plan = FILL_PLAN_BASE;
  /* Non-append, in-bounds id: fill with id*0x1b8, no warn. */
  wasm.isaac_sfx_table_fill_plan(0, 5, 0, 0, 0, plan);
  let f = readFillPlan(view, plan);
  eq(f.appendMode, false, "no append");
  eq(f.countRecomputed, false, "no count divide");
  eq(f.targetIndex, 5, "target id");
  eq(f.targetOffset, 5 * SFX_ENTRY_STRIDE, "target offset");
  eq(f.outOfBoundsWarn, false, "no warn");
  eq(f.fillSkipped, false, "fills");
  eq(f.fillNeeded, true, "fill needed");
  eq(f.slotCopies, 7, "seven slot copies");
  eq(f.headerStores, 6, "six header stores");
  eq(f.tailCopies, 14, "tail byte+dword per slot");
  eq(f.entryStringAssign, true, "entry string assign");
  eq(f.pureComplete, false, "never pure");
  /* The id bound: id >= 0x443 warns, then the RE-READ id decides. */
  wasm.isaac_sfx_table_fill_plan(0, 0x443, 0x442, 0, 0, plan);
  f = readFillPlan(view, plan);
  eq(f.outOfBoundsWarn, true, "warn at 0x443");
  eq(f.idRecheckNeeded, true, "recheck after warn");
  eq(f.fillSkipped, false, "re-read id < 0x443 still fills");
  eq(f.fillNeeded, true, "fill after recheck");
  wasm.isaac_sfx_table_fill_plan(0, 0x443, 0x443, 0, 0, plan);
  f = readFillPlan(view, plan);
  eq(f.fillSkipped, true, "re-read id >= 0x443 skips");
  eq(f.fillNeeded, false, "no fill");
  eq(f.slotCopies, 0, "no slot copies");
  eq(f.entryStringAssign, false, "no entry string assign");
  wasm.isaac_sfx_table_fill_plan(0, 0x444, 0x443, 0, 0, plan);
  f = readFillPlan(view, plan);
  eq(f.outOfBoundsWarn, true, "warn at 0x444");
  eq(f.fillSkipped, true, "0x444 re-read skips");
  /* Negative id: js fills directly, NO warn â€” original defect, pinned. */
  wasm.isaac_sfx_table_fill_plan(0, -1, 0, 0, 0, plan);
  f = readFillPlan(view, plan);
  eq(f.outOfBoundsWarn, false, "negative id never warns");
  eq(f.fillNeeded, true, "negative id fills");
  eq(f.targetOffset >>> 0, 0xfffffe48, "(-1*0x1b8) wraps");
  wasm.isaac_sfx_table_fill_plan(0, 0x80000000, 0, 0, 0, plan);
  f = readFillPlan(view, plan);
  eq(f.outOfBoundsWarn, false, "0x80000000 is negative -> no warn");
  eq(f.fillNeeded, true, "0x80000000 fills");
  /* Append mode: the flag's LOW byte decides; the id is discarded and the
     shared count divide re-derives the index. */
  wasm.isaac_sfx_table_fill_plan(1, 7, 0, 3 * SFX_ENTRY_STRIDE, 0, plan);
  f = readFillPlan(view, plan);
  eq(f.appendMode, true, "append on flag 1");
  eq(f.countRecomputed, true, "count divide ran");
  eq(f.targetIndex, 3, "target is the count, not the id");
  eq(f.targetOffset, 3 * SFX_ENTRY_STRIDE, "count offset");
  eq(f.outOfBoundsWarn, false, "append never warns");
  eq(f.fillNeeded, true, "append fills");
  wasm.isaac_sfx_table_fill_plan(0x100, 7, 0, 0, 0, plan);
  eq(readFillPlan(view, plan).appendMode, false, "0x100 low byte is 0");
  wasm.isaac_sfx_table_fill_plan(0x1ff, 7, 0, 0, 0, plan);
  eq(readFillPlan(view, plan).appendMode, true, "0x1ff low byte is 1");
  /* Negative span: the count divide wraps exactly like entry_count. */
  wasm.isaac_sfx_table_fill_plan(1, 0, 0, -SFX_ENTRY_STRIDE, 0, plan);
  f = readFillPlan(view, plan);
  eq(f.targetIndex, -1, "count of a negative span");
  eq(f.targetOffset >>> 0, 0xfffffe48, "wrapped count offset");
  eq(f.targetIndex, wasm.isaac_sfx_entry_count(-SFX_ENTRY_STRIDE),
    "cross-helper: shared count model");
  /* The string self-assign guard suppresses the entry string assign. */
  wasm.isaac_sfx_table_fill_plan(1, 0, 0, 0, 1, plan);
  eq(readFillPlan(view, plan).entryStringAssign, false,
    "self-assign suppresses entry string");
  /* Sample-slot plan. */
  const sp = SLOT_PLAN_BASE;
  wasm.isaac_sfx_sample_slot_plan(0, sp);
  let s = readSlotPlan(view, sp);
  eq(s.overflow, false, "count 0 ok");
  eq(s.slotOffset, 8, "slot 0 base");
  eq(s.countAfter, 1, "count becomes 1");
  eq(s.attrWalkNeeded, true, "walk runs");
  eq(s.pureComplete, true, "only the count store");
  wasm.isaac_sfx_sample_slot_plan(6, sp);
  s = readSlotPlan(view, sp);
  eq(s.overflow, false, "count 6 ok");
  eq(s.slotOffset, 8 + 6 * SFX_VOICE_STRIDE, "slot 6 base");
  eq(s.countAfter, 7, "count becomes 7");
  eq(s.slotOffset, wasm.isaac_sfx_load_voice_name_offset(6),
    "cross-helper: slot base == voice name offset");
  wasm.isaac_sfx_sample_slot_plan(7, sp);
  s = readSlotPlan(view, sp);
  eq(s.overflow, true, "count 7 overflows");
  eq(s.slotOffset, 0, "no slot on overflow");
  eq(s.countAfter, 7, "count unchanged on overflow");
  eq(s.attrWalkNeeded, false, "no walk on overflow");
  eq(s.pureComplete, false, "warn is host");
  /* UNSIGNED compare: huge counts overflow too. */
  wasm.isaac_sfx_sample_slot_plan(0xffffffff, sp);
  eq(readSlotPlan(view, sp).overflow, true, "0xffffffff overflows");
  wasm.isaac_sfx_sample_slot_plan(0x80000000, sp);
  eq(readSlotPlan(view, sp).overflow, true,
    "0x80000000 overflows (unsigned, not signed)");
  /* Weight offset: slot base + 0x34 == 0x3c + i*0x38. */
  eq(wasm.isaac_sfx_slot_weight_offset(0), 0x3c, "weight 0");
  eq(wasm.isaac_sfx_slot_weight_offset(3), 0x3c + 3 * SFX_VOICE_STRIDE,
    "weight 3");
  eq(wasm.isaac_sfx_slot_weight_offset(6), 0x3c + 6 * SFX_VOICE_STRIDE,
    "weight 6");
  eq(wasm.isaac_sfx_slot_weight_offset(3),
    wasm.isaac_sfx_load_stream_byte_offset(3) + 4,
    "cross-helper: weight == stream byte + 4");
  countCase();
});

test("v5 PE truth (native): sample node name test literals", () => {
  const view = new DataView(wasm.memory.buffer);
  const base = ATTR_WALK_NAME_BASE;
  const s = (str, off = 0) => {
    for (let k = 0; k < str.length; ++k) {
      view.setUint8(base + off + k, str.charCodeAt(k) & 0xff);
    }
    return base + off;
  };
  eq(wasm.isaac_sfx_xml_node_is_sample(6, s("sample"), 6), 1, "sample");
  eq(wasm.isaac_sfx_xml_node_is_sample(7, s("samples"), 7), 0, "len 7");
  eq(wasm.isaac_sfx_xml_node_is_sample(6, s("samply"), 6), 0, "last byte");
  eq(wasm.isaac_sfx_xml_node_is_sample(6, s("Sample"), 6), 0, "case");
  eq(wasm.isaac_sfx_xml_node_is_sample(0, s(""), 0), 0, "len 0");
  eq(wasm.isaac_sfx_xml_node_is_sample(6, s("sample"), 5), 0,
    "under-supplied cap");
  /* Full-word length test: 0x100 != 6 -> miss without reading. */
  eq(wasm.isaac_sfx_xml_node_is_sample(0x100, 0, 0), 0, "wide len");
  /* The name pointer fallback: a null child name is "" (len 0) -> miss. */
  eq(wasm.isaac_sfx_xml_node_is_sample(0, 0, 0), 0, "null name ptr");
  countCase();
});

test("v5 differential: deterministic randomized corpus", () => {
  let seed = (0x92d480 ^ 0x92d5b0 ^ 0x92d8ac) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const view = new DataView(wasm.memory.buffer);
  const samples = ATTR_WALK_BASE;
  const plan = ATTR_WALK_PLAN_BASE;
  const nameBase = ATTR_WALK_NAME_BASE;
  const names = ["id\0", "name\0", "path\0", "weight\0", "sample\0",
    "i\0", "idx\0", "ID\0", "volume\0", "", "nameX\0", "x\0"];

  const strcmpCase = () => {
    const nameNull = pick(rnd, 2);
    const nameIdx = pick(rnd, names.length);
    const constIdx = pick(rnd, SFX_ATTR_CONSTANT_COUNT + 1); // incl. invalid
    const wide = pick(rnd, 3) === 0;
    const nNull = wide && pick(rnd, 2) === 0 ? 0x100 : nameNull;
    const str = names[nameIdx];
    writeName(view, nameBase, str);
    const got = wasm.isaac_sfx_attr_strcmp(
      nNull, nameBase, str.length, constIdx);
    const want = sfxAttrStrcmp(nNull, str, str.length, constIdx);
    eq(got, want, `strcmp ${nNull}/${str}/${constIdx}`);
    seen("strcmpName", nameIdx);
    seen("strcmpConst", constIdx);
    seen("strcmpNull", nNull);
  };

  const sampleDraw = (i) => ({
    nameNull: pick(rnd, 4) === 0 ? 1 : 0,
    name: names[pick(rnd, names.length)],
    nameLen: 0,
    valueNull: pick(rnd, 4) === 0 ? 1 : 0,
    nextFlag: pick(rnd, 3) === 0 ? 0 : 1,
    nextNull: pick(rnd, 3) === 0 ? 1 : 0,
  });

  const walkCase = (tc) => {
    const site = pick(rnd, 3) === 0 ? 1 : 0;
    const headNull = pick(rnd, 4) === 0 ? 1 : 0;
    const count = 1 + pick(rnd, 4); // 1..4 samples
    const jsSamples = [];
    for (let i = 0; i < count; ++i) {
      const s = sampleDraw(i);
      s.nameLen = s.name.length;
      jsSamples.push(s);
      const off = samples + i * ATTR_SAMPLE_SIZE;
      writeName(view, nameBase + i * 64, s.name);
      view.setInt32(off + ATTR_SAMPLE_OFF.nameNull, s.nameNull, true);
      view.setInt32(off + ATTR_SAMPLE_OFF.namePtr, nameBase + i * 64, true);
      view.setInt32(off + ATTR_SAMPLE_OFF.nameLen, s.nameLen, true);
      view.setInt32(off + ATTR_SAMPLE_OFF.valueNull, s.valueNull, true);
      view.setInt32(off + ATTR_SAMPLE_OFF.nextFlag, s.nextFlag, true);
      view.setInt32(off + ATTR_SAMPLE_OFF.nextNull, s.nextNull, true);
    }
    wasm.isaac_sfx_attr_walk(headNull, samples, count, site, plan);
    const js = sfxAttrWalk(headNull, jsSamples, count, site);
    const w = readAttrWalk(view, plan);
    for (const key of Object.keys(js)) {
      eq(w[key], js[key], `walk t${tc} ${key}`);
    }
    seen("walkVisited", js.attrsVisited);
    seen("walkPure", js.pureComplete);
  };

  const idDraw = () => {
    const b = pick(rnd, 6);
    seen("fillIdDraw", b);
    switch (b) {
      case 0: return -1;
      case 1: return 0;
      case 2: return 0x442;
      case 3: return 0x443;
      case 4: return 0x444;
      default: return (rnd() | 0) >> pick(rnd, 20);
    }
  };
  const flagDraw = () => {
    const b = pick(rnd, 5);
    seen("fillFlagDraw", b);
    switch (b) {
      case 0: return 0;
      case 1: return 1;
      case 2: return 0x100;
      case 3: return 0x1ff;
      default: return 0xffffffff;
    }
  };
  const spanDraw = () => {
    const b = pick(rnd, 5);
    seen("fillSpanDraw", b);
    switch (b) {
      case 0: return 0;
      case 1: return SFX_ENTRY_STRIDE;
      case 2: return -SFX_ENTRY_STRIDE;
      case 3: return Math.imul(pick(rnd, 0x500), SFX_ENTRY_STRIDE) | 0;
      default: return (rnd() | 0) >> pick(rnd, 16);
    }
  };

  for (let t = 0; t < 400; ++t) {
    strcmpCase();
    walkCase(t);

    const flag = flagDraw();
    const id = idDraw();
    const after = idDraw();
    const span = spanDraw();
    const self = pick(rnd, 2);
    wasm.isaac_sfx_table_fill_plan(flag, id, after, span, self, plan);
    const jsF = sfxTableFillPlan(flag, id, after, span, self);
    const wf = readFillPlan(view, plan);
    for (const key of Object.keys(jsF)) {
      eq(wf[key], jsF[key], `t${t} fill ${key}`);
    }
    seen("fillAppend", jsF.appendMode);
    seen("fillWarn", jsF.outOfBoundsWarn);
    seen("fillSkip", jsF.fillSkipped);
    /* Cross-helper: the append index must be the shared count model. */
    if (jsF.appendMode) {
      eq(jsF.targetIndex, wasm.isaac_sfx_entry_count(span),
        `t${t} fill count shared`);
    }

    const vc = pick(rnd, 8);
    wasm.isaac_sfx_sample_slot_plan(vc, SLOT_PLAN_BASE);
    const jsS = sfxSampleSlotPlan(vc);
    const ws = readSlotPlan(view, SLOT_PLAN_BASE);
    for (const key of Object.keys(jsS)) {
      eq(ws[key], jsS[key], `t${t} slot ${key}`);
    }
    seen("slotOverflow", jsS.overflow);
    if (!jsS.overflow) {
      eq(jsS.slotOffset, wasm.isaac_sfx_load_voice_name_offset(vc),
        `t${t} slot base cross-helper`);
    }
    countCase();
  }
});

/* ------------------------------------------------------------------ *
 *  v6: PE ground truth asserted directly against the native module.    *
 *  Post-samples tail 0x0092da86..0x0092db29: preload counter, chain    *
 *  tests, proto teardown ordering, and the pinned original defects.    *
 * ------------------------------------------------------------------ */
test("v6 PE truth (native): preload counter, chain tests, wrap fill", () => {
  // 0x0092da9d: inc dword ptr [esi+0xc] â€” 32-bit wrap.
  eq(wasm.isaac_sfx_preload_counter_after(0), 1);
  eq(wasm.isaac_sfx_preload_counter_after(1), 2);
  eq(wasm.isaac_sfx_preload_counter_after(0xffffffff), 0);
  eq(wasm.isaac_sfx_preload_counter_after(0x80000000) >>> 0, 0x80000001);
  // 0x0092db21: test esi,esi ; jne 0x92d470 â€” FULL-WORD null test; only
  // 0 is a null link, so 0x100 must be accepted as a live next.
  eq(wasm.isaac_sfx_tail_chain_continue(0), 0);
  eq(wasm.isaac_sfx_tail_chain_continue(1), 1);
  eq(wasm.isaac_sfx_tail_chain_continue(0x100), 1);
  eq(wasm.isaac_sfx_tail_chain_continue(0xffffffff), 1);
  // 0x0092da86: imul ecx,[ebp-0x10264],0x1b8 â€” the entry offset is the
  // shared wrap multiply, so a negative (out-of-range) id fills with the
  // wrapped offset. Original defect, reproduced.
  eq(wasm.isaac_sfx_entry_offset(-1) >>> 0, (0xffffffff * 0x1b8) >>> 0);
  eq(wasm.isaac_sfx_entry_offset(-2) >>> 0, (0xfffffffe * 0x1b8) >>> 0);
  eq(wasm.isaac_sfx_entry_offset(0) >>> 0, 0);
  eq(wasm.isaac_sfx_entry_offset(1) >>> 0, 0x1b8);
  countCase();
});

test("v6 PE truth (native): tail plan literals", () => {
  const view = new DataView(wasm.memory.buffer);
  const plan = TAIL_PLAN_BASE;

  // One tail: entry 5, counter 3, SSO proto string, no next node.
  wasm.isaac_sfx_tail_plan(5, 3, 0xf, 0, 0, plan);
  let p = readTailPlan(view, plan);
  eq(p.entryIndex, 5);
  eq(p.entryOffset >>> 0, (5 * 0x1b8) >>> 0);
  eq(p.loadNeeded, true, "Load always runs before anything else");
  eq(p.counterBefore, 3);
  eq(p.counterAfter, 4, "counter steps after Load");
  eq(p.protoFreeNeeded, false, "SSO proto string is not freed");
  eq(p.protoUsesBackPointer, false);
  eq(p.protoFreeSize, 0);
  eq(p.protoSlackChecked, false);
  eq(p.protoCorruptFatal, false);
  eq(p.protoResetStores, 3, "size/cap/buf[0] always reset");
  eq(p.dtorRuns, true, "__ehvec_dtor always runs");
  eq(p.dtorCount, 7);
  eq(p.dtorStride, 0x38);
  eq(p.dtorVa, 0x0092cf10);
  eq(p.freeBeforeDtor, true, "string freed before the voice vector dtor");
  eq(p.resetBeforeDtor, true);
  eq(p.loadBeforeFree, true, "Load precedes the proto teardown");
  eq(p.loopBack, false, "null next exits the chain loop");
  eq(p.exitReached, true);
  eq(p.pureComplete, false, "Load/free/dtor remain host");

  // Big-alloc proto with a corrupt back pointer and a live next link:
  // 0x0092daa4 cmp dword [ebp-0x1024c],0x10 ; jb, then the 0x23 bias and
  // the slack-window test that aborts through 0x00b18894.
  wasm.isaac_sfx_tail_plan(-1, 0xffffffff, 0x1000, 0x24, 0x100, plan);
  p = readTailPlan(view, plan);
  eq(p.entryIndex, -1);
  eq(p.entryOffset >>> 0, (0xffffffff * 0x1b8) >>> 0, "negative id wraps");
  eq(p.counterBefore, 0xffffffff);
  eq(p.counterAfter, 0, "counter wraps");
  eq(p.protoFreeNeeded, true);
  eq(p.protoUsesBackPointer, true, "cap 0x1000 is the big-alloc edge");
  eq(p.protoFreeSize >>> 0, (0x1001 + 0x23) >>> 0, "size + 0x23 bias");
  eq(p.protoSlackChecked, true);
  eq(p.protoCorruptFatal, true, "back pointer inside the window is fatal");
  eq(p.dtorRuns, true);
  eq(p.loopBack, true, "0x100 is a live link (full-word test)");
  eq(p.exitReached, false);

  // The slack window is checked only on the big-alloc path: back == 0x23
  // (= 4 + 0x1f) is accepted, 0x24 is one past and fatal. A plain alloc
  // (cap 0x10) never checks it and its free size is cap + 1 with no bias.
  wasm.isaac_sfx_tail_plan(3, 0, 0x10, 0x24, 1, plan);
  p = readTailPlan(view, plan);
  eq(p.protoFreeNeeded, true, "cap 0x10 -> plain free");
  eq(p.protoUsesBackPointer, false, "plain path has no back pointer");
  eq(p.protoFreeSize, 0x11, "plain size = cap + 1, no bias");
  eq(p.protoSlackChecked, false, "slack only matters on the big path");
  eq(p.protoCorruptFatal, false, "plain path cannot corrupt-free");
  wasm.isaac_sfx_tail_plan(3, 0, 0x1000, 0x23, 1, plan);
  p = readTailPlan(view, plan);
  eq(p.protoUsesBackPointer, true);
  eq(p.protoFreeSize >>> 0, (0x1001 + 0x23) >>> 0);
  eq(p.protoSlackChecked, true);
  eq(p.protoCorruptFatal, false, "slack exactly at the window edge ok");
  wasm.isaac_sfx_tail_plan(3, 0, 0x1000, 0x24, 1, plan);
  eq(readTailPlan(view, plan).protoCorruptFatal, true, "one past is fatal");
  countCase();
});

test("v6 PE truth (native): sound chain walk literals", () => {
  const view = new DataView(wasm.memory.buffer);
  const links = CHAIN_FLAGS_BASE;
  const chain = TAIL_PLAN_BASE + TAIL_PLAN_SIZE;
  const run = (head, arr) => {
    for (let i = 0; i < arr.length; ++i) {
      view.setUint32(links + i * 4, arr[i] >>> 0, true);
    }
    wasm.isaac_sfx_sound_chain_plan(head, links, arr.length, chain);
    return readChainPlan(view, chain);
  };

  // 0x92d466: test esi,esi ; je 0x0092db29 â€” NULL head skips the loop.
  let c = run(0, [1, 1, 1]);
  eq(c.headNonzero, false);
  eq(c.soundsVisited, 0);
  eq(c.loopsBack, 0);
  eq(c.stopsAtNull, false);
  eq(c.truncated, false);
  // Head + first node NULL: stop after node 0.
  c = run(1, [0, 1, 1]);
  eq(c.headNonzero, true);
  eq(c.soundsVisited, 1);
  eq(c.loopsBack, 0);
  eq(c.stopsAtNull, true);
  eq(c.truncated, false);
  // Two live links (a full-word 0x100 included) then NULL.
  c = run(1, [0x100, 2, 0]);
  eq(c.headNonzero, true);
  eq(c.soundsVisited, 3);
  eq(c.loopsBack, 2);
  eq(c.stopsAtNull, true);
  // Bounded array that never reaches NULL: truncated.
  c = run(1, [1, 0x100, 3]);
  eq(c.soundsVisited, 3);
  eq(c.loopsBack, 3);
  eq(c.truncated, true);
  // No links supplied at all: truncated, nothing visited.
  c = run(1, []);
  eq(c.headNonzero, true);
  eq(c.soundsVisited, 0);
  eq(c.truncated, true);
  countCase();
});

test("v6 PE truth (native): warn stacks and fill header pins", () => {
  const view = new DataView(wasm.memory.buffer);
  const warn = WARN_STACK_BASE;

  // 0x0092d6cf: push fmt(0x00b7b170) ; push 0x10 ; call 0x00a112c0.
  // The "%d out of bounds" format has NO vararg word â€” PE formats garbage.
  // Original defect, reproduced and pinned.
  wasm.isaac_sfx_warn_stack(SFX_WARN_KIND_OUT_OF_BOUNDS, warn);
  let w = readWarnStack(view, warn);
  eq(w.argCount, 2, "oob: fmt + level only");
  eq(w.varargCount, 0, "oob: no vararg for the %d â€” the defect");
  eq(w.level, 0x10);
  eq(w.formatStringVa, 0x00b7b170);
  // 0x0092da76: pushes index, fmt(0xb7b220), level 1 â€” the index IS given.
  wasm.isaac_sfx_warn_stack(SFX_WARN_KIND_MAX_SAMPLES, warn);
  w = readWarnStack(view, warn);
  eq(w.argCount, 3);
  eq(w.varargCount, 1, "max-samples: index is supplied");
  eq(w.level, 1);
  eq(w.formatStringVa, 0x00b7b220);
  // Unknown kind: empty, never a guess.
  wasm.isaac_sfx_warn_stack(99, warn);
  w = readWarnStack(view, warn);
  eq(w.argCount, 0);
  eq(w.varargCount, 0);
  eq(w.level, 0);
  eq(w.formatStringVa, 0);

  // Fill loop header stores, in PE order: 0x190, 0x194, 0x198, 0x199,
  // 0x19c; indexes 1 (0x194) and 3 (0x199) copy uninitialized stack bytes.
  // Original defect, reproduced.
  for (let i = 0; i < SFX_FILL_HEADER_COUNT; ++i) {
    eq(wasm.isaac_sfx_fill_header_offset(i), SFX_FILL_HEADER_OFFS[i],
      `hdr off ${i}`);
  }
  eq(wasm.isaac_sfx_fill_header_offset(-1), -1);
  eq(wasm.isaac_sfx_fill_header_offset(5), -1);
  eq(wasm.isaac_sfx_fill_header_offset(0x100), -1);
  eq(wasm.isaac_sfx_fill_header_uninitialized(1), 1, "0x194 is garbage");
  eq(wasm.isaac_sfx_fill_header_uninitialized(3), 1, "0x199 is garbage");
  eq(wasm.isaac_sfx_fill_header_uninitialized(0), 0, "0x190 init");
  eq(wasm.isaac_sfx_fill_header_uninitialized(2), 0, "0x198 init");
  eq(wasm.isaac_sfx_fill_header_uninitialized(4), 0, "0x19c init");
  eq(wasm.isaac_sfx_fill_header_uninitialized(-1), 0);
  eq(wasm.isaac_sfx_fill_header_uninitialized(0x100), 0);
  countCase();
});


test("v6 differential: deterministic randomized corpus", () => {
  let seed = (0x92daa4 ^ 0x92d6cf ^ 0x92db21 ^ 0x92d470) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const view = new DataView(wasm.memory.buffer);
  const links = CHAIN_FLAGS_BASE;
  const plan = TAIL_PLAN_BASE;
  const warn = WARN_STACK_BASE;

  const indexDraw = () => {
    const branch = pick(rnd, 6);
    seen("v6IndexDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 1;
      case 2: return -1;                 // wrapped fill â€” original defect
      case 3: return -2;
      case 4: return 0x443;
      default: return (rnd() | 0) % 0x400 - 0x200; // -0x200..0x1ff
    }
  };
  const counterDraw = () => {
    const branch = pick(rnd, 5);
    seen("v6CounterDraw", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 1;
      case 2: return 0xffffffff; // wrap
      case 3: return 0x7fffffff;
      default: return rnd() >>> 0;
    }
  };
  const capDraw = () => {
    const branch = pick(rnd, 7);
    seen("v6CapDraw", branch);
    switch (branch) {
      case 0: return 0;        // SSO, nothing to free
      case 1: return 0xf;      // SSO edge (cmp 0x10)
      case 2: return 0x10;     // plain free, cap+1 bytes
      case 3: return 0xff;
      case 4: return 0xfff;    // just under the big-alloc edge
      case 5: return 0x1000;   // big-alloc edge -> back pointer
      default: return pick(rnd, 0x2000);
    }
  };
  const backDraw = () => {
    const branch = pick(rnd, 7);
    seen("v6BackDraw", branch);
    switch (branch) {
      case 0: return 0x23;     // exactly 4 + 0x1f â€” accepted
      case 1: return 0x24;     // one past â€” fatal
      case 2: return 0x1000;
      case 3: return 0;
      case 4: return 0xffffffff;
      case 5: return 4;
      default: return rnd() >>> 0;
    }
  };
  const nextDraw = () => {
    const branch = pick(rnd, 6);
    seen("v6NextDraw", branch);
    switch (branch) {
      case 0: return 0;        // null link -> exit
      case 1: return 1;
      case 2: return 0x100;     // full-word: live, not null
      case 3: return 0xffffffff;
      case 4: return 0x80000000;
      default: return (rnd() | 0) % 0x200;
    }
  };
  const linkDraw = () => {
    const branch = pick(rnd, 6);
    seen("v6ChainLink", branch);
    switch (branch) {
      case 0: return 0;        // null -> chain stops here
      case 1: return 1;
      case 2: return 0x100;    // full-word: still a link
      case 3: return 0x7fffffff;
      case 4: return 0xffffffff;
      default: return rnd() >>> 0;
    }
  };

  for (let t = 0; t < 350; ++t) {
    const kind = pick(rnd, 5) - 1; // -1..3
    seen("v6WarnKind", kind);
    wasm.isaac_sfx_warn_stack(kind, warn);
    const jsW = sfxWarnStack(kind);
    const ww = readWarnStack(view, warn);
    for (const key of Object.keys(jsW)) {
      eq(ww[key], jsW[key], `t${t} warn ${key}`);
    }

    const hi = pick(rnd, 7) - 1; // -1..5
    seen("v6HeaderIdx", hi);
    const hOff = wasm.isaac_sfx_fill_header_offset(hi);
    eq(hOff, sfxFillHeaderOffset(hi), `t${t} hdr off`);
    eq(wasm.isaac_sfx_fill_header_uninitialized(hi),
      sfxFillHeaderUninitialized(hi), `t${t} hdr uninit`);
    if (hi >= 0 && hi < SFX_FILL_HEADER_COUNT) {
      eq(hOff, SFX_FILL_HEADER_OFFS[hi], `t${t} hdr off literal`);
    }
    seen("v6Uninit", sfxFillHeaderUninitialized(hi));

    const counter = counterDraw();
    eq(wasm.isaac_sfx_preload_counter_after(counter) >>> 0,
      sfxPreloadCounterAfter(counter), `t${t} counter`);
    const nx = nextDraw();
    const cont = wasm.isaac_sfx_tail_chain_continue(nx);
    eq(cont, sfxTailChainContinue(nx), `t${t} continue`);
    seen("v6Loop", cont);

    const idx = indexDraw();
    const cap = capDraw();
    const back = backDraw();
    wasm.isaac_sfx_tail_plan(idx, counter, cap, back, nx, plan);
    const jsT = sfxTailPlan(idx, counter, cap, back, nx);
    const wt = readTailPlan(view, plan);
    for (const key of Object.keys(jsT)) {
      eq(wt[key], jsT[key], `t${t} tail ${key}`);
    }
    seen("v6Exit", jsT.exitReached);
    seen("v6FreeNeeded", jsT.protoFreeNeeded);
    seen("v6FreeBig", jsT.protoUsesBackPointer);
    seen("v6Fatal", jsT.protoCorruptFatal);
    // Cross-helper: the proto free facts are the shared string-free model.
    const free = sfxStringFreePlan(cap, back);
    eq(jsT.protoFreeNeeded, free.freeNeeded, `t${t} free needed shared`);
    eq(jsT.protoFreeSize, free.freeSize, `t${t} free size shared`);
    eq(jsT.protoUsesBackPointer, free.usesBackPointer,
      `t${t} free back shared`);
    eq(jsT.protoCorruptFatal, free.corruptFatal, `t${t} free fatal shared`);

    const head = pick(rnd, 4) === 0 ? 0 : 1;
    const len = pick(rnd, 6); // 0..5
    seen("v6ChainLen", len);
    const arr = [];
    for (let i = 0; i < len; ++i) {
      const l = linkDraw();
      arr.push(l);
      view.setUint32(links + i * 4, l >>> 0, true);
    }
    wasm.isaac_sfx_sound_chain_plan(head, links, len,
      plan + TAIL_PLAN_SIZE);
    const jsC = sfxSoundChainPlan(head, arr);
    const wc = readChainPlan(view, plan + TAIL_PLAN_SIZE);
    for (const key of Object.keys(jsC)) {
      eq(wc[key], jsC[key], `t${t} chain ${key}`);
    }
    seen("v6Stop", jsC.stopsAtNull);
    seen("v6Trunc", jsC.truncated);
    seen("v6ChainVisited", jsC.soundsVisited);
    if (jsC.stopsAtNull) {
      eq(jsC.loopsBack, jsC.soundsVisited - 1, `t${t} chain stop id`);
    }
    countCase();
  }
});

/* =========================== v7: the two stop bodies ======================
 *
 * 0x0092e230 StopSoundEffect(int id) and 0x0092e300 StopAll(). Every number
 * asserted below was read from the instruction stream or produced by a
 * machine census over tools/isaac-ng.unpacked.exe; none of it comes from a
 * decompiler and none of it is inherited from the older records, two of
 * which these tests actively contradict (see "the stale record" below).
 */


/* The v7 oracle returns booleans where the Wasm ABI returns i32, so the
   comparator normalises before strictEqual. Keys are taken from the JS side
   so a field the model stopped producing cannot silently go unchecked. */
function assertV7Equal(w, js, label) {
  const keys = Object.keys(js);
  assert.ok(keys.length > 0, label + ": nothing to compare");
  for (const key of keys) {
    const want = typeof js[key] === "boolean" ? (js[key] ? 1 : 0) : js[key];
    eq(w[key], want, label + " " + key);
  }
}

/* IsaacSfxStopVoiceSample: 6 x 4 bytes. */
const STOP_SAMPLE_SIZE = 24;
/* IsaacSfxStopAllVoiceSample: 9 x 4 bytes. */
