const XML_NESTED_PLAN_FIELDS = [
  "entered", "headGate", "markupKind", "nodeType", "allocatorCall",
  "allocatorVa", "allocatorTarget", "nodeSize", "attrsCall", "attrsVa",
  "childrenCall", "childrenVa", "namePtr", "nameLen", "nameEmpty",
  "nameError", "wsSkip", "tailGate", "closeError", "errorSlot",
  "errorStore", "scanLatched", "textPtr", "textLen", "nulPos",
  "cursorAfter", "hostCalls", "pureComplete", "sizeBytes", "callerCount",
];
