/* v13 PE truth for 0x00423480, transcribed branch-by-branch from the
   instruction stream (the full listing is in the header's v13 block):
   - 0x423487 `mov esi,edx ; cmp ebx,edx ; cmovb esi,ebx` is the UNSIGNED
     min of the two lengths.
   - 0x423493 `sub esi,4 ; jb` opens the dword pass iff common >= 4; the
     pass compares LITTLE-ENDIAN dwords (0x423498..0x4234a7).
   - 0x4234a9..0x4234d1 is the byte tail guarded by `cmp esi,-4/-3/-2/-1 ;
     je equal`, so exactly common % 4 bytes follow the dword pass.
   - 0x4234db `sbb eax,eax ; or eax,1` resolves the first differing byte by
     UNSIGNED value (+1 for greater, -1 for less).
   - 0x4234e8..0x4234f6 ties a fully-equal prefix by length: -1 when the
     a-side is shorter, +1 when longer, 0 when equal. */
test("v13 PE truth (native): the 0x00423480 compare laws", () => {
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x00423480/);
  assert.match(h, /0x0092d052/);
  assert.match(h, /sbb eax,eax ; or eax,1/);
  assert.match(h, /0x00b7b1bc/);

  const pairs = [
    ["ISAAC_SFX_HOST_VA_OGG_COMPARE", SFX_HOST_VA_OGG_COMPARE, 0x00423480],
    ["ISAAC_SFX_OGG_COMPARE_SIZE_BYTES", SFX_OGG_COMPARE_SIZE_BYTES, 0x7d],
    ["ISAAC_SFX_OGG_COMPARE_INSNS", SFX_OGG_COMPARE_INSNS, 65],
    ["ISAAC_SFX_OGG_COMPARE_CALLERS", SFX_OGG_COMPARE_CALLERS, 33],
    ["ISAAC_SFX_OGG_COMPARE_SFX_CALLSITE", SFX_OGG_COMPARE_SFX_CALLSITE,
     0x0092d052],
    ["ISAAC_SFX_OGG_LITERAL_VA", SFX_OGG_LITERAL_VA, 0x00b7b1bc],
    ["ISAAC_SFX_OGG_BYTE0", SFX_OGG_BYTE0, 0x2e],
    ["ISAAC_SFX_OGG_BYTE1", SFX_OGG_BYTE1, 0x6f],
    ["ISAAC_SFX_OGG_BYTE2", SFX_OGG_BYTE2, 0x67],
    ["ISAAC_SFX_OGG_BYTE3", SFX_OGG_BYTE3, 0x67],
    ["ISAAC_SFX_OGG_DWORD_LE", SFX_OGG_DWORD_LE, 0x67676f2e],
    ["ISAAC_SFX_OGG_SUFFIX_LEN", SFX_OGG_SUFFIX_LEN, 4],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }

  /* The Load site always compares four bytes, so the suffix law is the
     four-byte span: one dword pass, then byte resolution. */
  eq(sfxCmpCommonLen(4, 4), 4);
  eq(sfxCmpCommonLen(0x100, 4), 4);
  eq(sfxCmpCommonLen(4, 0x100), 4);
  eq(sfxCmpCommonLen(0, 0xffffffff), 0);
  eq(sfxCmpCommonLen(0xffffffff, 1), 1);
  eq(sfxCmpCommonLen(0xffffffff, 0xffffffff), 0xffffffff);

  eq(sfxCmpLengthTie(4, 4), 0);
  eq(sfxCmpLengthTie(3, 4), -1);
  eq(sfxCmpLengthTie(4, 3), 1);
  eq(sfxCmpLengthTie(0, 0x100), -1);
  eq(sfxCmpLengthTie(0xffffffff, 0), 1);
  eq(sfxCmpLengthTie(0x100, 0x100), 0);

  /* Equality and each byte position of the span, UNSIGNED at byte 0 (the
     0x80/0x01 row is the signed-vs-unsigned discriminator: int8 would say
     -1, the PE's `sbb/or` says +1). */
  eq(sfxCmp4ThreeWay(1, 2, 3, 4, 1, 2, 3, 4), 0);
  eq(sfxCmp4ThreeWay(1, 2, 3, 4, 1, 2, 3, 5), -1);
  eq(sfxCmp4ThreeWay(1, 2, 4, 4, 1, 2, 3, 9), 1);
  eq(sfxCmp4ThreeWay(0x80, 0, 0, 0, 0x01, 0, 0, 0), 1);
  eq(sfxCmp4ThreeWay(0, 0, 0, 0x80, 0, 0, 0, 0x7f), 1);
  eq(sfxCmp4ThreeWay(0, 0, 0, 0x80, 0, 0, 0, 0x80), 0);
  /* Wide inputs: the machine reads MEMORY BYTES, so equal low bytes make
     the dword pass equal even when the wide words differ. */
  eq(sfxCmp4ThreeWay(0x101, 0x202, 0x303, 0x403, 0x101, 0x202, 0x303, 0x404),
     -1);
  eq(sfxCmp4ThreeWay(0x12e, 0x16f, 0x167, 0x167, 0x2e, 0x6f, 0x67, 0x67), 0);

  /* The ".ogg" specialization. 2e 6f 67 67 is the literal at 0x00b7b1bc;
     the Load site tests `test eax,eax ; jne create ; mov al,1`. */
  eq(sfxOggSuffixCompare(0x2e, 0x6f, 0x67, 0x67), 0);
  eq(sfxOggSuffixCompare(0x12e, 0x16f, 0x167, 0x167), 0);
  eq(sfxOggSuffixCompare(0x4f, 0x6f, 0x67, 0x67), 1);   /* 'O' > '.' */
  eq(sfxOggSuffixCompare(0x21, 0x6f, 0x67, 0x67), -1);  /* '!' < '.' */
  eq(sfxOggSuffixCompare(0x2e, 0x4f, 0x67, 0x67), -1);  /* 'O' < 'o' */
  eq(sfxOggSuffixCompare(0x2e, 0x6f, 0x68, 0x67), 1);   /* 'h' > 'g' */
  eq(sfxOggSuffixCompare(0x2e, 0x6f, 0x67, 0x66), -1);  /* 'f' < 'g' */
  eq(sfxOggSuffixCompare(0x80, 0x6f, 0x67, 0x67), 1);   /* unsigned byte 0 */
  eq(sfxOggSuffixCompare(0x100, 0x100, 0x100, 0x100), -1); /* all zero bytes */

  eq(sfxOggSuffixMatch(0x2e, 0x6f, 0x67, 0x67), 1);
  eq(sfxOggSuffixMatch(0x12e, 0x16f, 0x167, 0x167), 1);
  eq(sfxOggSuffixMatch(0x2e, 0x6f, 0x67, 0x68), 0);
  eq(sfxOggSuffixMatch(0x2e, 0x6f, 0x66, 0x67), 0);
  eq(sfxOggSuffixMatch(0x2e, 0x6e, 0x67, 0x67), 0);
  eq(sfxOggSuffixMatch(0x2d, 0x6f, 0x67, 0x67), 0);
  eq(sfxOggSuffixMatch(0xffffffff, 0xffffffff, 0xffffffff, 0xffffffff), 0);

  /* Integration: the v3 host bit is exactly this law. */
  for (const tail of [
    [0x2e, 0x6f, 0x67, 0x67],
    [0x2e, 0x6f, 0x67, 0x68],
    [0x80, 0x6f, 0x67, 0x67],
    [0x100, 0x100, 0x100, 0x100],
  ]) {
    const cmp = sfxOggSuffixCompare(tail[0], tail[1], tail[2], tail[3]);
    eq(sfxLoadStreamByte(cmp), sfxLoadStreamByteFromTail(
      tail[0], tail[1], tail[2], tail[3]), `stream from tail ${tail}`);
    eq(
      sfxLoadStreamByteFromTail(tail[0], tail[1], tail[2], tail[3]),
      sfxOggSuffixMatch(tail[0], tail[1], tail[2], tail[3]),
      `match from tail ${tail}`,
    );
    countCase();
  }
});

test("Wasm matches JS: v13 0x00423480 compare differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const planBase = SCRATCH + 23000;

  /* Fixed rows: every branch of the four-byte span, both length gates, and
     the length tie. */
  const fixedBytes = [
    [0x2e, 0x6f, 0x67, 0x67],
    [0x2e, 0x6f, 0x67, 0x68],
    [0x2e, 0x6f, 0x66, 0x67],
    [0x2e, 0x6e, 0x67, 0x67],
    [0x2d, 0x6f, 0x67, 0x67],
    [0x80, 0x00, 0x00, 0x00],
    [0x01, 0x00, 0x00, 0x00],
    [0x00, 0x00, 0x00, 0x80],
    [0x00, 0x00, 0x00, 0x7f],
    [0xff, 0xff, 0xff, 0xff],
    [0x00, 0x00, 0x00, 0x00],
    [0x100, 0x100, 0x100, 0x100],
    [0x12e, 0x16f, 0x167, 0x167],
    [0x1ff, 0x1ff, 0x1ff, 0x1ff],
    [0xffffffff, 0xffffffff, 0xffffffff, 0xffffffff],
  ];
  const fixedLens = [0, 1, 2, 3, 4, 5, 7, 0x100, 0x1ff, 0xffffffff];
  for (const a of fixedBytes) {
    for (const b of fixedBytes) {
      eq(
        wasm.isaac_sfx_cmp4_three_way(a[0], a[1], a[2], a[3], b[0], b[1],
                                      b[2], b[3]),
        sfxCmp4ThreeWay(a[0], a[1], a[2], a[3], b[0], b[1], b[2], b[3]),
        `cmp4 ${a} vs ${b}`,
      );
      eq(
        wasm.isaac_sfx_ogg_suffix_compare(a[0], a[1], a[2], a[3]),
        sfxOggSuffixCompare(a[0], a[1], a[2], a[3]),
        `ogg cmp ${a}`,
      );
      eq(
        wasm.isaac_sfx_ogg_suffix_match(a[0], a[1], a[2], a[3]),
        sfxOggSuffixMatch(a[0], a[1], a[2], a[3]),
        `ogg match ${a}`,
      );
      eq(
        wasm.isaac_sfx_load_stream_byte_from_tail(a[0], a[1], a[2], a[3]),
        sfxLoadStreamByteFromTail(a[0], a[1], a[2], a[3]),
        `stream from tail ${a}`,
      );
      countCase();
      for (const lenA of fixedLens) {
        for (const lenB of fixedLens) {
          eq(
            wasm.isaac_sfx_cmp_common_len(lenA, lenB) >>> 0,
            sfxCmpCommonLen(lenA, lenB),
            `common ${lenA}/${lenB}`,
          );
          eq(
            wasm.isaac_sfx_cmp_length_tie(lenA, lenB),
            sfxCmpLengthTie(lenA, lenB),
            `tie ${lenA}/${lenB}`,
          );
          wasm.isaac_sfx_suffix_compare_plan(
            a[0], a[1], a[2], a[3], b[0], b[1], b[2], b[3], lenA, lenB,
            planBase,
          );
          assertPlanEqual(
            readSuffixPlan(view, planBase),
            sfxSuffixComparePlan(a[0], a[1], a[2], a[3], b[0], b[1], b[2],
                                 b[3], lenA, lenB),
            `suffix plan ${a}/${b}/${lenA}/${lenB}`,
          );
          countCase();
        }
      }
    }
  }

  /* The v3 Load voice plan must agree with the from-tail law: the opaque
     suffix_compare_result is now a computed decision. */
  const voiceBase = SCRATCH + 23200;
  for (const tail of fixedBytes) {
    const cmp = sfxOggSuffixCompare(tail[0], tail[1], tail[2], tail[3]);
    for (const index of [0, 1, 6, 7, 8]) {
      for (const size of [4, 5, 0xffffffff]) {
        for (const cap of [0, 0x0f, 0x10]) {
          wasm.isaac_sfx_load_voice_plan(index, size, cap, cmp, voiceBase);
          const w = readLoadVoicePlan(view, voiceBase);
          const js = sfxLoadVoicePlan(index, size, cap, cmp);
          eq(w.streamByteValue, js.streamByteValue, `voice stream ${tail}`);
          eq(
            w.streamByteValue,
            sfxLoadStreamByteFromTail(tail[0], tail[1], tail[2], tail[3]),
            `voice stream == from-tail ${tail}`,
          );
          countCase();
        }
      }
    }
  }

  /* Randomized differential. Each byte draw is biased to the literal and to
     the wide/low-byte boundary values so both match and mismatch arms stay
     hot; lengths walk the dword gate and the tail byte counts. */
  let seed = (0x00423480 ^ 0x00b7b1bc) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  function drawByte() {
    const branch = pick(rnd, 8);
    seen("v13ByteB", branch);
    switch (branch) {
      case 0: return 0x2e;
      case 1: return 0x6f;
      case 2: return 0x67;
      case 3: return 0x68;
      case 4: return 0;
      case 5: return 0xff;
      case 6: return 0x100;
      default: return pick(rnd, 0x200);
    }
  }
  function drawLen() {
    const branch = pick(rnd, 10);
    seen("v13LenB", branch);
    switch (branch) {
      case 0: return 0;
      case 1: return 1;
      case 2: return 2;
      case 3: return 3;
      case 4: return 4;
      case 5: return 5;
      case 6: return 7;
      case 7: return 0x100;
      case 8: return 0x1ff;
      default: return 0xffffffff;
    }
  }
  for (let k = 0; k < 400; ++k) {
    /* One row in five is an exact ".ogg" match (a = b = literal, equal
       lengths) so the match arm and the ogg-compare 0 outcome stay hot —
       random byte draws would never hit the 1-in-2^32 literal by chance. */
    const exact = pick(rnd, 5) === 0;
    seen("v13Exact", exact ? 1 : 0);
    const a = exact
      ? [0x2e, 0x6f, 0x67, 0x67]
      : [drawByte(), drawByte(), drawByte(), drawByte()];
    const b = exact
      ? [0x2e, 0x6f, 0x67, 0x67]
      : [drawByte(), drawByte(), drawByte(), drawByte()];
    const lenA = exact ? 4 : drawLen();
    const lenB = exact ? 4 : drawLen();

    const jsCmp = sfxCmp4ThreeWay(a[0], a[1], a[2], a[3], b[0], b[1], b[2],
                                  b[3]);
    eq(wasm.isaac_sfx_cmp4_three_way(a[0], a[1], a[2], a[3], b[0], b[1],
                                     b[2], b[3]), jsCmp, `rnd cmp4 ${k}`);
    eq(wasm.isaac_sfx_ogg_suffix_compare(a[0], a[1], a[2], a[3]),
       sfxOggSuffixCompare(a[0], a[1], a[2], a[3]), `rnd oggcmp ${k}`);
    eq(wasm.isaac_sfx_ogg_suffix_match(a[0], a[1], a[2], a[3]),
       sfxOggSuffixMatch(a[0], a[1], a[2], a[3]), `rnd match ${k}`);
    eq(wasm.isaac_sfx_load_stream_byte_from_tail(a[0], a[1], a[2], a[3]),
       sfxLoadStreamByteFromTail(a[0], a[1], a[2], a[3]), `rnd tail ${k}`);
    eq(wasm.isaac_sfx_cmp_common_len(lenA, lenB) >>> 0,
       sfxCmpCommonLen(lenA, lenB), `rnd common ${k}`);
    eq(wasm.isaac_sfx_cmp_length_tie(lenA, lenB),
       sfxCmpLengthTie(lenA, lenB), `rnd tie ${k}`);

    wasm.isaac_sfx_suffix_compare_plan(a[0], a[1], a[2], a[3], b[0], b[1],
                                       b[2], b[3], lenA, lenB, planBase);
    const w = readSuffixPlan(view, planBase);
    const js = sfxSuffixComparePlan(a[0], a[1], a[2], a[3], b[0], b[1],
                                    b[2], b[3], lenA, lenB);
    assertPlanEqual(w, js, `rnd plan ${k}`);
    seen("v13Three", w.threeWay);
    seen("v13DwordLoop", w.dwordLoop);
    seen("v13TailBytes", w.tailBytes);
    seen("v13Prefix", w.prefixEqual);
    seen("v13Match", w.match);
    seen("v13OggCmp", sfxOggSuffixCompare(a[0], a[1], a[2], a[3]));
    /* Cross-law invariant: a lexicographic compare returns 0 exactly when
       the compared prefixes are equal AND the lengths are equal, so the
       plan's match field must agree with that combination. */
    eq(w.match, w.prefixEqual === 1 && lenA === lenB ? 1 : 0,
       `rnd plan match invariant ${k}`);
    countCase();
  }
});

/* ---------------- v14: 0x00416040 the nested XML node parse --------------
 * The DECISION layer of the document's nested node parser. Whole body
 * 0x416040..0x416430 (0x3f1 bytes, 336 insns, 7 ret 4, 4 E8, 0 indirect,
 * 50 stores, 3 rel32 callers) stays host-irreducible: the node allocator
 * 0x416510 (itself calling 0xa0f4e0 / an indirect pool allocator), attrs
 * 0x4165a0, children 0x416770, and the host-length input walks. Landed
 * here: the head gate (0x21 -> MARKUP, 0x3f -> PI, else ELEMENT), the
 * 0xb1ae60 name-char table (1 except 0/9/10/13/32/47/62/63), the "?xml "
 * decl gate, the "<!" markup-kind cascade, the FULL-WORD name-empty
 * error (0xb1b690), the '>' tail close error (0xb1b6a8), the shared NUL
 * scan latch (0xb1b678), the node type/init template ({0x00,0x04,0x10,
 * 0x14,0x18,0x20}), the name/cdata NUL-in-place addresses, and the
 * per-path cursor arithmetic. PE-truth per exit, transcribed branch by
 * branch from the listings above; the plan additionally consumes the
 * HOST-walk recaptures (name_len, ws_skip, post_attrs, found_pos,
 * scan_latched, close_byte, prev_error). */

test("v14 PE truth (native): nested parse gates, error laws, node link", () => {
  const view = new DataView(wasm.memory.buffer);

  const h = readFileSync(header, "utf8");
  assert.match(h, /0x00416040/);
  assert.match(h, /0x00416510/);
  assert.match(h, /0x00a0f4e0/);
  assert.match(h, /0x004165a0/);
  assert.match(h, /0x00416770/);
  assert.match(h, /0xb1ae60/);
  assert.match(h, /0x00b1b678/);
  assert.match(h, /0x00b1b690/);
  assert.match(h, /0x00b1b6a8/);
  assert.match(h, /test dl,dl ; mov eax,0xb1b678/);

  /* Census pins. */
  const pairs = [
    ["ISAAC_SFX_XML_NESTED_PARSE_SIZE_BYTES", SFX_XML_NESTED_PARSE_SIZE_BYTES,
     0x3f1],
    ["ISAAC_SFX_XML_NESTED_PARSE_INSNS", SFX_XML_NESTED_PARSE_INSNS, 336],
    ["ISAAC_SFX_XML_NESTED_PARSE_RETS", SFX_XML_NESTED_PARSE_RETS, 7],
    ["ISAAC_SFX_XML_NESTED_PARSE_E8", SFX_XML_NESTED_PARSE_E8, 4],
    ["ISAAC_SFX_XML_NESTED_PARSE_STORES", SFX_XML_NESTED_PARSE_STORES, 50],
    ["ISAAC_SFX_XML_NESTED_PARSE_CALLERS", SFX_XML_NESTED_PARSE_CALLERS, 3],
    ["ISAAC_SFX_XML_NESTED_NAME_TABLE_VA", SFX_XML_NESTED_NAME_TABLE_VA,
     0x00b1ae60],
    ["ISAAC_SFX_XML_NESTED_ERR_UNEXPECTED_VA",
     SFX_XML_NESTED_ERR_UNEXPECTED_VA, 0x00b1b678],
    ["ISAAC_SFX_XML_NESTED_ERR_NAME_VA", SFX_XML_NESTED_ERR_NAME_VA,
     0x00b1b690],
    ["ISAAC_SFX_XML_NESTED_ERR_GT_VA", SFX_XML_NESTED_ERR_GT_VA, 0x00b1b6a8],
    ["ISAAC_SFX_XML_NESTED_ALLOC_VA", SFX_XML_NESTED_ALLOC_VA, 0x00416510],
    ["ISAAC_SFX_XML_NESTED_ALLOC_TARGET", SFX_XML_NESTED_ALLOC_TARGET,
     0x00a0f4e0],
    ["ISAAC_SFX_XML_NESTED_ATTRS_VA", SFX_XML_NESTED_ATTRS_VA, 0x004165a0],
    ["ISAAC_SFX_XML_NESTED_CHILDREN_VA", SFX_XML_NESTED_CHILDREN_VA,
     0x00416770],
    ["ISAAC_SFX_XML_NESTED_NODE_TYPE_ELEMENT",
     SFX_XML_NESTED_NODE_TYPE_ELEMENT, 1],
    ["ISAAC_SFX_XML_NESTED_NODE_TYPE_CDATA", SFX_XML_NESTED_NODE_TYPE_CDATA,
     3],
    ["ISAAC_SFX_XML_NESTED_NODE_SIZE", SFX_XML_NESTED_NODE_SIZE, 0x30],
    ["ISAAC_SFX_XML_NESTED_INIT_OFFSETS_COUNT",
     SFX_XML_NESTED_INIT_OFFSETS_COUNT, 6],
    ["ISAAC_SFX_XML_NODE_OFF_TEXT_04", SFX_XML_NODE_OFF_TEXT_04, 0x04],
    ["ISAAC_SFX_XML_NODE_OFF_TEXT_LEN_0C", SFX_XML_NODE_OFF_TEXT_LEN_0C,
     0x0c],
    ["ISAAC_SFX_XML_NODE_OFF_TYPE_14", SFX_XML_NODE_OFF_TYPE_14, 0x14],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }

  /* Head gate: 0x21 '!' -> MARKUP, 0x3f '?' -> PI, else ELEMENT. LOW BYTE
     (0x416051..0x41605d). 0x121 / 0x13f keep the low bytes. */
  eq(wasm.isaac_sfx_xml_nested_parse_head_gate(0x21), SFX_XML_NESTED_HEAD_MARKUP);
  eq(wasm.isaac_sfx_xml_nested_parse_head_gate(0x121), SFX_XML_NESTED_HEAD_MARKUP,
     "wide '!'");
  eq(wasm.isaac_sfx_xml_nested_parse_head_gate(0x3f), SFX_XML_NESTED_HEAD_PI);
  eq(wasm.isaac_sfx_xml_nested_parse_head_gate(0x13f), SFX_XML_NESTED_HEAD_PI,
     "wide '?'");
  eq(wasm.isaac_sfx_xml_nested_parse_head_gate(0x41), SFX_XML_NESTED_HEAD_ELEMENT);
  eq(wasm.isaac_sfx_xml_nested_parse_head_gate(0x100), SFX_XML_NESTED_HEAD_ELEMENT,
     "low 0 is ELEMENT");
  eq(wasm.isaac_sfx_xml_nested_parse_head_gate(0xffffffff),
     SFX_XML_NESTED_HEAD_ELEMENT);
  seen("v14Head", SFX_XML_NESTED_HEAD_MARKUP);
  seen("v14Head", SFX_XML_NESTED_HEAD_PI);
  seen("v14Head", SFX_XML_NESTED_HEAD_ELEMENT);

  /* Name-char table 0xb1ae60: 0 at exactly {0,9,10,13,32,47,62,63}, 1
     elsewhere (248 of 256 — verified against .rdata). */
  for (const z of [0, 9, 10, 13, 32, 47, 62, 63]) {
    eq(wasm.isaac_sfx_xml_nested_parse_name_char(z), 0, `name zero ${z}`);
    seen("v14Name", 0);
  }
  for (const z of [0x100 + 9, 0x100 + 32]) {
    eq(wasm.isaac_sfx_xml_nested_parse_name_char(z), 0, `wide zero ${z}`);
    seen("v14Name", 0);
  }
  for (const one of [1, 8, 11, 33, 46, 48, 61, 64, 0x41, 0x5f, 0xff]) {
    eq(wasm.isaac_sfx_xml_nested_parse_name_char(one), 1, `name one ${one}`);
    seen("v14Name", 1);
  }
  eq(wasm.isaac_sfx_xml_nested_parse_name_char(0x141), 1, "wide 'A'");
  eq(wasm.isaac_sfx_xml_nested_parse_name_char(0xffffffff), 1);
  /* Cross-check: '/' '>' '?' stop names (self-close / open / PI), spaces
     and NUL stop them too, but '<' is a name char here. */
  eq(wasm.isaac_sfx_xml_nested_parse_name_char(0x3c), 1, "'<' is a name char");

  /* "?xml " decl gate: x|X m|M l|L + space-table byte 4. */
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x78, 0x6d, 0x6c, 32), 1);
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x58, 0x4d, 0x4c, 32), 1);
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x178, 0x16d, 0x16c, 0x120),
     1, "wide xml letters + wide space");
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x79, 0x6d, 0x6c, 32), 0,
     "'y' is not 'x'");
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x78, 0x6e, 0x6c, 32), 0);
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x78, 0x6d, 0x6b, 32), 0);
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x78, 0x6d, 0x6c, 0x41),
     0, "'A' (0x41) is not a space");
  eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(0x78, 0x6d, 0x6c, 9), 1);
  seen("v14PiGate", 0);
  seen("v14PiGate", 1);

  /* "<!" markup kind, machine order. */
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x2d, 0x2d, 0, 0, 0, 0, 0, 0),
     SFX_XML_NESTED_MARKUP_COMMENT, "<!--");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x12d, 0x12d, 0, 0, 0, 0, 0,
                                                 0),
     SFX_XML_NESTED_MARKUP_COMMENT, "wide <!--");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x2d, 0x41, 0, 0, 0, 0, 0, 0),
     SFX_XML_NESTED_MARKUP_GENERIC, "'-A' is not comment");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x44, 0x4f, 0x43, 0x54, 0x59,
                                                 0x50, 0x45, 32),
     SFX_XML_NESTED_MARKUP_DOCTYPE, "<!DOCTYPE + space");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x44, 0x4f, 0x43, 0x54, 0x59,
                                                 0x50, 0x45, 0x41),
     SFX_XML_NESTED_MARKUP_GENERIC, "DOCTYPE needs space after");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x44, 0x4f, 0x43, 0x54, 0x59,
                                                 0x50, 0x46, 32),
     SFX_XML_NESTED_MARKUP_GENERIC, "last letter wrong");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x5b, 0x43, 0x44, 0x41, 0x54,
                                                 0x41, 0x5b, 0),
     SFX_XML_NESTED_MARKUP_CDATA, "<![CDATA[");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x5b, 0x43, 0x44, 0x41, 0x54,
                                                 0x41, 0x5d, 0),
     SFX_XML_NESTED_MARKUP_GENERIC, "last byte must equal first '['");
  eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(0x41, 0, 0, 0, 0, 0, 0, 0),
     SFX_XML_NESTED_MARKUP_GENERIC, "'A' falls through");
  seen("v14Markup", SFX_XML_NESTED_MARKUP_GENERIC);
  seen("v14Markup", SFX_XML_NESTED_MARKUP_COMMENT);
  seen("v14Markup", SFX_XML_NESTED_MARKUP_CDATA);
  seen("v14Markup", SFX_XML_NESTED_MARKUP_DOCTYPE);

  /* Name length / error laws. */
  eq(wasm.isaac_sfx_xml_nested_parse_name_len(0x1000, 0x1010) >>> 0, 0x10);
  eq(wasm.isaac_sfx_xml_nested_parse_name_len(0xfffffff0, 0x10) >>> 0, 0x20,
     "wrap name length");
  eq(wasm.isaac_sfx_xml_nested_parse_name_error(0x1234, 0), SFX_XML_NESTED_ERR_NAME_VA,
     "empty name -> expected element name");
  eq(wasm.isaac_sfx_xml_nested_parse_name_error(0x1234, 5) >>> 0, 0x1234,
     "non-empty keeps prev");
  eq(wasm.isaac_sfx_xml_nested_parse_name_error(0x1234, 0xffffffff) >>> 0,
     0x1234, "FULL-WORD: 0xffffffff non-empty");
  eq(wasm.isaac_sfx_xml_nested_parse_name_error(0x1234, 0x100) >>> 0, 0x1234);
  seen("v14NameErr", 0);
  seen("v14NameErr", 1);

  /* Tail close error: byte after '/' == '>' keeps the slot (cmove). */
  eq(wasm.isaac_sfx_xml_nested_parse_tail_error(0x1234, 0x3e) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_nested_parse_tail_error(0x1234, 0x13e) >>> 0, 0x1234,
     "wide '>'");
  eq(wasm.isaac_sfx_xml_nested_parse_tail_error(0x1234, 0x2f),
     SFX_XML_NESTED_ERR_GT_VA, "close without '>' -> expected >");
  eq(wasm.isaac_sfx_xml_nested_parse_tail_error(0x1234, 0x100),
     SFX_XML_NESTED_ERR_GT_VA, "low 0 is not '>'");
  seen("v14CloseErr", 0);
  seen("v14CloseErr", 1);

  /* Scan NUL latch: byte 0 -> "unexpected end of data", else keep. */
  eq(wasm.isaac_sfx_xml_nested_parse_scan_error(0x1234, 0),
     SFX_XML_NESTED_ERR_UNEXPECTED_VA);
  eq(wasm.isaac_sfx_xml_nested_parse_scan_error(0x1234, 0x100),
     SFX_XML_NESTED_ERR_UNEXPECTED_VA, "wide 0");
  eq(wasm.isaac_sfx_xml_nested_parse_scan_error(0x1234, 0x41) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_nested_parse_scan_error(0x1234, 0x1ff) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_nested_parse_scan_error(0xffffffff, 0x41) >>> 0,
     0xffffffff);
  seen("v14Latch", 0);
  seen("v14Latch", 1);

  /* Node type + init template. */
  eq(wasm.isaac_sfx_xml_nested_parse_node_type(SFX_XML_NESTED_HEAD_ELEMENT, 0),
     SFX_XML_NESTED_NODE_TYPE_ELEMENT);
  eq(wasm.isaac_sfx_xml_nested_parse_node_type(SFX_XML_NESTED_HEAD_MARKUP,
                                               SFX_XML_NESTED_MARKUP_CDATA),
     SFX_XML_NESTED_NODE_TYPE_CDATA);
  eq(wasm.isaac_sfx_xml_nested_parse_node_type(SFX_XML_NESTED_HEAD_MARKUP,
                                               SFX_XML_NESTED_MARKUP_COMMENT),
     0, "comment makes no node");
  eq(wasm.isaac_sfx_xml_nested_parse_node_type(SFX_XML_NESTED_HEAD_PI, 0), 0);
  eq(wasm.isaac_sfx_xml_nested_parse_node_type(SFX_XML_NESTED_HEAD_MARKUP,
                                               SFX_XML_NESTED_MARKUP_DOCTYPE),
     0);
  seen("v14NodeType", 0);
  seen("v14NodeType", 1);
  seen("v14NodeType", 3);

  for (const off of [0x00, 0x04, 0x10, 0x14, 0x18, 0x20]) {
    eq(wasm.isaac_sfx_xml_nested_parse_node_writes_offset(off), 1,
       `init off ${off}`);
    seen("v14Init", 1);
  }
  for (const off of [0x08, 0x0c, 0x24, 0x2c, 0xffffffff, 0x100]) {
    eq(wasm.isaac_sfx_xml_nested_parse_node_writes_offset(off), 0,
       `not init off ${off}`);
    seen("v14Init", 0);
  }
  eq(wasm.isaac_sfx_xml_nested_parse_node_writes_offset(0x14), 1,
     "type offset is a store");
  /* The v11 node find offsets by reference: name pairs + heads. */
  eq(SFX_XML_NODE_OFF_NAME_00, 0x00);
  eq(SFX_XML_NODE_OFF_NAME_LEN_08, 0x08);
  eq(SFX_XML_NODE_OFF_CHILDREN_18, 0x18);
  eq(SFX_XML_NODE_OFF_ATTRS_20, 0x20);
  eq(SFX_XML_NODE_OFF_TYPE_14, 0x14);
  eq(SFX_XML_NODE_OFF_TEXT_04, 0x04);
  eq(SFX_XML_NODE_OFF_TEXT_LEN_0C, 0x0c);

  /* NUL-in-place addresses (32-bit wrap add / sub). */
  eq(wasm.isaac_sfx_xml_nested_parse_nul_position(0x1000, 4) >>> 0, 0x1004);
  eq(wasm.isaac_sfx_xml_nested_parse_nul_position(0xfffffff0, 0x10) >>> 0, 0);
  eq(wasm.isaac_sfx_xml_nested_parse_cdata_text_len(0x1008, 0x1038) >>> 0,
     0x30);
  eq(wasm.isaac_sfx_xml_nested_parse_cdata_text_len(0x1008, 0x8) >>> 0,
     0xfffff000, "wrap text len");
  /* Normalised like the differential: 0 = no node / none, 1 = a direct
     name/text address, 2 = the 0xc71640 empty-string arm. */
  seen("v14Nul", 0);
  seen("v14Nul", 1);
  seen("v14Nul", 2);

  /* Cursor arithmetic per path. ELEMENT: post_attrs then +1 (GT) / +2
     (CLOSE) / +0. PI +2, COMMENT/CDATA +3, DOCTYPE +1, GENERIC +1. */
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_ELEMENT, 0, SFX_XML_NESTED_TAIL_GT, 0x1080, 0)
     >>> 0, 0x1081, "element '>'");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_ELEMENT, 0, SFX_XML_NESTED_TAIL_CLOSE, 0x1080, 0)
     >>> 0, 0x1082, "element '/'");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_ELEMENT, 0, SFX_XML_NESTED_TAIL_OTHER, 0x1080, 0)
     >>> 0, 0x1080, "element error");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_PI, SFX_XML_NESTED_MARKUP_GENERIC, 0, 0, 0x1004)
     >>> 0, 0x1006, "pi ?>");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_COMMENT, 0, 0, 0x1003)
     >>> 0, 0x1006, "comment -->");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_CDATA, 0, 0, 0x1038)
     >>> 0, 0x103b, "cdata ]]>");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_DOCTYPE, 0, 0, 0x1040)
     >>> 0, 0x1041, "doctype >");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_GENERIC, 0, 0, 0x1020)
     >>> 0, 0x1021, "generic >");
  eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(
       SFX_XML_NESTED_HEAD_ELEMENT, 0, SFX_XML_NESTED_TAIL_GT, 0xffffffff, 0)
     >>> 0, 0, "wrap element GT");
  seen("v14Cursor", 0x1081);
  seen("v14Cursor", 0x1082);
  seen("v14Cursor", 0x1080);
  seen("v14Cursor", 0x1006);
  seen("v14Cursor", 0x1003);
  seen("v14Cursor", 0x1038);
  seen("v14Cursor", 0x1040);
  seen("v14Cursor", 0x1020);

  /* The plan, fixed rows. ELEMENT GT: allocator + attrs + children are
     three host calls; the name error is the saved slot; NUL lands at
     name_ptr + name_len. */
  const plan = SCRATCH + 0x24000;
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0x1080, SFX_XML_NESTED_HEAD_ELEMENT, SFX_XML_NESTED_MARKUP_GENERIC,
    4, 1, SFX_XML_NESTED_TAIL_GT, 0x3e, 0, 0, 0x1234, plan);
  const el = readNestedPlan(view, plan);
  eq(el.entered, 1);
  eq(el.headGate, SFX_XML_NESTED_HEAD_ELEMENT);
  eq(el.nodeType, 1);
  eq(el.allocatorCall, 1);
  eq(el.allocatorVa, 0x00416510);
  eq(el.allocatorTarget, 0x00a0f4e0);
  eq(el.nodeSize, 0x30);
  eq(el.attrsCall, 1);
  eq(el.attrsVa, 0x004165a0);
  eq(el.childrenCall, 1);
  eq(el.childrenVa, 0x00416770);
  eq(el.namePtr, 0x1000);
  eq(el.nameLen, 4);
  eq(el.nameEmpty, 0);
  eq(el.nameError, 0x1234);
  eq(el.wsSkip, 1);
  eq(el.tailGate, SFX_XML_NESTED_TAIL_GT);
  eq(el.closeError, 0);
  eq(el.errorSlot, 0x1234);
  eq(el.errorStore, 1);
  eq(el.scanLatched, 0);
  eq(el.textPtr, 0);
  eq(el.textLen, 0);
  eq(el.nulPos, 0x1004);
  eq(el.cursorAfter, 0x1081);
  eq(el.hostCalls, 3, "element GT: alloc + attrs + children");
  eq(el.pureComplete, 0);
  eq(el.sizeBytes, 0x3f1);
  eq(el.callerCount, 3);
  seen("v14Host", 3);
  seen("v14Pure", 0);

  /* ELEMENT CLOSE: the close law's prev is the JUST-STORED name error
     (the cmove re-reads the slot). close byte '>' keeps name_error. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0x1080, SFX_XML_NESTED_HEAD_ELEMENT, 0, 4, 1,
    SFX_XML_NESTED_TAIL_CLOSE, 0x3e, 0, 0, 0x1234, plan);
  let el2 = readNestedPlan(view, plan);
  eq(el2.childrenCall, 0, "CLOSE tail never calls children");
  eq(el2.closeError, 0x1234, "close '>' keeps the stored name error");
  eq(el2.errorSlot, 0x1234);
  eq(el2.cursorAfter, 0x1082);
  eq(el2.hostCalls, 2);
  seen("v14Host", 2);

  /* ELEMENT CLOSE with a non-'>' byte: "expected >". */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0x1080, SFX_XML_NESTED_HEAD_ELEMENT, 0, 4, 1,
    SFX_XML_NESTED_TAIL_CLOSE, 0x2f, 0, 0, 0x1234, plan);
  el2 = readNestedPlan(view, plan);
  eq(el2.closeError, SFX_XML_NESTED_ERR_GT_VA);
  eq(el2.errorSlot, SFX_XML_NESTED_ERR_GT_VA);
  eq(el2.cursorAfter, 0x1082);
  seen("v14ErrGT", 1);

  /* ELEMENT OTHER: unconditional 0xb1b6a8 store, cursor unchanged. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0x1080, SFX_XML_NESTED_HEAD_ELEMENT, 0, 4, 1,
    SFX_XML_NESTED_TAIL_OTHER, 0x41, 0, 0, 0x1234, plan);
  el2 = readNestedPlan(view, plan);
  eq(el2.errorSlot, SFX_XML_NESTED_ERR_GT_VA);
  eq(el2.cursorAfter, 0x1080);
  eq(el2.hostCalls, 2);
  seen("v14ErrGT", 1);

  /* ELEMENT empty name: nameEmpty FULL-WORD, the name error flips. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0x1080, SFX_XML_NESTED_HEAD_ELEMENT, 0, 0, 0,
    SFX_XML_NESTED_TAIL_GT, 0x3e, 0, 0, 0x1234, plan);
  el2 = readNestedPlan(view, plan);
  eq(el2.nameEmpty, 1);
  eq(el2.nameError, SFX_XML_NESTED_ERR_NAME_VA);
  eq(el2.errorSlot, SFX_XML_NESTED_ERR_NAME_VA, "GT tail keeps name error");
  eq(el2.nulPos, 0x1000, "empty name still NULs at name_ptr+0");
  seen("v14Empty", 1);

  /* ELEMENT with name start 0: the machine takes the 0x416165 arm and
     NULs the shared empty string 0xc71640. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0, 0x1080, SFX_XML_NESTED_HEAD_ELEMENT, 0, 4, 1,
    SFX_XML_NESTED_TAIL_GT, 0x3e, 0, 0, 0x1234, plan);
  el2 = readNestedPlan(view, plan);
  eq(el2.nulPos, SFX_ATTR_EMPTY_STRING_VA, "empty-arm target 0xc71640");
  seen("v14Nul", 2);

  /* PI: found exit always stores the latch; cursor += 2. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_PI, SFX_XML_NESTED_MARKUP_GENERIC,
    0, 0, 0, 0, 0x1004, 0, 0x1234, plan);
  const pi = readNestedPlan(view, plan);
  eq(pi.headGate, SFX_XML_NESTED_HEAD_PI);
  eq(pi.nodeType, 0, "PI makes no node");
  eq(pi.errorSlot, 0x1234, "clean scan keeps prev");
  eq(pi.errorStore, 1);
  eq(pi.cursorAfter, 0x1006);
  eq(pi.hostCalls, 0);
  seen("v14Host", 0);
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_PI, SFX_XML_NESTED_MARKUP_GENERIC,
    0, 0, 0, 0, 0x1004, 1, 0x1234, plan);
  let pi2 = readNestedPlan(view, plan);
  eq(pi2.errorSlot, SFX_XML_NESTED_ERR_UNEXPECTED_VA,
     "NUL before '?>' latches unexpected end");
  eq(pi2.errorStore, 1);
  seen("v14ErrUnexp", 1);

  /* COMMENT: always stores the latch, cursor += 3, no node. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_COMMENT,
    0, 0, 0, 0, 0x1003, 0, 0x1234, plan);
  const cm = readNestedPlan(view, plan);
  eq(cm.nodeType, 0);
  eq(cm.errorStore, 1);
  eq(cm.errorSlot, 0x1234);
  eq(cm.cursorAfter, 0x1006);
  eq(cm.hostCalls, 0);
  seen("v14MarkupK", SFX_XML_NESTED_MARKUP_COMMENT);

  /* CDATA: allocator only, node type 3, text link + NUL at found. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_CDATA,
    0, 0, 0, 0, 0x1038, 1, 0x1234, plan);
  const cd = readNestedPlan(view, plan);
  eq(cd.nodeType, 3);
  eq(cd.allocatorCall, 1);
  eq(cd.attrsCall, 0, "cdata never calls attrs");
  eq(cd.childrenCall, 0);
  eq(cd.textPtr, 0x1008, "text starts at cursor+8");
  eq(cd.textLen, 0x30, "found - text_start");
  eq(cd.nulPos, 0x1038, "NUL in place at the terminator");
  eq(cd.errorSlot, SFX_XML_NESTED_ERR_UNEXPECTED_VA, "latched");
  eq(cd.errorStore, 1);
  eq(cd.cursorAfter, 0x103b);
  eq(cd.hostCalls, 1, "cdata: allocator only");
  seen("v14Host", 1);
  seen("v14MarkupK", SFX_XML_NESTED_MARKUP_CDATA);

  /* DOCTYPE: slot stored ONLY when latched; clean '>' stores nothing. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_DOCTYPE,
    0, 0, 0, 0, 0x1040, 0, 0x1234, plan);
  const dt = readNestedPlan(view, plan);
  eq(dt.errorSlot, 0x1234, "clean doctype leaves prev untouched");
  eq(dt.errorStore, 0, "no NUL -> no slot store");
  eq(dt.cursorAfter, 0x1041);
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_DOCTYPE,
    0, 0, 0, 0, 0x1040, 1, 0x1234, plan);
  let dt2 = readNestedPlan(view, plan);
  eq(dt2.errorStore, 1, "NUL during doctype stores immediately");
  eq(dt2.errorSlot, SFX_XML_NESTED_ERR_UNEXPECTED_VA);
  seen("v14MarkupK", SFX_XML_NESTED_MARKUP_DOCTYPE);
  seen("v14ErrStore", 0);
  seen("v14ErrStore", 1);

  /* GENERIC: the immediate-'>' corner — 0x4163fa `cmp cl,0x3e ; je done`
     happens BEFORE the slot read/store, so found == cursor+1 stores
     NOTHING. */
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_GENERIC,
    0, 0, 0, 0, 0x1001, 0, 0x1234, plan);
  const gen1 = readNestedPlan(view, plan);
  eq(gen1.errorStore, 0, "immediate '>' skips the slot entirely");
  eq(gen1.errorSlot, 0x1234);
  eq(gen1.cursorAfter, 0x1002);
  wasm.isaac_sfx_xml_nested_parse_plan(
    0x1000, 0, SFX_XML_NESTED_HEAD_MARKUP, SFX_XML_NESTED_MARKUP_GENERIC,
    0, 0, 0, 0, 0x1020, 1, 0x1234, plan);
  const gen2 = readNestedPlan(view, plan);
  eq(gen2.errorStore, 1, "scanned generic stores the latch");
  eq(gen2.errorSlot, SFX_XML_NESTED_ERR_UNEXPECTED_VA);
  eq(gen2.cursorAfter, 0x1021);
  seen("v14ErrStore", 0);
  seen("v14ErrStore", 1);
  seen("v14MarkupK", SFX_XML_NESTED_MARKUP_GENERIC);
  countCase();
});

test("Wasm matches JS: v14 nested parse differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const planBase = SCRATCH + 0x25000;

  let seed = (0x00416040 ^ 0xb1ae60 ^ 0xb1b690) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const headDraws = [
    0x21, 0x3f, 0x41, 0x2f, 0x3e, 0x100 + 0x21, 0x100 + 0x3f, 0x41,
  ];
  const nameDraws = [0, 9, 10, 13, 32, 47, 62, 63, 0x41, 0x5f, 0x100, 0x1ff];
  const byteDraws = [0, 0x3e, 0x2f, 0x41, 0x7c, 0x100, 0x1ff, 0xffffffff];
  const gateDraws = [
    SFX_XML_NESTED_HEAD_ELEMENT,
    SFX_XML_NESTED_HEAD_PI,
    SFX_XML_NESTED_HEAD_MARKUP,
  ];
  const markupDraws = [
    SFX_XML_NESTED_MARKUP_GENERIC,
    SFX_XML_NESTED_MARKUP_COMMENT,
    SFX_XML_NESTED_MARKUP_CDATA,
    SFX_XML_NESTED_MARKUP_DOCTYPE,
  ];
  const tailDraws = [
    SFX_XML_NESTED_TAIL_OTHER,
    SFX_XML_NESTED_TAIL_GT,
    SFX_XML_NESTED_TAIL_CLOSE,
  ];
  const lenDraws = [0, 1, 4, 0x100, 0x1ff, 0xffffffff];
  const posDraws = [0, 1, 0x1000, 0x103b, 0xfffffff0, 0xffffffff];

  /* Scalar gates, wide drives. */
  for (let k = 0; k < 200; ++k) {
    const hb = pick(rnd, headDraws.length);
    const nb = pick(rnd, nameDraws.length);
    const bb = pick(rnd, byteDraws.length);
    seen("v14HeadB", hb);
    seen("v14NameB", nb);
    seen("v14ByteB", bb);
    const head = headDraws[hb];
    const name = nameDraws[nb];
    const b = byteDraws[bb];
    eq(wasm.isaac_sfx_xml_nested_parse_head_gate(head),
       sfxXmlNestedParseHeadGate(head), `head ${head}`);
    eq(wasm.isaac_sfx_xml_nested_parse_name_char(name),
       sfxXmlNestedParseNameChar(name), `namechar ${name}`);
    eq(wasm.isaac_sfx_xml_nested_parse_scan_error(0x1234, b),
       sfxXmlNestedParseScanError(0x1234, b), `latch ${b}`);
    eq(wasm.isaac_sfx_xml_nested_parse_tail_error(0x1234, b),
       sfxXmlNestedParseTailError(0x1234, b), `tailerr ${b}`);
    eq(wasm.isaac_sfx_xml_nested_parse_name_error(0x1234, name),
       sfxXmlNestedParseNameError(0x1234, name), `nameerr ${name}`);
    eq(wasm.isaac_sfx_xml_nested_parse_name_len(0x1000, 0x1000 + name),
       sfxXmlNestedParseNameLen(0x1000, 0x1000 + name), `namelen ${name}`);
    seen("v14Head", wasm.isaac_sfx_xml_nested_parse_head_gate(head));
    seen("v14Name", wasm.isaac_sfx_xml_nested_parse_name_char(name));
    seen("v14Latch",
         wasm.isaac_sfx_xml_nested_parse_scan_error(0x1234, b) ===
             SFX_XML_NESTED_ERR_UNEXPECTED_VA ? 1 : 0);
    countCase();
  }

  /* Markup-kind cascade over wide byte slots. */
  const mkSets = [
    [0x2d, 0x2d, 0, 0, 0, 0, 0, 0],              /* --  comment */
    [0x44, 0x4f, 0x43, 0x54, 0x59, 0x50, 0x45, 32], /* DOCTYPE + sp */
    [0x5b, 0x43, 0x44, 0x41, 0x54, 0x41, 0x5b, 0],  /* [CDATA[ */
    [0x41, 0, 0, 0, 0, 0, 0, 0],                   /* generic */
  ];
  for (const mk of mkSets) {
    eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(...mk),
       sfxXmlNestedParseMarkupKind(...mk), `markup ${mk[0]}`);
    seen("v14Markup", wasm.isaac_sfx_xml_nested_parse_markup_kind(...mk));
    countCase();
  }
  for (const mk of mkSets) {
    const wide = mk.map((x) => x + 0x100);
    eq(wasm.isaac_sfx_xml_nested_parse_markup_kind(...wide),
       sfxXmlNestedParseMarkupKind(...wide), `wide markup ${mk[0]}`);
    countCase();
  }
  for (const k of [0x78, 0x58, 0x79]) {
    for (const j of [0x6d, 0x4d, 0x6e]) {
      eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(k, j, 0x6c, 32),
         sfxXmlNestedParsePiDeclGate(k, j, 0x6c, 32), `pi ${k}/${j}`);
      countCase();
    }
  }
  for (const k of [0x78, 0x58, 0x79]) {
    eq(wasm.isaac_sfx_xml_nested_parse_pi_decl_gate(k, 0x6d, 0x6c, 0x100 + 32),
       sfxXmlNestedParsePiDeclGate(k, 0x6d, 0x6c, 0x100 + 32),
       `wide pi ${k}`);
    countCase();
  }

  /* Node-type + init-offset + arithmetic differential. */
  for (const hg of gateDraws) {
    for (const mk of markupDraws) {
      eq(wasm.isaac_sfx_xml_nested_parse_node_type(hg, mk),
         sfxXmlNestedParseNodeType(hg, mk), `nodetype ${hg}/${mk}`);
      seen("v14NodeType", wasm.isaac_sfx_xml_nested_parse_node_type(hg, mk));
      countCase();
    }
  }
  for (const off of [0x00, 0x04, 0x08, 0x0c, 0x10, 0x14, 0x18, 0x20, 0x24,
                     0x2c, 0x100, 0xffffffff]) {
    eq(wasm.isaac_sfx_xml_nested_parse_node_writes_offset(off),
       sfxXmlNestedParseNodeWritesOffset(off), `initwrites ${off}`);
    seen("v14Init", wasm.isaac_sfx_xml_nested_parse_node_writes_offset(off));
    countCase();
  }
  for (const t of [0x1000, 0x1000 + 4, 0xfffffff0 + 0x10]) {
    eq(wasm.isaac_sfx_xml_nested_parse_nul_position(t, 4) >>> 0,
       sfxXmlNestedParseNulPosition(t, 4), `nul ${t}`);
    countCase();
  }
  for (const t of [0x1008, 0x1038, 0x8, 0xfffffff0, 0xffffffff]) {
    eq(wasm.isaac_sfx_xml_nested_parse_cdata_text_len(0x1008, t) >>> 0,
       sfxXmlNestedParseCdataTextLen(0x1008, t), `textlen ${t}`);
    countCase();
  }

  /* Cursor-after differential across all path kinds. */
  for (const hg of gateDraws) {
    for (const mk of markupDraws) {
      for (const tg of tailDraws) {
        for (const pa of posDraws) {
          eq(wasm.isaac_sfx_xml_nested_parse_cursor_after(hg, mk, tg, pa, 0x50)
             >>> 0,
             sfxXmlNestedParseCursorAfter(hg, mk, tg, pa, 0x50),
             `cursor ${hg}/${mk}/${tg}/${pa}`);
          countCase();
        }
      }
    }
  }

  /* Full plan differential. Draw a head gate first, then shape the
     recaptures to that path (element: lengths + tail; scans: found +
     latch). */
  for (let k = 0; k < 400; ++k) {
    const hg = gateDraws[pick(rnd, gateDraws.length)];
    const mk = markupDraws[pick(rnd, markupDraws.length)];
    const tg = tailDraws[pick(rnd, tailDraws.length)];
    const nameLen = lenDraws[pick(rnd, lenDraws.length)];
    const wsSkip = pick(rnd, 5);
    const closeByte = byteDraws[pick(rnd, byteDraws.length)];
    const foundPos = posDraws[pick(rnd, posDraws.length)];
    const latch = bit(rnd);
    const prev = 0x1024 + pick(rnd, 4);
    const base = 0x1000;
    const postAttrs = base + nameLen + wsSkip + pick(rnd, 8);
    seen("v14PlanHg", hg);
    seen("v14PlanMk", mk);
    seen("v14PlanTg", tg);
    seen("v14PlanLatch", latch);
    seen("v14PlanLen", Math.min(nameLen, 2));
    seen("v14PlanPrev", prev);

    wasm.isaac_sfx_xml_nested_parse_plan(
      base, postAttrs, hg, mk, nameLen, wsSkip, tg, closeByte, foundPos,
      latch, prev, planBase);
    const w = readNestedPlan(view, planBase);
    const js = sfxXmlNestedParsePlan(
      base, postAttrs, hg, mk, nameLen, wsSkip, tg, closeByte, foundPos,
      latch, prev);
    assertPlanEqual(w, js, `nested plan ${k}`);
    seen("v14Host", w.hostCalls);
    seen("v14Pure", w.pureComplete);
    seen("v14ErrStore", w.errorStore);
    /* Normalised to the small law domain (0/1), not the raw slot VA. */
    seen("v14ErrUnexp",
         w.errorSlot === SFX_XML_NESTED_ERR_UNEXPECTED_VA ? 1 : 0);
    seen("v14ErrGT", w.errorSlot === SFX_XML_NESTED_ERR_GT_VA ? 1 : 0);
    seen("v14Empty", w.nameEmpty);
    seen("v14Nul", w.nulPos > 0x10000 ? 2 : (w.nulPos === 0 ? 0 : 1));
    /* Cross-law invariant: the final error slot equals the name error on
       the GT arm, the close error on the CLOSE arm, the latched value on
       scan arms, and the named strings on the OTHER arm. */
    if (hg === SFX_XML_NESTED_HEAD_ELEMENT) {
      if (tg === SFX_XML_NESTED_TAIL_GT) {
        eq(w.errorSlot, w.nameError, `GT slot == name error ${k}`);
      }
    }
    if (hg === SFX_XML_NESTED_HEAD_MARKUP &&
        mk === SFX_XML_NESTED_MARKUP_CDATA) {
      eq(w.textLen, (foundPos - (base + 8)) >>> 0, `cdata text len ${k}`);
      eq(w.allocatorCall, 1, `cdata allocator ${k}`);
    }
    countCase();
  }
});

/* ---------------- v15: 0x00416510 pool + 0x004165a0 attrs --------------
 * The node allocator's PURE pool arithmetic and the attrs parse's pure
 * decision laws. The allocator grow call (0xa0f4e0 direct /
 * [pool+0x1000c] indirect) and the attrs scanner callees (0x416b70 /
 * 0x416920) stay host — the standing allocator decision. PE-truth per
 * law, transcribed branch-by-branch from the listings:
 *   align-up 0x41651a..0x416522: x + ((-x) & 3), wrap (neg/and/add).
 *   cap 0x416525..0x41652b: grow iff align4(free)+size > end, UNSIGNED
 *     (`jbe` fast arm at 0x41652b).
 *   request 0x416533..0x416540: (size<=0x10000?0x10000:size)+0xa, UNSIGNED.
 *   grow tail 0x41656d..0x416594: link=align4(r), node=align4(link+4),
 *     base=r, end=r+req, free=node+size.
 *   attr name table 0xb1af60: 0 at {0,9,10,13,32,33,47,60,61,62,63}.
 *   attr name-empty 0x4165ee FULL-WORD cmp -> 0xb1b6c4 else prev.
 *   attr '=' gate 0x416678 LOW BYTE cmp -> 0xb1b6dc else prev.
 *   attr quote 0x4166c5..0x4166cb: 0x27 single, 0x22 double, else none.
 *   attr value-close 0x4166f3 LOW BYTE equal -> prev else 0xb1b6e8.
 *   attr value len 0x4166e6 end-start wrap; 7 node store offsets. */

test("v15 PE truth (native): pool arithmetic + attrs decision laws", () => {
  const view = new DataView(wasm.memory.buffer);
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x00416510/);
  assert.match(h, /0x00a0f4e0/);
  assert.match(h, /0x1000c/);
  assert.match(h, /0x00b1af60/);
  assert.match(h, /0x00b1b6c4/);
  assert.match(h, /0x00b1b6dc/);
  assert.match(h, /0x00b1b6e8/);
  assert.match(h, /0x00b1b6b4/);

  /* Census pins. */
  const pairs = [
    ["ISAAC_SFX_XML_POOL_ALLOC_VA", SFX_XML_POOL_ALLOC_VA, 0x00416510],
    ["ISAAC_SFX_XML_POOL_DIRECT_TARGET", SFX_XML_POOL_DIRECT_TARGET,
     0x00a0f4e0],
    ["ISAAC_SFX_XML_POOL_OFF_BASE_00", SFX_XML_POOL_OFF_BASE_00, 0x00],
    ["ISAAC_SFX_XML_POOL_OFF_FREE_04", SFX_XML_POOL_OFF_FREE_04, 0x04],
    ["ISAAC_SFX_XML_POOL_OFF_END_08", SFX_XML_POOL_OFF_END_08, 0x08],
    ["ISAAC_SFX_XML_POOL_OFF_GROW_FN_1000C", SFX_XML_POOL_OFF_GROW_FN_1000C,
     0x1000c],
    ["ISAAC_SFX_XML_POOL_ALIGN", SFX_XML_POOL_ALIGN, 4],
    ["ISAAC_SFX_XML_POOL_CAP", SFX_XML_POOL_CAP, 0x10000],
    ["ISAAC_SFX_XML_POOL_GROW_OVERHEAD", SFX_XML_POOL_GROW_OVERHEAD, 0x0a],
    ["ISAAC_SFX_XML_POOL_ERR_OOM_VA", SFX_XML_POOL_ERR_OOM_VA, 0x00b1b6b4],
    ["ISAAC_SFX_XML_POOL_ERR_SLOT_VA", SFX_XML_POOL_ERR_SLOT_VA, 0x00c7de4c],
    ["ISAAC_SFX_XML_POOL_ALLOC_SIZE_BYTES", SFX_XML_POOL_ALLOC_SIZE_BYTES,
     0x90],
    ["ISAAC_SFX_XML_POOL_ALLOC_INSNS", SFX_XML_POOL_ALLOC_INSNS, 66],
    ["ISAAC_SFX_XML_POOL_ALLOC_RETS", SFX_XML_POOL_ALLOC_RETS, 1],
    ["ISAAC_SFX_XML_POOL_ALLOC_E8", SFX_XML_POOL_ALLOC_E8, 1],
    ["ISAAC_SFX_XML_POOL_ALLOC_INDIRECT", SFX_XML_POOL_ALLOC_INDIRECT, 1],
    ["ISAAC_SFX_XML_POOL_ALLOC_STORES", SFX_XML_POOL_ALLOC_STORES, 5],
    ["ISAAC_SFX_XML_POOL_ALLOC_CALLERS", SFX_XML_POOL_ALLOC_CALLERS, 16],
    ["ISAAC_SFX_XML_ATTR_NAME_TABLE_VA", SFX_XML_ATTR_NAME_TABLE_VA,
     0x00b1af60],
    ["ISAAC_SFX_XML_ATTR_ERR_NAME_VA", SFX_XML_ATTR_ERR_NAME_VA,
     0x00b1b6c4],
    ["ISAAC_SFX_XML_ATTR_ERR_EQ_VA", SFX_XML_ATTR_ERR_EQ_VA, 0x00b1b6dc],
    ["ISAAC_SFX_XML_ATTR_ERR_VALUE_VA", SFX_XML_ATTR_ERR_VALUE_VA,
     0x00b1b6e8],
    ["ISAAC_SFX_XML_ATTR_EQ_BYTE", SFX_XML_ATTR_EQ_BYTE, 0x3d],
    ["ISAAC_SFX_XML_ATTR_QUOTE_SINGLE_BYTE", SFX_XML_ATTR_QUOTE_SINGLE_BYTE,
     0x27],
    ["ISAAC_SFX_XML_ATTR_QUOTE_DOUBLE_BYTE", SFX_XML_ATTR_QUOTE_DOUBLE_BYTE,
     0x22],
    ["ISAAC_SFX_XML_ATTR_QUOTE_SINGLE", SFX_XML_ATTR_QUOTE_SINGLE, 1],
    ["ISAAC_SFX_XML_ATTR_QUOTE_DOUBLE", SFX_XML_ATTR_QUOTE_DOUBLE, 2],
    ["ISAAC_SFX_XML_ATTR_QUOTE_NONE", SFX_XML_ATTR_QUOTE_NONE, 3],
    ["ISAAC_SFX_XML_ATTR_NODE_SIZE", SFX_XML_ATTR_NODE_SIZE, 0x1c],
    ["ISAAC_SFX_XML_ATTR_NODE_STORE_OFFSETS_COUNT",
     SFX_XML_ATTR_NODE_STORE_OFFSETS_COUNT, 7],
    ["ISAAC_SFX_XML_ATTRS_SIZE_BYTES", SFX_XML_ATTRS_SIZE_BYTES, 0x1d0],
    ["ISAAC_SFX_XML_ATTRS_INSNS", SFX_XML_ATTRS_INSNS, 152],
    ["ISAAC_SFX_XML_ATTRS_RETS", SFX_XML_ATTRS_RETS, 1],
    ["ISAAC_SFX_XML_ATTRS_E8", SFX_XML_ATTRS_E8, 3],
    ["ISAAC_SFX_XML_ATTRS_STORES", SFX_XML_ATTRS_STORES, 31],
    ["ISAAC_SFX_XML_ATTRS_CALLERS", SFX_XML_ATTRS_CALLERS, 1],
    /* v16: the children parse picks up where v15 left off. */
    ["ISAAC_SFX_XML_CHILDREN_NESTED_VA", SFX_XML_CHILDREN_NESTED_VA,
     0x00416040],
    ["ISAAC_SFX_XML_CHILDREN_SCANNER_VA", SFX_XML_CHILDREN_SCANNER_VA,
     0x00416e80],
    ["ISAAC_SFX_XML_CHILDREN_ALLOC_VA", SFX_XML_CHILDREN_ALLOC_VA,
     0x00416510],
    ["ISAAC_SFX_XML_CHILDREN_ERR_END_VA", SFX_XML_CHILDREN_ERR_END_VA,
     0x00b1b678],
    ["ISAAC_SFX_XML_CHILDREN_ERR_GT_VA", SFX_XML_CHILDREN_ERR_GT_VA,
     0x00b1b6a8],
    ["ISAAC_SFX_XML_CHILDREN_ERR_SLOT_VA", SFX_XML_CHILDREN_ERR_SLOT_VA,
     0x00c7de4c],
    ["ISAAC_SFX_XML_CHILDREN_TEXT_DEFAULT_VA",
     SFX_XML_CHILDREN_TEXT_DEFAULT_VA, 0x00c71640],
    ["ISAAC_SFX_XML_CHILDREN_TEXT_TYPE", SFX_XML_CHILDREN_TEXT_TYPE, 2],
    ["ISAAC_SFX_XML_CHILDREN_NODE_SIZE", SFX_XML_CHILDREN_NODE_SIZE, 0x30],
    ["ISAAC_SFX_XML_CHILDREN_TOP_END", SFX_XML_CHILDREN_TOP_END, 0],
    ["ISAAC_SFX_XML_CHILDREN_TOP_TAG", SFX_XML_CHILDREN_TOP_TAG, 1],
    ["ISAAC_SFX_XML_CHILDREN_TOP_TEXT", SFX_XML_CHILDREN_TOP_TEXT, 2],
    ["ISAAC_SFX_XML_CHILDREN_CLOSE_OPEN_BYTE",
     SFX_XML_CHILDREN_CLOSE_OPEN_BYTE, 0x2f],
    ["ISAAC_SFX_XML_CHILDREN_TEXT_STORE_OFFSETS_COUNT",
     SFX_XML_CHILDREN_TEXT_STORE_OFFSETS_COUNT, 9],
    ["ISAAC_SFX_XML_CHILDREN_SIZE_BYTES", SFX_XML_CHILDREN_SIZE_BYTES,
     0x1a2],
    ["ISAAC_SFX_XML_CHILDREN_INSNS", SFX_XML_CHILDREN_INSNS, 139],
    ["ISAAC_SFX_XML_CHILDREN_RETS", SFX_XML_CHILDREN_RETS, 1],
    ["ISAAC_SFX_XML_CHILDREN_E8", SFX_XML_CHILDREN_E8, 3],
    ["ISAAC_SFX_XML_CHILDREN_STORES", SFX_XML_CHILDREN_STORES, 38],
    ["ISAAC_SFX_XML_CHILDREN_CALLERS", SFX_XML_CHILDREN_CALLERS, 1],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }

  /* Align-up: x + ((-x) & 3). Machine `neg edx ; and edx,3 ; add edx,x`. */
  eq(wasm.isaac_sfx_xml_pool_align4(0) >>> 0, 0);
  eq(wasm.isaac_sfx_xml_pool_align4(1) >>> 0, 4, "1 -> 4");
  eq(wasm.isaac_sfx_xml_pool_align4(2) >>> 0, 4);
  eq(wasm.isaac_sfx_xml_pool_align4(3) >>> 0, 4);
  eq(wasm.isaac_sfx_xml_pool_align4(4) >>> 0, 4);
  eq(wasm.isaac_sfx_xml_pool_align4(5) >>> 0, 8);
  eq(wasm.isaac_sfx_xml_pool_align4(0x100) >>> 0, 0x100);
  eq(wasm.isaac_sfx_xml_pool_align4(0x101) >>> 0, 0x104);
  eq(wasm.isaac_sfx_xml_pool_align4(0x1ff) >>> 0, 0x200);
  eq(wasm.isaac_sfx_xml_pool_align4(0xffffffff) >>> 0, 0, "wrap -1");
  eq(wasm.isaac_sfx_xml_pool_align4(0xfffffffe) >>> 0, 0);
  eq(wasm.isaac_sfx_xml_pool_align4(0xfffffffd) >>> 0, 0);
  eq(wasm.isaac_sfx_xml_pool_align4(0xfffffffc) >>> 0, 0xfffffffc);
  seen("v15Align", wasm.isaac_sfx_xml_pool_align4(0) & 3);
  seen("v15Align", wasm.isaac_sfx_xml_pool_align4(5) & 3);

  /* Need-grow: UNSIGNED strictly-above compare (`jbe` fast arm). */
  eq(wasm.isaac_sfx_xml_pool_need_grow(0, 0x10, 0x10), 0,
     "exactly at end is fast");
  eq(wasm.isaac_sfx_xml_pool_need_grow(0, 0x10, 0x11), 1, "1 over grows");
  eq(wasm.isaac_sfx_xml_pool_need_grow(1, 0x14, 0x10), 0,
     "aligned 4 + 16 == 0x14 is fast");
  eq(wasm.isaac_sfx_xml_pool_need_grow(1, 0x13, 0x10), 1);
  eq(wasm.isaac_sfx_xml_pool_need_grow(0xfffffffc, 0xffffffff, 0x100), 0,
     "wrap claimed 0xfc <= end");
  eq(wasm.isaac_sfx_xml_pool_need_grow(0, 0xffffffff, 0xffffffff), 0,
     "claimed == end is fast");
  eq(wasm.isaac_sfx_xml_pool_need_grow(0, 0xfffffffe, 0xffffffff), 1);
  eq(wasm.isaac_sfx_xml_pool_need_grow(0x100, 0x100, 0x100), 1);
  seen("v15Grow", wasm.isaac_sfx_xml_pool_need_grow(0, 0x10, 0x10));
  seen("v15Grow", wasm.isaac_sfx_xml_pool_need_grow(0, 0x10, 0x11));

  /* Grow request: UNSIGNED cap + 0xa. */
  eq(wasm.isaac_sfx_xml_pool_grow_request(0) >>> 0, 0x1000a);
  eq(wasm.isaac_sfx_xml_pool_grow_request(0x100) >>> 0, 0x1000a);
  eq(wasm.isaac_sfx_xml_pool_grow_request(0x1ff) >>> 0, 0x1000a);
  eq(wasm.isaac_sfx_xml_pool_grow_request(0xffff) >>> 0, 0x1000a);
  eq(wasm.isaac_sfx_xml_pool_grow_request(0x10000) >>> 0, 0x1000a,
     "at cap keeps cap");
  eq(wasm.isaac_sfx_xml_pool_grow_request(0x10001) >>> 0, 0x1000b);
  eq(wasm.isaac_sfx_xml_pool_grow_request(0xffffffff) >>> 0, 9,
     "unsigned: 0xffffffff > cap, +0xa wraps");
  eq(wasm.isaac_sfx_xml_pool_grow_request(0xfffffff6) >>> 0, 0,
     "wrap to 0");
  seen("v15Cap", 0);
  seen("v15Cap", 1);

  /* Grow tail: the layout arithmetic given the HOST alloc result. */
  const tail = SCRATCH + 0x26200;
  wasm.isaac_sfx_xml_pool_grow_tail(0x1000, 0x1000a, 0x1c, tail);
  let t = readPoolGrowTail(view, tail);
  eq(t.linkSlot, 0x1000);
  eq(t.nodePtr, 0x1004);
  eq(t.newBase, 0x1000);
  eq(t.newEnd, 0x1100a);
  eq(t.newFree, 0x1020);
  seen("v15Tail", 0);
  wasm.isaac_sfx_xml_pool_grow_tail(0x1001, 0xa, 4, tail);
  t = readPoolGrowTail(view, tail);
  eq(t.linkSlot, 0x1004, "misaligned alloc aligns the link slot");
  eq(t.nodePtr, 0x1008);
  eq(t.newBase, 0x1001);
  eq(t.newEnd, 0x100b);
  eq(t.newFree, 0x100c);
  seen("v15Tail", 1);
  wasm.isaac_sfx_xml_pool_grow_tail(0xffffffff, 0xa, 4, tail);
  t = readPoolGrowTail(view, tail);
  eq(t.linkSlot, 0, "wrap alloc");
  eq(t.nodePtr, 4);
  eq(t.newBase, 0xffffffff);
  eq(t.newEnd, 9, "wrap end");
  eq(t.newFree, 8, "wrap free");
  countCase();

  /* Pool plan: grow=0 -> the cap arithmetic is never computed. */
  const plan = SCRATCH + 0x26300;
  wasm.isaac_sfx_xml_pool_plan(0, 0x1000, 0x100, plan);
  let p = readPoolPlan(view, plan);
  eq(p.alignedFree, 0);
  eq(p.fastBump, 0x100);
  eq(p.grow, 0);
  eq(p.growRequest, 0, "fast arm never runs the cap math");
  eq(p.poolSlots, 4);
  eq(p.allocVa, 0x00416510);
  eq(p.allocTarget, 0x00a0f4e0);
  eq(p.growFnOffset, 0x1000c);
  eq(p.hostCalls, 0, "no grow -> no alloc call");
  eq(p.pureComplete, 0);
  seen("v15Host", 0);
  wasm.isaac_sfx_xml_pool_plan(1, 0x103, 0x100, plan);
  p = readPoolPlan(view, plan);
  eq(p.alignedFree, 4);
  eq(p.fastBump, 0x104);
  eq(p.grow, 1);
  eq(p.growRequest, 0x1000a, "grow arm computes the request");
  eq(p.hostCalls, 1);
  seen("v15Host", 1);
  wasm.isaac_sfx_xml_pool_plan(0xfffffff0, 0xffffffff, 0x100, plan);
  p = readPoolPlan(view, plan);
  eq(p.alignedFree, 0xfffffff0);
  eq(p.fastBump, 0xf0, "wrap claimed");
  eq(p.grow, 0);
  eq(p.growRequest, 0);
  seen("v15Wrap", 0);
  seen("v15Wrap", 1);

  /* Attr name table 0xb1af60: 0 at exactly {0,9,10,13,32,33,47,60,61,62,
     63}. STRICTER than the element table: '!' '<' '=' are attr-name
     stops but element-name chars. */
  for (const z of [0, 9, 10, 13, 32, 33, 47, 60, 61, 62, 63]) {
    eq(wasm.isaac_sfx_xml_attr_name_char(z), 0, `attr name zero ${z}`);
    seen("v15Name", 0);
  }
  for (const z of [0x100 + 33, 0x100 + 61]) {
    eq(wasm.isaac_sfx_xml_attr_name_char(z), 0, `wide attr zero ${z}`);
    seen("v15Name", 0);
  }
  for (const one of [1, 8, 11, 0x41, 0x5f, 0xff]) {
    eq(wasm.isaac_sfx_xml_attr_name_char(one), 1, `attr name one ${one}`);
    seen("v15Name", 1);
  }
  eq(wasm.isaac_sfx_xml_attr_name_char(0x41), 1, "'A'");
  eq(wasm.isaac_sfx_xml_attr_name_char(0x141), 1, "wide 'A'");
  eq(wasm.isaac_sfx_xml_attr_name_char(0xffffffff), 1);
  eq(wasm.isaac_sfx_xml_attr_name_char(0x21), 0, "'!' stops attr names");
  eq(wasm.isaac_sfx_xml_attr_name_char(0x3c), 0, "'<' stops attr names");
  eq(wasm.isaac_sfx_xml_attr_name_char(0x3d), 0, "'=' stops attr names");
  eq(wasm.isaac_sfx_xml_nested_parse_name_char(0x21), 1,
     "but '!' is an ELEMENT name char (0xb1ae60)");
  eq(wasm.isaac_sfx_xml_nested_parse_name_char(0x3c), 1,
     "and '<' too");
  seen("v15Name", 1);

  /* FULL-WORD name-empty -> 0xb1b6c4. */
  eq(wasm.isaac_sfx_xml_attr_name_error(0x1234, 0),
     SFX_XML_ATTR_ERR_NAME_VA, "empty attr name");
  eq(wasm.isaac_sfx_xml_attr_name_error(0x1234, 5) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_attr_name_error(0x1234, 0xffffffff) >>> 0, 0x1234,
     "FULL-WORD non-empty");
  eq(wasm.isaac_sfx_xml_attr_name_error(0xfffffff0, 0) >>> 0,
     SFX_XML_ATTR_ERR_NAME_VA);
  seen("v15NameErr", 0);
  seen("v15NameErr", 1);

  /* '=' gate: LOW BYTE. */
  eq(wasm.isaac_sfx_xml_attr_eq_error(0x1234, 0x3d) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_attr_eq_error(0x1234, 0x13d) >>> 0, 0x1234,
     "wide '='");
  eq(wasm.isaac_sfx_xml_attr_eq_error(0x1234, 0x41),
     SFX_XML_ATTR_ERR_EQ_VA, "no '='");
  eq(wasm.isaac_sfx_xml_attr_eq_error(0x1234, 0x100),
     SFX_XML_ATTR_ERR_EQ_VA, "low 0 is not '='");
  seen("v15EqErr", 0);
  seen("v15EqErr", 1);

  /* Quote dispatch: 0x27 single, 0x22 double, else none (machine order). */
  eq(wasm.isaac_sfx_xml_attr_quote_kind(0x27), SFX_XML_ATTR_QUOTE_SINGLE);
  eq(wasm.isaac_sfx_xml_attr_quote_kind(0x127), SFX_XML_ATTR_QUOTE_SINGLE);
  eq(wasm.isaac_sfx_xml_attr_quote_kind(0x22), SFX_XML_ATTR_QUOTE_DOUBLE);
  eq(wasm.isaac_sfx_xml_attr_quote_kind(0x122), SFX_XML_ATTR_QUOTE_DOUBLE);
  eq(wasm.isaac_sfx_xml_attr_quote_kind(0x41), SFX_XML_ATTR_QUOTE_NONE);
  eq(wasm.isaac_sfx_xml_attr_quote_kind(0x100), SFX_XML_ATTR_QUOTE_NONE);
  eq(wasm.isaac_sfx_xml_attr_quote_kind(0xffffffff), SFX_XML_ATTR_QUOTE_NONE);
  seen("v15Quote", SFX_XML_ATTR_QUOTE_SINGLE);
  seen("v15Quote", SFX_XML_ATTR_QUOTE_DOUBLE);
  seen("v15Quote", SFX_XML_ATTR_QUOTE_NONE);

  /* Value-close: LOW-BYTE equality on the two bytes. */
  eq(wasm.isaac_sfx_xml_attr_value_error(0x1234, 0x27, 0x27) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_attr_value_error(0x1234, 0x27, 0x127) >>> 0, 0x1234,
     "wide equal bytes");
  eq(wasm.isaac_sfx_xml_attr_value_error(0x1234, 0x27, 0x41),
     SFX_XML_ATTR_ERR_VALUE_VA, "unterminated");
  eq(wasm.isaac_sfx_xml_attr_value_error(0x1234, 0x41, 0x41) >>> 0, 0x1234,
     "unquoted terminator equals the saved byte");
  eq(wasm.isaac_sfx_xml_attr_value_error(0x1234, 0x100, 0x100) >>> 0, 0x1234,
     "both low 0");
  eq(wasm.isaac_sfx_xml_attr_value_error(0xffffffff, 0x27, 0x28) >>> 0,
     SFX_XML_ATTR_ERR_VALUE_VA);
  seen("v15ValErr", 0);
  seen("v15ValErr", 1);

  /* Value length: end - start, wrap. */
  eq(wasm.isaac_sfx_xml_attr_value_len(0x1000, 0x1030) >>> 0, 0x30);
  eq(wasm.isaac_sfx_xml_attr_value_len(0x1030, 0x1000) >>> 0, 0xffffffd0,
     "wrap value len (0x1000 - 0x1030 = -0x30)");
  eq(wasm.isaac_sfx_xml_attr_value_len(0xfffffff0, 0x10) >>> 0, 0x20);
  seen("v15ValLen", 0);
  seen("v15ValLen", 1);

  /* The 7 attr-node store offsets; 0x08/0x0c are attr-specific (the
     element init template does NOT store them). */
  for (const off of [0x00, 0x04, 0x08, 0x0c, 0x10, 0x14, 0x18]) {
    eq(wasm.isaac_sfx_xml_attr_node_writes_offset(off), 1, `attr off ${off}`);
    seen("v15Store", 1);
  }
  for (const off of [0x20, 0x24, 0x2c, 0x100, 0xffffffff]) {
    eq(wasm.isaac_sfx_xml_attr_node_writes_offset(off), 0, `not attr ${off}`);
    seen("v15Store", 0);
  }
  eq(wasm.isaac_sfx_xml_attr_node_writes_offset(0x08), 1,
     "attr stores name len");
  eq(wasm.isaac_sfx_xml_nested_parse_node_writes_offset(0x08), 0,
     "element template does not");

  /* Attr plan, fixed rows. */
  const aplan = SCRATCH + 0x26400;
  /* Not entered: first byte is not an attr-name char -> the 0x4165b5
     arm returns without touching anything. */
  wasm.isaac_sfx_xml_attr_plan(0x1234, 0x20, 0, 0, 0, 0, 0, 0, aplan);
  let ap = readAttrPlan(view, aplan);
  eq(ap.entered, 0, "space starts no attribute");
  eq(ap.nameEmpty, 0);
  eq(ap.nameError, 0x1234);
  eq(ap.quoteKind, SFX_XML_ATTR_QUOTE_NONE);
  eq(ap.eqError, 0x1234);
  eq(ap.valueError, 0x1234);
  eq(ap.errorSlot, 0x1234, "slot untouched when not entered");
  eq(ap.valueLen, 0);
  eq(ap.allocatorVa, 0x00416510);
  eq(ap.nodeSize, 0x1c);
  eq(ap.nodeStores, 0);
  eq(ap.hostCalls, 0);
  eq(ap.pureComplete, 0);
  eq(ap.sizeBytes, 0x1d0);
  eq(ap.callerCount, 1);
  seen("v15Entered", 0);
  seen("v15NodeStores", 0);
  seen("v15AHost", 0);

  /* Entered, unquoted value: the scan pre-stores 0xb1b6e8 (0x4166d0), so
     the close law's prev IS 0xb1b6e8; end != saved byte keeps it. */
  wasm.isaac_sfx_xml_attr_plan(0x1234, 0x61, 2, 0x3d, 0x61, 0x20, 0x2000,
                               0x2004, aplan);
  ap = readAttrPlan(view, aplan);
  eq(ap.entered, 1);
  eq(ap.nameEmpty, 0);
  eq(ap.nameError, 0x1234);
  eq(ap.quoteKind, SFX_XML_ATTR_QUOTE_NONE);
  eq(ap.eqError, 0x1234, "'=' present keeps prev");
  eq(ap.valueError, SFX_XML_ATTR_ERR_VALUE_VA, "unquoted terminator");
  eq(ap.errorSlot, SFX_XML_ATTR_ERR_VALUE_VA);
  eq(ap.valueLen, 4);
  eq(ap.nodeStores, 7);
  eq(ap.hostCalls, 2);
  seen("v15Entered", 1);
  seen("v15NodeStores", 7);
  seen("v15AHost", 2);
  seen("v15Quote", ap.quoteKind);

  /* Entered, single-quoted, clean close: quote matches -> the '=' gate
     value survives. */
  wasm.isaac_sfx_xml_attr_plan(0x1234, 0x61, 2, 0x3d, 0x27, 0x27, 0x2000,
                               0x2004, aplan);
  ap = readAttrPlan(view, aplan);
  eq(ap.quoteKind, SFX_XML_ATTR_QUOTE_SINGLE);
  eq(ap.eqError, 0x1234);
  eq(ap.valueError, 0x1234, "clean quoted close keeps the slot");
  eq(ap.errorSlot, 0x1234);
  seen("v15ValErr", 0);

  /* Single-quoted but unterminated (end byte 0x0a != 0x27). */
  wasm.isaac_sfx_xml_attr_plan(0x1234, 0x61, 2, 0x3d, 0x27, 0x0a, 0x2000,
                               0x2004, aplan);
  ap = readAttrPlan(view, aplan);
  eq(ap.valueError, SFX_XML_ATTR_ERR_VALUE_VA);
  eq(ap.errorSlot, SFX_XML_ATTR_ERR_VALUE_VA);
  seen("v15ValErr", 1);

  /* Empty attr name -> 0xb1b6c4, then the '=' gate re-reads it. */
  wasm.isaac_sfx_xml_attr_plan(0x1234, 0x61, 0, 0x3d, 0x27, 0x27, 0, 0,
                               aplan);
  ap = readAttrPlan(view, aplan);
  eq(ap.nameEmpty, 1);
  eq(ap.nameError, SFX_XML_ATTR_ERR_NAME_VA);
  eq(ap.eqError, SFX_XML_ATTR_ERR_NAME_VA, "equals byte keeps the name error");
  eq(ap.valueError, SFX_XML_ATTR_ERR_NAME_VA, "clean close keeps it too");
  eq(ap.errorSlot, SFX_XML_ATTR_ERR_NAME_VA);
  seen("v15NameErr", 1);
  countCase();
});

test("v20 PE truth (native): 0x00416510 allocator arm-select + OOM slot", () => {
  const view = new DataView(wasm.memory.buffer);
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x00416510/);
  assert.match(h, /0x416543/);   /* the arm-select test/je */
  assert.match(h, /0x41655a/);   /* mov eax,0xb1b6b4 */
  assert.match(h, /0x416561/);   /* the OOM cmovne */
  assert.match(h, /0x00b1b6b4/); /* "out of memory" */
  assert.match(h, /0x1000c/);    /* the pool grow-fn slot */

  const pairs = [
    ["ISAAC_SFX_XML_POOL_ARM_DIRECT", SFX_XML_POOL_ARM_DIRECT, 0],
    ["ISAAC_SFX_XML_POOL_ARM_INDIRECT", SFX_XML_POOL_ARM_INDIRECT, 1],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }

  /* Arm select, PE 0x41653a loads eax = [pool+0x1000c] (the pool mark /
     grow fn), 0x416543 `test eax,eax ; je 0x416551` — FULL-WORD zero
     test; 0 routes to the DIRECT arm (0xa0f4e0). Address-stable
     name; identify-zhl has no exact match. The grow fn is a pointer, so
     the WIDE drives 0x100/0x1ff/0xffffffff must all be INDIRECT — a
     low-byte transcription would misclassify 0x100 (low 0). */
  eq(wasm.isaac_sfx_xml_pool_grow_arm(0), SFX_XML_POOL_ARM_DIRECT,
     "pool mark 0 -> direct 0xa0f4e0");
  eq(wasm.isaac_sfx_xml_pool_grow_arm(0x100), SFX_XML_POOL_ARM_INDIRECT,
     "wide mark -> indirect (FULL-WORD)");
  eq(wasm.isaac_sfx_xml_pool_grow_arm(0x1ff), SFX_XML_POOL_ARM_INDIRECT);
  eq(wasm.isaac_sfx_xml_pool_grow_arm(0xffffffff), SFX_XML_POOL_ARM_INDIRECT,
     "FULL-WORD: 0xffffffff is a live pointer");
  eq(wasm.isaac_sfx_xml_pool_grow_arm(0x1000), SFX_XML_POOL_ARM_INDIRECT);
  seen("v20Arm", 0); seen("v20Arm", 1);
  countCase();

  /* OOM slot VALUE, PE 0x41655a..0x416561 `mov eax,0xb1b6b4 ; test
     edx,edx ; cmovne eax,[0xc7de4c]` — r == 0 -> OOM VA, else the PREV
     slot (recaptured). FULL-WORD test on r: 0x100/0x1ff/0xffffffff are
     SUCCESSFUL allocs and keep prev. */
  eq(wasm.isaac_sfx_xml_pool_oom_slot(0, 0x1234) >>> 0,
     SFX_XML_POOL_ERR_OOM_VA, "alloc failed -> out of memory");
  eq(wasm.isaac_sfx_xml_pool_oom_slot(0, 0xffffffff) >>> 0,
     SFX_XML_POOL_ERR_OOM_VA, "failure with wide prev slot");
  eq(wasm.isaac_sfx_xml_pool_oom_slot(0x100, 0x1234) >>> 0, 0x1234,
     "FULL-WORD: 0x100 is a successful alloc");
  eq(wasm.isaac_sfx_xml_pool_oom_slot(0x1ff, 0x1234) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_pool_oom_slot(0xffffffff, 0x1234) >>> 0, 0x1234,
     "0xffffffff keeps prev");
  eq(wasm.isaac_sfx_xml_pool_oom_slot(0x1000, 0) >>> 0, 0);
  eq(wasm.isaac_sfx_xml_pool_oom_slot(0, 0) >>> 0, SFX_XML_POOL_ERR_OOM_VA);
  seen("v20Oom", 0); seen("v20Oom", 1);
  countCase();
});

test("Wasm matches JS: v20 allocator arm + OOM slot differential", () => {
  let seed = (0x00416510 ^ 0x416543 ^ 0x416561 ^ 0x00b1b6b4) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const ptrDraws = [0, 0x100, 0x1ff, 0x1000, 0xfffffff0, 0xffffffff,
                    0xffff0000];
  const slotDraws = [0, 0x1111, 0x1234, 0xb1b6b4, 0xc7de4c, 0xffffffff];

  for (let k = 0; k < 400; ++k) {
    const gf = ptrDraws[pick(rnd, ptrDraws.length)];
    const r = ptrDraws[pick(rnd, ptrDraws.length)];
    const prev = slotDraws[pick(rnd, slotDraws.length)];

    eq(wasm.isaac_sfx_xml_pool_grow_arm(gf),
       sfxXmlPoolGrowArm(gf), `arm ${gf} (0x${gf.toString(16)})`);
    eq(wasm.isaac_sfx_xml_pool_oom_slot(r, prev) >>> 0,
       sfxXmlPoolOomSlot(r, prev), `oom r=0x${r.toString(16)} prev=0x${prev.toString(16)}`);
    seen("v20Arm", sfxXmlPoolGrowArm(gf));
    seen("v20Oom", sfxXmlPoolOomSlot(r, prev) === SFX_XML_POOL_ERR_OOM_VA
      ? 0 : 1);
    countCase();
  }
  /* Cross-law differential: the arm that 0xa0f4e0 runs on is exactly the
     direct arm the OOM slot belongs to. When the pool mark is 0 the
     allocator calls 0xa0f4e0 DIRECT and only then can the OOM slot law
     fire; a non-zero mark routes the request to [pool+0x1000c] and the
     slot is untouched (0x41654f jumps to the common tail). */
  eq(sfxXmlPoolGrowArm(0), SFX_XML_POOL_ARM_DIRECT);
  eq(sfxXmlPoolOomSlot(0, 0x1234), SFX_XML_POOL_ERR_OOM_VA);
});

test("v21 PE truth (native): 0x0092d140 element dispatch + sound gate", () => {
  const view = new DataView(wasm.memory.buffer);
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x0092d140/);
  assert.match(h, /0x92d466/);   /* the sound-element FULL-WORD gate */
  assert.match(h, /0x92d468/);   /* je 0x92db29 — the epilogue skip */
  assert.match(h, /0xb7b1b4/);   /* "sounds" — pushed at 0x92d3f2 */
  assert.match(h, /0xb66f40/);   /* "root" — pushed at 0x92d403 */
  assert.match(h, /0xb7b1ac/);   /* "sound" — pushed at 0x92d454 */
  assert.match(h, /0x413c70/);   /* the CHILD find (v12, pure) */

  const pairs = [
    ["ISAAC_SFX_XML_ELEM_SOUNDS_VA", SFX_XML_ELEM_SOUNDS_VA, 0xb7b1b4],
    ["ISAAC_SFX_XML_ELEM_SOUNDS_LEN", SFX_XML_ELEM_SOUNDS_LEN, 7],
    ["ISAAC_SFX_XML_ELEM_ROOT_VA", SFX_XML_ELEM_ROOT_VA, 0xb66f40],
    ["ISAAC_SFX_XML_ELEM_ROOT_LEN", SFX_XML_ELEM_ROOT_LEN, 4],
    ["ISAAC_SFX_XML_ELEM_SOUND_VA", SFX_XML_ELEM_SOUND_VA, 0xb7b1ac],
    ["ISAAC_SFX_XML_ELEM_SOUND_LEN", SFX_XML_ELEM_SOUND_LEN, 5],
    ["ISAAC_SFX_XML_SEH_STATE_PARSE", SFX_XML_SEH_STATE_PARSE, 1],
    ["ISAAC_SFX_XML_SEH_STATE_SOUND", SFX_XML_SEH_STATE_SOUND, 2],
    ["ISAAC_SFX_XML_ROOT_NAME_READ_OFF", SFX_XML_ROOT_NAME_READ_OFF, 4],
    ["ISAAC_SFX_XML_FIND_VARIANT_CHILD", SFX_XML_FIND_VARIANT_CHILD, 0],
    ["ISAAC_SFX_XML_FIND_VARIANT_ATTR", SFX_XML_FIND_VARIANT_ATTR, 1],
    ["ISAAC_SFX_SOUND_PIPE_ALL", SFX_SOUND_PIPE_ALL, 0xff],
    ["ISAAC_SFX_XML_SOUND_DISPATCH_HOST_CALLS",
     SFX_XML_SOUND_DISPATCH_HOST_CALLS, 4],
    ["ISAAC_SFX_XML_SOUND_DISPATCH_SIZE_BYTES",
     SFX_XML_SOUND_DISPATCH_SIZE_BYTES, 0x84],
    ["ISAAC_SFX_XML_SOUND_DISPATCH_CALLERS",
     SFX_XML_SOUND_DISPATCH_CALLERS, 2],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }

  /* The dispatch-name table — index 0..2 = sounds/root/sound; -1 out of
     range (the fill_header_offset convention). */
  eq(wasm.isaac_sfx_xml_dispatch_elem_va(0) >>> 0, 0xb7b1b4, "sounds va");
  eq(wasm.isaac_sfx_xml_dispatch_elem_len(0) >>> 0, 7, "sounds len");
  eq(wasm.isaac_sfx_xml_dispatch_elem_va(1) >>> 0, 0xb66f40, "root va");
  eq(wasm.isaac_sfx_xml_dispatch_elem_len(1) >>> 0, 4, "root len");
  eq(wasm.isaac_sfx_xml_dispatch_elem_va(2) >>> 0, 0xb7b1ac, "sound va");
  eq(wasm.isaac_sfx_xml_dispatch_elem_len(2) >>> 0, 5, "sound len");
  eq(wasm.isaac_sfx_xml_dispatch_elem_va(-1), -1, "OOR va");
  eq(wasm.isaac_sfx_xml_dispatch_elem_len(3), -1, "OOR len");
  eq(wasm.isaac_sfx_xml_dispatch_elem_len(0xffffffff | 0), -1, "wide OOR");
  seen("v21Elem", 0); seen("v21Elem", 1); seen("v21Elem", 2);
  countCase();

  /* The sound-element gate, PE 0x92d466 `test esi,esi ; je 0x92db29` on
     the find("sound") result — FULL-WORD (the tail_chain_continue 0x92db21
     family). 0x100/0x1ff/0xffffffff are LIVE nodes and pass; a low-byte
     transcription would skip 0x100 (low byte 0). */
  eq(wasm.isaac_sfx_xml_sound_gate(0), 0, "no sound element -> epilogue");
  eq(wasm.isaac_sfx_xml_sound_gate(1), 1);
  eq(wasm.isaac_sfx_xml_sound_gate(0x100), 1, "FULL-WORD: 0x100 is live");
  eq(wasm.isaac_sfx_xml_sound_gate(0x1ff), 1);
  eq(wasm.isaac_sfx_xml_sound_gate(0xffffffff), 1);
  eq(wasm.isaac_sfx_xml_sound_gate(0x1000), 1);
  seen("v21Gate", 0); seen("v21Gate", 1);
  countCase();

  /* The composed dispatch record. The gate is ONLY the sound find: the
     machine branches NOWHERE on find("sounds") or the root attr, so even
     a null "sounds"/"root" result still reports them and only the sound
     result decides the pipeline. */
  const plan = SCRATCH + 0x29000;
  wasm.isaac_sfx_xml_sound_dispatch_plan(0, 0, 0, plan);
  let dp = readSoundDispatchPlan(view, plan);
  eq(dp.soundsFound, 0);
  eq(dp.rootAttrFound, 0);
  eq(dp.soundFound, 0);
  eq(dp.loopEntered, 0);
  eq(dp.epilogueSkip, 1, "no sound element -> the 0x92db29 epilogue");
  eq(dp.stagesMask, 0, "the whole pipeline is skipped");
  eq(dp.perSoundHostCalls, 0);
  eq(dp.dispatchHostCalls, SFX_XML_SOUND_DISPATCH_HOST_CALLS,
     "the 3 finds + 1 assign still run");
  eq(dp.sehStateParse, SFX_XML_SEH_STATE_PARSE);
  eq(dp.sehStateSound, SFX_XML_SEH_STATE_SOUND);
  eq(dp.rootNameReadOff, SFX_XML_ROOT_NAME_READ_OFF);
  eq(dp.soundsFindKind, SFX_XML_FIND_VARIANT_CHILD);
  eq(dp.rootFindKind, SFX_XML_FIND_VARIANT_ATTR);
  eq(dp.soundFindKind, SFX_XML_FIND_VARIANT_CHILD);
  eq(dp.soundsElemVa >>> 0, SFX_XML_ELEM_SOUNDS_VA);
  eq(dp.rootElemVa >>> 0, SFX_XML_ELEM_ROOT_VA);
  eq(dp.soundElemVa >>> 0, SFX_XML_ELEM_SOUND_VA);
  eq(dp.sizeBytes, SFX_XML_SOUND_DISPATCH_SIZE_BYTES);
  eq(dp.callerCount, SFX_XML_SOUND_DISPATCH_CALLERS);
  seen("v21Pipe", 0);
  countCase();

  /* Sound element found (a null "sounds"/"root" does NOT kill it — the
     machine has no gate there). WIDE find_sound passes the FULL-WORD
     gate. */
  wasm.isaac_sfx_xml_sound_dispatch_plan(0, 0, 0x100, plan);
  dp = readSoundDispatchPlan(view, plan);
  eq(dp.soundsFound, 0, "null 'sounds' find is only reported");
  eq(dp.rootAttrFound, 0, "null root attr is only reported");
  eq(dp.soundFound, 1, "the 0x100 sound node is LIVE (FULL-WORD)");
  eq(dp.loopEntered, 1);
  eq(dp.epilogueSkip, 0);
  eq(dp.stagesMask, SFX_SOUND_PIPE_ALL,
     "proto -> attrs -> append -> fill -> sample -> slot -> tail -> chain");
  eq(dp.perSoundHostCalls, 1, "SoundEffect::Load per visited node");
  seen("v21Pipe", 1);
  countCase();

  /* The FULL-WORD nature of the pipe gate: 0x100 on the SOUND result vs
     the reports of the first two finds. */
  wasm.isaac_sfx_xml_sound_dispatch_plan(0x100, 0, 0xffffffff, plan);
  dp = readSoundDispatchPlan(view, plan);
  eq(dp.soundsFound, 1);
  eq(dp.rootAttrFound, 0);
  eq(dp.soundFound, 1);
  eq(dp.epilogueSkip, 0);
  countCase();
});

test("Wasm matches JS: v21 dispatch + sound gate differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const plan = SCRATCH + 0x29000;
  const chain = SCRATCH + 0x29080;
  const links = SCRATCH + 0x29090;

  let seed = (0x0092d140 ^ 0x92d466 ^ 0xb7b1b4 ^ 0xb66f40 ^ 0xb7b1ac) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const nodeDraws = [0, 0x100, 0x1ff, 0x1000, 0xfffffff0, 0xffffffff,
                     0xffff0000];

  for (let k = 0; k < 400; ++k) {
    const sf = nodeDraws[pick(rnd, nodeDraws.length)];
    const rf = nodeDraws[pick(rnd, nodeDraws.length)];
    const fd = nodeDraws[pick(rnd, nodeDraws.length)];

    eq(wasm.isaac_sfx_xml_sound_gate(fd) >>> 0,
       sfxXmlSoundGate(fd), `gate 0x${fd.toString(16)}`);
    wasm.isaac_sfx_xml_sound_dispatch_plan(sf, rf, fd, plan);
    assertPlanEqual(readSoundDispatchPlan(view, plan),
                    sfxXmlSoundDispatchPlan(sf, rf, fd), `dispatch ${k}`);
    seen("v21Gate", sfxXmlSoundGate(fd));
    seen("v21Pipe", sfxXmlSoundGate(fd));
    seen("v21Elem", pick(rnd, 3));
    countCase();

    /* Cross-law differential: the sound-element gate IS the FIRST link
       test of the v6 sound-chain walk — head_nonzero at 0x92d466 is the
       very same FULL-WORD test, and the tail-chain continue at 0x92db21
       re-uses it per link. */
    const dir = new Uint32Array(wasm.memory.buffer, links, 1);
    dir[0] = fd;
    const done = new Int32Array(wasm.memory.buffer, chain);
    wasm.isaac_sfx_sound_chain_plan(fd, links, 1, chain);
    eq(done[0] !== 0 ? 1 : 0, sfxXmlSoundGate(fd),
       `chain head == gate (0x${fd.toString(16)})`);
    eq(done[1], sfxXmlSoundGate(fd) !== 0 ? 1 : 0,
       "chain sees one visited sound");
    eq(wasm.isaac_sfx_xml_sound_gate(fd),
       wasm.isaac_sfx_tail_chain_continue(fd),
       "gate row equals the tail chain continue row");
    countCase();
  }
});

test("v22 PE truth (native): 0x0092cfb0 Load hook wiring + voice free", () => {
  const view = new DataView(wasm.memory.buffer);
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x0092cfb0/);
  assert.match(h, /0x92d094/);   /* mov ecx,[ebp-0x34] - the probe target */
  assert.match(h, /0x92d097/);   /* test ecx,ecx ; je - FULL-WORD gate */
  assert.match(h, /0x92d0a2/);   /* test al,al ; je - LOW-BYTE gate */
  assert.match(h, /0x92d0ab/);   /* test eax,eax - hook ptr gate */
  assert.match(h, /c7f484/);   /* the attach-hook fn pointer */
  assert.match(h, /0x92d0ca/);   /* cmp cap,0x10 ; jb - the SSO free skip */
  assert.match(h, /0x92d0cf/);   /* lea ecx,[cap+1] - size = cap+1 */
  assert.match(h, /0x92d0d4/);   /* cmp size,0x1000 ; jb - fast free */
  assert.match(h, /0x92d0e7/);   /* cmp slack,0x1f ; ja - UNSIGNED fatal */
  assert.match(h, /b18894/);   /* the corrupt-free abort IAT */

  eq(headerConstant(h, "ISAAC_SFX_LOAD_PROBE_SLOT_0C"),
     SFX_LOAD_PROBE_SLOT_0C, "header probe slot");
  eq(SFX_LOAD_PROBE_SLOT_0C, 0x0c, "vtbl[0x0c] probe slot");
  countCase();

  /* Hook wiring, PE 0x92d094..0x92d0b8. The probe TARGET is a FULL-WORD
     test; the probe RESULT is a LOW-BYTE test — 0x100/0x10000 mean al == 0
     and must NOT run the hook. */
  const plan = SCRATCH + 0x29800;
  const rows = [
    [0, 0, 0, 0, 0, 0, 0],
    [0x100, 0x100, 0, 1, 0, 0, 0],      /* 0x100 target LIVE, al=0 -> no */
    [1, 1, 1, 1, 1, 1, 1],
    [1, 0x100, 1, 1, 0, 1, 0],          /* LOW-BYTE: 0x100 probe = no hook */
    [1, 0x1ff, 1, 1, 1, 1, 1],          /* al=0xff -> hook runs */
    [1, 0xff, 1, 1, 1, 1, 1],
    [1, 0x10000, 1, 1, 0, 1, 0],        /* al=0 again */
    [1, 0xffffffff, 0, 1, 1, 0, 0],     /* hook ptr null -> no hook */
    [0, 0xffffffff, 1, 0, 1, 1, 0],     /* target null -> no probe, no hook */
    [0xffffffff, 0xffffffff, 0xffffffff, 1, 1, 1, 1],
  ];
  for (const [t, r, p, pr, pb, hp, hr] of rows) {
    wasm.isaac_sfx_load_hook_plan(t, r, p, plan);
    const wp = readHookPlan(view, plan);
    const jp = sfxLoadHookPlan(t, r, p);
    eq(wp.probeRuns, pr, `hook probe_runs ${t}/${r}/${p}`);
    eq(wp.probeByteNonzero, pb, `hook probe_byte ${t}/0x${(r >>> 0).toString(16)}`);
    eq(wp.hookPtrNonzero, hp, `hook ptr ${t}/${r}/${p}`);
    eq(wp.hookRuns, hr, `hook runs ${t}/0x${(r >>> 0).toString(16)}/${p}`);
    assertPlanEqual(wp, jp, `hook plan ${t}/0x${(r >>> 0).toString(16)}/${p}`);
    seen("v22Probe", wp.probeRuns);
    seen("v22Byte", wp.probeByteNonzero);
    seen("v22Hook", wp.hookRuns);
    countCase();
  }

  /* Voice free, PE 0x92d0ca..0x92d0f5. cap < 0x10 skips entirely; the
     0x1000 edge is SLOW (cap 0xfff -> size 0x1000); 0xffffffff wraps to
     size 0 -> fast. Reset is NEVER needed here. */
  const caps = [0, 0xf, 0x10, 0x11, 0xffe, 0xfff, 0x1000, 0x1001, 0xffffffff];
  const backs = [0, 0x1f, 0x20, 0x23, 0x24, 0x100, 2, 0xffffffff];
  let fatalCases = 0;
  for (const cap of caps) {
    for (const back of backs) {
      wasm.isaac_sfx_load_voice_free_plan(cap, back, plan);
      const wp = readVoiceFreePlan(view, plan);
      const jp = sfxLoadVoiceFreePlan(cap, back);
      assertPlanEqual(wp, jp, `free plan cap=0x${cap.toString(16)} back=${back}`);
      eq(wp.resetNeeded, 0, "no reset stores at this site");
      if (cap >= 0x10) {
        seen("v22Free", wp.freeNeeded);
        seen("v22Fast", wp.freeFast);
        if (cap >= 0xfff || cap === 0xffffffff) seen("v22Fatal", wp.corruptFatal);
        if (wp.corruptFatal) fatalCases += 1;
      }
      countCase();
    }
  }
  assert.ok(fatalCases > 0, "the corrupt-free abort path is exercised");
  countCase();

  /* The 0x1000 fast/slow boundary rows, spelled out (cf. the v4 tail
     plan pins). */
  wasm.isaac_sfx_load_voice_free_plan(0xffe, 0, plan);
  let wp = readVoiceFreePlan(view, plan);
  eq(wp.freeNeeded, 1);
  eq(wp.freeFast, 1, "cap 0xffe -> size 0xfff is FAST");
  eq(wp.freeSize >>> 0, 0xfff, "plain size = cap+1");
  eq(wp.slackChecked, 0);
  eq(wp.corruptFatal, 0);
  seen("v22Free", 1); seen("v22Fast", 1);
  countCase();

  wasm.isaac_sfx_load_voice_free_plan(0xfff, 0x23, plan);
  wp = readVoiceFreePlan(view, plan);
  eq(wp.freeFast, 0, "cap 0xfff -> size 0x1000 is the BIG-ALLOC edge");
  eq(wp.freeSize >>> 0, (0x1000 + 0x23) >>> 0, "size + 0x23 bias");
  eq(wp.slackChecked, 1);
  eq(wp.corruptFatal, 0, "slack 0x23-4 == 0x1f is NOT fatal");
  seen("v22Free", 1); seen("v22Fast", 0);
  countCase();

  wasm.isaac_sfx_load_voice_free_plan(0x1000, 0x24, plan);
  wp = readVoiceFreePlan(view, plan);
  eq(wp.freeFast, 0);
  eq(wp.freeSize >>> 0, (0x1001 + 0x23) >>> 0);
  eq(wp.corruptFatal, 1, "slack 0x24-4 == 0x20 > 0x1f -> abort 0x00b18894");
  seen("v22Fatal", 1);
  countCase();

  wasm.isaac_sfx_load_voice_free_plan(0xffffffff, 2, plan);
  wp = readVoiceFreePlan(view, plan);
  eq(wp.freeNeeded, 1);
  eq(wp.freeFast, 1, "cap 0xffffffff -> size wraps to 0 -> FAST");
  eq(wp.freeSize >>> 0, 0);
  eq(wp.corruptFatal, 0, "the fast path never reads the back pointer");
  seen("v22Fast", 1);
  countCase();
});

test("Wasm matches JS: v22 Load hook + voice free differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const plan = SCRATCH + 0x29800;

  let seed = (0x0092cfb0 ^ 0x92d097 ^ 0x92d0a2 ^ 0x92d0ca ^ 0x92d0d4) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const targetDraws = [0, 1, 0x100, 0x1ff, 0xfffffff0, 0xffffffff, 0xffff0000];
  const probeDraws = [0, 1, 0xff, 0x100, 0x1ff, 0x10000, 0xffffffff, 0xffffff00];
  const ptrDraws = [0, 1, 0x100, 0xffffffff];
  const capDraws = [0, 1, 0xf, 0x10, 0x11, 0xffe, 0xfff, 0x1000, 0x1001,
                    0xffffffff];
  const backDraws = [0, 1, 2, 0x1f, 0x20, 0x23, 0x24, 0x100, 0xffffffff];

  for (let k = 0; k < 400; ++k) {
    const t = targetDraws[pick(rnd, targetDraws.length)];
    const r = probeDraws[pick(rnd, probeDraws.length)];
    const p = ptrDraws[pick(rnd, ptrDraws.length)];
    const cap = capDraws[pick(rnd, capDraws.length)];
    const back = backDraws[pick(rnd, backDraws.length)];

    wasm.isaac_sfx_load_hook_plan(t, r, p, plan);
    assertPlanEqual(readHookPlan(view, plan), sfxLoadHookPlan(t, r, p),
                    `t${k} hook`);
    seen("v22Probe", sfxLoadHookPlan(t, r, p).probeRuns);
    seen("v22Byte", sfxLoadHookPlan(t, r, p).probeByteNonzero);
    seen("v22Hook", sfxLoadHookPlan(t, r, p).hookRuns);
    countCase();

    wasm.isaac_sfx_load_voice_free_plan(cap, back, plan);
    assertPlanEqual(readVoiceFreePlan(view, plan),
                    sfxLoadVoiceFreePlan(cap, back), `t${k} free`);
    seen("v22Free", sfxLoadVoiceFreePlan(cap, back).freeNeeded);
    seen("v22Fast", sfxLoadVoiceFreePlan(cap, back).freeFast);
    seen("v22Fatal", sfxLoadVoiceFreePlan(cap, back).corruptFatal);
    seen("v22Reset", sfxLoadVoiceFreePlan(cap, back).resetNeeded);
    countCase();

    /* Cross-law: the SSO skip of the Load voice free IS the heap-free
       decision of the v3 voice plan (heapFreeNeeded; the machine compares
       the SAME capacity field at 0x92d0ca and 0x92d045). */
    eq(sfxLoadVoiceFreePlan(cap, back).freeNeeded,
       sfxLoadVoicePlan(0, 0x10, cap, 1).heapFreeNeeded ? 1 : 0,
       `t${k} freeNeeded == voice heapFreeNeeded for cap=0x${cap.toString(16)}`);
    countCase();
  }
});

test("Wasm matches JS: v23 TryRedirectPath probe walk", () => {
  const view = new DataView(wasm.memory.buffer);
  const h = readFileSync(header, "utf8");
  const plan = SCRATCH + 0x2b000;

  /* Constant mirrors: header vs model. */
  eq(headerConstant(h, "ISAAC_SFX_REDIRECT_PROBE_MASK"),
     SFX_REDIRECT_PROBE_MASK, "probe mask");
  eq(headerConstant(h, "ISAAC_SFX_REDIRECT_PROBE_CAP"),
     SFX_REDIRECT_PROBE_CAP, "probe cap");
  eq(SFX_REDIRECT_PROBE_MASK, 0x7fff, "mask 0x7fff = 0x8000 slots");
  eq(SFX_REDIRECT_PROBE_CAP, 0x8000, "cap 0x8000");
  eq(SFX_REDIRECT_SLOT_OFF, 0x0c, "slot table off +0xc");
  eq(SFX_REDIRECT_SLOT_STRIDE, 4, "slot stride 4");
  eq(SFX_REDIRECT_KEY0_OFF, 0, "key0 +0");
  eq(SFX_REDIRECT_KEY1_OFF, 4, "key1 +4");
  eq(SFX_REDIRECT_DTOR_THIS_OFF, 0x0c, "dtor this +0xc");
  eq(SFX_REDIRECT_FREE_SIZE, 0x24, "free size 0x24");
  eq(SFX_REDIRECT_DTOR_VA, 0x0040d040, "node dtor host VA");
  eq(SFX_REDIRECT_FREE_VA, 0x00aef15c, "sized-free host VA");
  eq(SFX_REDIRECT_FIRST_PROBE_VA, 0x008f5b60, "first probe VA");
  eq(SFX_REDIRECT_WALK_END_VA, 0x008f5bc1, "walk end VA");
  eq(SFX_REDIRECT_FOUND_TAIL_VA, 0x008f608f, "found tail VA");
  countCase();

  /* probe_start / probe_next: the 0x7fff wrap. */
  const startRows = [
    [0, 0], [1, 1], [0x7fff, 0x7fff], [0x8000, 0], [0xffffffff, 0x7fff],
    [0x12345678, 0x12345678 & 0x7fff],
  ];
  for (const [hash, want] of startRows) {
    eq(wasm.isaac_sfx_redirect_probe_start(hash), want,
       `start 0x${(hash >>> 0).toString(16)}`);
    eq(sfxRedirectProbeStart(hash), want, `js start 0x${(hash >>> 0).toString(16)}`);
    countCase();
  }
  for (const [idx, want] of [[0, 1], [0x7ffe, 0x7fff], [0x7fff, 0], [0xffffffff, 0]]) {
    eq(wasm.isaac_sfx_redirect_probe_next(idx), want,
       `next 0x${(idx >>> 0).toString(16)}`);
    eq(sfxRedirectProbeNext(idx), want, `js next 0x${(idx >>> 0).toString(16)}`);
    countCase();
  }

  /* probe_cap: UNSIGNED — 0x8000 IS the cap, 0xffffffff is. */
  const capRows = [[0, 0], [0x7fff, 0], [0x8000, 1], [0x8001, 1],
                   [0xffffffff, 1]];
  for (const [count, want] of capRows) {
    eq(wasm.isaac_sfx_redirect_probe_cap(count), want,
       `cap 0x${(count >>> 0).toString(16)}`);
    eq(sfxRedirectProbeCap(count), want,
       `js cap 0x${(count >>> 0).toString(16)}`);
    seen("v23Cap", sfxRedirectProbeCap(count));
    countCase();
  }

  /* probe_match: FULL-WORD equality on BOTH keys. */
  const matchRows = [
    [0x11111111, 0x22222222, 0x11111111, 0x22222222, 1],
    [0x11111111, 0x22222222, 0x11111111, 0x22222223, 0],
    [0x11111111, 0x22222222, 0x11111110, 0x22222222, 0],
    [0, 0, 0, 0, 1],
    [0xffffffff, 0xffffffff, 0xffffffff, 0xffffffff, 1],
    [0x11111111, 0x22222222, 0x22222222, 0x11111111, 0],
  ];
  for (const [k0, k1, s0, s1, want] of matchRows) {
    eq(wasm.isaac_sfx_redirect_probe_match(k0, k1, s0, s1), want,
       `match ${k0}/${k1}/${s0}/${s1}`);
    eq(sfxRedirectProbeMatch(k0, k1, s0, s1), want, `js match`);
    seen("v23Match", sfxRedirectProbeMatch(k0, k1, s0, s1));
    countCase();
  }

  /* probe_step: all four outcomes + the cap eviction. */
  const stepRows = [
    /* count, index, present, match -> outcome, nextCount, nextIndex, destroy */
    [0, 0x1234, 0, 0, 2, 0, 0x1234, 0],            /* empty -> NOT_FOUND */
    [0, 0x1234, 0, 1, 2, 0, 0x1234, 0],            /* empty ignores match */
    [0x7fff, 0x7fff, 0, 0, 2, 0x7fff, 0x7fff, 0],  /* empty at pre-cap */
    [0, 0x1234, 1, 1, 1, 0, 0x1234, 0],            /* match -> FOUND */
    [0x7fff, 0x1234, 1, 1, 1, 0x7fff, 0x1234, 0],  /* match below cap */
    [0x8000, 0x1234, 1, 1, 3, 0x8000, 0x1234, 0x24], /* match AT cap: EVICT */
    [0x8000, 0x1234, 1, 0, 3, 0x8000, 0x1234, 0x24], /* mismatch AT cap: EVICT */
    [0x8000, 0x1234, 0, 0, 2, 0x8000, 0x1234, 0],  /* empty at cap: no free */
    [0xffffffff, 0x1234, 1, 1, 1, 0xffffffff, 0x1234, 0], /* wrap count MATCH: jne takes -> FOUND */
    [0xffffffff, 0x1234, 1, 0, 1, 0xffffffff, 0x1234, 0], /* wrap MISMATCH: jae -> jne(≠0x8000) taken -> FOUND (unreachable in machine) */
    [0x1234, 0x7fff, 1, 0, 0, 0x1235, 0, 0],       /* mismatch -> CONTINUE wrap */
    [0x1234, 0x1234, 1, 0, 0, 0x1235, 0x1235, 0],  /* mismatch -> CONTINUE */
    [0x7fff, 0x7fff, 1, 0, 0, 0x8000, 0, 0],       /* count->cap, idx wrap */
  ];
  for (const [count, index, present, match, out, nc, ni, ds] of stepRows) {
    wasm.isaac_sfx_redirect_probe_step(count, index, present, match, plan);
    const wp = readRedirectStep(view, plan);
    const jp = sfxRedirectProbeStep(count, index, present, match);
    eq(wp.outcome, out, `step outcome c=0x${(count >>> 0).toString(16)} i=0x${(index >>> 0).toString(16)} p=${present} m=${match}`);
    eq(wp.nextCount >>> 0, nc >>> 0, `step nextCount`);
    eq(wp.nextIndex >>> 0, ni >>> 0, `step nextIndex`);
    eq(wp.destroySize >>> 0, ds >>> 0, `step destroySize`);
    assertPlanEqual(wp, jp, `step c=0x${(count >>> 0).toString(16)} i=0x${(index >>> 0).toString(16)} p=${present} m=${match}`);
    seen("v23Outcome", wp.outcome);
    if (wp.outcome === 3) seen("v23Destroy", wp.destroySize);
    countCase();
  }

  /* Native/JS differential over a wider random domain. */
  let seed = (0x008f5ad0 ^ 0x8f5b60 ^ 0x8f5bc1 ^ 0x40d040 ^ 0xaef15c) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const countDraws = [0, 1, 0x7fff, 0x8000, 0x8001, 0xffffffff, 0x12345678];
  const indexDraws = [0, 1, 0x7fff, 0x8000, 0xffffffff, 0x1248];
  for (let k = 0; k < 400; ++k) {
    const count = countDraws[pick(rnd, countDraws.length)];
    const index = indexDraws[pick(rnd, indexDraws.length)];
    const present = pick(rnd, 2);
    const match = pick(rnd, 2);
    wasm.isaac_sfx_redirect_probe_step(count, index, present, match, plan);
    assertPlanEqual(readRedirectStep(view, plan),
                    sfxRedirectProbeStep(count, index, present, match),
                    `t${k} step`);
    seen("v23Outcome", sfxRedirectProbeStep(count, index, present, match).outcome);
    countCase();

    const hash = rnd();
    eq(wasm.isaac_sfx_redirect_probe_start(hash),
       sfxRedirectProbeStart(hash), `t${k} start`);
    const nxt = rnd();
    eq(wasm.isaac_sfx_redirect_probe_next(nxt),
       sfxRedirectProbeNext(nxt), `t${k} next`);
    countCase();
  }
});

test("v24 PE truth (native): 0x92d140 callee string/alloc/vector growth", () => {
  const h = readFileSync(header, "utf8");
  /* The callee VA anchors recorded in the v24 census. */
  for (const [name, expected] of [
    ["ISAAC_SFX_ASSIGN_VA_40CCD0", 0x0040ccd0],
    ["ISAAC_SFX_BUILD_VA_421680", 0x00421680],
    ["ISAAC_SFX_GROW_ALLOC_VA_40CF00", 0x0040cf00],
    ["ISAAC_SFX_VEC_PUSH_GROW_VA_92E900", 0x0092e900],
    ["ISAAC_SFX_VEC_RESERVE_VA_92EE40", 0x0092ee40],
    ["ISAAC_SFX_VEC_COPY_CTOR_VA_40CF50", 0x0040cf50],
    ["ISAAC_SFX_FILE_OPEN_VA_A178D0", 0x00a178d0],
    ["ISAAC_SFX_FILE_OPEN_ALLOC_VA_A648B0", 0x00a648b0],
    ["ISAAC_SFX_VEC_MAX_COUNT", 0x94f209],
    ["ISAAC_SFX_VEC_RESERVE_FLOOR", 0x443],
    ["ISAAC_SFX_STRING_SSO_CAP", 0xf],
    ["ISAAC_SFX_STRING_CAP_CLAMP", 0x7fffffff],
    ["ISAAC_SFX_BUILD_FLOOR_16", 0x16],
    ["ISAAC_SFX_ALLOC_FAST_LIMIT", 0x1000],
    ["ISAAC_SFX_ALLOC_BIG_BIAS", 0x23],
    ["ISAAC_SFX_ALLOC_ALIGN_MASK", 0xffffffe0],
    ["ISAAC_SFX_THROW_LEN_40CCC0", 0x0040ccc0],
    ["ISAAC_SFX_THROW_LENGTH_40CEE0", 0x0040cee0],
    ["ISAAC_SFX_THROW_VEC_COUNT_MAX_415BC0", 0x00415bc0],
  ]) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    countCase();
  }
  /* JS mirrors pinned to their literals. */
  eq(SFX_STRING_SSO_CAP, 0xf, "js SSO cap");
  eq(SFX_STRING_CAP_CLAMP, 0x7fffffff, "js clamp");
  eq(SFX_BUILD_FLOOR_16, 0x16, "js build floor");
  eq(SFX_ALLOC_FAST_LIMIT, 0x1000, "js fast limit");
  eq(SFX_VEC_MAX_COUNT, 0x94f209, "js vec MAX");
  eq(SFX_VEC_RESERVE_FLOOR, 0x443, "js reserve floor");
  countCase();
});

/* The UNSIGNED/byte-form pins of the 0x92d140 callee laws. The wide drives
   (0x100/0x1ff/0xffffffff) are the whole point: the machine compares FULL
   WORDS on the capacity/count gates and a single LOW BYTE on the path
   empty test. */
test("Wasm matches JS: v24 string/alloc/vector growth + file-open laws", () => {
  const view = new DataView(wasm.memory.buffer);
  const plan = SCRATCH + 0x2c000;
  const GROW_BIG_OFF = {
    allocSize: 0,
    wrapped: 4,
  };

  /* assign_grow: len > cap UNSIGNED (0x40cce2 cmp/ja). */
  const growRows = [
    [0x1000, 0xfff, 1], [0xfff, 0x1000, 0], [0, 0, 0],
    [0xffffffff, 1, 1], [0x1000, 0x1000, 0], [0x7fffffff, 0x7ffffffe, 1],
  ];
  for (const [len, cap, want] of growRows) {
    eq(wasm.isaac_sfx_string_assign_grow(len, cap), want,
       `assign_grow len=0x${(len >>> 0).toString(16)} cap=0x${(cap >>> 0).toString(16)}`);
    eq(sfxStringAssignGrow(len, cap), want, `js assign_grow`);
    seen("v24Grow", sfxStringAssignGrow(len, cap));
    countCase();
  }

  /* assign_sso: FULL-WORD cap < 0x10 (0x40cce8 cmp cap,0x10 ; jb) — the
     0x100/0x1ff wide rows must NOT collapse to a low-byte test. */
  const ssoRows = [[0, 1], [0xf, 1], [0x10, 0], [0xff, 0], [0x100, 0],
                   [0x1ff, 0], [0xffffffff, 0]];
  for (const [cap, want] of ssoRows) {
    eq(wasm.isaac_sfx_string_assign_sso(cap), want,
       `assign_sso cap=0x${(cap >>> 0).toString(16)}`);
    eq(sfxStringAssignSso(cap), want, `js assign_sso`);
    seen("v24Sso", sfxStringAssignSso(cap));
    countCase();
  }

  /* grow_len_ok: len > 0x7fffffff UNSIGNED -> throw gate (0x40cd0e ja). */
  const lenOkRows = [[0, 1], [0x1000, 1], [0x7ffffffe, 1], [0x7fffffff, 1],
                     [0x80000000, 0], [0xffffffff, 0]];
  for (const [len, want] of lenOkRows) {
    eq(wasm.isaac_sfx_string_grow_len_ok(len), want,
       `grow_len_ok len=0x${(len >>> 0).toString(16)}`);
    eq(sfxStringGrowLenOk(len), want, `js grow_len_ok`);
    seen("v24LenOk", sfxStringGrowLenOk(len));
    countCase();
  }

  /* grow_cap chain (0x40cd1a..0x40cd49): clamp1/clamp2/max, all U. */
  const growCapRows = [
    [0x10, 0x10, 0x1f],          /* max(0x1f, 0x18) */
    [0x100, 0x20, 0x180],        /* max(0x2f, 0x180) */
    [0xfffffff0, 0x10, 0x7fffffff], /* clamp2: cap > 0x7fffffff-(cap>>1) */
  ];
  for (const [cap, len, want] of growCapRows) {
    eq(wasm.isaac_sfx_string_grow_cap(cap, len), want,
       `grow_cap cap=0x${(cap >>> 0).toString(16)} len=0x${(len >>> 0).toString(16)}`);
    eq(sfxStringGrowCap(cap, len), want, `js grow_cap`);
    seen("v24GrowCap", sfxStringGrowCap(cap, len));
    countCase();
  }

  /* build_total: 32-bit wrap (0x421684 add). */
  const totalRows = [[0x10, 0x20, 0x30], [0xffffffff, 1, 0],
                     [0x1000, 0x1000, 0x2000]];
  for (const [a, b, want] of totalRows) {
    eq(wasm.isaac_sfx_string_build_total(a, b), want,
       `build_total ${a >>> 0}+${b >>> 0}`);
    eq(sfxStringBuildTotal(a, b), want, `js build_total`);
    seen("v24BTotal", sfxStringBuildTotal(a, b));
    countCase();
  }

  /* build_sso: total <= 0xf (0x4216ad cmp/jbe UNSIGNED) — 0xf IS SSO. */
  const buildSsoRows = [[0, 1], [0xf, 1], [0x10, 0], [0x100, 0],
                        [0xffffffff, 0]];
  for (const [total, want] of buildSsoRows) {
    eq(wasm.isaac_sfx_string_build_sso(total), want,
       `build_sso total=0x${(total >>> 0).toString(16)}`);
    eq(sfxStringBuildSso(total), want, `js build_sso`);
    seen("v24BSso", sfxStringBuildSso(total));
    countCase();
  }

  /* build_cap: SSO -> 0xf; else total|0xf clamped, floored 0x16. */
  const buildCapRows = [[0xf, 0xf], [0x10, 0x1f], [0x1000, 0x100f],
                        [0xffffffff, 0x7fffffff]];
  for (const [total, want] of buildCapRows) {
    eq(wasm.isaac_sfx_string_build_cap(total), want,
       `build_cap total=0x${(total >>> 0).toString(16)}`);
    eq(sfxStringBuildCap(total), want, `js build_cap`);
    seen("v24BCap", sfxStringBuildCap(total));
    countCase();
  }

  /* alloc fast/zero: size < 0x1000 UNSIGNED; FULL-WORD size == 0. */
  for (const [size, want] of [[0, 1], [0xfff, 1], [0x1000, 0],
                              [0x10000, 0], [0xffffffff, 0]]) {
    eq(wasm.isaac_sfx_grow_alloc_fast(size), want,
       `alloc_fast 0x${(size >>> 0).toString(16)}`);
    eq(sfxGrowAllocFast(size), want, `js alloc_fast`);
    seen("v24Fast", sfxGrowAllocFast(size));
    countCase();
  }
  for (const [size, want] of [[0, 1], [1, 0], [0x100, 0], [0xffffffff, 0]]) {
    eq(wasm.isaac_sfx_grow_alloc_zero(size), want,
       `alloc_zero 0x${(size >>> 0).toString(16)}`);
    eq(sfxGrowAllocZero(size), want, `js alloc_zero`);
    seen("v24Zero", sfxGrowAllocZero(size));
    countCase();
  }

  /* big-arm plan: size+0x23 with the UNSIGNED wrap gate (0x40cf09 jbe). */
  const bigRows = [
    [0x1000, 0x1023, 0],
    [0xffffffe0, 0x3, 1],      /* wraps, throws 0x40cee0 */
    [0xffffffff, 0x22, 1],
  ];
  for (const [size, allocSize, wrapped] of bigRows) {
    wasm.isaac_sfx_grow_alloc_big_plan(size, plan);
    const wp = {
      allocSize: readU32(view, plan + GROW_BIG_OFF.allocSize),
      wrapped: readI32(view, plan + GROW_BIG_OFF.wrapped),
    };
    const jp = sfxGrowAllocBigPlan(size);
    eq(wp.allocSize >>> 0, allocSize >>> 0,
       `big alloc_size 0x${(size >>> 0).toString(16)}`);
    eq(wp.wrapped, wrapped, `big wrapped 0x${(size >>> 0).toString(16)}`);
    assertPlanEqual(wp, jp, `big 0x${(size >>> 0).toString(16)}`);
    seen("v24Big", wp.allocSize);
    seen("v24Wrap", wp.wrapped);
    countCase();
  }

  /* align: (raw+0x23) & ~0x1f (0x40cf1f) — wrap row collides with 0. */
  for (const [raw, want] of [[0, 0x20], [0x21, 0x40], [0x3e0, 0x400],
                             [0xffffffff, 0x20]]) {
    eq(wasm.isaac_sfx_grow_alloc_align(raw), want,
       `alloc_align 0x${(raw >>> 0).toString(16)}`);
    eq(sfxGrowAllocAlign(raw), want, `js alloc_align`);
    seen("v24Align", sfxGrowAllocAlign(raw));
    countCase();
  }

  /* vec_cap_gate: ecc > 0x94f209-(ecc>>1) UNSIGNED (0x92e990/0x92eea7). */
  for (const [ecc, want] of [[0x10, 0], [0x700000, 1], [0x94f209, 1],
                             [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_vec_cap_gate(ecc), want,
       `vec_cap_gate 0x${(ecc >>> 0).toString(16)}`);
    eq(sfxVecCapGate(ecc), want, `js vec_cap_gate`);
    seen("v24Arm", sfxVecCapGate(ecc));
    countCase();
  }

  /* push-back new: max(ecc+(ecc>>1), count+1) UNSIGNED cmovae; the
     reserve NEVER takes count+1 (0x92e9f6..0x92e9fd). */
  for (const [ecc, count, want] of [[4, 0, 6], [4, 7, 8], [0xffffffff, 0, 0x7ffffffe]]) {
    eq(wasm.isaac_sfx_vec_push_grow_new(ecc, count), want,
       `push_grow_new ecc=0x${(ecc >>> 0).toString(16)} c=${count}`);
    eq(sfxVecPushGrowNew(ecc, count), want, `js push_grow_new`);
    seen("v24PushNew", sfxVecPushGrowNew(ecc, count));
    countCase();
  }

  /* reserve new: max(ecc+(ecc>>1), 0x443) — the floor of 0x92ef27. */
  for (const [ecc, want] of [[0x10, 0x443], [0x800, 0xc00], [0xffffffff, 0x7ffffffe]]) {
    eq(wasm.isaac_sfx_vec_reserve_grow_new(ecc), want,
       `reserve_grow_new 0x${(ecc >>> 0).toString(16)}`);
    eq(sfxVecReserveGrowNew(ecc), want, `js reserve_grow_new`);
    seen("v24ReserveNew", sfxVecReserveGrowNew(ecc));
    countCase();
  }

  /* overflow: new_cap > 0x94f209 UNSIGNED (0x92ea03/0x92ef3c ja). */
  for (const [nc, want] of [[0x1000, 0], [0x94f209, 0], [0x94f20a, 1],
                            [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_vec_cap_overflow(nc), want,
       `vec_cap_overflow 0x${(nc >>> 0).toString(16)}`);
    eq(sfxVecCapOverflow(nc), want, `js vec_cap_overflow`);
    seen("v24Overflow", sfxVecCapOverflow(nc));
    countCase();
  }

  /* count_max: EQUALITY ONLY (0x92e961 cmp/je) — 0x94f20a is NOT the
     gate even though it is also over the cap. */
  for (const [count, want] of [[0, 0], [0x94f208, 0], [0x94f209, 1],
                               [0x94f20a, 0], [0xffffffff, 0]]) {
    eq(wasm.isaac_sfx_vec_count_max(count), want,
       `vec_count_max 0x${(count >>> 0).toString(16)}`);
    eq(sfxVecCountMax(count), want, `js vec_count_max`);
    seen("v24CountMax", sfxVecCountMax(count));
    countCase();
  }

  /* copy sso/cap: size < 0x10 (JAE polarity at 0x40cf7d); heap cap =
     size|0xf clamped (cmova U). */
  for (const [size, want] of [[0, 1], [0xf, 1], [0x10, 0], [0x100, 0]]) {
    eq(wasm.isaac_sfx_string_copy_sso(size), want,
       `copy_sso 0x${(size >>> 0).toString(16)}`);
    eq(sfxStringCopySso(size), want, `js copy_sso`);
    seen("v24CopySso", sfxStringCopySso(size));
    countCase();
  }
  for (const [size, want] of [[0x10, 0x1f], [0x1000, 0x100f],
                              [0x80000000, 0x7fffffff]]) {
    eq(wasm.isaac_sfx_string_copy_cap(size), want,
       `copy_cap 0x${(size >>> 0).toString(16)}`);
    eq(sfxStringCopyCap(size), want, `js copy_cap`);
    seen("v24CopyCap", sfxStringCopyCap(size));
    countCase();
  }

  /* file-open path gate: FULL-WORD NULL then LOW-BYTE empty (0xa178f9/
     0xa17901). first_byte 0x100 -> al == 0 -> EMPTY (a full-word test
     would wrongly open). */
  for (const [ptr, fb, want] of [[0, 1, 0], [0, 0, 0], [1, 0, 0],
                                 [1, 0x100, 0], [1, 1, 1], [1, 0x41, 1],
                                 [0xffffffff, 0xff, 1], [1, 0x1ff, 1]]) {
    eq(wasm.isaac_sfx_file_open_path_gate(ptr, fb), want,
       `path_gate ptr=0x${(ptr >>> 0).toString(16)} fb=0x${(fb >>> 0).toString(16)}`);
    eq(sfxFileOpenPathGate(ptr, fb), want, `js path_gate`);
    seen("v24Path", sfxFileOpenPathGate(ptr, fb));
    countCase();
  }
  /* Result flag FULL-WORD (0xa1792a cmp [ebp+8],0 ; jne): 0x100 opens. */
  for (const [flag, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_file_open_flag_gate(flag), want,
       `flag_gate 0x${(flag >>> 0).toString(16)}`);
    eq(sfxFileOpenFlagGate(flag), want, `js flag_gate`);
    seen("v24Flag", sfxFileOpenFlagGate(flag));
    countCase();
  }

  /* Native/JS differential over draw sets that stay inside each bucket's
     exact value set. */
  let seed = (0x92d140 ^ 0x40ccd0 ^ 0x421680 ^ 0x40cf00 ^ 0x92e900 ^
              0x92ee40 ^ 0x40cf50 ^ 0xa178d0) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const growPairs = [[0x10, 0x10], [0x100, 0x20], [0xfffffff0, 0x10]];
  const bpairs = [[0x10, 0x20], [0xffffffff, 1], [0x1000, 0x1000]];
  const bcaps = [0xf, 0x10, 0x1000, 0xffffffff];
  const bigs = [0x1000, 0xffffffe0, 0xffffffff];
  const aligns = [0, 0x21, 0x3e0];
  const eccs = [0x10, 0x700000, 0xffffffff];
  const pushPairs = [[4, 0], [4, 7], [0xffffffff, 0]];
  const resEccs = [0x10, 0x800, 0xffffffff];
  const overs = [0x1000, 0x94f209, 0xffffffff];
  const cms = [0, 0x94f208, 0x94f209, 0x94f20a];
  const copySizes = [0, 0xf, 0x10, 0x100];
  const ccapSizes = [0x10, 0x1000, 0x80000000];
  const paths = [[0, 1], [1, 0], [1, 0x100], [1, 0x41], [1, 0x1ff]];
  const flags = [0, 1, 0x100, 0xffffffff];
  for (let k = 0; k < 400; ++k) {
    const [gc, gl] = growPairs[pick(rnd, growPairs.length)];
    eq(wasm.isaac_sfx_string_assign_grow(gl, gc), sfxStringAssignGrow(gl, gc),
       `t${k} assign_grow`);
    eq(wasm.isaac_sfx_string_grow_cap(gc, gl), sfxStringGrowCap(gc, gl),
       `t${k} grow_cap`);
    seen("v24Grow", sfxStringAssignGrow(gl, gc));
    seen("v24GrowCap", sfxStringGrowCap(gc, gl));
    const cap = ccapSizes[pick(rnd, ccapSizes.length)];
    eq(wasm.isaac_sfx_string_copy_cap(cap), sfxStringCopyCap(cap),
       `t${k} copy_cap`);
    seen("v24CopyCap", sfxStringCopyCap(cap));
    const [b1, b2] = bpairs[pick(rnd, bpairs.length)];
    eq(wasm.isaac_sfx_string_build_total(b1, b2),
       sfxStringBuildTotal(b1, b2), `t${k} build_total`);
    const wrappedTotal = (b1 + b2) >>> 0;
    eq(wasm.isaac_sfx_string_build_sso(wrappedTotal),
       sfxStringBuildSso(wrappedTotal), `t${k} build_sso`);
    seen("v24BTotal", sfxStringBuildTotal(b1, b2));
    seen("v24BSso", sfxStringBuildSso(wrappedTotal));
    const bigSize = bigs[pick(rnd, bigs.length)];
    wasm.isaac_sfx_grow_alloc_big_plan(bigSize, plan);
    const bigJs = sfxGrowAllocBigPlan(bigSize);
    assertPlanEqual(
      {
        allocSize: readU32(view, plan + GROW_BIG_OFF.allocSize),
        wrapped: readI32(view, plan + GROW_BIG_OFF.wrapped),
      },
      bigJs, `t${k} big`);
    seen("v24Big", bigJs.allocSize);
    seen("v24Wrap", bigJs.wrapped);
    const alignRaw = aligns[pick(rnd, aligns.length)];
    eq(wasm.isaac_sfx_grow_alloc_align(alignRaw),
       sfxGrowAllocAlign(alignRaw), `t${k} align`);
    seen("v24Align", sfxGrowAllocAlign(alignRaw));
    const ecc = eccs[pick(rnd, eccs.length)];
    eq(wasm.isaac_sfx_vec_cap_gate(ecc), sfxVecCapGate(ecc), `t${k} arm`);
    const re = resEccs[pick(rnd, resEccs.length)];
    eq(wasm.isaac_sfx_vec_reserve_grow_new(re),
       sfxVecReserveGrowNew(re), `t${k} reserve`);
    seen("v24Arm", sfxVecCapGate(ecc));
    seen("v24ReserveNew", sfxVecReserveGrowNew(re));
    const [pe, pc] = pushPairs[pick(rnd, pushPairs.length)];
    eq(wasm.isaac_sfx_vec_push_grow_new(pe, pc), sfxVecPushGrowNew(pe, pc),
       `t${k} push`);
    seen("v24PushNew", sfxVecPushGrowNew(pe, pc));
    const ov = overs[pick(rnd, overs.length)];
    eq(wasm.isaac_sfx_vec_cap_overflow(ov), sfxVecCapOverflow(ov),
       `t${k} overflow`);
    seen("v24Overflow", sfxVecCapOverflow(ov));
    const cm = cms[pick(rnd, cms.length)];
    eq(wasm.isaac_sfx_vec_count_max(cm), sfxVecCountMax(cm),
       `t${k} count_max`);
    seen("v24CountMax", sfxVecCountMax(cm));
    const cs = copySizes[pick(rnd, copySizes.length)];
    eq(wasm.isaac_sfx_string_copy_sso(cs), sfxStringCopySso(cs),
       `t${k} copy_sso`);
    seen("v24CopySso", sfxStringCopySso(cs));
    const [pp, pf] = paths[pick(rnd, paths.length)];
    eq(wasm.isaac_sfx_file_open_path_gate(pp, pf),
       sfxFileOpenPathGate(pp, pf), `t${k} path`);
    seen("v24Path", sfxFileOpenPathGate(pp, pf));
    const fg = flags[pick(rnd, flags.length)];
    eq(wasm.isaac_sfx_file_open_flag_gate(fg), sfxFileOpenFlagGate(fg),
       `t${k} flag`);
    seen("v24Flag", sfxFileOpenFlagGate(fg));
    countCase();
  }
});

test("Wasm matches JS: v15 pool + attrs differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const planBase = SCRATCH + 0x27000;

  let seed = (0x00416510 ^ 0x004165a0 ^ 0x00b1af60 ^ 0x00b1b6e8) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const freeDraws = [0, 1, 2, 3, 4, 5, 0x100, 0x1ff, 0xfffffff0, 0xfffffffd,
                     0xffffffff];
  const endDraws = [0, 0x10, 0x100, 0x10000, 0x10005, 0xfffffff0,
                    0xffffffff];
  const sizeDraws = [0, 1, 3, 4, 0x100, 0x1ff, 0xffff, 0x10000, 0x10001,
                     0xfffffff6, 0xffffffff];
  const byteDraws = [0, 0x22, 0x27, 0x3d, 0x41, 0x21, 0x3c, 0x3e, 0x2f,
                     0x3f, 0x100, 0x1ff, 0xffffffff];
  const lenDraws = [0, 1, 4, 0x100, 0x1ff, 0xffffffff];
  const prevDraws = [0x1024, 0x1234, 0xfffffff0];
  const posDraws = [0x1000, 0x2000, 0xfffffff0, 0xffffffff];

  for (let k = 0; k < 400; ++k) {
    const f = pick(rnd, freeDraws.length);
    const e = pick(rnd, endDraws.length);
    const s = pick(rnd, sizeDraws.length);
    const b = pick(rnd, byteDraws.length);
    const l = pick(rnd, lenDraws.length);
    const pv = pick(rnd, prevDraws.length);
    seen("v15FreeB", f);
    seen("v15EndB", e);
    seen("v15SizeB", s);
    seen("v15ByteB", b);
    seen("v15LenB", l);
    seen("v15PrevB", pv);
    const free = freeDraws[f];
    const end = endDraws[e];
    const size = sizeDraws[s];
    const byteVal = byteDraws[b];
    const len = lenDraws[l];
    const prev = prevDraws[pv];
    const v1 = posDraws[pick(rnd, posDraws.length)];
    const v2 = posDraws[pick(rnd, posDraws.length)];

    /* Pool scalars, wide drives. */
    eq(wasm.isaac_sfx_xml_pool_align4(free) >>> 0,
       sfxXmlPoolAlign4(free), `align4 ${free}`);
    eq(wasm.isaac_sfx_xml_pool_need_grow(free, end, size),
       sfxXmlPoolNeedGrow(free, end, size), `needgrow ${free}/${end}/${size}`);
    eq(wasm.isaac_sfx_xml_pool_grow_request(size) >>> 0,
       sfxXmlPoolGrowRequest(size), `growreq ${size}`);
    const req = sfxXmlPoolGrowRequest(size);
    wasm.isaac_sfx_xml_pool_grow_tail(free, req, size, planBase);
    assertPlanEqual(readPoolGrowTail(view, planBase),
                    sfxXmlPoolGrowTail(free, req, size), `growtail ${k}`);
    seen("v15Grow", wasm.isaac_sfx_xml_pool_need_grow(free, end, size));
    seen("v15Host", wasm.isaac_sfx_xml_pool_need_grow(free, end, size));
    seen("v15Align", wasm.isaac_sfx_xml_pool_align4(free) & 3);
    countCase();

    /* Attr scalar laws. */
    eq(wasm.isaac_sfx_xml_attr_name_char(byteVal),
       sfxXmlAttrNameChar(byteVal), `namechar ${byteVal}`);
    eq(wasm.isaac_sfx_xml_attr_name_error(prev, len) >>> 0,
       sfxXmlAttrNameError(prev, len), `nameerr ${len}`);
    eq(wasm.isaac_sfx_xml_attr_eq_error(prev, byteVal) >>> 0,
       sfxXmlAttrEqError(prev, byteVal), `eqerr ${byteVal}`);
    eq(wasm.isaac_sfx_xml_attr_quote_kind(byteVal),
       sfxXmlAttrQuoteKind(byteVal), `quote ${byteVal}`);
    eq(wasm.isaac_sfx_xml_attr_value_error(prev, byteVal, 0x27) >>> 0,
       sfxXmlAttrValueError(prev, byteVal, 0x27), `valerr ${byteVal}`);
    eq(wasm.isaac_sfx_xml_attr_value_len(v1, v2) >>> 0,
       sfxXmlAttrValueLen(v1, v2), `vallen ${v1}/${v2}`);
    eq(wasm.isaac_sfx_xml_attr_node_writes_offset(byteVal),
       sfxXmlAttrNodeWritesOffset(byteVal), `attrwrites ${byteVal}`);
    seen("v15Name", wasm.isaac_sfx_xml_attr_name_char(byteVal));
    seen("v15NameErr", wasm.isaac_sfx_xml_attr_name_error(prev, len) ===
         SFX_XML_ATTR_ERR_NAME_VA ? 0 : 1);
    seen("v15EqErr", wasm.isaac_sfx_xml_attr_eq_error(prev, byteVal) ===
         SFX_XML_ATTR_ERR_EQ_VA ? 0 : 1);
    seen("v15Quote", wasm.isaac_sfx_xml_attr_quote_kind(byteVal));
    seen("v15ValErr", wasm.isaac_sfx_xml_attr_value_error(prev, byteVal,
                                                          0x27) ===
         SFX_XML_ATTR_ERR_VALUE_VA ? 0 : 1);
    seen("v15Store", wasm.isaac_sfx_xml_attr_node_writes_offset(byteVal));
    countCase();

    /* Both plans. */
    wasm.isaac_sfx_xml_pool_plan(free, end, size, planBase);
    const wp = readPoolPlan(view, planBase);
    const jp = sfxXmlPoolPlan(free, end, size);
    assertPlanEqual(wp, jp, `pool plan ${k}`);
    seen("v15Grow", wp.grow);
    seen("v15Host", wp.hostCalls);
    seen("v15Wrap", (free + size) >>> 0 !== 0 ? 1 : 0);

    const quote = byteDraws[pick(rnd, byteDraws.length)];
    const eqb = byteDraws[pick(rnd, byteDraws.length)];
    const eb = byteDraws[pick(rnd, byteDraws.length)];
    const first = byteDraws[pick(rnd, byteDraws.length)];
    wasm.isaac_sfx_xml_attr_plan(prev, first, len, eqb, quote, eb, v1, v2,
                                 planBase);
    const wa = readAttrPlan(view, planBase);
    const ja = sfxXmlAttrPlan(prev, first, len, eqb, quote, eb, v1, v2);
    assertPlanEqual(wa, ja, `attr plan ${k}`);
    seen("v15Entered", wa.entered);
    seen("v15NodeStores", wa.nodeStores);
    seen("v15AHost", wa.hostCalls);
    seen("v15NameErr", wa.nameError === SFX_XML_ATTR_ERR_NAME_VA ? 0 : 1);
    seen("v15EqErr", wa.eqError === SFX_XML_ATTR_ERR_EQ_VA ? 0 : 1);
    seen("v15ValErr", wa.valueError === SFX_XML_ATTR_ERR_VALUE_VA ? 0 : 1);
    seen("v15Quote", wa.quoteKind);
    seen("v15ValLen", wa.valueLen > 0x10000 ? 1 : 0);
    countCase();
  }
});

/* v16 PE truth for 0x00416770, re-transcribed branch-by-branch from the
   machine listing (cpu-dump/00416770.txt — the full listing is in the
   v16 notes; NOT copied from the C++ or the model):
   - LOOP top 0x416780: ebx = *cursor (the PRE-ws start; ebx becomes the
     TEXT start); ws skip while ws_table[byte] (0xb1b060) != 0; *cursor =
     first non-ws (0x41679e store on EVERY path).
   - 0x4167a0 `mov al,[cursor]` then `test al,al ; je 0x4167ef` — the
     END arm stores [0xc7de4c] <- 0xb1b678 UNCONDITIONALLY and FALLS
     THROUGH into the TEXT arm; `cmp al,0x3c ; jne 0x4167f9` — if not
     '<' it is the TEXT arm; otherwise the TAG arm. So END == TEXT minus
     the slot store. The gate reads a BYTE (al), so wide inputs act on
     their low byte.
   - TAG 0x4167ac `cmp byte [cursor+1],0x2f ; je 0x4168af` — the CLOSE
     path scans the closing name over 0xb1ae60 then ws over 0xb1b060,
     then `mov eax,0xb1b6a8 ; cmp byte [ecx],0x3e ; cmove eax,[0xc7de4c]`
     — the slot keeps its value iff the byte is '>' (LOW BYTE), else
     "expected >" — *cursor = name_end+1 and `ret 8` (parent untouched).
   - TAG element: *cursor = cursor+1 (0x4167bd store); call 0x416040;
     `test ecx,ecx ; je 0x416780` — node == 0 continues the loop WITHOUT
     linking (the "no more children" gate, FULL-WORD).
   - link 0x4167ca / 0x416841 `cmp dword [parent+0x18],0 ; je FIRST`:
     FIRST stores node->prev (node+0x28) <- CONSTANT 0 and parent->
     children <- node; the append arm stores node->prev <- [parent+0x1c]
     (RE-READ at 0x4167da) and last->next <- node. Both arms parent->last
     <- node. The children-head test is FULL-WORD.
   - TEXT/END: *cursor = ebx (UNDO the ws skip, 0x4167fb); scanner
     0x416e80 (cursor-write contract); allocator 0x416510(size 0x30);
     node ctor [0]=0 [0x10]=0 [0x14]=2 [0x18]=0 [0x20]=0 [4]=text_start
     [0xc]=text_end-text_start (0x416817 sub, wrap); the SAME link gate;
     accum 0x41686c..81 `mov ecx,0xc71640 ; mov eax,[parent+4] ; test
     eax,eax ; cmovne ecx,eax ; cmp byte [ecx],0 ; jne skip` — store
     the span iff parent->text != 0 (FULL-WORD) AND *parent->text == 0
     (LOW BYTE); with parent->text == 0 the machine tests byte
     [0xc71640] == 0xed, so the default arm NEVER stores; NUL in place
     at the scanner end; continue at the gate WITHOUT a ws re-skip.
   - host calls per arm: END/TEXT 2 (scanner + allocator), TAG element 1
     (recursion — the element node comes from the nested parse, the
     children body itself allocates nothing), TAG close 0. */
test("v16 PE truth (native): 0x00416770 children recursion/continuation",
     () => {
  const view = new DataView(wasm.memory.buffer);
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x00416770/);
  assert.match(h, /0x00416e80/);
  assert.match(h, /first byte 0xed/);
  assert.match(h, /0x00c71640/);
  assert.match(h, /0x41690f/);

  /* Top gate: the 0x4167a2..a8 byte test. Wide drives act on the LOW
     byte (al was loaded from the cursor). */
  eq(wasm.isaac_sfx_xml_children_top_gate(0), SFX_XML_CHILDREN_TOP_END);
  eq(wasm.isaac_sfx_xml_children_top_gate(0x100), SFX_XML_CHILDREN_TOP_END,
     "wide NUL is still the END arm");
  eq(wasm.isaac_sfx_xml_children_top_gate(0x3c), SFX_XML_CHILDREN_TOP_TAG);
  eq(wasm.isaac_sfx_xml_children_top_gate(0x13c), SFX_XML_CHILDREN_TOP_TAG,
     "wide '<'");
  eq(wasm.isaac_sfx_xml_children_top_gate(0x41), SFX_XML_CHILDREN_TOP_TEXT);
  eq(wasm.isaac_sfx_xml_children_top_gate(0x1ff), SFX_XML_CHILDREN_TOP_TEXT);
  eq(wasm.isaac_sfx_xml_children_top_gate(0xffffffff),
     SFX_XML_CHILDREN_TOP_TEXT);
  eq(wasm.isaac_sfx_xml_children_top_gate(0x2f), SFX_XML_CHILDREN_TOP_TEXT,
     "'/' is text at the TOP (only cursor+1 is the close gate)");
  seen("v16Top", wasm.isaac_sfx_xml_children_top_gate(0x100));
  seen("v16TopB", 0x100);
  seen("v16Top", wasm.isaac_sfx_xml_children_top_gate(0x13c));
  seen("v16Top", wasm.isaac_sfx_xml_children_top_gate(0x1ff));

  /* Close-open: cursor+1 == '/' (LOW BYTE). */
  eq(wasm.isaac_sfx_xml_children_close_open(0x2f), 1);
  eq(wasm.isaac_sfx_xml_children_close_open(0x12f), 1, "wide '/'");
  eq(wasm.isaac_sfx_xml_children_close_open(0x2e), 0);
  eq(wasm.isaac_sfx_xml_children_close_open(0x3c), 0);
  eq(wasm.isaac_sfx_xml_children_close_open(0x100), 0, "low 0 is not '/'");
  eq(wasm.isaac_sfx_xml_children_close_open(0xffffffff), 0);
  seen("v16Close", wasm.isaac_sfx_xml_children_close_open(0x2f));
  seen("v16Close", wasm.isaac_sfx_xml_children_close_open(0x12f));

  /* Nested-return gate: FULL-WORD node test (0x4167c6). */
  eq(wasm.isaac_sfx_xml_children_nested_live(0), 0, "0 -> loop without link");
  eq(wasm.isaac_sfx_xml_children_nested_live(0x100), 1,
     "FULL-WORD: 0x100 is a live node");
  eq(wasm.isaac_sfx_xml_children_nested_live(0xffffffff), 1);
  eq(wasm.isaac_sfx_xml_children_nested_live(1), 1);
  seen("v16Live", 0);
  seen("v16Live", 1);

  /* Link arm: FULL-WORD children-head test (0x4167ca / 0x416841). */
  eq(wasm.isaac_sfx_xml_children_link_first(0), 1, "empty head -> FIRST");
  eq(wasm.isaac_sfx_xml_children_link_first(0x100), 0,
     "FULL-WORD: 0x100 low byte 0 is NOT an empty head");
  eq(wasm.isaac_sfx_xml_children_link_first(0xffffffff), 0);
  eq(wasm.isaac_sfx_xml_children_link_first(1), 0);
  seen("v16LinkFirst", 0);
  seen("v16LinkFirst", 1);

  /* The +0x28 store: FIRST stores the CONSTANT 0, append stores
     parent->last (0x4167d7 / 0x416855). */
  eq(wasm.isaac_sfx_xml_children_link_prev(0, 0x2000) >>> 0, 0,
     "FIRST arm stores the constant 0, not last");
  eq(wasm.isaac_sfx_xml_children_link_prev(0x100, 0x2000) >>> 0, 0x2000);
  eq(wasm.isaac_sfx_xml_children_link_prev(0x100, 0) >>> 0, 0);
  eq(wasm.isaac_sfx_xml_children_link_prev(0xffffffff, 0x2000) >>> 0,
     0x2000);
  eq(wasm.isaac_sfx_xml_children_link_prev(0, 0xffffffff) >>> 0, 0);
  seen("v16LinkPrev", 0);
  seen("v16LinkPrev", 1);

  /* Text length: 0x416817 `sub edx,ebx`, wrap. */
  eq(wasm.isaac_sfx_xml_children_text_len(0x1000, 0x1030) >>> 0, 0x30);
  eq(wasm.isaac_sfx_xml_children_text_len(0x1030, 0x1000) >>> 0,
     0xffffffd0, "wrap: end before start");
  eq(wasm.isaac_sfx_xml_children_text_len(0xfffffff0, 0x10) >>> 0, 0x20);
  eq(wasm.isaac_sfx_xml_children_text_len(0x1000, 0x1000) >>> 0, 0);
  /* marker: > 0x10000 means the wrap row hit */
  seen("v16TextLen", wasm.isaac_sfx_xml_children_text_len(0x1030, 0x1000) >
       0x10000 ? 1 : 0);
  seen("v16TextLen", wasm.isaac_sfx_xml_children_text_len(0x1000, 0x1030) >
       0x10000 ? 1 : 0);

  /* Text accum (0x41686c..81): FULL-WORD parent->text on the cmovne,
     LOW-BYTE *text on the cmp. parent_text == 0 tests byte[0xc71640] ==
     0xed -> NEVER stores. */
  eq(wasm.isaac_sfx_xml_children_text_accum(0x2000, 0), 1,
     "non-null parent, empty first byte -> store");
  eq(wasm.isaac_sfx_xml_children_text_accum(0x2000, 0x100), 1,
     "wide first byte 0 is still empty");
  eq(wasm.isaac_sfx_xml_children_text_accum(0x2000, 0x41), 0);
  eq(wasm.isaac_sfx_xml_children_text_accum(0, 0), 0,
     "default 0xc71640 (byte 0xed) never stores — KEY discriminator");
  eq(wasm.isaac_sfx_xml_children_text_accum(0xffffffff, 0), 1,
     "FULL-WORD parent pointer");
  eq(wasm.isaac_sfx_xml_children_text_accum(0x2000, 0xffffffff) >>> 0, 0,
     "low 0xff first byte");
  seen("v16Accum", 0);
  seen("v16Accum", 1);

  /* Text node ctor offsets {0x00,0x04,0x0c,0x10,0x14,0x18,0x20,0x28,0x2c}. */
  for (const off of [0x00, 0x04, 0x0c, 0x10, 0x14, 0x18, 0x20, 0x28, 0x2c]) {
    eq(wasm.isaac_sfx_xml_children_text_node_writes_offset(off), 1,
       `text ctor off ${off}`);
    seen("v16Store", 1);
  }
  for (const off of [0x08, 0x24, 0x30, 0x100, 0xffffffff]) {
    eq(wasm.isaac_sfx_xml_children_text_node_writes_offset(off), 0,
       `not text ${off}`);
    seen("v16Store", 0);
  }
  eq(wasm.isaac_sfx_xml_children_text_node_writes_offset(0x08), 0,
     "the TEXT node never stores name_len (the ELEMENT template does)");

  /* Cursor continuation: END/TEXT -> scanner end, TAG elem -> tag_pos+1,
     TAG close -> name_end+1 (wrap). */
  eq(wasm.isaac_sfx_xml_children_cursor_after(SFX_XML_CHILDREN_TOP_END, 0,
                                              0x1000, 0x1030, 0x2000) >>> 0,
     0x1030);
  eq(wasm.isaac_sfx_xml_children_cursor_after(SFX_XML_CHILDREN_TOP_TEXT, 1,
                                              0x1000, 0x1030, 0x2000) >>> 0,
     0x1030, "TEXT ignores close_open");
  eq(wasm.isaac_sfx_xml_children_cursor_after(SFX_XML_CHILDREN_TOP_TAG, 0,
                                              0x1000, 0x1030, 0x2000) >>> 0,
     0x1001, "element: cursor+1 (0x4167bd)");
  eq(wasm.isaac_sfx_xml_children_cursor_after(SFX_XML_CHILDREN_TOP_TAG, 1,
                                              0x1000, 0x1030, 0x2000) >>> 0,
     0x2001, "close: name_end+1 (0x416904)");
  eq(wasm.isaac_sfx_xml_children_cursor_after(SFX_XML_CHILDREN_TOP_TAG, 0,
                                              0xffffffff, 0, 0) >>> 0, 0,
     "wrap tag_pos+1");
  eq(wasm.isaac_sfx_xml_children_cursor_after(SFX_XML_CHILDREN_TOP_TAG, 1,
                                              0, 0, 0xffffffff) >>> 0, 0,
     "wrap name_end+1");
  seen("v16Cursor", 0);
  seen("v16Cursor", 1);
  seen("v16Cursor", 2);

  /* Plan fixed rows. */
  const cplan = SCRATCH + 0x27800;
  /* END arm: the '/' test never runs, the slot gets 0xb1b678, and the
     arm falls through into the TEXT machinery (alloc + link + accum). */
  wasm.isaac_sfx_xml_children_plan(0x100, 0x2f, 0xfff, 0, 0x100, 0x2000,
                                   0x1000, 0x1030, 0x2000, 0, 0x1060, 0x3e,
                                   0x1234, cplan);
  let cp = readChildrenPlan(view, cplan);
  eq(cp.topGate, SFX_XML_CHILDREN_TOP_END);
  eq(cp.endError >>> 0, SFX_XML_CHILDREN_ERR_END_VA,
     "END stores 0xb1b678 unconditionally (0x4167ef)");
  eq(cp.closeOpen, 0, "the cursor+1 '/' test never runs on END");
  eq(cp.nestedRecurses, 0);
  eq(cp.nestedLive, 1, "END falls into the TEXT arm and allocates");
  eq(cp.linkNeeded, 1);
  eq(cp.linkFirst, 0, "0x100 children head is append (FULL-WORD)");
  eq(cp.linkPrev >>> 0, 0x2000);
  eq(cp.textLen >>> 0, 0x30);
  eq(cp.textType >>> 0, 2, "text node type at +0x14");
  eq(cp.textAccum, 1, "parent non-null and empty -> store");
  eq(cp.cursorUndo, 1, "0x4167fb restores *cursor to the pre-ws start");
  eq(cp.closeError >>> 0, 0x1234, "slot untouched after the END store");
  eq(cp.cursorAfter >>> 0, 0x1030, "scanner end");
  eq(cp.hostCalls, 2, "scanner + allocator");
  eq(cp.pureComplete, 0);
  eq(cp.sizeBytes >>> 0, 0x1a2);
  eq(cp.insns, 139);
  eq(cp.stores, 38);
  eq(cp.callerCount, 1);
  seen("v16EndErr", 0);
  seen("v16EndErr", 1);
  seen("v16Cursor", 0);
  seen("v16Host", cp.hostCalls);

  /* TAG element, nested returned 0 -> the loop continues WITHOUT link. */
  wasm.isaac_sfx_xml_children_plan(0x3c, 0x61, 0x2000, 0, 0, 0, 0x1000,
                                   0x1030, 0x2000, 0, 0x1060, 0x3e, 0x5555,
                                   cplan);
  cp = readChildrenPlan(view, cplan);
  eq(cp.topGate, SFX_XML_CHILDREN_TOP_TAG);
  eq(cp.closeOpen, 0);
  eq(cp.nestedRecurses, 1);
  eq(cp.nestedLive, 0, "nested returned 0 -> no child");
  eq(cp.linkNeeded, 0, "the 'no more children' gate");
  eq(cp.linkFirst, 0, "not computed");
  eq(cp.linkPrev >>> 0, 0);
  eq(cp.textLen >>> 0, 0, "no text arm");
  eq(cp.textType >>> 0, 0);
  eq(cp.textAccum, 0);
  eq(cp.cursorUndo, 0, "the TAG arm keeps the ws-skipped cursor");
  eq(cp.closeError >>> 0, 0x5555, "slot untouched");
  eq(cp.cursorAfter >>> 0, 0x2001, "cursor+1 before the recursion");
  eq(cp.hostCalls, 1, "the recursion only");
  seen("v16Cursor", 1);
  seen("v16Host", cp.hostCalls);

  /* TAG element, nested node live, EMPTY children head -> FIRST arm. */
  wasm.isaac_sfx_xml_children_plan(0x3c, 0x61, 0x2000, 0x100, 0, 0x2000,
                                   0x1000, 0x1030, 0x2000, 0, 0x1060, 0x3e,
                                   0x5555, cplan);
  cp = readChildrenPlan(view, cplan);
  eq(cp.nestedLive, 1);
  eq(cp.linkNeeded, 1);
  eq(cp.linkFirst, 1, "empty head -> FIRST (FULL-WORD)");
  eq(cp.linkPrev >>> 0, 0, "FIRST stores the CONSTANT 0, not last");
  eq(cp.hostCalls, 1);
  seen("v16LinkFirst", 1);
  seen("v16LinkPrev", 0);

  /* TAG close: no node, no link, the '>' keep-slot law at the post-walk
     byte, cursor past the '>'. */
  wasm.isaac_sfx_xml_children_plan(0x3c, 0x2f, 0x2000, 0x100, 0x100, 0x2000,
                                   0x1000, 0x1030, 0x2000, 0, 0x3000, 0x3e,
                                   0x7777, cplan);
  cp = readChildrenPlan(view, cplan);
  eq(cp.closeOpen, 1);
  eq(cp.nestedRecurses, 0);
  eq(cp.nestedLive, 0);
  eq(cp.linkNeeded, 0, "the close tag links nothing");
  eq(cp.closeError >>> 0, 0x7777, "'>' keeps the slot (low byte)");
  eq(cp.cursorAfter >>> 0, 0x3001, "name_end + 1");
  eq(cp.hostCalls, 0, "the close path calls nothing");
  eq(cp.textLen >>> 0, 0);
  eq(cp.cursorUndo, 0);
  eq(cp.linkFirst, 0);
  eq(cp.linkPrev >>> 0, 0);
  seen("v16Close", 1);
  seen("v16Host", cp.hostCalls);
  wasm.isaac_sfx_xml_children_plan(0x3c, 0x2f, 0x2000, 0x100, 0x100, 0x2000,
                                   0x1000, 0x1030, 0x2000, 0, 0x3000, 0x2f,
                                   0x7777, cplan);
  cp = readChildrenPlan(view, cplan);
  eq(cp.closeError >>> 0, SFX_XML_CHILDREN_ERR_GT_VA,
     "no '>' -> 'expected >' (0x4168f0..ff)");
  seen("v16CloseErr", 0);
  seen("v16CloseErr", 1);

  /* TEXT arm: top byte is not '<'; the parent->text == 0 arm tests
     0xc71640's 0xed and never stores. */
  wasm.isaac_sfx_xml_children_plan(0x41, 0x2f, 0x2000, 0, 0, 0x2000, 0x1000,
                                   0x1030, 0, 0, 0x1060, 0x3e, 0x1234,
                                   cplan);
  cp = readChildrenPlan(view, cplan);
  eq(cp.topGate, SFX_XML_CHILDREN_TOP_TEXT);
  eq(cp.closeOpen, 0);
  eq(cp.nestedRecurses, 0);
  eq(cp.nestedLive, 1);
  eq(cp.linkNeeded, 1);
  eq(cp.linkFirst, 1);
  eq(cp.linkPrev >>> 0, 0);
  eq(cp.textLen >>> 0, 0x30);
  eq(cp.textType >>> 0, 2);
  eq(cp.textAccum, 0, "parent_text==0 -> 0xc71640's byte is 0xed");
  eq(cp.cursorUndo, 1);
  eq(cp.closeError >>> 0, 0x1234);
  eq(cp.cursorAfter >>> 0, 0x1030);
  eq(cp.hostCalls, 2);
  eq(cp.endError >>> 0, 0x1234, "slot untouched on the TEXT arm");
  seen("v16EndErr", 0);
  seen("v16Accum", 0);
  seen("v16Cursor", 0);
  seen("v16Host", cp.hostCalls);
  countCase();
});

test("Wasm matches JS: v16 children differential", () => {
  const view = new DataView(wasm.memory.buffer);
  const planBase = SCRATCH + 0x28000;

  let seed = (0x00416770 ^ 0x00416040 ^ 0x00416e80 ^ 0x00c71640) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const byteDraws = [0, 0x22, 0x27, 0x3d, 0x41, 0x21, 0x3c, 0x3e, 0x2f,
                     0x3f, 0x100, 0x13c, 0x12f, 0x1ff, 0xffffffff];
  const nodeDraws = [0, 1, 0x100, 0xffffffff];
  const headDraws = [0, 1, 0x100, 0xffffffff];
  const lastDraws = [0, 0x2000, 0xffffffff];
  const ptDraws = [0, 0x100, 0x2000, 0xffffffff];
  const posDraws = [0x1000, 0x1030, 0xfffffff0, 0xffffffff];
  const prevDraws = [0x1024, 0x1234, 0x7777, 0xfffffff0, 0xffffffff];

  for (let k = 0; k < 400; ++k) {
    const topByte = byteDraws[pick(rnd, byteDraws.length)];
    const closeByte = byteDraws[pick(rnd, byteDraws.length)];
    const tagPos = posDraws[pick(rnd, posDraws.length)];
    const nestedNode = nodeDraws[pick(rnd, nodeDraws.length)];
    const childrenHead = headDraws[pick(rnd, headDraws.length)];
    const lastChild = lastDraws[pick(rnd, lastDraws.length)];
    const textStart = posDraws[pick(rnd, posDraws.length)];
    const textEnd = posDraws[pick(rnd, posDraws.length)];
    const parentText = ptDraws[pick(rnd, ptDraws.length)];
    const textFirstByte = byteDraws[pick(rnd, byteDraws.length)];
    const nameEnd = posDraws[pick(rnd, posDraws.length)];
    const closeTailByte = byteDraws[pick(rnd, byteDraws.length)];
    const prevError = prevDraws[pick(rnd, prevDraws.length)];
    seen("v16TopB", topByte);
    seen("v16CloseB", closeByte);
    seen("v16NodeB", nestedNode);
    seen("v16HeadB", childrenHead);
    seen("v16LastB", lastChild);
    seen("v16PtB", parentText);
    seen("v16FbB", textFirstByte);
    seen("v16PosB", textStart);
    seen("v16PosB", textEnd);
    seen("v16TailB", closeTailByte);
    seen("v16PrevE", prevError);

    /* Scalar laws. */
    eq(wasm.isaac_sfx_xml_children_top_gate(topByte),
       sfxXmlChildrenTopGate(topByte), `top ${topByte}`);
    eq(wasm.isaac_sfx_xml_children_close_open(closeByte),
       sfxXmlChildrenCloseOpen(closeByte), `close ${closeByte}`);
    eq(wasm.isaac_sfx_xml_children_nested_live(nestedNode),
       sfxXmlChildrenNestedLive(nestedNode), `live ${nestedNode}`);
    eq(wasm.isaac_sfx_xml_children_link_first(childrenHead),
       sfxXmlChildrenLinkFirst(childrenHead), `first ${childrenHead}`);
    eq(wasm.isaac_sfx_xml_children_link_prev(childrenHead, lastChild) >>> 0,
       sfxXmlChildrenLinkPrev(childrenHead, lastChild),
       `prev ${childrenHead}/${lastChild}`);
    eq(wasm.isaac_sfx_xml_children_text_len(textStart, textEnd) >>> 0,
       sfxXmlChildrenTextLen(textStart, textEnd),
       `len ${textStart}/${textEnd}`);
    eq(wasm.isaac_sfx_xml_children_text_accum(parentText, textFirstByte),
       sfxXmlChildrenTextAccum(parentText, textFirstByte),
       `accum ${parentText}/${textFirstByte}`);
    eq(wasm.isaac_sfx_xml_children_text_node_writes_offset(textFirstByte),
       sfxXmlChildrenTextNodeWritesOffset(textFirstByte),
       `writes ${textFirstByte}`);
    seen("v16Top", wasm.isaac_sfx_xml_children_top_gate(topByte));
    seen("v16Close", wasm.isaac_sfx_xml_children_close_open(closeByte));
    seen("v16Live", wasm.isaac_sfx_xml_children_nested_live(nestedNode));
    seen("v16LinkFirst", wasm.isaac_sfx_xml_children_link_first(childrenHead));
    seen("v16LinkPrev", wasm.isaac_sfx_xml_children_link_prev(childrenHead,
                                                              lastChild) ===
         0 ? 0 : 1);
    seen("v16Accum", wasm.isaac_sfx_xml_children_text_accum(parentText,
                                                            textFirstByte));
    seen("v16Store", wasm.isaac_sfx_xml_children_text_node_writes_offset(
      textFirstByte));
    countCase();

    /* The plan record. */
    wasm.isaac_sfx_xml_children_plan(topByte, closeByte, tagPos, nestedNode,
                                     childrenHead, lastChild, textStart,
                                     textEnd, parentText, textFirstByte,
                                     nameEnd, closeTailByte, prevError,
                                     planBase);
    const wc = readChildrenPlan(view, planBase);
    const jc = sfxXmlChildrenPlan(topByte, closeByte, tagPos, nestedNode,
                                  childrenHead, lastChild, textStart,
                                  textEnd, parentText, textFirstByte,
                                  nameEnd, closeTailByte, prevError);
    assertPlanEqual(wc, jc, `children plan ${k}`);
    seen("v16Top", wc.topGate);
    seen("v16EndErr", wc.endError === SFX_XML_CHILDREN_ERR_END_VA ? 1 : 0);
    seen("v16Close", wc.closeOpen);
    seen("v16Recurse", wc.nestedRecurses);
    seen("v16Live", wc.nestedLive);
    seen("v16LinkFirst", wc.linkFirst);
    seen("v16LinkPrev", wc.linkPrev === 0 ? 0 : 1);
    seen("v16TextLen", wc.textLen > 0x10000 ? 1 : 0);
    seen("v16Type", wc.textType);
    seen("v16Accum", wc.textAccum);
    seen("v16Undo", wc.cursorUndo);
    seen("v16CloseErr", wc.closeError === SFX_XML_CHILDREN_ERR_GT_VA ? 0 : 1);
    seen("v16Host", wc.hostCalls);
    seen("v16Cursor", wc.topGate === SFX_XML_CHILDREN_TOP_TAG
      ? (wc.closeOpen !== 0 ? 2 : 1) : 0);
    seen("v16Pure", wc.pureComplete);
    countCase();
  }
});

test("v18 PE truth (native): 0x00416dc0 utf8-append + attrs gates", () => {
  const h = readFileSync(header, "utf8");
  /* Header pins: the helper's address-stable constants. */
  assert.match(h, /0x00416dc0/);
  assert.match(h, /0x00b1b704/);
  assert.match(h, /0x00c7de4c/);
  assert.match(h, /0x110000/);
  assert.match(h, /0x416b70/);
  assert.match(h, /0x416920/);
  assert.match(h, /0x00b1a860/);
  assert.match(h, /0x00b1a960/);
  assert.match(h, /0x00b1ab60/);
  assert.match(h, /0x00b1ac60/);

  /* PE-truth references re-transcribed branch-by-branch from
     cpu-dump/00416dc0.txt (NOT from the C++): the four jae arms. */
  const peLen = (v) => {
    const u = v >>> 0;
    if (u < 0x80) return 1;
    if (u < 0x800) return 2;
    if (u < 0x10000) return 3;
    return u < 0x110000 ? 4 : 0;
  };
  const peByte = (v, index) => {
    const u = v >>> 0;
    const len = peLen(u);
    if (index >= len) return 0x100; /* the machine writes nothing */
    if (len === 1) return u & 0xff; /* mov [eax], dl */
    if (len === 2) {
      return index === 0
        ? (0xc0 | ((u >>> 6) & 0xff))
        : (0x80 | (u & 0x3f));
    }
    if (len === 3) {
      if (index === 0) return 0xe0 | ((u >>> 12) & 0xff);
      if (index === 1) return 0x80 | ((u >>> 6) & 0x3f);
      return 0x80 | (u & 0x3f);
    }
    if (index === 0) return 0xf0 | ((u >>> 18) & 0xff);
    if (index === 1) return 0x80 | ((u >>> 12) & 0x3f);
    if (index === 2) return 0x80 | ((u >>> 6) & 0x3f);
    return 0x80 | (u & 0x3f);
  };
  const peErr = (prev, v) =>
    (v >>> 0) < 0x110000 ? prev >>> 0 : 0xb1b704;

  eq(peLen(0x7f), 1);
  eq(peLen(0x80), 2);
  eq(peLen(0x7ff), 2);
  eq(peLen(0x800), 3);
  eq(peLen(0xffff), 3);
  eq(peLen(0x10000), 4);
  eq(peLen(0x10ffff), 4);
  eq(peLen(0x110000), 0); /* error arm: no write */
  eq(peLen(0xffffffff), 0);
  eq(peByte(0x24, 0), 0x24);
  eq(peByte(0x80, 0), 0xc2); /* 0xc0 | (0x80>>6 = 2) */
  eq(peByte(0x80, 1), 0x80); /* 0x80 | (0x80 & 0x3f = 0) */
  eq(peByte(0xbe, 0), 0xc2); /* 0xc0 | (0xbe>>6 = 2) */
  eq(peByte(0xbe, 1), 0xbe); /* 0x80 | (0xbe & 0x3f = 0x3e) */
  eq(peByte(0x7ff, 0), 0xdf); /* 0xc0 | (0x7ff>>6 = 0x1f) */
  eq(peByte(0x7ff, 1), 0xbf); /* 0x80 | 0x3f */
  eq(peByte(0x800, 0), 0xe0); /* 0xe0 | (0x800>>12 = 0) */
  eq(peByte(0x800, 1), 0xa0); /* 0x80 | (0x800>>6 & 0x3f = 0x20) */
  eq(peByte(0x800, 2), 0x80);
  eq(peByte(0xffff, 0), 0xef); /* 0xe0 | (0xffff>>12 = 0xf) */
  eq(peByte(0xffff, 1), 0xbf);
  eq(peByte(0xffff, 2), 0xbf);
  eq(peByte(0x10000, 0), 0xf0); /* 0xf0 | (0x10000>>18 = 0) */
  eq(peByte(0x10000, 1), 0x90); /* 0x80 | (0x10000>>12 & 0x3f = 0x10) */
  eq(peByte(0x10000, 2), 0x80);
  eq(peByte(0x10000, 3), 0x80);
  eq(peByte(0x10ffff, 0), 0xf4); /* 0xf0 | (0x10ffff>>18 = 4) */
  eq(peByte(0x10ffff, 1), 0x8f); /* 0x80 | (0x10ffff>>12 & 0x3f = 0xf) */
  eq(peByte(0x10ffff, 2), 0xbf);
  eq(peByte(0x10ffff, 3), 0xbf);
  eq(peByte(0x110000, 0), 0x100, "error arm writes no byte");
  eq(peByte(0xffffffff, 3), 0x100);
  eq(peErr(0x1234, 0x10000), 0x1234);
  eq(peErr(0x1234, 0x10ffff), 0x1234);
  eq(peErr(0x1234, 0x110000) >>> 0, 0xb1b704,
     "UNCONDITIONAL store, no prev recapture");
  eq(peErr(0x1234, 0xffffffff) >>> 0, 0xb1b704);

  /* The four attrs-leaf gates from their OWN dumps (0x416b70 uses
     0xb1a860/0xb1ab60, 0x416920 uses 0xb1a960/0xb1ac60). */
  const peDqSkip = (b) => {
    const c = b & 0xff;
    return (c === 0 || c === 0x22 || c === 0x26) ? 0 : 1;
  };
  const peDqText = (b) => {
    const c = b & 0xff;
    return (c === 0 || c === 0x22) ? 0 : 1;
  };
  const peSqSkip = (b) => {
    const c = b & 0xff;
    return (c === 0 || c === 0x26 || c === 0x27) ? 0 : 1;
  };
  const peSqText = (b) => {
    const c = b & 0xff;
    return (c === 0 || c === 0x27) ? 0 : 1;
  };
  for (const b of [0, 0x22, 0x26, 0x27, 0x41, 0x3c, 0x100, 0x1ff,
                   0xffffffff]) {
    eq(peDqSkip(b), sfxXmlAttrDquoteSkipChar(b), `dqskip ${b}`);
    eq(peDqText(b), sfxXmlAttrDquoteTextChar(b), `dqtext ${b}`);
    eq(peSqSkip(b), sfxXmlAttrSquoteSkipChar(b), `sqskip ${b}`);
    eq(peSqText(b), sfxXmlAttrSquoteTextChar(b), `sqtext ${b}`);
    eq(wasm.isaac_sfx_xml_attr_dquote_skip_char(b),
       sfxXmlAttrDquoteSkipChar(b), `wasm dqskip ${b}`);
    eq(wasm.isaac_sfx_xml_attr_dquote_text_char(b),
       sfxXmlAttrDquoteTextChar(b), `wasm dqtext ${b}`);
    eq(wasm.isaac_sfx_xml_attr_squote_skip_char(b),
       sfxXmlAttrSquoteSkipChar(b), `wasm sqskip ${b}`);
    eq(wasm.isaac_sfx_xml_attr_squote_text_char(b),
       sfxXmlAttrSquoteTextChar(b), `wasm sqtext ${b}`);
    seen("v18DqSkip", peDqSkip(b));
    seen("v18DqText", peDqText(b));
    seen("v18SqSkip", peSqSkip(b));
    seen("v18SqText", peSqText(b));
    countCase();
  }

  /* The dquote and squote sets differ exactly at the quote bytes. */
  eq(sfxXmlAttrDquoteSkipChar(0x22), 0);
  eq(sfxXmlAttrDquoteSkipChar(0x27), 1);
  eq(sfxXmlAttrSquoteSkipChar(0x22), 1);
  eq(sfxXmlAttrSquoteSkipChar(0x27), 0);
  eq(sfxXmlAttrDquoteTextChar(0x26), 1, "'&' continues a dquote value");
  eq(sfxXmlAttrSquoteTextChar(0x26), 1, "'&' continues a squote value");
});

test("Wasm matches JS: v18 utf8 + attrs-gate differential", () => {
  let seed = (0x00416dc0 ^ 0x00416b70 ^ 0x00416920 ^ 0x00b1b704) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const valueDraws = [0, 0x41, 0x7f, 0x80, 0x3e, 0x7ff, 0x800, 0xffff,
                      0x10000, 0x10ffff, 0x110000, 0xffffffff, 0x1234567,
                      0x100, 0x1000, 0xd7ff, 0xd800, 0xdfff];
  const idxDraws = [0, 1, 2, 3, 0x100, 0xffffffff];
  const byteDraws = [0, 0x22, 0x26, 0x27, 0x41, 0x3c, 0x3e, 0x100, 0x1ff,
                     0xffffffff];
  const prevDraws = [0, 0x1234, 0xb1b6f8, 0xffffffff];

  for (let k = 0; k < 500; ++k) {
    const value = valueDraws[pick(rnd, valueDraws.length)];
    const index = idxDraws[pick(rnd, idxDraws.length)];
    const prev = prevDraws[pick(rnd, prevDraws.length)];
    seen("v18Value", value);
    seen("v18Index", index);
    seen("v18Prev", prev);
    eq(wasm.isaac_sfx_xml_utf8_len(value) >>> 0,
       sfxXmlUtf8Len(value) >>> 0, `len ${value}`);
    eq(wasm.isaac_sfx_xml_utf8_byte(value, index) >>> 0,
       sfxXmlUtf8Byte(value, index) >>> 0, `byte ${value}/${index}`);
    eq(wasm.isaac_sfx_xml_utf8_error(prev, value) >>> 0,
       sfxXmlUtf8Error(prev, value) >>> 0, `error ${prev}/${value}`);
    seen("v18Len", sfxXmlUtf8Len(value));
    seen("v18Byte", sfxXmlUtf8Byte(value, index) === SFX_XML_UTF8_NO_BYTE
      ? 0 : 1);
    seen("v18Err", sfxXmlUtf8Error(prev, value) === 0xb1b704 ? 1 : 0);
    countCase();

    const b = byteDraws[pick(rnd, byteDraws.length)];
    eq(wasm.isaac_sfx_xml_attr_dquote_skip_char(b),
       sfxXmlAttrDquoteSkipChar(b), `dqskip ${b}`);
    eq(wasm.isaac_sfx_xml_attr_dquote_text_char(b),
       sfxXmlAttrDquoteTextChar(b), `dqtext ${b}`);
    eq(wasm.isaac_sfx_xml_attr_squote_skip_char(b),
       sfxXmlAttrSquoteSkipChar(b), `sqskip ${b}`);
    eq(wasm.isaac_sfx_xml_attr_squote_text_char(b),
       sfxXmlAttrSquoteTextChar(b), `sqtext ${b}`);
    seen("v18DqSkip", sfxXmlAttrDquoteSkipChar(b));
    seen("v18DqText", sfxXmlAttrDquoteTextChar(b));
    seen("v18SqSkip", sfxXmlAttrSquoteSkipChar(b));
    seen("v18SqText", sfxXmlAttrSquoteTextChar(b));
    countCase();
  }

  /* Homestretch sanity: the exact UTF-8 encodings the three scanners
     emit for common numeric character references. */
  const enc = (v) => {
    const len = sfxXmlUtf8Len(v);
    const out = [];
    for (let i = 0; i < 4; ++i) {
      const b = sfxXmlUtf8Byte(v, i);
      if (b !== SFX_XML_UTF8_NO_BYTE) out.push(b);
    }
    eq(out.length, len, `encoding length ${v}`);
    return out;
  };
  assert.deepStrictEqual(enc(0x26), [0x26]);
  assert.deepStrictEqual(enc(0x3e), [0x3e]);
  assert.deepStrictEqual(enc(0xa9), [0xc2, 0xa9]);   /* © */
  assert.deepStrictEqual(enc(0x20ac), [0xe2, 0x82, 0xac]); /* € */
  assert.deepStrictEqual(enc(0x1f600), [0xf0, 0x9f, 0x98, 0x80]);
  eq(enc(0x110000).length, 0, "error arm emits nothing");
});

test("v19 PE truth (native): 0x004165a0 attrs parse-loop decisions", () => {
  const view = new DataView(wasm.memory.buffer);
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x004165a0/);
  assert.match(h, /IsaacSfxXmlAttrsIterPlan/);
  assert.match(h, /0x4165bb/);   /* the once-per-loop edx capture */
  assert.match(h, /0x41662a/);   /* the FULL-WORD head gate */
  assert.match(h, /0x416687/);   /* *cursor = ws1_end+1 (past '=') */
  assert.match(h, /0x4166cd/);   /* value_start = ws2_end+1, unquoted */
  assert.match(h, /0x4166fe/);   /* *cursor = value_end+1 */
  assert.match(h, /0x41668c/);   /* the NUL-in-place address law */
  assert.match(h, /0xc71640/);

  const pairs = [
    ["ISAAC_SFX_XML_ATTR_OFF_NAME_00", SFX_XML_ATTR_OFF_NAME_00, 0x00],
    ["ISAAC_SFX_XML_ATTR_OFF_VALUE_04", SFX_XML_ATTR_OFF_VALUE_04, 0x04],
    ["ISAAC_SFX_XML_ATTR_OFF_NAME_LEN_08", SFX_XML_ATTR_OFF_NAME_LEN_08,
     0x08],
    ["ISAAC_SFX_XML_ATTR_OFF_VALUE_LEN_0C", SFX_XML_ATTR_OFF_VALUE_LEN_0C,
     0x0c],
    ["ISAAC_SFX_XML_ATTR_OFF_PARENT_10", SFX_XML_ATTR_OFF_PARENT_10, 0x10],
    ["ISAAC_SFX_XML_ATTR_OFF_PREV_14", SFX_XML_ATTR_OFF_PREV_14, 0x14],
    ["ISAAC_SFX_XML_ATTR_OFF_NEXT_18", SFX_XML_ATTR_OFF_NEXT_18, 0x18],
    ["ISAAC_SFX_XML_ATTR_PARENT_OFF_HEAD_20",
     SFX_XML_ATTR_PARENT_OFF_HEAD_20, 0x20],
    ["ISAAC_SFX_XML_ATTR_PARENT_OFF_TAIL_24",
     SFX_XML_ATTR_PARENT_OFF_TAIL_24, 0x24],
    ["ISAAC_SFX_XML_ATTR_NUL_DEFAULT_VA", SFX_XML_ATTR_NUL_DEFAULT_VA,
     0x00c71640],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }
  /* The attrs offsets agree with the v12 find walks (attr head 0x20,
     attr next 0x18) and the v16 shared default buffer 0xc71640. */
  eq(SFX_XML_ATTR_PARENT_OFF_HEAD_20, 0x20);
  eq(SFX_XML_ATTR_OFF_NEXT_18, 0x18);
  eq(SFX_XML_ATTR_NUL_DEFAULT_VA, SFX_XML_CHILDREN_TEXT_DEFAULT_VA);

  /* PE-truth references re-transcribed branch-by-branch from
     cpu-dump/004165a0.txt (NOT from the C++):
     - 0x416687 `lea eax,[ecx+1]` (after '='), 0x4166cd/0x416713
       `lea esi,[ecx+1]` (value start, BOTH arms), 0x4166fe `inc eax`
       (after the value) — all +1 wrap.
     - 0x41662a `cmp dword [parent+0x20],0 ; je` FULL-WORD head gate;
       0x416630/0x416636 tail RE-READ twice; 0x416639 [tail+0x18]=node;
       0x41663e [node+0x14]=0; 0x416645 [parent+0x20]=node (first only);
       0x416648 [parent+0x24]=node ALWAYS; 0x41664b [node+0x10]=parent;
       0x41664e [node+0x18]=0 ALWAYS.
     - 0x41668c..0x41669e (name) / 0x416701..0x41672c (value) NUL addr:
       `test eax,eax ; je` (FULL-WORD) -> ptr!=0 ? ptr+len : 0xc71640;
       the fallback xors the offset. */

  /* The three +1 cursor laws, wrap. */
  eq(wasm.isaac_sfx_xml_attr_cursor_after_eq(0x1000) >>> 0, 0x1001);
  eq(wasm.isaac_sfx_xml_attr_cursor_after_eq(0x100) >>> 0, 0x101);
  eq(wasm.isaac_sfx_xml_attr_cursor_after_eq(0xffffffff) >>> 0, 0,
     "wrap after '='");
  eq(wasm.isaac_sfx_xml_attr_value_start(0x2000) >>> 0, 0x2001);
  eq(wasm.isaac_sfx_xml_attr_value_start(0x1ff) >>> 0, 0x200);
  eq(wasm.isaac_sfx_xml_attr_value_start(0xffffffff) >>> 0, 0,
     "wrap value start");
  eq(wasm.isaac_sfx_xml_attr_cursor_after_value(0x3000) >>> 0, 0x3001);
  eq(wasm.isaac_sfx_xml_attr_cursor_after_value(0x100) >>> 0, 0x101);
  eq(wasm.isaac_sfx_xml_attr_cursor_after_value(0xffffffff) >>> 0, 0,
     "wrap after value");
  seen("v19Cursor", 0);
  seen("v19Cursor", 1);
  countCase();

  /* Link gates: FULL-WORD head test, wide drives on the head. */
  eq(wasm.isaac_sfx_xml_attr_link_first(0), 1);
  eq(wasm.isaac_sfx_xml_attr_link_first(0x100), 0, "wide head live");
  eq(wasm.isaac_sfx_xml_attr_link_first(0xffffffff), 0);
  eq(wasm.isaac_sfx_xml_attr_link_prev(0, 0x1234) >>> 0, 0,
     "first arm prev = 0");
  eq(wasm.isaac_sfx_xml_attr_link_prev(0x100, 0x1234) >>> 0, 0x1234,
     "append prev = tail");
  eq(wasm.isaac_sfx_xml_attr_link_prev(0xffffffff, 0x1234) >>> 0, 0x1234);
  eq(wasm.isaac_sfx_xml_attr_link_tail_next(0, 0x5555) >>> 0, 0,
     "first arm has no tail to wire");
  eq(wasm.isaac_sfx_xml_attr_link_tail_next(0x100, 0x5555) >>> 0, 0x5555,
     "append wires tail->next");
  eq(wasm.isaac_sfx_xml_attr_link_new_head(0, 0x5555) >>> 0, 0x5555,
     "first arm writes the head");
  eq(wasm.isaac_sfx_xml_attr_link_new_head(0x100, 0x5555) >>> 0, 0x100,
     "append keeps the head");
  eq(wasm.isaac_sfx_xml_attr_link_new_head(0xffffffff, 0x5555) >>> 0,
     0xffffffff);
  seen("v19LinkFirst", 0); seen("v19LinkFirst", 1);
  seen("v19TailNext", 0); seen("v19TailNext", 1);
  seen("v19NewHead0", 0); seen("v19NewHead1", 1);
  countCase();

  /* NUL-in-place addresses (FULL-WORD ptr test, 0xc71640 fallback). */
  eq(wasm.isaac_sfx_xml_attr_nul_addr(0, 5) >>> 0, 0xc71640,
     "null ptr fallback");
  eq(wasm.isaac_sfx_xml_attr_nul_addr(0x1000, 5) >>> 0, 0x1005);
  eq(wasm.isaac_sfx_xml_attr_nul_addr(0xfffffff0, 0x20) >>> 0, 0x10,
     "wrap addr");
  eq(wasm.isaac_sfx_xml_attr_nul_addr(0x1000, 0xffffffff) >>> 0, 0xfff,
     "wrap len");
  eq(wasm.isaac_sfx_xml_attr_nul_addr(0xffffffff, 2) >>> 0, 1, "wrap both");
  seen("v19Nul", 0); seen("v19Nul", 1);
  countCase();

  /* The composed per-iteration record, fixed rows from the trace. */
  const ip = SCRATCH + 0x28000;
  const ITER = (e, f, ns, ne, w1, eqb, w2, q, vs, ve, eb, ph, pt, n, np,
                vp, cb) => {
    wasm.isaac_sfx_xml_attrs_iter_plan(e, f, ns, ne, w1, eqb, w2, q, vs,
                                       ve, eb, ph, pt, n, np, vp, cb, ip);
    return readAttrsIterPlan(view, ip);
  };

  /* Row 1: not entered (first byte 0x20 = SPACE is table-0). The
     0x4165b5 arm returns; every decision field is "not computed". */
  let w = ITER(0x1234, 0x20, 0x5000, 0x5002, 0x5010, 0x3d, 0x5011, 0x22,
               0x5012, 0x5016, 0x22, 0, 0, 0x7000, 0x5000, 0x5012, 0x20);
  eq(w.entered, 0, "space starts no attribute");
  eq(w.nameEmpty, 0);
  eq(w.nameError >>> 0, 0x1234, "nothing computed");
  eq(w.quoteKind, SFX_XML_ATTR_QUOTE_NONE);
  eq(w.eqError >>> 0, 0x1234);
  eq(w.valueError >>> 0, 0x1234);
  eq(w.errorSlot >>> 0, 0x1234);
  eq(w.valueLen >>> 0, 0);
  eq(w.cursorAfterEq >>> 0, 0);
  eq(w.valueStartPos >>> 0, 0);
  eq(w.cursorAfterValue >>> 0, 0);
  eq(w.linkFirst, 0);
  eq(w.nodePrev >>> 0, 0);
  eq(w.tailNext >>> 0, 0);
  eq(w.newHead >>> 0, 0);
  eq(w.nameNulAddr >>> 0, 0);
  eq(w.valueNulAddr >>> 0, 0);
  eq(w.iterate, 0);
  eq(w.nodeSize >>> 0, SFX_XML_ATTR_NODE_SIZE);
  eq(w.nodeStores, 0);
  eq(w.hostCalls, 0);
  eq(w.pureComplete, 0);
  eq(w.sizeBytes >>> 0, SFX_XML_ATTRS_SIZE_BYTES);
  eq(w.callerCount, 1);
  eq(w.parentOffHead >>> 0, 0x20);
  eq(w.parentOffTail >>> 0, 0x24);
  eq(w.nodeOffParent >>> 0, 0x10);
  eq(w.nodeOffPrev >>> 0, 0x14);
  eq(w.nodeOffNext >>> 0, 0x18);
  eq(w.nulDefaultVa >>> 0, 0xc71640);
  seen("v19IterEntered", 0);
  seen("v19IterHost", 0);
  seen("v19IterSlot", 0);
  countCase();

  /* Row 2: clean double-quoted attr on the FIRST arm. */
  w = ITER(0x1111, 0x61, 0x5000, 0x5002, 0x5010, 0x3d, 0x5011, 0x22,
           0x5012, 0x5016, 0x22, 0, 0, 0x7000, 0x5000, 0x5012, 0x20);
  eq(w.entered, 1);
  eq(w.nameEmpty, 0);
  eq(w.nameError >>> 0, 0x1111, "name gate keeps the ENTRY slot");
  eq(w.quoteKind, SFX_XML_ATTR_QUOTE_DOUBLE);
  eq(w.eqError >>> 0, 0x1111);
  eq(w.valueError >>> 0, 0x1111, "clean close keeps the slot");
  eq(w.errorSlot >>> 0, 0x1111);
  eq(w.valueLen >>> 0, 4);
  eq(w.cursorAfterEq >>> 0, 0x5011, "ws1_end + 1");
  eq(w.valueStartPos >>> 0, 0x5012, "ws2_end + 1");
  eq(w.cursorAfterValue >>> 0, 0x5017, "value_end + 1");
  eq(w.linkFirst, 1, "parent head 0 -> first arm");
  eq(w.nodePrev >>> 0, 0);
  eq(w.tailNext >>> 0, 0);
  eq(w.newHead >>> 0, 0x7000, "first arm writes the head");
  eq(w.nameNulAddr >>> 0, 0x5002, "name ptr + name len");
  eq(w.valueNulAddr >>> 0, 0x5016, "value ptr + value len");
  eq(w.iterate, 0, "space after ws3 does not continue");
  eq(w.hostCalls, 2);
  eq(w.nodeStores, 7);
  seen("v19IterEntered", 1);
  seen("v19IterHost", 2);
  seen("v19IterSlot", 0);
  seen("v19NameEmpty", 0);
  seen("v19IterQuote", w.quoteKind);
  countCase();

  /* Row 3: '=' gate misses -> 0xb1b6dc; the quoted value-close keeps it. */
  w = ITER(0x1111, 0x61, 0x5000, 0x5002, 0x5010, 0x41, 0x5011, 0x22,
           0x5012, 0x5016, 0x22, 0x8000, 0x8004, 0x7000, 0x5000, 0x5012,
           0x78);
  eq(w.eqError >>> 0, SFX_XML_ATTR_ERR_EQ_VA, "'A' is not '='");
  eq(w.valueError >>> 0, SFX_XML_ATTR_ERR_EQ_VA,
     "quoted close keeps the '=' gate value");
  eq(w.errorSlot >>> 0, SFX_XML_ATTR_ERR_EQ_VA);
  eq(w.linkFirst, 0, "append arm");
  eq(w.nodePrev >>> 0, 0x8004, "node->prev = tail");
  eq(w.tailNext >>> 0, 0x7000, "[tail+0x18] = node");
  eq(w.newHead >>> 0, 0x8000, "head untouched on append");
  eq(w.iterate, 1, "'x' is an attr-name char -> continue");
  seen("v19IterSlot", 1);
  countCase();

  /* Row 4: the unquoted arm — the 0x4166d0 PRE-store makes the close
     law ALWAYS 0xb1b6e8, even when end_byte == quote_byte. */
  w = ITER(0x1111, 0x61, 0x5000, 0x5002, 0x5010, 0x3d, 0x5011, 0x66,
           0x5012, 0x5016, 0x66, 0, 0, 0x7000, 0x5000, 0x5012, 0x20);
  eq(w.quoteKind, SFX_XML_ATTR_QUOTE_NONE);
  eq(w.valueError >>> 0, SFX_XML_ATTR_ERR_VALUE_VA,
     "unquoted close is always 0xb1b6e8");
  eq(w.errorSlot >>> 0, SFX_XML_ATTR_ERR_VALUE_VA);
  seen("v19IterSlot", 2);
  seen("v19IterQuote", SFX_XML_ATTR_QUOTE_NONE);
  countCase();

  /* Row 5: wide / LOW-BYTE drives on every byte gate, FULL-WORD head. */
  w = ITER(0x1111, 0x100 + 0x61, 0x5000, 0x5002, 0x5010, 0x100 + 0x3d,
           0x5011, 0x100 + 0x22, 0x5012, 0x5016, 0x100 + 0x22, 0x100,
           0x8004, 0x7000, 0x5000, 0x5012, 0x100 + 0x78);
  eq(w.entered, 1, "wide 'a' enters");
  eq(w.eqError >>> 0, 0x1111, "wide '=' passes the gate");
  eq(w.quoteKind, SFX_XML_ATTR_QUOTE_DOUBLE, "wide '\"' is DOUBLE");
  eq(w.valueError >>> 0, 0x1111, "wide close byte matches");
  eq(w.linkFirst, 0, "wide head 0x100 is live (FULL-WORD)");
  eq(w.iterate, 1, "wide 'x' continues");
  w = ITER(0x1111, 0x61, 0x5000, 0x5002, 0x5010, 0x3d, 0x5011, 0x22,
           0x5012, 0x5016, 0x22, 0xffffffff, 0x8004, 0x7000, 0x5000,
           0x5012, 0xffffffff);
  eq(w.linkFirst, 0, "head 0xffffffff is live");
  eq(w.iterate, 1, "byte 0xff is an attr-name char");
  seen("v19IterLink", 0); seen("v19IterLink", 1);
  seen("v19IterIterate", 0); seen("v19IterIterate", 1);
  seen("v19IterQuote", w.quoteKind);
  seen("v19IterSlot", 0);
  countCase();

  /* Row 6: the stale-slot law across TWO iterations. The once-captured
     edx (0x4165bb) feeds the name gate on EVERY iteration; the slot a
     previous iteration wrote NEVER leaks back. Row 3 ended with
     0xb1b6dc; this second attribute with the SAME entry slot still gets
     0x1111 from its name/'='/value gates. */
  w = ITER(0x1111, 0x62, 0x6000, 0x6003, 0x6010, 0x41, 0x6011, 0x27,
           0x6012, 0x6018, 0x27, 0x8000, 0x8004, 0x7100, 0x6000, 0x6012,
           0x20);
  eq(w.nameError >>> 0, 0x1111, "name gate never sees iter-1's slot");
  eq(w.eqError >>> 0, SFX_XML_ATTR_ERR_EQ_VA, "iter-2 '=' miss");
  eq(w.valueError >>> 0, SFX_XML_ATTR_ERR_EQ_VA,
     "value close keeps the ITER-2 eq value");
  eq(w.errorSlot >>> 0, SFX_XML_ATTR_ERR_EQ_VA);
  eq(w.linkFirst, 0, "second attr appends");
  eq(w.nodePrev >>> 0, 0x8004);
  seen("v19IterSlot", 1);
  seen("v19IterQuote", w.quoteKind);
  countCase();

  /* Row 7: FULL-WORD empty-name law (dead in the machine — the scan
     always leaves name_len >= 1 — but transcribed). */
  w = ITER(0x1111, 0x61, 0x5000, 0x5000, 0x5010, 0x3d, 0x5011, 0x27,
           0x5012, 0x5016, 0x27, 0, 0, 0x7000, 0x5000, 0x5012, 0x20);
  eq(w.nameEmpty, 1, "name_end == name_start (FULL-WORD)");
  eq(w.nameError >>> 0, SFX_XML_ATTR_ERR_NAME_VA, "empty -> 0xb1b6c4");
  eq(w.eqError >>> 0, SFX_XML_ATTR_ERR_NAME_VA,
     "the '=' gate re-reads the just-stored name error");
  eq(w.valueError >>> 0, SFX_XML_ATTR_ERR_NAME_VA,
     "clean squote close keeps it");
  eq(w.errorSlot >>> 0, SFX_XML_ATTR_ERR_NAME_VA);
  seen("v19IterSlot", 3);
  seen("v19NameEmpty", 1);
  countCase();
});

test("Wasm matches JS: v19 attrs loop-decision differential", () => {
  const view = new DataView(wasm.memory.buffer);
  let seed = (0x4165a0 ^ 0x4165bb ^ 0x41662a ^ 0xc71640) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const byteDraws = [0, 0x20, 0x61, 0x62, 0x3d, 0x22, 0x27, 0x66, 0x78,
                     0x3e, 0x100, 0x1ff, 0xffffffff];
  const posDraws = [0, 0x1000, 0x5000, 0x5012, 0xfffffff0, 0xffffffff];
  const slotDraws = [0, 0x1111, 0x1234, 0xb1b6dc, 0xffffffff];
  const headDraws = [0, 0x100, 0x8000, 0xffffffff];
  const ip = SCRATCH + 0x28000;

  for (let k = 0; k < 500; ++k) {
    const e = slotDraws[pick(rnd, slotDraws.length)];
    const f = byteDraws[pick(rnd, byteDraws.length)];
    const ne = posDraws[pick(rnd, posDraws.length)];
    /* The FULL-WORD empty-name arm needs a forced name_end ==
       name_start row; the machine cannot reach it, the law can. */
    let ns = posDraws[pick(rnd, posDraws.length)];
    if (pick(rnd, 8) === 0) ns = ne;
    const w1 = posDraws[pick(rnd, posDraws.length)];
    const eqb = byteDraws[pick(rnd, byteDraws.length)];
    const w2 = posDraws[pick(rnd, posDraws.length)];
    const q = byteDraws[pick(rnd, byteDraws.length)];
    const vs = posDraws[pick(rnd, posDraws.length)];
    const ve = posDraws[pick(rnd, posDraws.length)];
    const eb = byteDraws[pick(rnd, byteDraws.length)];
    const ph = headDraws[pick(rnd, headDraws.length)];
    const pt = posDraws[pick(rnd, posDraws.length)];
    const n = 0x7000 + pick(rnd, 4) * 0x100;
    const np = posDraws[pick(rnd, posDraws.length)];
    const vp = posDraws[pick(rnd, posDraws.length)];
    const cb = byteDraws[pick(rnd, byteDraws.length)];

    /* The scalar laws (wide drives unmasked). */
    eq(wasm.isaac_sfx_xml_attr_cursor_after_eq(w1) >>> 0,
       sfxXmlAttrCursorAfterEq(w1), `cursor_eq ${w1}`);
    eq(wasm.isaac_sfx_xml_attr_value_start(w2) >>> 0,
       sfxXmlAttrValueStart(w2), `valstart ${w2}`);
    eq(wasm.isaac_sfx_xml_attr_cursor_after_value(ve) >>> 0,
       sfxXmlAttrCursorAfterValue(ve), `cursor_val ${ve}`);
    eq(wasm.isaac_sfx_xml_attr_link_first(ph),
       sfxXmlAttrLinkFirst(ph), `linkfirst ${ph}`);
    eq(wasm.isaac_sfx_xml_attr_link_prev(ph, pt) >>> 0,
       sfxXmlAttrLinkPrev(ph, pt), `linkprev ${ph}/${pt}`);
    eq(wasm.isaac_sfx_xml_attr_link_tail_next(ph, n) >>> 0,
       sfxXmlAttrLinkTailNext(ph, n), `tailnext ${ph}/${n}`);
    eq(wasm.isaac_sfx_xml_attr_link_new_head(ph, n) >>> 0,
       sfxXmlAttrLinkNewHead(ph, n), `newhead ${ph}/${n}`);
    eq(wasm.isaac_sfx_xml_attr_nul_addr(np, ne) >>> 0,
       sfxXmlAttrNulAddr(np, ne), `nul ${np}/${ne}`);
    seen("v19Nul", sfxXmlAttrNulAddr(np, ne) === SFX_XML_ATTR_NUL_DEFAULT_VA
      ? 0 : 1);
    seen("v19Cursor", sfxXmlAttrCursorAfterEq(w1) === 0
      || sfxXmlAttrValueStart(w2) === 0
      || sfxXmlAttrCursorAfterValue(ve) === 0 ? 0 : 1);
    countCase();

    /* The composed per-iteration plan. */
    wasm.isaac_sfx_xml_attrs_iter_plan(e, f, ns, ne, w1, eqb, w2, q, vs,
                                       ve, eb, ph, pt, n, np, vp, cb, ip);
    const w = readAttrsIterPlan(view, ip);
    const j = sfxXmlAttrsIterPlan(e, f, ns, ne, w1, eqb, w2, q, vs, ve,
                                  eb, ph, pt, n, np, vp, cb);
    assertPlanEqual(w, j, `attrs iter ${k}`);
    seen("v19IterEntered", w.entered);
    seen("v19IterLink", w.linkFirst);
    seen("v19IterIterate", w.iterate);
    seen("v19IterQuote", w.quoteKind);
    seen("v19IterHost", w.hostCalls);
    seen("v19NameEmpty", w.nameEmpty);
    seen("v19IterSlot", w.errorSlot === SFX_XML_ATTR_ERR_EQ_VA ? 1
      : (w.errorSlot === SFX_XML_ATTR_ERR_VALUE_VA ? 2
         : (w.errorSlot === SFX_XML_ATTR_ERR_NAME_VA ? 3 : 0)));
    countCase();
  }
});



test("executed assertion / case counts", (t) => {
  t.diagnostic(`executed assertions: ${ASSERT_COUNT}`);
  t.diagnostic(`executed differential cases: ${CASE_COUNT}`);
  assert.ok(ASSERT_COUNT > 20000, `expected a large corpus, got ${ASSERT_COUNT}`);
  assert.ok(CASE_COUNT > 1000, `expected many cases, got ${CASE_COUNT}`);
});

/* ---------- v26 (open-bodies): 0xa17f40 / 0xa17ea0 attempt bodies of
   the 0xa178d0 file-open retry gate (wave-18; ABI converges at 26 — the
   sibling v25e did 25→26, v26b declares no second bump). attempt #1
   (0xa17f40) probes the open object's 0x8000-slot table (this+0x108,
   stride 4) keyed on (hash1, hash2) with a 15-bit wrap probe; attempt
   #2 (0xa17ea0) allocates a small object, dispatches vtbl[0x24] and
   keeps-or-destroys on the loader's al. Both write the CALLER's result
   slot only through *out (their own [ebp+8] writes are arg-slot spills:
   0xa17f8a hash1, 0xa1800a alloc1, 0xa17eca alloc2 — NOT the caller
   slot). All byte-ish gates driven WIDE (0x100/0x1ff/0xffffffff). */

test("v26 open-bodies PE truth (native): attempt bodies of the open gate", () => {
  const h = readFileSync(header, "utf8");
  for (const [name, expected] of [
    ["ISAAC_SFX_OPEN_ATTEMPT1_VA_A17F40", 0x00a17f40],
    ["ISAAC_SFX_OPEN_ATTEMPT2_VA_A17EA0", 0x00a17ea0],
    ["ISAAC_SFX_OPEN_ATTEMPT1_HASH1_VA_A159D0", 0x00a159d0],
    ["ISAAC_SFX_OPEN_ATTEMPT1_HASH2_VA_A15AB0", 0x00a15ab0],
    ["ISAAC_SFX_OPEN_ATTEMPT2_LOADER_VA_A524B0", 0x00a524b0],
    ["ISAAC_SFX_OPEN_ATTEMPT2_LOADER_VA_A52540", 0x00a52540],
    ["ISAAC_SFX_OPEN_ATTEMPT2_VTABLE_B9E940", 0x00b9e940],
    ["ISAAC_SFX_OPEN_ATTEMPT1_CTOR_VA_A68A50", 0x00a68a50],
    ["ISAAC_SFX_OPEN_ATTEMPT1_SLOTS_OFF_108", 0x108],
    ["ISAAC_SFX_OPEN_ATTEMPT_PROBE_MASK", 0x7fff],
    ["ISAAC_SFX_OPEN_ATTEMPT_PROBE_LIMIT", 0x8000],
    ["ISAAC_SFX_OPEN_ATTEMPT1_ALLOC_SIZE", 0xc2c],
    ["ISAAC_SFX_OPEN_ATTEMPT2_ALLOC_SIZE", 0x10],
    ["ISAAC_SFX_OPEN_OUT_NONE", 0xffffffff],
  ]) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    countCase();
  }
  for (const [jsName, expected] of [
    [SFX_OPEN_ATTEMPT1_VA_A17F40, 0x00a17f40],
    [SFX_OPEN_ATTEMPT2_VA_A17EA0, 0x00a17ea0],
    [SFX_OPEN_ATTEMPT_PROBE_MASK, 0x7fff],
    [SFX_OPEN_ATTEMPT_PROBE_LIMIT, 0x8000],
    [SFX_OPEN_ATTEMPT2_LOADER_VA_A52540, 0x00a52540],
    [SFX_OPEN_ATTEMPT2_VTABLE_B9E940, 0x00b9e940],
    [SFX_OPEN_OUT_NONE, 0xffffffff],
  ]) {
    eq(jsName, expected, `js pin ${jsName}`);
    countCase();
  }
});

test("Wasm matches JS: v26 open-bodies attempt-1 probe/match/found laws", () => {
  /* probe_start: 0xa17f8d `and esi,0x7fff` — FULL-WORD mask;
     0x8000 -> 0 (15-bit), 0xffffffff -> 0x7fff. */
  for (const [hash1, want] of [
    [0, 0], [1, 1], [0x7fff, 0x7fff], [0x8000, 0],
    [0xffff, 0x7fff], [0xffffffff, 0x7fff],
  ]) {
    eq(wasm.isaac_sfx_open_attempt1_probe_start(hash1) >>> 0, want >>> 0,
       `probe_start hash1=0x${(hash1 >>> 0).toString(16)}`);
    eq(sfxOpenAttempt1ProbeStart(hash1) >>> 0, want >>> 0, `js probe_start`);
    seen("v26OpenProbeStart", sfxOpenAttempt1ProbeStart(hash1));
    countCase();
  }

  /* probe_next: 0xa17fcf/d0 `inc esi ; and esi,0x7fff` — wrap at
     0x7fff back to 0; FULL-WORD inc then mask. */
  for (const [idx, want] of [
    [0, 1], [0x7ffe, 0x7fff], [0x7fff, 0], [0x8000, 1],
    [0xffffffff, 0], [0x100, 0x101],
  ]) {
    eq(wasm.isaac_sfx_open_attempt1_probe_next(idx) >>> 0, want >>> 0,
       `probe_next idx=0x${(idx >>> 0).toString(16)}`);
    eq(sfxOpenAttempt1ProbeNext(idx) >>> 0, want >>> 0, `js probe_next`);
    seen("v26OpenProbeNext", sfxOpenAttempt1ProbeNext(idx));
    countCase();
  }

  /* probe_done: 0xa17fc5/0xa17fee `cmp counter,0x8000 ; jae` — UNSIGNED
     bound; 0xffffffff >= 0x8000 -> 1 (a signed jge would read 0xffffffff
     as -1 and NOT stop). */
  for (const [counter, want] of [
    [0, 0], [1, 0], [0x7fff, 0], [0x8000, 1], [0x8001, 1],
    [0xffffffff, 1],
  ]) {
    eq(wasm.isaac_sfx_open_attempt1_probe_done(counter), want,
       `probe_done counter=0x${(counter >>> 0).toString(16)}`);
    eq(sfxOpenAttempt1ProbeDone(counter), want, `js probe_done`);
    seen("v26OpenProbeDone", sfxOpenAttempt1ProbeDone(counter));
    countCase();
  }

  /* slot_match: 0xa17fb8/0xa17fbd — FULL-WORD pair: key1==hash1 AND
     key2==hash2; single-key fallbacks must miss. */
  for (const [k1, k2, h1, h2, want] of [
    [1, 2, 1, 2, 1],
    [1, 2, 1, 3, 0],
    [1, 2, 3, 2, 0],
    [0x100, 2, 0x100, 2, 1],
    [0x100, 2, 0x100, 3, 0],
    [0xffffffff, 0xffffffff, 0xffffffff, 0xffffffff, 1],
    [0xffffffff, 0, 0xffffffff, 0, 1],
  ]) {
    eq(wasm.isaac_sfx_open_attempt1_slot_match(k1, k2, h1, h2), want,
       `match k1=0x${(k1 >>> 0).toString(16)} k2=0x${(k2 >>> 0).toString(16)}`);
    eq(sfxOpenAttempt1SlotMatch(k1, k2, h1, h2), want, `js match`);
    seen("v26OpenMatch", sfxOpenAttempt1SlotMatch(k1, k2, h1, h2));
    countCase();
  }

  /* found: 0xa17fe1 (slot nonzero) + 0xa17fee (counter < 0x8000, UNSIGNED)
     — both must hold. */
  for (const [slot, counter, want] of [
    [0, 5, 0],
    [1, 5, 1],
    [1, 0x7fff, 1],
    [1, 0x8000, 0],
    [1, 0xffffffff, 0],
    [0x100, 0x7fff, 1],
  ]) {
    eq(wasm.isaac_sfx_open_attempt1_found(slot, counter), want,
       `found slot=0x${(slot >>> 0).toString(16)} c=0x${(counter >>> 0).toString(16)}`);
    eq(sfxOpenAttempt1Found(slot, counter), want, `js found`);
    seen("v26OpenFound", sfxOpenAttempt1Found(slot, counter));
    countCase();
  }

  /* ret: al=1 (0xa18027/0xa18041) iff name_ok && found. */
  for (const [nok, found, want] of [[0, 1, 0], [1, 0, 0], [1, 1, 1]]) {
    eq(wasm.isaac_sfx_open_attempt1_ret(nok, found), want, `ret1 ${nok}/${found}`);
    eq(sfxOpenAttempt1Ret(nok, found), want, `js ret1`);
    seen("v26OpenRet", sfxOpenAttempt1Ret(nok, found));
    countCase();
  }

  /* out_plan (attempt-1 *out write law): NONE when name fail / miss /
     out==0; else alloc_ok ? ctor_result : 0. out is FULL-WORD — a
     0x100 out pointer must write. NONE (0xffffffff) = no write (caller
     slot stays 0 from the pre-reset -> retry gate fires). */
  for (const [nok, found, out, allocOk, ctor, want] of [
    [0, 1, 1, 1, 5, SFX_OPEN_OUT_NONE],
    [1, 0, 1, 1, 5, SFX_OPEN_OUT_NONE],
    [1, 1, 0, 1, 5, SFX_OPEN_OUT_NONE],
    [1, 1, 1, 0, 5, 0],
    [1, 1, 1, 1, 5, 5],
    [1, 1, 1, 1, 0xffffffff, 0xffffffff],
    [1, 1, 0x100, 1, 7, 7],
    [1, 1, 0xffffffff, 1, 7, 7],
  ]) {
    eq(wasm.isaac_sfx_open_attempt1_out_plan(nok, found, out, allocOk,
                                             ctor) >>> 0, want >>> 0,
       `out_plan1 ${nok}/${found}/${out}/${allocOk}/0x${(ctor >>> 0).toString(16)}`);
    eq(sfxOpenAttempt1OutPlan(nok, found, out, allocOk, ctor) >>> 0,
       want >>> 0, `js out_plan1`);
    seen("v26OpenOutPlan", sfxOpenAttempt1OutPlan(nok, found, out, allocOk,
                                                  ctor));
    countCase();
  }

  /* Cross-pin: the v25f retry gate consumes the caller slot — attempt-1
     leaves the slot writable ONLY via *out; NONE/no-alloc cases leave 0
     and MUST retry, the written-nonzero case must NOT retry. */
  const retryPin = [
    [1, 1, 1, 1, 5, 0],   /* written 5 -> no retry */
    [1, 1, 1, 0, 5, 1],   /* alloc fail -> *out=0 -> retry */
    [1, 1, 0, 1, 5, 1],   /* out==0 host arm? (boxed: NONE -> slot 0) */
    [1, 0, 1, 1, 5, 1],   /* miss -> NONE -> retry */
  ];
  for (const [nok, found, out, allocOk, ctor, want] of retryPin) {
    const slot = sfxOpenAttempt1OutPlan(nok, found, out, allocOk, ctor);
    const retry = slot === SFX_OPEN_OUT_NONE || slot === 0 ? 1 : 0;
    eq(wasm.isaac_sfx_file_open_retry_gate(
         slot === SFX_OPEN_OUT_NONE ? 0 : slot), want,
       `retry-pin slot=0x${(slot >>> 0).toString(16)}`);
    eq(retry, want, `js retry-pin`);
    countCase();
  }
});

test("Wasm matches JS: v26 open-bodies attempt-2 gates/keep/out laws", () => {
  /* out_gate: 0xa17eba `test ebx,ebx ; je host-arm` — FULL-WORD. */
  for (const [out, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_open_attempt2_out_gate(out), want,
       `out_gate2 out=0x${(out >>> 0).toString(16)}`);
    eq(sfxOpenAttempt2OutGate(out), want, `js out_gate2`);
    seen("v26OpenOutGate", sfxOpenAttempt2OutGate(out));
    countCase();
  }

  /* alloc_gate: 0xa17ecd `test esi,esi ; je` — FULL-WORD. */
  for (const [alloc, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_open_attempt2_alloc_gate(alloc), want,
       `alloc_gate2 alloc=0x${(alloc >>> 0).toString(16)}`);
    eq(sfxOpenAttempt2AllocGate(alloc), want, `js alloc_gate2`);
    seen("v26OpenAllocGate", sfxOpenAttempt2AllocGate(alloc));
    countCase();
  }

  /* dispatch_direct: 0xa17ef8 `cmp fn,0xa52540 ; jne indirect` — the
     vtbl[0x24] pointer equality to the 0xa52540 constant. */
  for (const [fn, want] of [
    [0, 0], [0xa52540, 1], [0xa52541, 0], [0xa5253f, 0],
    [0xffffffff, 0],
  ]) {
    eq(wasm.isaac_sfx_open_attempt2_dispatch_direct(fn), want,
       `dispatch fn=0x${(fn >>> 0).toString(16)}`);
    eq(sfxOpenAttempt2DispatchDirect(fn), want, `js dispatch`);
    seen("v26OpenDispatch", sfxOpenAttempt2DispatchDirect(fn));
    countCase();
  }

  /* keep: 0xa17f08 `test al,al ; jne keep` — LOW-BYTE al test:
     0x100 must NOT keep, 0x1ff MUST (al=0xff), 0xffffffff MUST. */
  for (const [res, want] of [
    [0, 0], [1, 1], [0xff, 1], [0x100, 0], [0x1ff, 1],
    [0xffffffff, 1],
  ]) {
    eq(wasm.isaac_sfx_open_attempt2_keep(res), want,
       `keep res=0x${(res >>> 0).toString(16)}`);
    eq(sfxOpenAttempt2Keep(res), want, `js keep`);
    seen("v26OpenKeep", sfxOpenAttempt2Keep(res));
    countCase();
  }

  /* ret2: 0xa17f1a `setne al` = alloc_ok && keep (obj != NULL). */
  for (const [allocOk, keep, want] of [[0, 1, 0], [1, 0, 0], [1, 1, 1]]) {
    eq(wasm.isaac_sfx_open_attempt2_ret(allocOk, keep), want,
       `ret2 ${allocOk}/${keep}`);
    eq(sfxOpenAttempt2Ret(allocOk, keep), want, `js ret2`);
    seen("v26OpenRet2", sfxOpenAttempt2Ret(allocOk, keep));
    countCase();
  }

  /* out_plan2 (attempt-2 *out write law): NONE when name fail or out==0
     (host arms); else kept ? alloc_ptr : 0. */
  for (const [nok, out, allocOk, keep, allocPtr, want] of [
    [0, 1, 1, 1, 0x44, SFX_OPEN_OUT_NONE],
    [1, 0, 1, 1, 0x44, SFX_OPEN_OUT_NONE],
    [1, 1, 1, 1, 0x44, 0x44],
    [1, 1, 1, 0, 0x44, 0],
    [1, 1, 0, 1, 0x44, 0],
    [1, 1, 1, 1, 0, 0],
    [1, 0x100, 1, 1, 0x44, 0x44],
    [1, 0xffffffff, 1, 1, 0xffffffff, 0xffffffff],
  ]) {
    eq(wasm.isaac_sfx_open_attempt2_out_plan(nok, out, allocOk, keep,
                                             allocPtr) >>> 0, want >>> 0,
       `out_plan2 ${nok}/${out}/${allocOk}/${keep}/0x${(allocPtr >>> 0).toString(16)}`);
    eq(sfxOpenAttempt2OutPlan(nok, out, allocOk, keep, allocPtr) >>> 0,
       want >>> 0, `js out_plan2`);
    seen("v26OpenOutPlan2", sfxOpenAttempt2OutPlan(nok, out, allocOk, keep,
                                                   allocPtr));
    countCase();
  }
});

/* ---------- v27: 0xa17180 build body of the 0xa178d0 file-open (wave-19
   handoff; ABI 26 -> 27). The body builds the canonical key handle the
   open passes to attempt #1/#2; 56 direct rel32 callers. Pure decision
   layer: ABS arm iff name!=0 (FULL-WORD 0xa171a8) && strlen>2 (UNSIGNED
   jbe 0xa171ba) && name[1]==':' (BYTE 0xa171bf) && name[2] in {'\\','/'}
   (BYTE 0xa171c8/0xa171cc); ABS tail: validator al keep (LOW-BYTE
   0xa171e9), return = keep ? s1 : 0 (0xa1720a), dispose edge iff
   !keep && s1!=0 (FULL-WORD 0xa171ed); FAIL arm: resolve-result gate
   (FULL-WORD 0xa17230), variant select (BYTE flag 0xa17238: 0 -> A),
   variant-A dispose edge (FULL-WORD 0xa17279). Host: a5a7a0/a524b0/
   a16c60/a68790/a648b0 + inline strlen; every final return value is a
   HOST canonicalizer result. Byte-ish gates driven WIDE (0x100/0x1ff/
   0xffffffff). */

test("v27 PE truth (native): build-body consts + dead-this census pins", () => {
  const h = readFileSync(header, "utf8");
  for (const [name, expected] of [
    ["ISAAC_SFX_BUILD_VA_A17180", 0x00a17180],
    ["ISAAC_SFX_BUILD_CHAR_COLON", 0x3a],
    ["ISAAC_SFX_BUILD_CHAR_BACKSLASH", 0x5c],
    ["ISAAC_SFX_BUILD_CHAR_SLASH", 0x2f],
    ["ISAAC_SFX_BUILD_MIN_ABS_LEN", 2],
    ["ISAAC_SFX_BUILD_CANON_VA_A5A7A0", 0x00a5a7a0],
    ["ISAAC_SFX_BUILD_RESOLVE_VA_A16C60", 0x00a16c60],
    ["ISAAC_SFX_BUILD_JOIN_VA_A68790", 0x00a68790],
  ]) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    countCase();
  }
  for (const [jsName, expected] of [
    [SFX_BUILD_VA_A17180, 0x00a17180],
    [SFX_BUILD_CHAR_COLON, 0x3a],
    [SFX_BUILD_CHAR_BACKSLASH, 0x5c],
    [SFX_BUILD_CHAR_SLASH, 0x2f],
    [SFX_BUILD_MIN_ABS_LEN, 2],
    [SFX_BUILD_CANON_VA_A5A7A0, 0x00a5a7a0],
    [SFX_BUILD_RESOLVE_VA_A16C60, 0x00a16c60],
    [SFX_BUILD_JOIN_VA_A68790, 0x00a68790],
  ]) {
    eq(jsName, expected, `js pin ${jsName}`);
    countCase();
  }
});

test("Wasm matches JS: v27 build-body abs-gate/keep/out/dispose laws", () => {
  /* abs_gate: 0xa171a8 (FULL-WORD name) + 0xa171ba (UNSIGNED jbe
     len<=2) + 0xa171bf (BYTE c1==':') + 0xa171c8/cc (BYTE c2 in
     {'\\','/'}). All four must hold; len is UNSIGNED (0xffffffff >
     2 must ABS), c1/c2 are BYTE-masked (0x13a must read 0x3a). */
  for (const [nz, len, c1, c2, want] of [
    [1, 3, 0x3a, 0x5c, 1],        /* "X:\" -> ABS */
    [1, 3, 0x3a, 0x2f, 1],        /* "X:/" -> ABS */
    [1, 4, 0x3a, 0x5c, 1],        /* longer abs */
    [0, 3, 0x3a, 0x5c, 0],        /* name NULL -> FAIL */
    [1, 2, 0x3a, 0x5c, 0],        /* len==2 (jbe) -> FAIL */
    [1, 1, 0x3a, 0x5c, 0],        /* len==1 -> FAIL */
    [1, 0, 0x3a, 0x5c, 0],        /* len==0 -> FAIL */
    [1, 3, 0x2f, 0x5c, 0],        /* c1 != ':' -> FAIL */
    [1, 3, 0x3a, 0x3a, 0],        /* c2 == ':' -> FAIL */
    [1, 3, 0x3a, 0x2e, 0],        /* c2 == '.' -> FAIL */
    [1, 0xffffffff, 0x3a, 0x5c, 1], /* UNSIGNED len (signed would FAIL) */
    [1, 0x100, 0x3a, 0x5c, 1],    /* wide len */
    [1, 3, 0x13a, 0x5c, 1],       /* c1 byte-masked */
    [1, 3, 0x3a, 0x15c, 1],       /* c2 byte-masked */
    [1, 3, 0x3a, 0x1ff, 0],       /* 0xff is not slash/colon */
    [1, 3, 0x1ff, 0x5c, 0],       /* 0xff is not colon */
  ]) {
    eq(wasm.isaac_sfx_build_abs_gate(nz, len, c1, c2), want,
       `abs_gate ${nz}/0x${(len >>> 0).toString(16)}/0x${(c1 >>> 0).toString(16)}/0x${(c2 >>> 0).toString(16)}`);
    eq(sfxBuildAbsGate(nz, len, c1, c2), want, `js abs_gate`);
    seen("v27BuildAbs", sfxBuildAbsGate(nz, len, c1, c2));
    countCase();
  }

  /* abs_keep: 0xa171e9 `test al,al ; jne RET` — LOW-BYTE: 0x100 must
     NOT keep, 0x1ff MUST (al=0xff), 0xffffffff MUST. */
  for (const [ok, want] of [
    [0, 0], [1, 1], [0xff, 1], [0x100, 0], [0x1ff, 1],
    [0xffffffff, 1],
  ]) {
    eq(wasm.isaac_sfx_build_abs_keep(ok), want,
       `abs_keep ok=0x${(ok >>> 0).toString(16)}`);
    eq(sfxBuildAbsKeep(ok), want, `js abs_keep`);
    seen("v27BuildKeep", sfxBuildAbsKeep(ok));
    countCase();
  }

  /* abs_out: 0xa1720a `mov eax,esi` — keep ? s1 : 0. s1 is a FULL-WORD
     handle value (0xffffffff must pass through when kept). */
  for (const [keep, s1, want] of [
    [0, 5, 0],
    [1, 5, 5],
    [1, 0, 0],
    [0, 0, 0],
    [1, 0xffffffff, 0xffffffff],
    [0, 0xffffffff, 0],
  ]) {
    eq(wasm.isaac_sfx_build_abs_out(keep, s1) >>> 0, want >>> 0,
       `abs_out ${keep}/0x${(s1 >>> 0).toString(16)}`);
    eq(sfxBuildAbsOut(keep, s1) >>> 0, want >>> 0, `js abs_out`);
    seen("v27BuildOut", sfxBuildAbsOut(keep, s1));
    countCase();
  }

  /* abs_dispose: 0xa171ed `test esi,esi ; je RET` (FULL-WORD s1) with
     keep==0 — dispose edge fires iff !keep && s1 != 0. */
  for (const [keep, s1, want] of [
    [0, 0, 0],
    [0, 5, 1],
    [0, 0x100, 1],
    [1, 5, 0],
    [1, 0, 0],
    [1, 0xffffffff, 0],
    [0, 0xffffffff, 1],
  ]) {
    eq(wasm.isaac_sfx_build_abs_dispose(keep, s1), want,
       `abs_dispose ${keep}/0x${(s1 >>> 0).toString(16)}`);
    eq(sfxBuildAbsDispose(keep, s1), want, `js abs_dispose`);
    seen("v27BuildDispose", sfxBuildAbsDispose(keep, s1));
    countCase();
  }

  /* Cross-pin: the ABS arm returns esi (s1) iff NO dispose edge fired —
     the dispose arm xors esi to 0 (0xa17208). out == s1 EXACTLY when
     disp == 0; a dispose always folds the return to 0. */
  for (const [keep, s1] of [
    [0, 5], [1, 5], [1, 0], [0, 0x100], [0, 0], [1, 0xffffffff],
  ]) {
    const disp = sfxBuildAbsDispose(keep, s1);
    const out = sfxBuildAbsOut(keep, s1);
    eq(out === s1 ? 1 : 0, disp === 0 ? 1 : 0,
       `abs out==s1 iff !disp ${keep}/0x${(s1 >>> 0).toString(16)}`);
    eq(disp === 1 ? out : 0, 0, `abs dispose folds return ${keep}`);
    countCase();
  }
});

test("Wasm matches JS: v27 build-body resolve/variant/dispose gates", () => {
  /* resolve_gate: 0xa17230 `test edi,edi ; je RET0` — FULL-WORD gate
     on the FAIL-arm 0xa16c60 result. */
  for (const [r, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_build_resolve_gate(r), want,
       `resolve_gate r=0x${(r >>> 0).toString(16)}`);
    eq(sfxBuildResolveGate(r), want, `js resolve_gate`);
    seen("v27BuildResolve", sfxBuildResolveGate(r));
    countCase();
  }

  /* variant_select: 0xa17238 `cmp byte[ebp+0xb],0 ; je A` — LOW-BYTE:
     flag byte 0 -> VARIANT A; 0x100 must be A (low byte 0), 0x1ff is B
     (low byte 0xff). */
  for (const [flag, want] of [
    [0, 1], [1, 0], [0xff, 0], [0x100, 1], [0x1ff, 0],
    [0xffffffff, 0],
  ]) {
    eq(wasm.isaac_sfx_build_variant_select(flag), want,
       `variant flag=0x${(flag >>> 0).toString(16)}`);
    eq(sfxBuildVariantSelect(flag), want, `js variant`);
    seen("v27BuildVariant", sfxBuildVariantSelect(flag));
    countCase();
  }

  /* variant_a_dispose: 0xa17279 `test esi,esi ; je skip` — FULL-WORD
     s2 gate on the variant-A dispose edge. */
  for (const [s2, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_build_variant_a_dispose(s2), want,
       `varA_disp s2=0x${(s2 >>> 0).toString(16)}`);
    eq(sfxBuildVariantADispose(s2), want, `js varA_disp`);
    seen("v27BuildVarADisp", sfxBuildVariantADispose(s2));
    countCase();
  }

  /* Cross-pin: the abs-gate AND the resolve gate are independent —
     abs==1 selects the ABS arm (no resolve); abs==0 selects the FAIL
     arm where the resolve gate decides between RET 0 and the variant
     select. The machine's arm select is exactly abs_gate. */
  eq(sfxBuildAbsGate(1, 3, 0x3a, 0x5c), 1, `abs==1 -> ABS arm`);
  eq(sfxBuildAbsGate(1, 2, 0x3a, 0x5c), 0, `abs==0 -> FAIL arm`);
  eq(sfxBuildAbsGate(1, 3, 0x3a, 0x5c) === 1 &&
       sfxBuildAbsDispose(1, 0x44) === 0 ? 1 : 0, 1,
     `ABS arm never resolves (host canon result kept as-is)`);
  countCase();
});

/* ---------- v28: 0xa159d0 / 0xa15ab0 string-hash pair (wave-20;
   ABI 27 -> 28). The file-open canonical-key hashes: hash #1
   (0xa159d0, djb2-style h = h*33 + norm(byte), 23 direct rel32
   callers) and hash #2 (0xa15ab0, FNV-1a h = (h ^ norm(byte)) *
   0x1000193, 2 callers). Both bodies are self-contained folds (0 E8 /
   0 indirect / 0 mem-stores); the string POINTER/BYTES are the host
   input stream, the fold arithmetic lands. Shared per-byte layer:
   norm (A..Z -> a..z UNSIGNED (b-0x41)>0x19, then 0x5c -> 0x2f) +
   loop-continue (LOW-BYTE byte!=0); per-hash layer: FULL-WORD null
   gate (s==0 -> 0), seed init, fold step. Consumers unchanged: v26
   probe_start (hash1 & 0x7fff) / slot_match (hash1+hash2 pair).
   Byte-ish gates driven WIDE (0x100/0x1ff/0xffffffff). */

/* Independent PE-truth helper: the byte normalize transcribed directly
   from 0xa159f7..0xa15a11 / 0xa15ad7..0xa15aee (8-bit wraps, UNSIGNED
   above test, backslash->slash). NOT derived from the model. */
const expectedNorm = (b) => {
  const x = b & 0xff;
  const d = (x - 0x41) & 0xff;
  const lo = (x + 0x20) & 0xff;
  let n = d > 0x19 ? x : lo;
  if (n === 0x5c) n = 0x2f;
  return n;
};

function longPathBytes() {
  return "C:\\Program Files (x86)\\Steam\\steamapps\\common\\The Binding of Isaac Rebirth\\resources\\sounds"
    .split("").map((ch) => ch.charCodeAt(0));
}

/* The fold contract: h = init(); for each byte c (until continue(c)
   is 0): h = step(h, c). The expected fold values below were computed
   by a per-instruction PE simulator over the disassembly dump (not
   from these laws). */
function foldHash1(bytes) {
  let h = sfxHash1Init();
  for (const c of bytes) {
    if (sfxHashByteContinue(c) === 0) break;
    h = sfxHash1Step(h, c);
  }
  return h >>> 0;
}
function foldHash2(bytes) {
  let h = sfxHash2Init();
  for (const c of bytes) {
    if (sfxHashByteContinue(c) === 0) break;
    h = sfxHash2Step(h, c);
  }
  return h >>> 0;
}
function wasmFoldHash1(bytes) {
  let h = wasm.isaac_sfx_hash1_init() >>> 0;
  for (const c of bytes) {
    if (wasm.isaac_sfx_hash_byte_continue(c) === 0) break;
    h = wasm.isaac_sfx_hash1_step(h, c) >>> 0;
  }
  return h >>> 0;
}
function wasmFoldHash2(bytes) {
  let h = wasm.isaac_sfx_hash2_init() >>> 0;
  for (const c of bytes) {
    if (wasm.isaac_sfx_hash_byte_continue(c) === 0) break;
    h = wasm.isaac_sfx_hash2_step(h, c) >>> 0;
  }
  return h >>> 0;
}

test("v28 PE truth (native): string-hash consts + caller census pins", () => {
  const h = readFileSync(header, "utf8");
  for (const [name, expected] of [
    ["ISAAC_SFX_HASH1_VA_A159D0", 0x00a159d0],
    ["ISAAC_SFX_HASH2_VA_A15AB0", 0x00a15ab0],
    ["ISAAC_SFX_HASH1_SEED", 0x1505],
    ["ISAAC_SFX_HASH2_SEED", 0x5bb2220e],
    ["ISAAC_SFX_HASH2_PRIME", 0x1000193],
    ["ISAAC_SFX_HASH_NORM_A", 0x41],
    ["ISAAC_SFX_HASH_NORM_LOWER_DELTA", 0x19],
    ["ISAAC_SFX_HASH_NORM_CASE_SHIFT", 0x20],
    ["ISAAC_SFX_HASH_NORM_BACKSLASH", 0x5c],
    ["ISAAC_SFX_HASH_NORM_SLASH", 0x2f],
    ["ISAAC_SFX_HASH1_CALLER_COUNT", 23],
    ["ISAAC_SFX_HASH2_CALLER_COUNT", 2],
  ]) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    countCase();
  }
  for (const [jsName, expected] of [
    [SFX_HASH1_VA_A159D0, 0x00a159d0],
    [SFX_HASH2_VA_A15AB0, 0x00a15ab0],
    [SFX_HASH1_SEED, 0x1505],
    [SFX_HASH2_SEED, 0x5bb2220e],
    [SFX_HASH2_PRIME, 0x1000193],
    [SFX_HASH_NORM_A, 0x41],
    [SFX_HASH_NORM_LOWER_DELTA, 0x19],
    [SFX_HASH_NORM_CASE_SHIFT, 0x20],
    [SFX_HASH_NORM_BACKSLASH, 0x5c],
    [SFX_HASH_NORM_SLASH, 0x2f],
    [SFX_HASH1_CALLER_COUNT, 23],
    [SFX_HASH2_CALLER_COUNT, 2],
  ]) {
    eq(jsName, expected, `js pin ${jsName}`);
    countCase();
  }
  /* Census re-derived by raw .text `e8 rel32` byte scan (2026-08-18):
     the C11 corrected count (23) stands; the four resync sites
     0x40e567/0x40ee12/0xa12c57/0xa16313 are byte-verified. */
  eq(SFX_HASH1_CALLER_COUNT, 23, "hash1 census (C11 corrected count)");
  eq(SFX_HASH2_CALLER_COUNT, 2, "hash2 census");
  countCase();
});

test("Wasm matches JS: v28 hash byte norm + loop-continue gates", () => {
  /* norm: 0xa159f7..0xa15a11 (hash1) == 0xa15ad7..0xa15aee (hash2) —
     BYTE in/out. Full 0..255 sweep: A..Z collapse into a..z and 0x5c
     collapses into 0x2f (229 distinct outputs). */
  for (let b = 0; b < 256; ++b) {
    eq(wasm.isaac_sfx_hash_byte_norm(b), expectedNorm(b), `norm ${b}`);
    eq(sfxHashByteNorm(b), expectedNorm(b), `js norm ${b}`);
    seen("v28Norm", sfxHashByteNorm(b));
    countCase();
  }
  for (const [c, want] of [
    [0x100, 0x00], [0x13a, 0x3a], [0x141, 0x61], [0x15a, 0x7a],
    [0x15c, 0x2f], [0x1ff, 0xff], [0xffffffff, 0xff],
  ]) {
    eq(wasm.isaac_sfx_hash_byte_norm(c), want,
       `norm wide 0x${(c >>> 0).toString(16)}`);
    eq(sfxHashByteNorm(c), want, `js norm wide`);
    seen("v28NormWide", sfxHashByteNorm(c));
    countCase();
  }

  /* continue: `test ch/ch,ch/ch ; jne` — LOW-BYTE: 0x100 must NOT
     continue (low byte 0), 0x1ff MUST (low byte 0xff). */
  for (const [c, want] of [
    [0, 0], [1, 1], [0xff, 1], [0x100, 0], [0x1ff, 1],
    [0xffffffff, 1], [0x80, 1],
  ]) {
    eq(wasm.isaac_sfx_hash_byte_continue(c), want,
       `continue 0x${(c >>> 0).toString(16)}`);
    eq(sfxHashByteContinue(c), want, `js continue`);
    seen("v28Cont", sfxHashByteContinue(c));
    countCase();
  }
});

test("Wasm matches JS: v28 hash1 (0xa159d0) djb2 fold laws", () => {
  /* null gate: 0xa159d5 `test esi,esi ; jne body` — FULL-WORD. */
  for (const [s, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_hash1_null_gate(s), want,
       `h1_null 0x${(s >>> 0).toString(16)}`);
    eq(sfxHash1NullGate(s), want, `js h1_null`);
    seen("v28H1Null", sfxHash1NullGate(s));
    countCase();
  }

  /* step: 0xa15a14..0xa15a1c — h*33 + norm (mod 2^32). Wide bytes
     read their low byte (0x100 -> 0x00, 0x1ff -> 0xff). */
  for (const [h, c] of [
    [0x1505, 0x00], [0x1505, 0x41], [0x1505, 0x5a], [0x1505, 0x5c],
    [0x1505, 0x2f], [0x1505, 0x61], [0x1505, 0x7a], [0x1505, 0xff],
    [0x1505, 0x100], [0x1505, 0x1ff], [0x1505, 0xffffffff],
    [0xffffffff, 0x61], [0x7fffffff, 0x41],
  ]) {
    const want = (Math.imul(h >>> 0, 33) + expectedNorm(c)) >>> 0;
    eq(wasm.isaac_sfx_hash1_step(h, c) >>> 0, want >>> 0,
       `h1_step 0x${(h >>> 0).toString(16)}/0x${(c >>> 0).toString(16)}`);
    eq(sfxHash1Step(h, c), want, `js h1_step`);
    seen("v28H1Step", sfxHash1Step(h, c));
    countCase();
  }

  /* fold: machine-derived rows (per-instruction PE simulator). */
  const rows = [
    [[], 0x00001505],
    [[0x41], 0x0002b606],          /* "A" */
    [[0x61], 0x0002b606],          /* "a" — case-folded */
    [[0x5c], 0x0002b5d4],          /* "\" — backslash-folded */
    [[0x2f], 0x0002b5d4],          /* "/" */
    [[0x66, 0x6f, 0x6f], 0x0b887389],   /* "foo" */
    [[0x46, 0x4f, 0x4f], 0x0b887389],   /* "FOO" */
    [[0x41, 0x62, 0x5c], 0x0b885c57],   /* "Ab\" */
    [[0x43, 0x3a, 0x5c, 0x55, 0x73, 0x65, 0x72, 0x73, 0x5c, 0x4c, 0x75, 0x63, 0x61],
     0x6bd88af7],                       /* "C:\Users\Luca" */
    [[0x49, 0x53, 0x41, 0x41, 0x43], 0x0fabc626], /* "ISAAC" */
    [[0xff, 0x80], 0x00598ba4],
    [longPathBytes(), 0x223095f7],
  ];
  for (const [bytes, want] of rows) {
    eq(foldHash1(bytes), want >>> 0, `h1 fold ${JSON.stringify(bytes)}`);
    eq(wasmFoldHash1(bytes), want >>> 0, `wasm h1 fold`);
    eq(foldHash1(bytes), wasmFoldHash1(bytes), `h1 fold wasm==js`);
    seen("v28H1Fold", foldHash1(bytes));
    countCase();
  }

  /* Cross-pins: case fold + backslash fold equality, hash resolution,
     and the v26 probe-start consumer fed by the landed fold. */
  eq(foldHash1([0x41]), foldHash1([0x61]), "h1 case fold");
  eq(foldHash1([0x5c]), foldHash1([0x2f]), "h1 backslash fold");
  eq(foldHash1([0x61]) === foldHash1([0x62]) ? 0 : 1, 1, "h1 distinguishes");
  eq(sfxOpenAttempt1ProbeStart(foldHash1([0x66, 0x6f, 0x6f])), 0x7389,
     'probe_start(h1("foo")) == 0x7389 (0x0b887389 & 0x7fff)');
  countCase();
});

test("Wasm matches JS: v28 hash2 (0xa15ab0) FNV-1a fold laws", () => {
  /* null gate: 0xa15ab2 `test ecx,ecx ; jne body` — FULL-WORD. */
  for (const [s, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_hash2_null_gate(s), want,
       `h2_null 0x${(s >>> 0).toString(16)}`);
    eq(sfxHash2NullGate(s), want, `js h2_null`);
    seen("v28H2Null", sfxHash2NullGate(s));
    countCase();
  }

  /* step: 0xa15af4..0xa15af6 — (h ^ norm) * 0x1000193 (mod 2^32). */
  for (const [h, c] of [
    [0x5bb2220e, 0x41], [0x5bb2220e, 0x5a], [0x5bb2220e, 0x5c],
    [0x5bb2220e, 0x2f], [0x5bb2220e, 0x61], [0x5bb2220e, 0x00],
    [0x5bb2220e, 0xff], [0x5bb2220e, 0x100], [0x5bb2220e, 0x1ff],
    [0x5bb2220e, 0xffffffff], [0xffffffff, 0x61], [0, 0x41],
  ]) {
    const want = Math.imul(h >>> 0 ^ expectedNorm(c), 0x1000193) >>> 0;
    eq(wasm.isaac_sfx_hash2_step(h, c) >>> 0, want >>> 0,
       `h2_step 0x${(h >>> 0).toString(16)}/0x${(c >>> 0).toString(16)}`);
    eq(sfxHash2Step(h, c), want, `js h2_step`);
    seen("v28H2Step", sfxHash2Step(h, c));
    countCase();
  }

  /* fold: machine-derived rows (per-instruction PE simulator). */
  const rows = [
    [[], 0x5bb2220e],
    [[0x41], 0xc86c34bd],          /* "A" */
    [[0x61], 0xc86c34bd],          /* "a" — case-folded */
    [[0x5c], 0x7a6bb9f3],          /* "\" */
    [[0x66, 0x6f, 0x6f], 0xc3fb0fee],   /* "foo" */
    [[0x46, 0x4f, 0x4f], 0xc3fb0fee],   /* "FOO" */
    [[0x41, 0x62, 0x5c], 0x5e521686],   /* "Ab\" */
    [[0x43, 0x3a, 0x5c, 0x55, 0x73, 0x65, 0x72, 0x73, 0x5c, 0x4c, 0x75, 0x63, 0x61],
     0x4276416e],                       /* "C:\Users\Luca" */
    [[0x49, 0x53, 0x41, 0x41, 0x43], 0xd994bd71], /* "ISAAC" */
    [[0x5a], 0xcd6c3c9c],          /* "Z" */
    [[0x5c, 0x5c], 0x93959554],    /* "\\" */
    [[0xff, 0x80], 0x0c99f859],
  ];
  for (const [bytes, want] of rows) {
    eq(foldHash2(bytes), want >>> 0, `h2 fold ${JSON.stringify(bytes)}`);
    eq(wasmFoldHash2(bytes), want >>> 0, `wasm h2 fold`);
    eq(foldHash2(bytes), wasmFoldHash2(bytes), `h2 fold wasm==js`);
    seen("v28H2Fold", foldHash2(bytes));
    countCase();
  }

  /* Cross-pins: case fold, stream independence, and the v26
     slot_match consumer fed by both landed folds. */
  eq(foldHash2([0x41]), foldHash2([0x61]), "h2 case fold");
  eq(foldHash2([0x41]) === foldHash1([0x41]) ? 0 : 1, 1,
     "h1/h2 independent streams");
  eq(sfxOpenAttempt1SlotMatch(
       foldHash1([0x66, 0x6f, 0x6f]), foldHash2([0x66, 0x6f, 0x6f]),
       foldHash1([0x66, 0x6f, 0x6f]), foldHash2([0x66, 0x6f, 0x6f])), 1,
     'slot_match(h1("foo"), h2("foo")) pair');
  eq(sfxOpenAttempt1SlotMatch(
       foldHash1([0x66, 0x6f, 0x6f]), foldHash2([0x66, 0x6f, 0x6f]),
       foldHash1([0x66, 0x6f, 0x6f]), foldHash2([0x62, 0x61, 0x72])), 0,
     "slot_match mismatched h2");
  countCase();
});

/* ---------- v25f: 0xa178d0 file-open POST-GATE decisions + 0x92d140
   call-site arg-prep (wave-16; NO ABI bump). v24 laws 19/20 covered the
   path NULL/empty gates and the result flag; v9 (table_open_gate)
   covered the 0x92d1af call-site open-result gate. These are the
   REMAINING decision islands of the open body: the attempt-#2 retry
   gate (0xa1792a cmp [ebp+8],0 ; jne), the arg2 OUT-store gate
   (0xa1793d/0xa17951), the esi ALLOC-arm gate (0xa17941/0xa17955), the
   SEH guard select (0xa17945 vs 0xa17959) and the call-site arg-prep
   pins (0x92d190 this=0xc37a10, 0x92d195 arg2=0). ALL gates FULL-WORD;
   the 0x100/0x1ff/0xffffffff drives are the point. */

test("v25f PE truth (native): 0xa178d0 post-gate gates + 0x92d140 arg prep", () => {
  const h = readFileSync(header, "utf8");
  for (const [name, expected] of [
    ["ISAAC_SFX_OPEN_CALL_THIS_C37A10", 0xc37a10],
    ["ISAAC_SFX_OPEN_CALL_ARG2", 0],
    ["ISAAC_SFX_OPEN_GUARD_NONE", 0xffffffff],
    ["ISAAC_SFX_OPEN_GUARD_RETRY", 0],
    ["ISAAC_SFX_OPEN_GUARD_SKIP", 1],
  ]) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    countCase();
  }
  /* JS mirrors pinned to their literals. */
  eq(SFX_OPEN_CALL_THIS_C37A10, 0xc37a10, "js this pin");
  eq(SFX_OPEN_CALL_ARG2, 0, "js arg2 pin");
  eq(SFX_OPEN_GUARD_NONE, 0xffffffff, "js guard none");
  eq(SFX_OPEN_GUARD_RETRY, 0, "js guard retry");
  eq(SFX_OPEN_GUARD_SKIP, 1, "js guard skip");
  countCase();
});

test("Wasm matches JS: v25f file-open retry/out/alloc/guard laws", () => {
  /* retry gate: FULL-WORD result slot == 0 runs attempt #2 (0xa1792a
     cmp [ebp+8],0 ; jne 0xa1794e) — 0x100 must NOT retry, and it is the
     exact complement of the v24 flag gate. */
  for (const [r1, want] of [[0, 1], [1, 0], [0x100, 0], [0xffffffff, 0]]) {
    eq(wasm.isaac_sfx_file_open_retry_gate(r1), want,
       `retry r1=0x${(r1 >>> 0).toString(16)}`);
    eq(sfxFileOpenRetryGate(r1), want, `js retry`);
    eq(wasm.isaac_sfx_file_open_retry_gate(r1),
       1 - wasm.isaac_sfx_file_open_flag_gate(r1),
       `retry == !flag r1=0x${(r1 >>> 0).toString(16)}`);
    seen("v25fRetry", sfxFileOpenRetryGate(r1));
    countCase();
  }

  /* out gate: FULL-WORD arg2 (0xa1793d/0xa17951 test ; jne) — a low-byte
     test would skip the *arg2 = esi store on 0x100. */
  for (const [arg2, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_file_open_out_gate(arg2), want,
       `out arg2=0x${(arg2 >>> 0).toString(16)}`);
    eq(sfxFileOpenOutGate(arg2), want, `js out`);
    seen("v25fOut", sfxFileOpenOutGate(arg2));
    countCase();
  }

  /* alloc arm gate: FULL-WORD handle (0xa17941/0xa17955 test esi ; je) —
     the guard write + the 0xa648b0 alloc arm need a non-zero handle. */
  for (const [h, want] of [[0, 0], [1, 1], [0x100, 1], [0xffffffff, 1]]) {
    eq(wasm.isaac_sfx_file_open_alloc_gate(h), want,
       `alloc h=0x${(h >>> 0).toString(16)}`);
    eq(sfxFileOpenAllocGate(h), want, `js alloc`);
    seen("v25fAlloc", sfxFileOpenAllocGate(h));
    countCase();
  }

  /* guard select: NONE when arg2 != 0 or handle == 0 (the out-store and
     esi==0 tails leave the SEH state at its initial -1); else SKIP=1
     when attempt #2 was skipped (0xa17945 literal) vs RETRY=0 when it
     ran (0xa17959 writes eax==arg2==0). FULL-WORD result1. */
  for (const [r1, arg2, h, want] of [
    [1, 0, 1, SFX_OPEN_GUARD_SKIP],
    [0, 0, 1, SFX_OPEN_GUARD_RETRY],
    [0x100, 0, 1, SFX_OPEN_GUARD_SKIP],
    [0xffffffff, 0, 1, SFX_OPEN_GUARD_SKIP],
    [0, 0x100, 1, SFX_OPEN_GUARD_NONE],
    [1, 1, 1, SFX_OPEN_GUARD_NONE],
    [1, 0xffffffff, 0xffffffff, SFX_OPEN_GUARD_NONE],
    [0, 0, 0, SFX_OPEN_GUARD_NONE],
    [0, 0, 0x100, SFX_OPEN_GUARD_RETRY],
    [0x100, 0, 0x100, SFX_OPEN_GUARD_SKIP],
  ]) {
    eq(wasm.isaac_sfx_file_open_guard_select(r1, arg2, h) >>> 0, want >>> 0,
       `guard (0x${(r1 >>> 0).toString(16)},0x${(arg2 >>> 0).toString(16)},0x${(h >>> 0).toString(16)})`);
    eq(sfxFileOpenGuardSelect(r1, arg2, h), want, `js guard`);
    seen("v25fGuard", sfxFileOpenGuardSelect(r1, arg2, h));
    countCase();
  }

  /* call-site arg-prep pins: 0x92d190 this=0xc37a10, 0x92d195 arg2=0. */
  eq(wasm.isaac_sfx_open_call_arg2(), SFX_OPEN_CALL_ARG2, "call arg2");
  eq(wasm.isaac_sfx_open_call_this(), SFX_OPEN_CALL_THIS_C37A10, "call this");
  eq(sfxOpenCallArg2(), SFX_OPEN_CALL_ARG2, "js call arg2");
  eq(sfxOpenCallThis(), SFX_OPEN_CALL_THIS_C37A10, "js call this");
  seen("v25fCallArg2", wasm.isaac_sfx_open_call_arg2());
  seen("v25fCallThis", wasm.isaac_sfx_open_call_this());
  countCase();
});

/* ------------------------------------------------------------------ *
 * v25a: 0x92d93a..0x92d984 "path" dispatch arm caller-side            *
 * (wave-16; NO ABI bump — coordinator merges). The "path" attr arm of *
 * the per-sample slot walk (FIRST arm, slot site, constant "path"     *
 * 0xb66e0c): value scan prep, the concat TOTAL gate 0x92d963          *
 * (`cmp eax,ecx ; jb` UNSIGNED strict, wrap limit 0x7fffffff-         *
 * root_len, length_error 0x40ccc0) and the cmovae root-buffer select  *
 * 0x92d96b (`cmp cap,0x10 ; lea eax,SSO ; cmovae eax,[heap]` —        *
 * UNSIGNED, boundary 0x10 picks the heap).                            *
 * ------------------------------------------------------------------ */

const SAMPLE_PATH_PLAN_FIELDS = [
  "value_len", "limit", "overflow", "root_buf", "concat_called",
  "throw_va", "host_calls", "pure_complete",
];
const SAMPLE_PATH_PLAN_U32 = ["limit", "root_buf", "throw_va"];
function readSamplePathPlan(view, base) {
  return readFields(view, base, SAMPLE_PATH_PLAN_FIELDS,
                    SAMPLE_PATH_PLAN_U32);
}

/* IsaacSfxSamplePathPlan: 8 x 4 bytes -> 32 bytes. */
const SAMPLE_PATH_PLAN_BASE = SCRATCH + 0x12900;
const SAMPLE_PATH_VALUE_BASE = SCRATCH + 0x12a00;

test("v25a PE truth (native): 0x92d93a..0x92d984 path-arm concat caller",
     () => {
  const view = new DataView(wasm.memory.buffer);
  const plan = SAMPLE_PATH_PLAN_BASE;
  const value = SAMPLE_PATH_VALUE_BASE;

  /* 0x92d961 sub eax,esi: 0x7fffffff - root_len, 32-bit wrap. */
  eq(wasm.isaac_sfx_sample_path_limit(0), 0x7fffffff, "limit(0)");
  eq(wasm.isaac_sfx_sample_path_limit(0x100), 0x7ffffeff, "limit(0x100)");
  eq(wasm.isaac_sfx_sample_path_limit(0xffffffff) >>> 0, 0x80000000,
     "limit wrap (root 0xffffffff)");
  eq(wasm.isaac_sfx_sample_path_limit(0x7fffffff), 0, "limit(0x7fffffff)");
  countCase();

  /* 0x92d963 cmp eax,ecx ; jb 0x92dbca — UNSIGNED STRICT: value_len >
     limit throws. The equality row must NOT throw (a jbe mutant flips). */
  eq(wasm.isaac_sfx_sample_path_overflow(0x100, 0x7ffffeff), 0,
     "value == limit does NOT overflow (strict jb)");
  eq(wasm.isaac_sfx_sample_path_overflow(0x100, 0x7ffffe00), 0,
     "value below limit");
  eq(wasm.isaac_sfx_sample_path_overflow(0x100, 0x7fffff00), 1,
     "value one above limit");
  /* UNSIGNED: values with the high bit set (negative as i32) still
     overflow — a signed compare mutant dies here. */
  eq(wasm.isaac_sfx_sample_path_overflow(0, 0xffffffff), 1,
     "0xffffffff overflows (unsigned)");
  eq(wasm.isaac_sfx_sample_path_overflow(0, 0x80000000), 1,
     "0x80000000 overflows (unsigned)");
  /* Wrap: root 0xffffffff -> limit 0x80000000; equality again no-throw. */
  eq(wasm.isaac_sfx_sample_path_overflow(0xffffffff, 0x80000000), 0,
     "wrap equality no-throw");
  eq(wasm.isaac_sfx_sample_path_overflow(0xffffffff, 0x80000001), 1,
     "wrap overflow");
  countCase();

  /* 0x92d96b cmp [ebp-0x18],0x10 ; lea eax,[ebp-0x2c] ;
     cmovae eax,[ebp-0x2c] — UNSIGNED, boundary 0x10 -> heap; a low-byte
     (cap&0xff) mutant flips the 0x100 row. */
  eq(wasm.isaac_sfx_sample_path_root_buf(0, 0x1111, 0x2222), 0x1111,
     "cap 0 -> sso");
  eq(wasm.isaac_sfx_sample_path_root_buf(0xf, 0x1111, 0x2222), 0x1111,
     "cap 0xf -> sso");
  eq(wasm.isaac_sfx_sample_path_root_buf(0x10, 0x1111, 0x2222), 0x2222,
     "cap 0x10 -> heap (cmovae boundary)");
  eq(wasm.isaac_sfx_sample_path_root_buf(0x100, 0x1111, 0x2222), 0x2222,
     "cap 0x100 -> heap (FULL-WORD, not low byte)");
  eq(wasm.isaac_sfx_sample_path_root_buf(0x1ff, 0x1111, 0x2222), 0x2222,
     "cap 0x1ff -> heap");
  eq(wasm.isaac_sfx_sample_path_root_buf(0xffffffff, 0x1111, 0x2222), 0x2222,
     "cap max -> heap");
  countCase();

  /* The composed plan: seeded value string, null-value fallback, both
     cap arms. */
  writeName(view, value, "abc");
  wasm.isaac_sfx_sample_path_plan(
    0x100, 0xf, 0x1111, 0x2222, 0, value, 0x40, SFX_THROW_LEN_40CCC0, plan);
  let p = readSamplePathPlan(view, plan);
  eq(p.value_len, 3, "plan value_len of 'abc'");
  eq(p.limit, 0x7ffffeff, "plan limit");
  eq(p.overflow, 0, "plan no overflow");
  eq(p.root_buf, 0x1111, "plan root_buf sso");
  eq(p.concat_called, 1, "plan concat called");
  eq(p.throw_va, 0, "plan no throw");
  eq(p.host_calls, 1, "plan host calls (concat OR throw)");
  eq(p.pure_complete, 0, "plan pure_complete");

  wasm.isaac_sfx_sample_path_plan(
    0, 0x10, 0x1111, 0x2222, 1, 0, 0x40, SFX_THROW_LEN_40CCC0, plan);
  p = readSamplePathPlan(view, plan);
  eq(p.value_len, 0, "plan null value -> len 0");
  eq(p.overflow, 0, "plan null value no overflow");
  eq(p.root_buf, 0x2222, "plan root_buf heap (cap 0x10)");
  eq(p.concat_called, 1, "plan concat with empty value");
  eq(p.throw_va, 0, "plan no throw with empty value");

  /* The wrap throw arm: root 0xffffffff -> limit 0x80000000 and a huge
     scanned value must set throw_va. Seed 8 bytes of NUL-free data and a
     len bound that reaches them. */
  for (let k = 0; k < 8; ++k) {
    view.setUint8(value + k, 0x41 + k);
  }
  wasm.isaac_sfx_sample_path_plan(
    0xffffffff, 0xf, 0x1111, 0x2222, 0, value, 0x50000000,
    SFX_THROW_LEN_40CCC0, plan);
  p = readSamplePathPlan(view, plan);
  eq(p.limit, 0x80000000, "plan wrap limit");
  /* value_len is bounded by the NUL-terminated 8-byte seed: 8 <
     0x80000000, so the strict-jb overflow arm does NOT fire here. The
     wrap-throw arm needs value_len > 0x80000000, unreachable with
     finite zeroed memory — the machine never binds it on this input. */
  eq(p.value_len, 8, "plan scan len at bound");
  eq(p.overflow, 0, "plan wrap overflow (8 < limit)");
  eq(p.concat_called, 1, "plan concat runs when not overflowing");
  eq(p.throw_va, 0, "plan no throw (value_len below limit)");
  countCase();
});

test("Wasm matches JS: v25a path-arm caller differential", () => {
  let seed = (0x92d93a ^ 0x92d984 ^ 0x92d963 ^ 0x92d96b) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const view = new DataView(wasm.memory.buffer);
  const plan = SAMPLE_PATH_PLAN_BASE;
  const value = SAMPLE_PATH_VALUE_BASE;
  const strings = ["", "a", "abc", "path/to/file.ogg", "x\0y",
                   "0123456789abcdef", "weight", "very long path\0tail"];

  for (let t = 0; t < 400; ++t) {
    const rootLen = pick(rnd, 4) === 0
      ? [0, 0x100, 0xffffffff, 0x7fffffff][pick(rnd, 4)]
      : pick(rnd, 0x10000);
    const rootCap = pick(rnd, 3) === 0
      ? [0, 0xf, 0x10, 0x100, 0x1ff, 0xffffffff][pick(rnd, 6)]
      : pick(rnd, 0x10000);
    const valueNull = pick(rnd, 4) === 0 ? 1 : 0;
    const valueWide = pick(rnd, 3) === 0 ? 0x100 : 0;
    const si = pick(rnd, strings.length);
    const str = strings[si].split("\0")[0];
    const valueMax = pick(rnd, 3) === 0
      ? [0, 1, str.length, 0x100][pick(rnd, 4)]
      : str.length + pick(rnd, 0x20);
    const n = valueNull !== 0 ? 0 : value + valueWide;
    writeName(view, value, strings[si]);
    /* NUL-terminate what was written: the strlen scan must stop at the
       string end even when an earlier PE-truth row left nonzero bytes
       past it (wasm scans memory; the model scans the JS string). */
    view.setUint8(value + str.length, 0);
    /* The wide (0x100) pointer offset reads zero-initialized memory; the
       JS oracle must see the same bytes, so its value string is "". */
    if (valueWide !== 0) {
      const bytes = new Uint8Array(wasm.memory.buffer, value + 0x100, 64);
      bytes.fill(0);
    }
    wasm.isaac_sfx_sample_path_plan(
      rootLen, rootCap, 0x1111, 0x2222, valueNull, n, valueMax,
      SFX_THROW_LEN_40CCC0, plan);
    const w = readSamplePathPlan(view, plan);
    const js = sfxSamplePathPlan(
      rootLen, rootCap, 0x1111, 0x2222, valueNull,
      valueNull !== 0 ? 0 : (valueWide !== 0 ? "" : str), valueMax,
      SFX_THROW_LEN_40CCC0);
    for (const key of SAMPLE_PATH_PLAN_FIELDS) {
      eq(w[key], js[key], `v25a t${t} ${key}`);
    }
    seen("v25aCap", rootCap);
    seen("v25aRoot", rootLen);
    seen("v25aStr", si);
    seen("v25aNull", valueNull);
    seen("v25aOverflow", js.overflow);
    countCase();
  }
});

/* v25c: 0x00416e80 numeric/amp entity scan gates (wave-16, banner v25c,
   NO ABI bump — the coordinator merges). The scanner's CASE 0 numeric
   entity run WALK layer + the amp named-entity consume/emit split. */
test("v25c PE truth (native): numeric/amp entity scan gates of 0x416e80", () => {
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x416fc0/);   /* cmp cl,0x78 -> hex/decimal path */
  assert.match(h, /0x416fc5/);   /* hex entry: movzx [esi+3] ; add esi,3 */
  assert.match(h, /0x416ff1/);   /* decimal entry: add esi,2 */
  assert.match(h, /0x416fd2/);   /* entry run gate cmp al,0xff */
  assert.match(h, /0x41701f/);   /* ';' at read pos = &+entry+run_len */
  assert.match(h, /IsaacSfxXmlScanNumRunPlan/);

  const pairs = [
    ["ISAAC_SFX_XML_SCAN_VA", SFX_XML_SCAN_VA, 0x00416e80],
    ["ISAAC_SFX_XML_SCAN_NUM_X_BYTE", SFX_XML_SCAN_HEX_X_BYTE, 0x78],
    ["ISAAC_SFX_XML_SCAN_NUM_ENTRY_DEC", SFX_XML_SCAN_NUM_ENTRY_DEC, 2],
    ["ISAAC_SFX_XML_SCAN_NUM_ENTRY_HEX", SFX_XML_SCAN_NUM_ENTRY_HEX, 3],
    ["ISAAC_SFX_XML_SCAN_NUM_NOT_DIGIT", SFX_XML_SCAN_NUM_NOT_DIGIT, 0xff],
    ["ISAAC_SFX_XML_SCAN_AMP_LITERAL_CONSUMED",
     SFX_XML_SCAN_AMP_LITERAL_CONSUMED, 1],
    ["ISAAC_SFX_XML_SCAN_AMP_LITERAL_EMIT",
     SFX_XML_SCAN_AMP_LITERAL_EMIT, 0x26],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }

  /* Reference rows re-transcribed branch-by-branch from
     cpu-dump/00416e80.txt (0x416fbb..0x417036), NOT from the C++:
     - 0x416fc0 `cmp cl,0x78 ; jne 0x416fee`: cl is loaded with
       `mov cl, byte[esi+2]`, so the compare is a LOW-BYTE 'x' test —
       0x178 / 0x10000078 are hex.
     - 0x416fc5 movzx eax,[esi+3] ; add esi,3 vs 0x416fee movzx eax,cl ;
       0x416ff1 add esi,2: the first-digit '&' offset is 3 hex / 2 dec.
     - 0x416fd2/0x416ffa (entry) and 0x416fe8/0x417013 (loop bottom)
       `cmp al,0xff ; je/jne`: al = the loaded nibble BYTE, so the gate
       is the LOW byte of the nibble — 0x1ff/0xffffffff stop the run.
     - 0x416fd6..0x416fdd shl edx,4 ; add edx,eax and 0x417000..0x417007
       lea ecx,[edx+edx*4] ; lea edx,[eax+ecx*2]; `inc esi` per digit:
       run_len digits fold (32-bit wrap), read pos at 0x41701f =
       & + entry + run_len.
     - Named commits 0x416f09..0x416fb6: add esi,5/6/6/4/4 + inc edx,
       emits 0x26/0x27/0x22/0x3e/0x3c; literal arm 0x417036..0x41703b:
       mov al,[esi] ; inc esi ; mov [edx],al ; inc edx — consume 1,
       emit '&' 0x26. So skip = packed>>8 (0 -> 1), emit = packed&0xff
       (0 -> 0x26). */
  const hexPathRows = [
    [0x78, 1], [0x178, 1], [0x10000078, 1], [0x77, 0], [0x79, 0],
    [0x57, 0], [0xff, 0], [0xffffffff, 0], [0x100, 0], [0x278, 1],
  ];
  for (const [b, want] of hexPathRows) {
    eq(wasm.isaac_sfx_xml_scan_num_hex_path(b), want, `hex_path ${b}`);
    eq(sfxXmlScanNumHexPath(b), want, `js hex_path ${b}`);
    countCase();
  }
  eq(wasm.isaac_sfx_xml_scan_num_entry_digits(0), 2, "dec entry");
  eq(wasm.isaac_sfx_xml_scan_num_entry_digits(1), 3, "hex entry");
  eq(wasm.isaac_sfx_xml_scan_num_entry_digits(0x100), 3, "wide is_hex");
  eq(wasm.isaac_sfx_xml_scan_num_entry_digits(0xffffffff), 3,
     "wide is_hex 2");
  eq(sfxXmlScanNumEntryDigits(0), 2);
  eq(sfxXmlScanNumEntryDigits(1), 3);
  eq(sfxXmlScanNumEntryDigits(0x100), 3);
  eq(sfxXmlScanNumEntryDigits(0xffffffff), 3);
  countCase();

  const gateRows = [
    [0xff, 0], [0x1ff, 0], [0xffffffff, 0], [0x00, 1], [0x0f, 1],
    [0x100, 1], [0x3b, 1], [0x2e, 1],
  ];
  for (const [n, want] of gateRows) {
    eq(wasm.isaac_sfx_xml_scan_num_digit_gate(n), want, `gate ${n}`);
    eq(sfxXmlScanNumDigitGate(n), want, `js gate ${n}`);
    countCase();
  }
  eq(wasm.isaac_sfx_xml_scan_num_end_digits(0, 3), 5, "dec 3 digits");
  eq(wasm.isaac_sfx_xml_scan_num_end_digits(1, 5), 8, "hex 5 digits");
  eq(wasm.isaac_sfx_xml_scan_num_end_digits(1, 0), 3, "hex 0 digits");
  eq(wasm.isaac_sfx_xml_scan_num_end_digits(0, 0xffffffff) >>> 0, 1,
     "wrap: 2 + 0xffffffff");
  eq(wasm.isaac_sfx_xml_scan_num_end_digits(1, 0xffffffff) >>> 0, 2,
     "wrap: 3 + 0xffffffff");
  eq(sfxXmlScanNumEndDigits(0, 0xffffffff) >>> 0, 1);
  eq(sfxXmlScanNumEndDigits(1, 0xffffffff) >>> 0, 2);
  countCase();

  const ampRows = [
    [0x0000, 1, 0x26],  /* no match -> literal '&' (consume 1, emit '&') */
    [0x0526, 5, 0x26],  /* &amp;   */
    [0x0627, 6, 0x27],  /* &apos;  */
    [0x0622, 6, 0x22],  /* &quot;  */
    [0x043e, 4, 0x3e],  /* &gt;    */
    [0x043c, 4, 0x3c],  /* &lt;    */
  ];
  for (const [packed, skip, emit] of ampRows) {
    eq(wasm.isaac_sfx_xml_scan_amp_consumed(packed), skip,
       `consumed ${packed}`);
    eq(wasm.isaac_sfx_xml_scan_amp_emit(packed), emit, `emit ${packed}`);
    eq(sfxXmlScanAmpConsumed(packed), skip, `js consumed ${packed}`);
    eq(sfxXmlScanAmpEmit(packed), emit, `js emit ${packed}`);
    countCase();
  }
  eq(wasm.isaac_sfx_xml_scan_amp_consumed(0x100), 1, "packed 0x100");
  eq(wasm.isaac_sfx_xml_scan_amp_emit(0x1ff), 0xff, "emit low byte");
  eq(sfxXmlScanAmpConsumed(0x100), 1);
  eq(sfxXmlScanAmpEmit(0x1ff), 0xff);
  countCase();
});

test("Wasm matches JS: v25c numeric-run fold walk + wide gate drives", () => {
  const view = new DataView(wasm.memory.buffer);
  const NIB = SCRATCH + 0x2c000;   /* nibble bytes */
  const PLAN = SCRATCH + 0x2c100;  /* IsaacSfxXmlScanNumRunPlan: 9x4=36 B */
  const put = (arr) => {
    const len = Math.max(arr.length, 16);
    const u8 = new Uint8Array(wasm.memory.buffer, NIB, len);
    u8.fill(0xff);
    arr.forEach((b, i) => { u8[i] = b; });
  };
  const readPlan = () => ({
    hexPath: view.getInt32(PLAN, true),
    entryDigits: view.getInt32(PLAN + 4, true),
    firstDigitOk: view.getInt32(PLAN + 8, true),
    runLen: view.getInt32(PLAN + 12, true),
    value: view.getUint32(PLAN + 16, true),
    endDigits: view.getInt32(PLAN + 20, true),
    utf8Va: view.getUint32(PLAN + 24, true),
    pureComplete: view.getInt32(PLAN + 28, true),
    scanVa: view.getUint32(PLAN + 32, true),
  });
  const run = (isHex, nibbles, count) => {
    put(nibbles);
    wasm.isaac_sfx_xml_scan_num_run(isHex, NIB, count, PLAN);
    return readPlan();
  };
  const js = (isHex, nibbles, count) =>
    sfxXmlScanNumRun(isHex, nibbles, count, {});

  const base = (isHex, runLen, value, end) => ({
    hexPath: isHex !== 0 ? 1 : 0,
    entryDigits: isHex !== 0 ? 3 : 2,
    firstDigitOk: 1,
    runLen,
    value: value >>> 0,
    endDigits: end,
    utf8Va: SFX_XML_UTF8_VA,
    pureComplete: 1,
    scanVa: SFX_XML_SCAN_VA,
  });

  const rows = [
    [1, [0x0a, 0x03, 0x0b], 3, base(1, 3, 0xa3b, 6)],       /* hex A3B */
    [0, [0x01, 0x02, 0x03], 3, base(0, 3, 123, 5)],        /* dec 123 */
    [0, [0x31, 0x32, 0x33], 2, base(0, 2, 0x31 * 10 + 0x32, 4)],
    [1, [], 0, {
      hexPath: 1, entryDigits: 3, firstDigitOk: 0, runLen: 0,
      value: 0, endDigits: 3, utf8Va: SFX_XML_UTF8_VA,
      pureComplete: 1, scanVa: SFX_XML_SCAN_VA,
    }],                          /* empty run */
    [1, [0xff, 0x0a], 2, {
      hexPath: 1, entryDigits: 3, firstDigitOk: 0, runLen: 0,
      value: 0, endDigits: 3, utf8Va: SFX_XML_UTF8_VA,
      pureComplete: 1, scanVa: SFX_XML_SCAN_VA,
    }],                          /* first byte not a digit */
    [1, [0x0a, 0xff, 0x0b], 3, base(1, 1, 0xa, 4)],        /* stops mid */
    [0, [0x05, 0xff, 0x09], 3, base(0, 1, 5, 3)],          /* dec stops */
    [1, [0x08, 0, 0, 0, 0, 0, 0, 0, 0, 0x01], 10,
     base(1, 10, 1, 13)],  /* 0x80000000 << 4 wraps to 0; +1 -> 1 */
    [0, [9, 9, 9, 9, 9, 9, 9, 9, 9, 9], 10,
     base(0, 10, 9999999999, 12)], /* dec 9999999999 wraps to
                                      1410065407 */
    [0, [9, 9, 9, 9], 4, base(0, 4, 9999, 6)], /* NO byte truncation:
                                                  the fold keeps the full
                                                  dword (shl/lea on edx) */
  ];
  for (const [isHex, nibbles, count, want] of rows) {
    const w = run(isHex, nibbles, count);
    const j = js(isHex, nibbles, count);
    assert.deepStrictEqual(w, want, `run ${isHex} ${nibbles}`);
    assert.deepStrictEqual(j, want, `js run ${isHex} ${nibbles}`);
    countCase();
  }
  eq(run(0, [1, 2, 3], 3).value >>> 0, 123, "wrap check dec");
  eq(js(0, [1, 2, 3], 3).value >>> 0, 123, "wrap check js dec");
  countCase();

  /* WIDE nibbles: the machine reads BYTES (movzx eax, al at 0x416fd7 /
     0x417000), so the fold consumes ONLY the low byte — a 0x100 element
     folds as 0x00 (digit, continues), a 0x1ff element folds as 0xff
     (the run STOPS). The wasm memory is byte-truncated by construction
     (Uint8Array writes), so these rows drive the JS mirror directly. */
  {
    const wideRun = js(1, [0x100, 0x05], 2);
    eq(wideRun.runLen, 2, "wide 0x100 digit continues");
    eq(wideRun.value >>> 0, 5, "wide 0x100 folds as byte 0x00");
    eq(wideRun.endDigits, 5, "wide 0x100 end");
    const wideStop = js(1, [0x1ff, 0x05], 2);
    eq(wideStop.runLen, 0, "wide 0x1ff stops the run");
    eq(wideStop.value >>> 0, 0, "wide 0x1ff value 0");
    eq(wideStop.endDigits, 3, "wide 0x1ff end entry-only");
    const wideDecGate = sfxXmlScanNumDigitGate(0xffffffff);
    eq(wideDecGate, 0, "wide 0xffffffff nibble stops");
    countCase();
  }

  /* Randomized wide differential on the scalar laws. */
  let seed = (0x00416e80 ^ 0xb1ad60 ^ 0x00416dc0) >>> 0;
  const rnd = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed;
  };
  const wide = [0, 0x78, 0x178, 0x10000078, 0x77, 0x79, 0xff,
                0x1ff, 0xffffffff, 0x100, 0x30, 0x39, 0x41, 0x46,
                0x61, 0x66, 0x3b, 0, 0x526, 0x627, 0x622, 0x43e,
                0x43c, 0x100, 0x20000];
  for (let k = 0; k < 400; ++k) {
    const b = wide[pick(rnd, wide.length)];
    const isHex = wide[pick(rnd, wide.length)];
    const rl = wide[pick(rnd, wide.length)];
    const packed = wide[pick(rnd, wide.length)];
    seen("v25cB", b);
    seen("v25cIsHex", isHex);
    seen("v25cRunLen", rl);
    seen("v25cPacked", packed);
    eq(wasm.isaac_sfx_xml_scan_num_hex_path(b),
       sfxXmlScanNumHexPath(b), `hex_path ${b}`);
    eq(wasm.isaac_sfx_xml_scan_num_entry_digits(isHex),
       sfxXmlScanNumEntryDigits(isHex), `entry ${isHex}`);
    eq(wasm.isaac_sfx_xml_scan_num_digit_gate(b),
       sfxXmlScanNumDigitGate(b), `gate ${b}`);
    eq(wasm.isaac_sfx_xml_scan_num_end_digits(isHex, rl) >>> 0,
       sfxXmlScanNumEndDigits(isHex, rl) >>> 0, `end ${isHex}/${rl}`);
    eq(wasm.isaac_sfx_xml_scan_amp_consumed(packed),
       sfxXmlScanAmpConsumed(packed), `consumed ${packed}`);
    eq(wasm.isaac_sfx_xml_scan_amp_emit(packed),
       sfxXmlScanAmpEmit(packed), `emit ${packed}`);
    seen("v25cHexPath", sfxXmlScanNumHexPath(b));
    seen("v25cGate", sfxXmlScanNumDigitGate(b));
    seen("v25cEnd", sfxXmlScanNumEndDigits(isHex, rl));
    seen("v25cConsumed", sfxXmlScanAmpConsumed(packed));
    seen("v25cEmit", sfxXmlScanAmpEmit(packed));
    countCase();
  }

  /* Randomized run-plan differential (arrays written into scratch). */
  for (let k = 0; k < 200; ++k) {
    const isHex = pick(rnd, 2);
    const len = pick(rnd, 9);
    const nibbles = [];
    for (let i = 0; i < len; ++i) {
      /* 0..15 or 0xff terminator or the odd 0x100 wide byte. */
      const r = pick(rnd, 17);
      nibbles.push(r === 16 ? 0xff : r);
    }
    const want = js(isHex, nibbles, len);
    const w = run(isHex, nibbles, len);
    assert.deepStrictEqual(w, want, `rand run ${isHex} ${nibbles}`);
    countCase();
  }

  /* A null nibbles pointer with count>0 must not crash nor fold. */
  wasm.isaac_sfx_xml_scan_num_run(1, 0, 5, PLAN);
  const nullPlan = readPlan();
  eq(nullPlan.runLen, 0, "null nibbles run 0");
  eq(nullPlan.value >>> 0, 0, "null nibbles value 0");
  countCase();
});

/* ---------- v25d: 0x92d528/0x92da3a numeric-scan gates at the atoi
   IAT 0xb187a8 (wave-16, banner v25d, NO ABI bump — coordinator
   merges). The v24 census labeled the slot "strtoul (numeric parse)
   HOST"; the import table says **atoi** (hint 80) — ONE arg
   (`push ecx ; call [0xb187a8] ; add esp,4`), full eax. These laws are
   the PURE decisions around the two atoi calls of the 0x92d140 reader:

   Island A (0x92d51a..0x92d537, `id` attr arm):
     0x92d51a eax=[esi+4] ; 0x92d51d ecx=0xc71640 ; 0x92d522 test eax,eax
     ; 0x92d524 cmovne ecx,eax  — FULL-WORD NULL select -> atoi ARG.
     0x92d527 push ecx ; 0x92d528 call atoi ; 0x92d52e add esp,4 ;
     0x92d531 [ebp-0x10264]=eax — the count field, FULL 32-bit eax
     (later SIGNED-checked at 0x92d6c4 test/js + cmp 0x443/jl — v9).
   Island B (0x92da2c..0x92da49, `weight` attr arm):
     0x92da2c eax=[edi+4] ; ... ; 0x92da36 cmovne — SAME select.
     0x92da39 push ; 0x92da3a call atoi ; 0x92da46 add esp,4 ;
     0x92da40 ecx=[ebp-0x1040c] — slot re-read **AFTER** the call
     (defect-class-1: capture post-call, never the pre-call fold) ;
     0x92da49 [ecx+0x34]=eax — slot->weight, FULL 32-bit.
   The attr-name strcmp gates (0x92d4f1/0x92da03) + the arm/action
   route (which attr parses vs assigns) are v5-landed; the atoi CALL
   stays host. Reference rows transcribed from cpu-dump/0092d140.txt
   (never from the C++ or this suite's earlier groups). */
test("v25d PE truth (native): 0x92d528/0x92da3a atoi arg select + stores", () => {
  const h = readFileSync(header, "utf8");
  assert.match(h, /0x92d51d/);   /* the atoi ARG cmovne select (island A) */
  assert.match(h, /0x92da40/);   /* post-call slot re-read */
  assert.match(h, /isaac_sfx_numeric_weight_slot_after/);

  const pairs = [
    ["ISAAC_SFX_NUMERIC_ID_CALL_92D528",
     SFX_NUMERIC_ID_CALL_92D528, 0x0092d528],
    ["ISAAC_SFX_NUMERIC_WEIGHT_CALL_92DA3A",
     SFX_NUMERIC_WEIGHT_CALL_92DA3A, 0x0092da3a],
    ["ISAAC_SFX_NUMERIC_COUNT_FIELD_10264",
     SFX_NUMERIC_COUNT_FIELD_10264, 0x00010264],
    ["ISAAC_SFX_NUMERIC_WEIGHT_OFF_34",
     SFX_NUMERIC_WEIGHT_OFF_34, 0x34],
  ];
  for (const [name, mirror, expected] of pairs) {
    eq(headerConstant(h, name), expected, `header ${name}`);
    eq(mirror, expected, `JS mirror ${name}`);
    countCase();
  }

  /* FULL-WORD NULL select for the atoi ARG (0x92d522 test eax,eax ;
     0x92d524 cmovne ecx,eax): 0 is the ONLY null — 0x100/0x1ff/
     0xffffffff pass through as real pointers. A LOW-BYTE mutant
     wrongly substitutes the empty string on 0x100. */
  const argRows = [
    [0, SFX_ATTR_EMPTY_STRING_VA],
    [1, 1],
    [0x100, 0x100],
    [0x1ff, 0x1ff],
    [0xffffffff, 0xffffffff],
  ];
  for (const [ptr, want] of argRows) {
    eq(wasm.isaac_sfx_numeric_atoi_arg(ptr) >>> 0, want >>> 0,
       `atoi arg ptr=0x${(ptr >>> 0).toString(16)}`);
    eq(sfxNumericAtoiArg(ptr) >>> 0, want >>> 0,
       `js atoi arg 0x${(ptr >>> 0).toString(16)}`);
    countCase();
  }

  /* IAT pin: the numeric parse slot is atoi (hint 80), 0xb187a8. */
  eq(wasm.isaac_sfx_numeric_atoi_iat_va() >>> 0, 0xb187a8,
     "iat va");
  eq(sfxNumericAtoiIatVa() >>> 0, 0xb187a8, "js iat va");
  countCase();

  /* 0x92d531 count store: FULL 32-bit eax — 0x1ff stays 0x1ff
     (a byte-store mutant truncates), 0xffffffff stays signed -1. */
  const countRows = [
    [0, 0], [1, 1], [0x100, 0x100], [0x1ff, 0x1ff],
    [0xffffffff, -1],
  ];
  for (const [r, want] of countRows) {
    eq(wasm.isaac_sfx_numeric_id_count(r), want,
       `id count a=${r.toString(16)}`);
    eq(sfxNumericIdCount(r), want, `js id count ${r.toString(16)}`);
    countCase();
  }

  /* 0x92da40 POST-CALL slot re-read: the weight store targets the
     slot pointer as read AFTER the atoi call. slot_pre is a trap
     input — a pre-call fold diverges whenever the pointer moved
     across the call (here the 0x1111 -> 0x2222 row). */
  const slotRows = [
    [0x1111, 0x2222, 0x2222],
    [0x2222, 0x2222, 0x2222],
    [0, 0x100, 0x100],
    [0xffffffff, 1, 1],
  ];
  for (const [pre, post, want] of slotRows) {
    eq(wasm.isaac_sfx_numeric_weight_slot_after(pre, post) >>> 0,
       want >>> 0, `slot_after pre=${pre.toString(16)}`);
    eq(sfxNumericWeightSlotAfter(pre, post) >>> 0, want >>> 0,
       `js slot_after`);
    countCase();
  }

  /* 0x92da49 weight store: FULL 32-bit eax at slot+0x34. */
  const weightRows = [
    [0, 0], [1, 1], [0x100, 0x100], [0x1ff, 0x1ff],
    [0xffffffff, -1],
  ];
  for (const [r, want] of weightRows) {
    eq(wasm.isaac_sfx_numeric_weight_value(r), want,
       `weight v=${r.toString(16)}`);
    eq(sfxNumericWeightValue(r), want, `js weight ${r.toString(16)}`);
    countCase();
  }
});

test("Wasm matches JS: v25d atoi numeric-scan gates (wide drives)", () => {
  /* Wide drives on every width-bearing gate: the atoi ARG select is
     FULL-WORD (0x100/0x1ff/0xffffffff are real pointers — the wasm arg
     is NOT pre-masked the way a low-byte law would require). */
  const widePtrs = [0, 1, 0x100, 0x1ff, 0xffffffff, 0x10000000];
  for (const ptr of widePtrs) {
    eq(wasm.isaac_sfx_numeric_atoi_arg(ptr) >>> 0,
       sfxNumericAtoiArg(ptr) >>> 0,
       `arg ptr=0x${(ptr >>> 0).toString(16)}`);
    seen("v25dArg", ptr >>> 0);
    countCase();
  }
  const wideVals = [0, 1, 0x100, 0x1ff, 0xffffffff, 0x7fffffff,
                    -0x80000000];
  for (const v of wideVals) {
    eq(wasm.isaac_sfx_numeric_id_count(v), sfxNumericIdCount(v),
       `id count v=${v.toString(16)}`);
    eq(wasm.isaac_sfx_numeric_weight_value(v), sfxNumericWeightValue(v),
       `weight v=${v.toString(16)}`);
    seen("v25dValue", v >>> 0);
    countCase();
  }
  const wideSlots = [
    [0x1111, 0x2222], [0x2222, 0x2222], [0, 0x100],
    [0xffffffff, 1], [0x10000000, 0xffffffff],
  ];
  for (const [pre, post] of wideSlots) {
    eq(wasm.isaac_sfx_numeric_weight_slot_after(pre, post) >>> 0,
       sfxNumericWeightSlotAfter(pre, post) >>> 0,
       `slot_after pre=${pre.toString(16)} post=${post.toString(16)}`);
    seen("v25dSlot", pre >>> 0);
    countCase();
  }

  /* Cross-pin: the atoi IAT VA matches the v24-era const. */
  eq(wasm.isaac_sfx_numeric_atoi_iat_va(),
     SFX_ATTR_PARSE_IAT_VA, "iat va == SFX_ATTR_PARSE_IAT_VA");
  countCase();
});
