test("Wasm matches JS: v30 duck-wrapper decision laws", () => {
  /* 0x92e620..0x92e6d3, ret 0xc @ 0x92e6d3 (thiscall, 3 stack args:
     id @ 8, volume @ 0xc, pitch @ 0x10), 3 conditional branches
     (jb@0x92e638, je@0x92e641, je@0x92e65d). The decision tree is pure:
     comiss vs the .rdata 0.01f threshold (0xbaa06c = 0x3c23d70a), the
     silent/audible arm pick, the is_playing gates, and the PLAY arm's
     pre-play (0x956780) + Play(*(0xc7169c)+0x2a324, id', vol, 2, 1,
     pitch, 0) delegation (6 stack args, ret 0x18). All five callees
     stay host with exact arities. Transcribed from cpu-dump/0092e620.txt
     + the 0092e600.txt full-window dump. */
  const rows = [
    ["va", "isaac_sfx_duck_va", sfxDuckVa, SFX_DUCK_VA_92E620, 0x0092e620],
    ["endVa", "isaac_sfx_duck_end_va", sfxDuckEndVa, SFX_DUCK_END_VA_92E6D3,
     0x0092e6d3],
    ["firstRetVa", "isaac_sfx_duck_first_ret_va", sfxDuckFirstRetVa,
     SFX_DUCK_FIRST_RET_VA_92E653, 0x0092e653],
    ["nextVa", "isaac_sfx_duck_next_va", sfxDuckNextVa,
     SFX_DUCK_NEXT_VA_92E6E0, 0x0092e6e0],
    ["callerCount", "isaac_sfx_duck_caller_count", sfxDuckCallerCount,
     SFX_DUCK_CALLER_COUNT, 31],
    ["imm32Ref1Va", "isaac_sfx_duck_imm32_ref1_va", sfxDuckImm32Ref1Va,
     SFX_DUCK_IMM32_REF1_VA_86DAF1, 0x0086daf1],
    ["imm32Ref2Va", "isaac_sfx_duck_imm32_ref2_va", sfxDuckImm32Ref2Va,
     SFX_DUCK_IMM32_REF2_VA_89564A, 0x0089564a],
    ["thresholdVa", "isaac_sfx_duck_threshold_va", sfxDuckThresholdVa,
     SFX_DUCK_THRESHOLD_VA_BAA06C, 0x00baa06c],
    ["thresholdBits", "isaac_sfx_duck_threshold_bits", sfxDuckThresholdBits,
     SFX_DUCK_THRESHOLD_BITS_3C23D70A, 0x3c23d70a],
    ["idArgOff", "isaac_sfx_duck_id_arg_off", sfxDuckIdArgOff,
     SFX_DUCK_ID_ARG_OFF_8, 0x08],
    ["volArgOff", "isaac_sfx_duck_vol_arg_off", sfxDuckVolArgOff,
     SFX_DUCK_VOL_ARG_OFF_C, 0x0c],
    ["pitchArgOff", "isaac_sfx_duck_pitch_arg_off", sfxDuckPitchArgOff,
     SFX_DUCK_PITCH_ARG_OFF_10, 0x10],
    ["stackArgs", "isaac_sfx_duck_stack_args", sfxDuckStackArgs,
     SFX_DUCK_STACK_ARGS_3, 3],
    ["armSilentVa", "isaac_sfx_duck_arm_silent_va", sfxDuckArmSilentVa,
     SFX_DUCK_ARM_SILENT_VA_92E63A, 0x0092e63a],
    ["armAudibleVa", "isaac_sfx_duck_arm_audible_va", sfxDuckArmAudibleVa,
     SFX_DUCK_ARM_AUDIBLE_VA_92E656, 0x0092e656],
    ["armPlayVa", "isaac_sfx_duck_arm_play_va", sfxDuckArmPlayVa,
     SFX_DUCK_ARM_PLAY_VA_92E68C, 0x0092e68c],
    ["gateAudibleGt", "isaac_sfx_duck_gate_audible_gt", sfxDuckGateAudibleGt,
     SFX_DUCK_GATE_AUDIBLE_GT, 1],
    ["sharedIdPushVa", "isaac_sfx_duck_shared_id_push_va",
     sfxDuckSharedIdPushVa, SFX_DUCK_SHARED_ID_PUSH_VA_92E637, 0x0092e637],
    ["silentStopWhenPlaying", "isaac_sfx_duck_silent_stop_when_playing",
     sfxDuckSilentStopWhenPlaying, SFX_DUCK_SILENT_STOP_WHEN_PLAYING, 1],
    ["silentIdleExitVa", "isaac_sfx_duck_silent_idle_exit_va",
     sfxDuckSilentIdleExitVa, SFX_DUCK_SILENT_IDLE_EXIT_VA_92E6CF,
     0x0092e6cf],
    ["audibleAdjustWhenPlaying", "isaac_sfx_duck_audible_adjust_when_playing",
     sfxDuckAudibleAdjustWhenPlaying, SFX_DUCK_AUDIBLE_ADJUST_WHEN_PLAYING,
     1],
    ["volumeBeforePitch", "isaac_sfx_duck_volume_before_pitch",
     sfxDuckVolumeBeforePitch, SFX_DUCK_VOLUME_BEFORE_PITCH, 1],
    ["audiblePlayWhenIdle", "isaac_sfx_duck_audible_play_when_idle",
     sfxDuckAudiblePlayWhenIdle, SFX_DUCK_AUDIBLE_PLAY_WHEN_IDLE, 1],
    ["prePlayVa", "isaac_sfx_duck_pre_play_va", sfxDuckPrePlayVa,
     SFX_DUCK_PRE_PLAY_VA_956780, 0x00956780],
    ["preSlotOff", "isaac_sfx_duck_pre_slot_off", sfxDuckPreSlotOff,
     SFX_DUCK_PRE_SLOT_OFF_8, 0x08],
    ["playRootVa", "isaac_sfx_duck_play_root_va", sfxDuckPlayRootVa,
     SFX_DUCK_PLAY_ROOT_VA_C7169C, 0x00c7169c],
    ["playRecvOff", "isaac_sfx_duck_play_recv_off", sfxDuckPlayRecvOff,
     SFX_DUCK_PLAY_RECV_OFF_2A324, 0x2a324],
    ["playVa", "isaac_sfx_duck_play_va", sfxDuckPlayVa,
     SFX_DUCK_PLAY_VA_92DC30, 0x0092dc30],
    ["playArg3", "isaac_sfx_duck_play_arg3", sfxDuckPlayArg3,
     SFX_DUCK_PLAY_ARG3_IMM_2, 2],
    ["playArg4", "isaac_sfx_duck_play_arg4", sfxDuckPlayArg4,
     SFX_DUCK_PLAY_ARG4_IMM_1, 1],
    ["playArg6", "isaac_sfx_duck_play_arg6", sfxDuckPlayArg6,
     SFX_DUCK_PLAY_ARG6_IMM_0, 0],
    ["playStackArgs", "isaac_sfx_duck_play_stack_args", sfxDuckPlayStackArgs,
     SFX_DUCK_PLAY_STACK_ARGS_6, 6],
    ["isPlayingVa", "isaac_sfx_duck_is_playing_va", sfxDuckIsPlayingVa,
     SFX_DUCK_IS_PLAYING_VA_92E560, 0x0092e560],
    ["stopVa", "isaac_sfx_duck_stop_va", sfxDuckStopVa,
     SFX_DUCK_STOP_VA_92E230, 0x0092e230],
    ["setVolumeVa", "isaac_sfx_duck_set_volume_va", sfxDuckSetVolumeVa,
     SFX_DUCK_SET_VOLUME_VA_92DF40, 0x0092df40],
    ["setPitchVa", "isaac_sfx_duck_set_pitch_va", sfxDuckSetPitchVa,
     SFX_DUCK_SET_PITCH_VA_92E050, 0x0092e050],
    ["branches", "isaac_sfx_duck_branches", sfxDuckBranches,
     SFX_DUCK_BRANCH_COUNT_3, 3],
  ];
  for (const [key, wasmName, jsFn, jsConst, want] of rows) {
    eq(wasm[wasmName]() >>> 0, want, `wasm ${key}`);
    eq(jsFn(), want, `js fn ${key}`);
    eq(jsConst, want, `js const ${key}`);
    seen(`v30${key[0].toUpperCase() + key.slice(1)}`, want);
    countCase();
  }
  /* Cross-pins: the wrapper's delegation facts must equal the family's
     existing records (v1 roots + v8 preload + v29 dtor) - the SAME
     machine facts, so the getters must equal the model constants the
     older blocks already pin. */
  eq(sfxDuckPlayRootVa(), SFX_GLOBAL_ROOT_VA,
     "duck play root == v1 global root *(0xc7169c)");
  eq(sfxDuckPlayRecvOff(), SFX_MANAGER_RECEIVER_OFF,
     "duck receiver off == v1 manager receiver off");
  eq(sfxDuckPlayVa(), SFX_HOST_VA_PLAY,
     "duck play callee == v1 Play root");
  eq(sfxDuckIsPlayingVa(), SFX_HOST_VA_IS_PLAYING,
     "duck gate callee == v1 is-playing root");
  eq(sfxDuckStopVa(), SFX_HOST_VA_STOP,
     "duck silent action == v1 stop root");
  eq(sfxDuckSetVolumeVa(), SFX_HOST_VA_SET_VOLUME,
     "duck audible action 1 == v1 set-volume root");
  eq(sfxDuckSetPitchVa(), SFX_HOST_VA_SET_PITCH,
     "duck audible action 2 == v1 set-pitch root");
  eq(sfxDuckNextVa(), 0x0092e6e0,
     "duck next == the v29 audit's GetVolume frontier root");
  eq(sfxDuckThresholdBits(), 0x3c23d70a,
     "duck threshold float bits = 0.01f");
  eq(sfxDuckBranches(), 3,
     "duck body has 3 conditional branches (jb + je + je)");
  eq(sfxDuckGateAudibleGt() === 1, true,
     "comiss jb: 0.01f < volume -> AUDIBLE arm, fall -> SILENT");
  eq(sfxDuckVolumeBeforePitch() === 1, true,
     "set_volume (0x92e66d) runs before set_pitch (0x92e680)");
  eq(sfxDuckSilentStopWhenPlaying() === 1, true,
     "silent arm stops only when is_playing is true");
  eq(sfxDuckAudibleAdjustWhenPlaying() === 1, true,
     "audible arm adjusts only when is_playing is true");
  eq(sfxDuckAudiblePlayWhenIdle() === 1, true,
     "audible idle jumps to the PLAY arm (je 0x92e68c)");
  eq(sfxDuckPlayStackArgs(), 6,
     "Play consumes 6 stack args (ret 0x18) - all play-arm pushes");
  eq(sfxDuckPrePlayVa(), 0x00956780,
     "pre-play ctor is the sfx-side consumer of the PM lease");
  countCase();
});

/* ---------- v31: SetPan / GetVolume / vector clear ---------- */

const SETPAN_VOICE_PLAN_SIZE = 28;
const SETPAN_VOICE_PLAN_OFF = {
  enter: 0,
  pendingClear: 4,
  panStored: 8,
  action: 12,
  warnLogNeeded: 16,
  deviceCallNeeded: 20,
  storedPanBits: 24,
};

const GETVOLUME_PLAN_SIZE = 20;
const GETVOLUME_PLAN_OFF = {
  gateKind: 0,
  warnLogNeeded: 4,
  isPlayingGateRan: 8,
  returnsBaseVolume: 12,
  baseVolumeOff: 16,
};

const CLEARVEC_FREE_PLAN_SIZE = 28;
const CLEARVEC_FREE_PLAN_OFF = {
  destroyRuns: 0,
  blockSize: 4,
  usesBackPointer: 8,
  freeSize: 12,
  slackChecked: 16,
  corruptFatal: 20,
  zeroStores: 24,
};

function readSetPanVoicePlan(view, base) {
  return {
    enter: readI32(view, base + SETPAN_VOICE_PLAN_OFF.enter),
    pendingClear: readI32(view, base + SETPAN_VOICE_PLAN_OFF.pendingClear),
    panStored: readI32(view, base + SETPAN_VOICE_PLAN_OFF.panStored) !== 0,
    action: readI32(view, base + SETPAN_VOICE_PLAN_OFF.action),
    warnLogNeeded:
      readI32(view, base + SETPAN_VOICE_PLAN_OFF.warnLogNeeded) !== 0,
    deviceCallNeeded:
      readI32(view, base + SETPAN_VOICE_PLAN_OFF.deviceCallNeeded) !== 0,
    storedPanBits: readU32(view, base + SETPAN_VOICE_PLAN_OFF.storedPanBits),
  };
}

function readGetVolumePlan(view, base) {
  return {
    gateKind: readI32(view, base + GETVOLUME_PLAN_OFF.gateKind),
    warnLogNeeded: readI32(view, base + GETVOLUME_PLAN_OFF.warnLogNeeded) !== 0,
    isPlayingGateRan:
      readI32(view, base + GETVOLUME_PLAN_OFF.isPlayingGateRan) !== 0,
    returnsBaseVolume:
      readI32(view, base + GETVOLUME_PLAN_OFF.returnsBaseVolume) !== 0,
    baseVolumeOff: readU32(view, base + GETVOLUME_PLAN_OFF.baseVolumeOff),
  };
}

function readClearVecFreePlan(view, base) {
  return {
    destroyRuns: readI32(view, base + CLEARVEC_FREE_PLAN_OFF.destroyRuns) !== 0,
    blockSize: readU32(view, base + CLEARVEC_FREE_PLAN_OFF.blockSize),
    usesBackPointer:
      readI32(view, base + CLEARVEC_FREE_PLAN_OFF.usesBackPointer) !== 0,
    freeSize: readU32(view, base + CLEARVEC_FREE_PLAN_OFF.freeSize),
    slackChecked:
      readI32(view, base + CLEARVEC_FREE_PLAN_OFF.slackChecked) !== 0,
    corruptFatal:
      readI32(view, base + CLEARVEC_FREE_PLAN_OFF.corruptFatal) !== 0,
    zeroStores: readI32(view, base + CLEARVEC_FREE_PLAN_OFF.zeroStores),
  };
}

