test("Wasm matches JS: v32 channel/entry ctor + release laws (stream state machine)", () => {
  /* Oracular transcription from the fresh dumps cpu-dump/00a2a990.txt,
     00a2ae60.txt, 0092cea0.txt, 0092ce30.txt, 008f2c90.txt — NOT derived
     from the cpp. release_arg / old_secondary / hook_ptr are FULL dwords
     (0x100/0x1ff/0xffffffff drives must echo verbatim); the vtbl[0xc]
     probe result is a LOW-BYTE gate (& 0xff). */
  const view = new DataView(wasm.memory.buffer);
  const ctorBase = SCRATCH + 0x10300;
  const relBase = SCRATCH + 0x10380;
  const entryBase = SCRATCH + 0x10400;

  /* --- channel ctor defaults (0 inputs) --- */
  wasm.isaac_sfx_channel_ctor_defaults(ctorBase);
  const ctorPlan = readChannelCtorPlan(view, ctorBase);
  const ctorWant = sfxChannelCtorDefaults();
  eq(ctorPlan.channel00After, ctorWant.channel00After, "ctor channel = 0");
  eq(ctorPlan.secondary04Alloc, ctorWant.secondary04Alloc, "ctor secondary alloc");
  eq(ctorPlan.secondary04Vtable, ctorWant.secondary04Vtable,
     "ctor secondary vtable 0xb9c430");
  eq(ctorPlan.loopPending08After, ctorWant.loopPending08After,
     "ctor loop/pending word 0");
  eq(ctorPlan.flag0aAfter, ctorWant.flag0aAfter, "ctor flag 0");
  eq(ctorPlan.volume0cAfter, ctorWant.volume0cAfter, "ctor volume 1.0f");
  eq(ctorPlan.pan10After, ctorWant.pan10After, "ctor pan 0.0f");
  eq(ctorPlan.pitch14After, ctorWant.pitch14After, "ctor pitch 1.0f");
  eq(ctorPlan.channel00After, 0, "NULL BY CONSTRUCTION (wasm)");
  countCase();

  /* --- entry ctor defaults (0 inputs) --- */
  wasm.isaac_sfx_entry_ctor_defaults(entryBase);
  const entryPlan = readEntryCtorPlan(view, entryBase);
  const entryWant = sfxEntryCtorDefaults();
  eq(entryPlan.frameEnd04After, entryWant.frameEnd04After,
     "entry frame-end default -1");
  eq(entryPlan.voices190After, entryWant.voices190After, "entry voices 0");
  eq(entryPlan.enabled198After, entryWant.enabled198After, "entry enabled 0");
  eq(entryPlan.entryStringCap, entryWant.entryStringCap, "entry string cap 0xf");
  eq(entryPlan.voiceSlots, entryWant.voiceSlots, "seven voice slots");
  eq(entryPlan.channelsNull, entryWant.channelsNull,
     "all seven channels null after construction");
  eq(entryPlan.streamBytesZero, entryWant.streamBytesZero,
     "stream bytes zeroed per slot");
  eq(entryPlan.frameEnd04After, -1, "fresh entries carry the -1 sentinel");
  countCase();

  /* --- release law: full-dword arg echo + hook gate (wide drives) --- */
  const releaseRows = [];
  for (const arg of [0, 1, 0x100, 0x1ff, 0x7fffffff, 0xffffffff]) {
    for (const oldSec of [0, 0x1000]) {
      for (const probe of [0, 1, 0x100, 0x1ff]) {
        for (const hook of [0, SFX_RELEASE_HOOK_GLOBAL_C7F484]) {
          releaseRows.push([arg, oldSec, probe, hook]);
        }
      }
    }
  }
  /* 6*2*4*2 = 96 rows — well inside the 500-draw cap. */
  for (const [arg, oldSec, probe, hook] of releaseRows) {
    wasm.isaac_sfx_channel_release_plan(arg, oldSec, probe, hook, relBase);
    assertPlanEqual(
      readChannelReleasePlan(view, relBase),
      sfxChannelReleasePlan(arg, oldSec, probe, hook),
      `v32 release ${arg}/${oldSec}/${probe}/${hook}`,
    );
    countCase();
    if ((arg & 0xff) !== arg) {
      eq(readChannelReleasePlan(view, relBase).channel00After, arg | 0,
         `release echo is FULL dword (${arg})`);
    }
    if (probe === 0x100) {
      eq(readChannelReleasePlan(view, relBase).hookRuns, 0,
         "probe byte gate: 0x100 (low byte 0) answers NO");
    } else if (probe === 0x1ff) {
      eq(readChannelReleasePlan(view, relBase).hookRuns,
         oldSec !== 0 && hook !== 0 ? 1 : 0,
         "probe byte gate: 0x1ff (low byte 0xff) answers YES");
    }
    if (oldSec === 0) {
      eq(readChannelReleasePlan(view, relBase).hookProbeRuns, 0,
         `hook probe skipped on null old secondary (${arg})`);
      eq(readChannelReleasePlan(view, relBase).hookRuns, 0,
         `hook skipped on null old secondary (${arg})`);
    }
  }
  /* Constant edges of the release law. */
  const r = sfxChannelReleasePlan(0, 0, 0, 0);
  eq(r.channel00After, 0, "reset/dtor pass arg 0 -> channel stays null");
  eq(r.secondary04Vtable, SFX_RELEASE_SECONDARY_VTABLE_B9C430,
     "fresh secondary carries the 0xb9c430 pair-object vtable");
  eq(r.argEcho14, 0, "arg echoed into the new object's +0x14");
  const rLive = sfxChannelReleasePlan(0x12345678, 0x2000, 1, 0xc7f484);
  eq(rLive.channel00After, 0x12345678, "release echoes the runtime handle");
  eq(rLive.hookRuns, 1, "hook runs when old secondary live + probe + hook");
  countCase();

  /* --- cross-law: the stream state machine (census verdict) --- */
  eq(sfxChannelCtorDefaults().channel00After, 0,
     "FRESH wrapper: channel null by construction (0xa2a9bc/0xa2aa29)");
  eq(sfxChannelReleasePlan(0, 0, 0, 0).channel00After, 0,
     "RESET/DTOR: release(0) keeps the channel null (0xa2abd0/0xa2ab40)");
  eq(sfxChannelReleasePlan(0x5aa5, 0, 0, 0).channel00After, 0x5aa5,
     "ATTACH path: release passes the device handle (0xa2add0 -> 0xa2ae60)");
  eq(sfxEntryCtorDefaults().channelsNull, 7,
     "a fresh entry is in the 92e300 all-null no-op class (v85/v88 gate)");
  eq(SFX_ENTRY_CTOR_FRAME_END_NEG1, 0xffffffff,
     "divergence 0 of 92e300 vs 92e230: no [entry+4]=-1 because fresh "
     + "entries already carry it");
  countCase();
});

/* ---------- v33: SoundEffect::Load load-arm gates (wave-26 F14;
   notes sfx-v33-load/census-sfx-load.py) ----------
   Verify-open: 0x92cfb0 = exact `__thiscall void SoundEffect::Load()`
   (47-B SoundEffects.zhl pattern; 22 rel32 callers incl. the 0x92cf40
   wrapper @0x92cf8e — corrected-census confirmed). The body's pure
   decision layer (v3 split + v13/v22 islands) leaves THREE gaps this
   block lands: the ENTRY GATE (0x92cfe0 `cmp dword [esi+0x190],0 ;
   jbe 0x92d10f` — UNSIGNED full-dword zero check; 0 is the only skip
   value; skip still lands on the enabled:=1 tail), the per-voice
   LOAD-ARM enum (0x92d023..0x92d0c7: FATAL size<4 -> 0x499950,
   STREAM ".ogg" match -> al=1 with the device arm skipped ENTIRELY,
   DEVICE -> vtbl[0x24] open + assign + probe + hook, al=0) and the
   typed-host COLD-TAIL declaration (abort 0x92d132 -> IAT 0xb18894,
   sole inbound 0x92d0ea ja; fatal 0x92d138 -> 0x499950, sole inbound
   0x92d028 jb; enable 0x92d10f, 2 inbounds). All pins from the fresh
   dump cpu-dump/0092cfb0.txt + the corrected .text census. */

const LOAD_ARM_PLAN_SIZE = 32;
const LOAD_ARM_PLAN_OFF = {
  armKind: 0,
  fatal: 4,
  oggMatch: 8,
  fileOpenNeeded: 12,
  streamByteValue: 16,
  usesHeapBuffer: 20,
  heapFreeNeeded: 24,
  suffixCompareNeeded: 28,
};

function readLoadArmPlan(view, base) {
  return {
    armKind: readI32(view, base + LOAD_ARM_PLAN_OFF.armKind),
    fatal: readI32(view, base + LOAD_ARM_PLAN_OFF.fatal),
    oggMatch: readI32(view, base + LOAD_ARM_PLAN_OFF.oggMatch),
    fileOpenNeeded: readI32(view, base + LOAD_ARM_PLAN_OFF.fileOpenNeeded),
    streamByteValue: readI32(view, base + LOAD_ARM_PLAN_OFF.streamByteValue),
    usesHeapBuffer: readI32(view, base + LOAD_ARM_PLAN_OFF.usesHeapBuffer),
    heapFreeNeeded: readI32(view, base + LOAD_ARM_PLAN_OFF.heapFreeNeeded),
    suffixCompareNeeded:
      readI32(view, base + LOAD_ARM_PLAN_OFF.suffixCompareNeeded),
  };
}

