test("Wasm matches JS: v37 dtor-forest decision laws", () => {
  const view = new DataView(wasm.memory.buffer);

  /* --- owned-free gate: FULL dword ptr test (7 sites) --- */
  for (const ptr of [0, 1, 0x100, 0xffffffff]) {
    const want = sfxDtorOwnedFreeGate(ptr);
    eq(wasm.isaac_sfx_dtor_owned_free_gate(ptr), want,
       `owned ${ptr.toString(16)}`);
    eq(want, (ptr >>> 0) !== 0 ? 1 : 0, `owned semantic ${ptr.toString(16)}`);
    countCase();
  }
  eq(sfxDtorOwnedFreeGate(0), 0, "null owned ptr -> no release");
  eq(sfxDtorOwnedFreeGate(0x100), 1, "0x100 is a LIVE pointer (full dword)");
  eq(sfxDtorOwnedFreeGate(0xffffffff), 1, "wide ptr gates");
  countCase();

  /* --- lock-byte clear: byte in, byte out (8 sites) --- */
  for (const b of [0, 1, 0xfe, 0xff, 0x100, 0x101, 0xffffffff]) {
    const want = sfxDtorLockBitClear(b);
    eq(wasm.isaac_sfx_dtor_lock_bit_clear(b), want,
       `lock ${b.toString(16)}`);
    eq(want, ((b & 0xff) & 0xfe) >>> 0,
       `lock semantic ${b.toString(16)}`);
    countCase();
  }
  eq(sfxDtorLockBitClear(0xff), 0xfe, "0xff -> 0xfe (bit0 cleared)");
  eq(sfxDtorLockBitClear(0x101), 0, "0x101 low byte 1 -> 0");
  eq(sfxDtorLockBitClear(0), 0, "0 stays 0");
  countCase();

  /* --- flags put0: FULL dword and (3 sites) --- */
  for (const flags of [0, 1, 2, 0x100, 0xffffffff]) {
    const want = sfxDtorFlagsPut0(flags);
    eq(wasm.isaac_sfx_dtor_flags_put0(flags) >>> 0, want,
       `put0 ${flags.toString(16)}`);
    eq(want, (flags & ~1) >>> 0, `put0 semantic ${flags.toString(16)}`);
    countCase();
  }
  eq(sfxDtorFlagsPut0(1), 0, "bit0 cleared");
  eq(sfxDtorFlagsPut0(3), 2, "other bits kept");
  eq(sfxDtorFlagsPut0(0x100), 0x100, "wide flags keep high bit");
  countCase();

  /* --- census pin parity: wasm getter == js getter == hand value --- */
  for (const [w, j, label, hand] of [
    [wasm.isaac_sfx_nested_dtor_va(), sfxNestedDtorVa(), "nestedva", 0xa2af30],
    [wasm.isaac_sfx_nested_dtor_shared_bodies(), sfxNestedDtorSharedBodies(),
     "nested-shared", 3],
    [wasm.isaac_sfx_nested_dtor_e8_callers(), sfxNestedDtorE8Callers(),
     "nested-callers", 3],
    [wasm.isaac_sfx_manager_vftable_va(), sfxManagerVftableVa(),
     "mgrvftable", 0xb9c4dc],
    [wasm.isaac_sfx_secondary1_vftable_va(), sfxSecondary1VftableVa(),
     "sec1vftable", 0xba306c],
    [wasm.isaac_sfx_secondary2_vftable_va(), sfxSecondary2VftableVa(),
     "sec2vftable", 0xba30b0],
    [wasm.isaac_sfx_manager_base_vftable_va(), sfxManagerBaseVftableVa(),
     "basevftable", 0xb9fdcc],
    [wasm.isaac_sfx_member_vftable_va(), sfxMemberVftableVa(),
     "membervftable", 0xb81c0c],
    [wasm.isaac_sfx_member_base_vftable_va(), sfxMemberBaseVftableVa(),
     "memberbase", 0xba04b4],
    [wasm.isaac_sfx_pair_vftable_va(), sfxPairVftableVa(),
     "pairvftable", 0xb9c430],
    [wasm.isaac_sfx_pair_base_vftable_va(), sfxPairBaseVftableVa(),
     "pairbase", 0xb1a6fc],
    [wasm.isaac_sfx_flag_bit1_setter_va(), sfxFlagBit1SetterVa(),
     "flagseter1", 0xa13590],
    [wasm.isaac_sfx_dtor_forest_vtables(), sfxDtorForestVtables(),
     "forestvtables", 6],
    [wasm.isaac_sfx_dtor_delete_gate_bodies(), sfxDtorDeleteGateBodies(),
     "deletegate", 8],
    [wasm.isaac_sfx_dtor_owned_free_gate_sites(), sfxDtorOwnedFreeGateSites(),
     "ownedgates", 7],
    [wasm.isaac_sfx_dtor_lock_clear_sites(), sfxDtorLockClearSites(),
     "lockclears", 8],
    [wasm.isaac_sfx_dtor_flags_put0_sites(), sfxDtorFlagsPut0Sites(),
     "put0sites", 3],
    [wasm.isaac_sfx_dtor_owned_free_size(), sfxDtorOwnedFreeSize(),
     "ownedsize", 0x1c],
    [wasm.isaac_sfx_dtor_block_free_va(), sfxDtorBlockFreeVa(),
     "blockfree", 0x4149d0],
    [wasm.isaac_sfx_dtor_block_free_site(), sfxDtorBlockFreeSite(),
     "blockfree-site", 0xa2af6f],
    [wasm.isaac_sfx_list_clear_va(), sfxListClearVa(),
     "listclear", 0xa2bcb0],
    [wasm.isaac_sfx_list_clear_callers(), sfxListClearCallers(),
     "listclear-callers", 5],
    [wasm.isaac_sfx_hook_callable_va(), sfxHookCallableVa(),
     "hookcallable", 0xa2bb10],
    [wasm.isaac_sfx_release_fnptr_va(), sfxReleaseFnptrVa(),
     "releasefnptr", 0xb18274],
    [wasm.isaac_sfx_dtor_vptr_store1_va(), sfxDtorVptrStore1Va(),
     "vptrstore1", 0xa2af34],
    [wasm.isaac_sfx_dtor_vptr_store2_va(), sfxDtorVptrStore2Va(),
     "vptrstore2", 0xa2afc6],
    [wasm.isaac_sfx_hook_install_lock_sites(), sfxHookInstallLockSites(),
     "installlocks", 2],
    [wasm.isaac_sfx_hook_clear_lock_sites(), sfxHookClearLockSites(),
     "clearlocks", 2],
    [wasm.isaac_sfx_hook_clear_reinit_stores(), sfxHookClearReinitStores(),
     "reinitstores", 4],
  ]) {
    eq(w, j, `${label} wasm==js`);
    eq(j, hand, `${label} hand`);
    countCase();
  }
});

/* ---------- v38: 0xa2bb10 hook-callable decision layer (wave-31 F4;
   notes sfx-v38-hook; fresh dump cpu-dump/00a2bb10.txt) ----------
   Verify-open: the v37 §2h reached-leaves audit's only caller-bearing
   upstream body — the v22 attach-hook BODY. The brief's 0x92cfb0
   Load decision surface was CLOSED at v33 (its 22 rel32 callers
   re-censused this unit, all in landed/out-of-extent bodies) and the
   0x92e68c ducking play arm was LANDED at v30. 0xa2bb10: cdecl, ONE
   stack arg = the pair pointer; 0 E8/E9 direct callers, 2 imm32
   installs (0xa2afeb + 0xa7d53a), dispatched via 0xc7f484 by the
   family's own islands. Oracular rows from the fresh listing + the
   lea-corrected census — NOT derived from the cpp. */

const V38_HOOK_PLAN_OFF = {
  pair1Gate: 0,
  lockWordGate: 4,
  bodyRuns: 8,
  keyGate: 12,
  walkRuns: 16,
  walkIterations: 20,
  walkMatchFound: 24,
  warnRuns: 28,
  mapRuns: 32,
  mapStep: 36,
  foundArmRuns: 40,
  advanceCalls: 44,
  removeCallRuns: 48,
  freeRuns: 52,
  islandHookRuns: 56,
  tailUnlockRuns: 60,
  mapFindCallRuns: 64,
};

function readV38HookPlan(view, base) {
  const o = V38_HOOK_PLAN_OFF;
  return {
    pair1Gate: readU32(view, base + o.pair1Gate),
    lockWordGate: readU32(view, base + o.lockWordGate),
    bodyRuns: readU32(view, base + o.bodyRuns),
    keyGate: readU32(view, base + o.keyGate),
    walkRuns: readU32(view, base + o.walkRuns),
    walkIterations: readU32(view, base + o.walkIterations),
    walkMatchFound: readU32(view, base + o.walkMatchFound),
    warnRuns: readU32(view, base + o.warnRuns),
    mapRuns: readU32(view, base + o.mapRuns),
    mapStep: readU32(view, base + o.mapStep),
    foundArmRuns: readU32(view, base + o.foundArmRuns),
    advanceCalls: readU32(view, base + o.advanceCalls),
    removeCallRuns: readU32(view, base + o.removeCallRuns),
    freeRuns: readU32(view, base + o.freeRuns),
    islandHookRuns: readU32(view, base + o.islandHookRuns),
    tailUnlockRuns: readU32(view, base + o.tailUnlockRuns),
    mapFindCallRuns: readU32(view, base + o.mapFindCallRuns),
  };
}

